\section{Introduction}

 We are interested to understand how a perturbation of the initial value $y_{0}$ of the linear $n-$dimensional Ordinary Differential Equation (ODE) 
\begin{equation}
	\left\{ 
	\begin{array}{l}
		y^{\prime }\left( t\right) =Ay\left( t\right) ,\ t\in\mathbb{R}, \\ 
		y\left( 0\right) =y_{0},%
	\end{array}%
	\right.  \label{ode}
\end{equation}%
where $A\in \mathbb{C}^{n\times n}$ and $y_0,y(t)\in\mathbb{C}^n$, is propagated to the solution $y(t)=\mathrm{e}^{tA}y_0$ of (\ref{ode}) over a long time $t$. This perturbation, propagating along the solution, is measured by a relative error rather than an absolute error. In other words, we study the (relative) conditioning of the linear problem
\begin{equation}
	y_0\mapsto \mathrm{e}^{tA}y_0  \label{due}
\end{equation}
for large time $t$.

The conditioning of the problem (\ref{due}) has received little attention in literature despite of its significance in the context of ODEs. In contrast, the study of the conditioning of the matrix exponential $\mathrm{e}^{tA}$ is quite extensive; see, for example, \cite{Levis1969}, \cite{van2006}, \cite{Kagstrom1977}, \cite{Van1977}, \cite{moler2003}, \cite{Mohy2008}, \cite{Zhu2008}, \cite{Mohy2011}, \cite{Ed}, and \cite{ALMOHY2017}. However, none of these papers examined how the conditioning depends on $t$, a crucial aspect for ODEs. This type of analysis, for $A$ normal, was addressed in \cite{Maset2018} for the problem (\ref{due}) and in \cite{FarooqMaset2021} for the problem $A \mapsto \mathrm{e}^{tA}y_0$. In the present paper, for the problem (\ref{due}), we consider a general matrix $A$. 

The present paper complements the work presented in \cite{Maset2022}. The paper \cite{Maset2022} offers a non-technical exposition without proofs of the main results found in the present paper. It includes motivations, practical examples, and numerical tests. Consequently, these aspects are not addressed in the present paper, which focuses on providing the proofs of all results and the necessary theoretical development for obtaining them.   



\subsection{The condition numbers}

Suppose that the initial value $y_{0}\neq 0$ in (\ref{ode}) is perturbed to $%
\widetilde{y}_{0}$ and, as consequence, the solution $y$ is perturbed to $\widetilde{y}$. Let $\left\Vert \ \cdot \ \right\Vert $ be an arbitray vector norm on $\mathbb{C}^{n}$.  We introduce
the normwise relative error 
\begin{equation*}
\varepsilon =\frac{\left\Vert \widetilde{y}_{0}-y_{0}\right\Vert }{%
\left\Vert y_{0}\right\Vert }  %\label{varepsilon}
\end{equation*}
of $\widetilde{y}_{0}$ and the normwise relative error 
\begin{equation*}
\delta \left( t\right) =\frac{\left\Vert \widetilde{y}\left( t\right)
-y\left( t\right) \right\Vert }{\left\Vert y\left( t\right) \right\Vert }  \label{deltat}
\end{equation*}%
of $\widetilde{y}(t)$. By writing
\begin{equation*}
\widetilde{y}_0=y_0+\varepsilon \Vert y_0\Vert \widehat{z}_0,
\end{equation*}
where $\widehat{z}_0\in\mathbb{C}^n$ with $\Vert \widehat{z%
}_0 \Vert=1$ is the direction of perturbation, we obtain 
\begin{equation*}
\delta \left( t\right) =K\left( t,y_{0},\widehat{z}_{0}\right) \cdot  \label{magnification}
\varepsilon ,
\end{equation*}%
where
\begin{equation}
K\left( t,y_{0},\widehat{z}_{0}\right) :=\frac{\left\Vert \mathrm{e}^{tA}%
\widehat{z}_{0}\right\Vert }{\left\Vert \mathrm{e}^{tA}\widehat{y}%
_{0}\right\Vert },  \label{Ktayz0}
\end{equation}%
with  $\widehat{y}_{0}:=\frac{y_{0}}{\left\Vert y_{0}\right\Vert }$, is called the \emph{directional condition number} of the problem (\ref{due}).


Along with the condition number (\ref{Ktayz0}), we also introduce other two condition numbers: the \emph{condition number} of the
problem (\ref{due}) (see \cite{Burgisser2013} for the definition of
condition number of a general problem) given by 
\begin{equation}
K\left( t,y_{0}\right) :=\max\limits_{\substack{ \widehat{z}_0\in \mathbb{C%
}^{n}  \\ \Vert \widehat{z}_0\Vert =1}}K\left( t,y_{0},\widehat{z}%
_0\right) =\frac{\left\Vert \mathrm{e}^{tA}\right\Vert }{\left\Vert \mathrm{e%
}^{tA}\widehat{y}_{0}\right\Vert },  \label{KAy0}
\end{equation}%
where $\left\Vert \mathrm{e}^{tA}\right\Vert $ is the matrix norm of $%
\mathrm{e}^{tA}$ induced by the vector norm $\left\Vert \ \cdot \
\right\Vert $; and the \emph{global condition number} of the problem (\ref{due}) given by
\begin{equation}
K\left( t\right) :=\max\limits_{\substack{ y_0\in \mathbb{C}^{n}  \\ %
y_0\neq 0}}K\left( t,y_{0}\right) =\left\Vert \mathrm{e}^{tA}\right\Vert
\cdot \left\Vert \mathrm{e}^{-tA}\right\Vert=\kappa\left(\mathrm{e}%
^{tA}\right),  \label{KA0}
\end{equation}
which equals the standard condition number $\kappa\left(\mathrm{e}%
^{tA}\right)$ of the matrix $\mathrm{e}^{tA}$. 

Observe that $K\left( t,y_{0}\right)$ is the worst condition number $%
K(t,y_0,\widehat{z}_0)$ by varying $\widehat{%
z}_0$ and $K(t)$ is the worst condition number $K(t,y_0)$ by varying $y_0$, i.e. the worst
condition number $K(t,y_0,\widehat{z}_0)$ by varying both $y_0$ and $\widehat{z}_0$.

The paper \cite{Maset2018} studied the condition numbers (\ref{Ktayz0}%
), (\ref{KAy0}) and (\ref{KA0}) in case of  $A $ normal and the Euclidean norm as vector norm on $\mathbb{R}^n$. The present paper study the general case where $A$ (complex) and the vector norm are arbitrary.

\begin{remark}\label{remreal}
We also consider the case of a real ODE (\ref{ode}). In this case, we
replace $\mathbb{C}$ by $\mathbb{R}$ and we have $A\in\mathbb{R}^{n\times n}$
and $y_0,y(t),\widetilde{y}_0,\widetilde{y}(t)\in\mathbb{R}^n$. Moreover, the
condition numbers (\ref{KAy0}) and (\ref{KA0}) are defined by maxima over 
$\widehat{z}_0\in \mathbb{R}^{n}$ with $\Vert \widehat{z}_0\Vert=1$ and $%
y_0\in \mathbb{R}^{n}$ with $y_0\neq 0$, respectively.
\end{remark}

\subsection{Plan of the paper}

The present paper is quite long and technical. For this reason, it should be read after or alongside the previously cited expository work \cite{Maset2022}, which presents the main results given here without proofs and extensive technical details.

Here is the plan of the paper. Section 2 introduces some necessary technical linear algebra results concerning the Jordan Canonical Form (JCF) of $A$. Section 3 developes notions and notations for understanding the asymptotic (long-time) behavior considered in the next sections. Section 4 analyzes the asymptotic behaviors of the three conditions numbers $K(t,y_0,$\ $\widehat{z}_0)$, $K(t,y_0)$ and $K(t)$, by introducing the three asymptotic condition numbers $K_\infty(t,y_0,%
	\widehat{z}_0)$, $K_\infty(t,y_0)$ and $%
	K_\infty(t)$. Section 5 summarizes the most important result of Section 4. From Section 6 to the last Section 10, the results of the asymptotic 
	behavior analysis are applied in a generic situation for a real matrix $A$.






\section{Linear Algebra Results} \label{JCFsection}



We introduce linear algebra notations and results necessary for the analysis developed in this paper. Although the content pertains to the well-known topic of the JCF of a matrix, it addresses very specific aspects that are either not known or not sufficiently detailed for the purposes of this paper.

This section can be skipped and referred back to as needed while reading the subsequent sections.



The main goal of the section is to derive a formula for the matrix exponential $\mathrm{e}^{tA}$, where it is explicitly
identified how $\mathrm{e}^{tA}$ depends on $t$. Since it is
based on the JCF of $A$, first we revise such a form.

\subsection{The JCF of the matrix $A$} \label{JCFsubsection}

Let $A\in\mathbb{C}^{n\times n}$ and let $\lambda _{1},\ldots,\lambda _{p}$
be the distinct eigenvalues of $A$. The matrix $A$ is similar to a matrix $%
J\in \mathbb{C}^{n\times n}$, called a \emph{Jordan Canonical Form (JCF)} of 
$A$, with the following structure.
\begin{itemize}
\item The matrix $J$ is block-diagonal with $p$ blocks $J^{\left( 1\right)
},\ldots ,J^{\left( p\right) }$ called \emph{Jordan blocks}:%
\begin{equation*}
J=\mathrm{diag}\left(J^{(1)},\ldots,J^{(p)}\right)\in\mathbb{C}^{n\times n}.
\end{equation*}%
\item For any $i\in\{1,\ldots ,p\}$, the Jordan block $J^{\left( i\right) }$ has dimension $%
\nu _{i}$, where $\nu _{i}$ is the algebraic multiplicity of $\lambda _{i}$,
and it is block-diagonal with $d_{i}$ blocks $J^{\left( i,1\right) },\ldots
,J^{\left( i,d_{i}\right) }$ called \emph{Jordan mini-blocks}, where $d_{i}$
is the geometric multiplicity of $\lambda _{i}$: 
\begin{equation*}
J^{(i)}=\mathrm{diag}\left(J^{\left( i,1\right) },\ldots
,J^{\left( i,d_{i}\right)}\right)\in\mathbb{C}^{\nu_i\times\nu_i}.
\end{equation*}%
\item For any $i\in\{1,\ldots ,p\}$ and for any $j\in\{1,\ldots ,d_{i}\}$, the Jordan mini-block $%
J^{\left( i,j\right) }$ is upper bi-diagonal: 
\begin{equation*}
J^{\left( i,j\right) }=\left[ 
\begin{array}{ccccc}
\lambda _{i} & 1 &  &  &  \\ 
& . & 1 &  &  \\ 
&  & . & 1 &  \\ 
&  &  & . & 1 \\ 
&  &  &  & \lambda _{i}%
\end{array}%
\right]\in\mathbb{C}^{m_{ij}\times m_{ij}} .
\end{equation*}%
The dimension of $J^{\left( i,j\right) }$ is denoted by $m_{ij}$.
\end{itemize}
There is a unique JCF of $A$, except for permutations of the blocks and permutations of the mini-blocks within the blocks.

For any $i\in\{1,\ldots,p\}$, we have
$$
\sum\limits_{j=1}^{d_{i}}m_{ij}=\nu _{i}
$$
and we call
\begin{equation}
m_{i}:=\max_{j\in\{1,\ldots ,d_{i}\}}m_{ij}  \label{ascent}
\end{equation}%
the \emph{ascent} (or \emph{index}) of $\lambda _{i}$.

An eigenvalue $\lambda_i$, $i\in\{1,\ldots,p\}$, is called \emph{defective} if $d_i<\nu_i$ and \emph{non-defective} if $d_i=\nu_i$. Clearly, $\lambda_i$ is non-defective if and only if $m_i=1$, i.e. $J^{(i)}$ is diagonal. The matrix $A$ is diagonalizable if and only if all the eigenvalues $\lambda_1,\ldots,\lambda_p$ are non-defective, i.e. $J$ is diagonal.

An eigenvalue $\lambda_i$, $i\in\{1,\ldots,p\}$, is called \emph{simple} if $d_i=\nu_i=1$.




\subsubsection{Three-index notation}

In the following, we denote an index $l\in\{1,\ldots,n\}$ by three indices $%
\left( i,j,k\right) $, where (see Figure \ref{threeindeces}):

\begin{itemize}
\item $i\in\{1, \ldots, p\}$ is the index of the block $J^{(i)}$ traversed by the $l$-th column (or row) of $J$.;

\item $j\in \left\{ 1,\ldots,d_{i}\right\} $ is the index of the mini-block $%
J^{(i,j)}$ of $J^{(i)}$ traversed by the $l$-th column (or row) of $J$;

\item $k\in \left\{ 1,\ldots,m_{ij}\right\} $ is the index of the column (or row) of
the mini-block $J^{(i,j)}$ included in the $l$-th column (row) of $J$.
\end{itemize}

Observe that the triples $(i,j,k)$ appear lexicographically ordered when the index $l$ moves from $1$ to $n$.

