\subsubsection{The Jordan basis}

Since $A$ is similar to $J$, there exists $V\in \mathbb{C}^{n\times n}$
non-singular such that 
\begin{equation}
J=V^{-1}AV.  \label{JCF}
\end{equation}%
Let
$$
V=\left[v^{(1)}\ \cdots\ v^{(n)}\right].
$$
The $n$ columns $v^{(1)},\ldots, v^{(n)}$ of $V$ constitute a \emph{Jordan basis} of the
space $\mathbb{C}^{n}$.
In the three-index notation, the $n$ columns $%
v^{(l)}$, $l\in\{1,\ldots,n\}$, are denoted by 
\begin{equation}
v^{\left( i,j,k\right) },\ i\in\{1,\ldots ,p\},\ j\in\{1,\ldots ,d_{i}\}\text{\ and\ }%
k\in\{1,\ldots ,m_{ij}\}.  \label{JB}
\end{equation}

For $i\in\{1,\ldots,p\}$, the vectors
\begin{equation*}
v^{\left( i,j,1\right) },\ j\in\{1,\ldots ,d_{i}\},
\end{equation*}
are \emph{eigenvectors} corresponding to the eigenvalue $\lambda_i$: they constitute a basis for the \emph{eigenspace} corresponding to the eigenvalue $\lambda_i$. The vectors
\begin{equation*}
v^{\left( i,j,k\right) },\ j\in\{1,\ldots ,d_{i}\}\text{\ and\ }%
k\in\{1,\ldots ,m_{ij}\},
\end{equation*}
are \emph{generalized eigenvectors} corresponding to the eigenvalue $\lambda_i$: they constitute a basis for the \emph{generalized eigenspace} corresponding to the eigenvalue $\lambda_i$.


\subsubsection{Jordan chains}
The Jordan basis (\ref{JB}) is partitioned in the \emph{Jordan chains} 
\begin{eqnarray*}
&&\left(v^{\left( i,j,k\right)}\right)_{k=1,\ldots,m_{ij}}=\left(v^{\left( i,j,1\right)},v^{\left( i,j,2\right)},\ldots,v^{\left(
i,j,m_{ij}\right)}\right)\\
&&i\in\{1,\ldots,p\}\text{\ and\ }j\in\{1,\ldots,d_i\}.
\end{eqnarray*}

The elements of a
Jordan chain satisfy 
\begin{eqnarray}  \label{ge}
&&\left(A-\lambda_iI\right)v^{\left( i,j,1\right)}=0  \notag \\
&&\left(A-\lambda_iI\right)v^{\left( i,j,k+1\right)}=v^{\left(
i,j,k\right)},\ k\in\{1,\ldots,m_{ij}-1\}.  \notag \\
\end{eqnarray}
The chain stops with $v^{\left( i,j,m_{ij}\right)}$ since the system 
\begin{equation*}
\left(A-\lambda_iI\right)x=v^{\left( i,j,m_{ij}\right)}
\end{equation*}
has not a solution.

Observe that (\ref{JCF}) is equivalent to have (\ref{ge}), for $i\in\{1,\ldots,p\}$ and $j\in\{1,\ldots,d_i\}$, and that there is a correspondence one-to-one between mini-blocks and Jordan chains.
\subsubsection{The matrix $zA$}

The next proposition describes the JCF and a Jordan basis of the matrix $%
z A$, where $z\in\mathbb{C}\setminus\{0\}$, in terms of the JCF
and a Jordan basis of $A$.

\begin{proposition}
\label{Vfor-A} 
Let $z\in\mathbb{C}\setminus\{0\}$. The
distinct eigenvalues of $z A$ are $z\lambda_i$,\ $i\in\{1,\ldots,p\}$.
For any $i\in\{1,\ldots,p\}$, the number and the dimensions of the mini-blocks corresponding to the eigenvalue $z\lambda_i$ in the JCF of $z A
$ are equal to the number and the dimensions of the mini-blocks corresponding to the eigenvalue $\lambda_i$ in the JCF of $A$. A Jordan basis of $zA$ is 
\begin{equation}
z^{-(k-1)}v^{\left( i,j,k\right) },\ i\in\{1,\ldots ,p\},\ j\in\{1,\ldots ,d_{i}\}%
\text{\ and\ }k\in\{1,\ldots ,m_{ij}\}.  \label{vv}
\end{equation}
\end{proposition}
\begin{proof}
Let $i\in\{1,\ldots,p\}$. Given a Jordan chain 
\begin{equation*}
\left(v^{\left( i,j,k\right)}\right)_{k=1,\ldots,m_{ij}}  \label{chainsstart}
\end{equation*}
of $A$ corresponding to the eigenvalue $\lambda_i$, we have that
\begin{equation}
	\left(z^{-(k-1)}v^{\left( i,j,k\right) }\right)_{k=1,\ldots,m_{ij}} \label{chains}
\end{equation}
is a Jordan chain of $z A$ corresponding to the eigenvalue $z\lambda_i$.

In fact, we have (see (\ref{ge})) 
\begin{eqnarray*}
&&\left(z A-z\lambda_iI\right)v^{\left( i,j,1\right) }=0\\
&&\left(z A-z\lambda_iI\right)z^{-k}v^{\left( i,j,k+1\right)
}=z^{-(k-1)}v^{\left( i,j,k\right) },\ k\in\{1,\ldots,m_{ij}-1\}.
\end{eqnarray*}
Moreover, the system
$$
\left(z A-z\lambda_iI\right)x=z^{-(m_{ij}-1)}v^{\left( i,j,m_{ij}\right)}
$$
has no solution; otherwise, the system
$$
\left(A-\lambda_iI\right)y=v^{\left( i,j,m_{ij}\right)}
$$
would have the solution $y = z^{m_{ij}} x$.

By exchanging the role of $A$ and $zA$, i.e. we consider $zA$ and $z^{-1}(zA)$, we also see that given a Jordan chain 
\begin{equation*}
	\left(u^{\left( i,j,k\right)}\right)_{k=1,\ldots,m_{ij}(zA)} 
\end{equation*}
of $zA$ corresponding to the eigenvalue $z\lambda_i$, 
\begin{equation*}
	\left(z^{k-1}u^{\left( i,j,k\right) }\right)_{k=1,\ldots,m_{ij}(zA)}
\end{equation*}
is a Jordan chain of $A$ corresponding to the eigenvalue $\lambda_i$ (here, $m_{ij}(zA)$ denotes the length of a Jordan chain of $zA$). This shows that the Jordan chains of $zA$ are all of type (\ref{chains}). Consequently, the number and the lenghts of the Jordan chains corresponding to the eigenvalue $z\lambda_i$ of $\alpha A$ are equal to the number and the lengths of the Jordan chains corresponding to the eigenvalue $\lambda_i$ of $A$. Therefore, the number and the dimensions of the mini-blocks corresponding to the eigenvalue $z\lambda_i$ of $z A
$ are equal to the number and the dimensions of the mini-blocks corresponding to the eigenvalue $\lambda_i$ of $A$.

A Jordan basis for $z A$ is given by collecting all the Jordan chains (\ref{chains}). Thus, we obtain the Jordan basis (\ref{vv}) for $z A$.
\end{proof}
\subsubsection{The real case}

When $A$ is a real matrix, the distinct complex eigenvalues $%
\lambda_1,\ldots,\lambda_p$ of $A$ are divided in real eigenvalues and
complex conjugate pairs of eigenvalues. The next proposition describes the JCF and a
Jordan basis of $A$, when $A$ is real, in terms of these real
eigenvalues and complex conjugate pairs of eigenvalues.

Here and in the following, for a vector or matrix $Z$, $\overline{Z}$
denotes the vector or matrix given by the complex conjugates of the elements
of $Z$.

\begin{proposition}
\label{Prop22} Assume $A\in\mathbb{R}^{n\times n}$. For $i_{1},i_{2}\in\{1,%
\ldots ,p\}$ with $i_{1}\neq i_{2}$ such that $\lambda _{i_{2}}=\overline{%
\lambda _{i_{1}}}$, i.e. $\lambda _{i_{1}}$ and $\lambda _{i_{2}}$ form a
complex conjugate pair of eigenvalues, we have 
\begin{equation}
\nu _{i_{2}}=\nu _{i_{1}},\ d_{i_{2}}=d_{i_{1}}\text{\ and\ }
m_{i_{2}j}=m_{i_{1}j},\ j\in\{1,\ldots,d_{i_{2}}\}.  \label{R2}
\end{equation}
Moreover, there exists a Jordan basis of $A$ such that:
\begin{itemize}
\item for $i\in\{1,\ldots,p\}$ such that $\lambda_{i}\in\mathbb{R}$, we have 
\begin{equation*}
v^{\left( i,j,k\right) }\in\mathbb{R}^n,\ j\in\{1,\ldots ,d_{i}\}\text{\ and\ }%
k\in\{1,\ldots ,m_{ij}\};  \label{conjugate}
\end{equation*}

\item for $i_{1},i_{2}\in\{1,\ldots ,p\}$ with $i_{1}\neq i_{2}$ such that $%
\lambda _{i_{2}}=\overline{\lambda _{i_{1}}}$, we have 
\begin{equation}
v^{\left( i_{2},j,k\right) }=\overline{v^{\left( i_{1},j,k\right) }},\
j\in\{1,\ldots ,d_{i_{2}}\}\text{\ and\ }k\in\{1,\ldots
,m_{i_{2}j}\}.  \label{R3}
\end{equation}
Observe that $d_{i_2}=d_{i_1}$ and $m_{i_2j}=m_{i_1j}$ hold in (\ref{R3}).
\end{itemize}
\end{proposition}

\begin{proof}
Consider a complex conjugate pair given by $\lambda_{i_1}$ and $\lambda _{i_{2}}=\overline{%
\lambda _{i_{1}}}$. Given a Jordan chain 
\begin{equation*}
\left(v^{\left( i_1,j,k\right)}\right)_{k=1,\ldots,m_{i_1j}}  \label{chains2start}
\end{equation*}
of $A$ corresponding to the eigenvalue $\lambda_{i_1}$, we have that
\begin{equation}
	\left(\overline{v^{\left( i_1,j,k\right) }}\right)_{k=1,\ldots ,m_{i_1j}}
	\label{chains2}
\end{equation}
is a Jordan chain of $A$ corresponding to the eigenvalue $\lambda_{i_2}=\overline{\lambda_{i_1}}$.

In fact, by conjugating both sides in (%
\ref{ge}), we have
\begin{eqnarray*}
&&\left(A-\overline{\lambda_{i_1}}I\right)\overline{v^{\left( i_1,j,1\right) }}=0\\
&&\left(A-\overline{\lambda_{i_1}}I\right)\overline{v^{\left( i_1,j,k+1\right)
}}=\overline{v^{\left( i_1,j,k\right) }},\ k\in\{1,\ldots,m_{i_1j}-1\}.
\end{eqnarray*}
Moreover, the system
$$
\left(A-\overline{\lambda_{i_1}}I\right)x=\overline{v^{\left( i_1,j,m_{i_1j}\right)}}
$$
has no solution; otherwise, the system
$$
\left(A-\lambda_{i_1}I\right)y=v^{\left( i_1,j,m_{i_1j}\right)}
$$
would have the solution $y =\overline{x}$.

By exchanging the role of $\lambda_{i_1}$ and $\lambda_{i_2}=\overline{\lambda_{i_1}}$, i.e. we consider $\lambda_{i_2}$ and $\overline{\lambda_{i_2}}$, we also see that given a Jordan chain 
\begin{equation*}
	\left(u^{\left( i_2,j,k\right)}\right)_{k=1,\ldots,m_{i_2j}} 
\end{equation*}
corresponding to the eigenvalue $\lambda_{i_2}$, 
\begin{equation*}
	\left(\overline{u^{\left( i_2,j,k\right) }}\right)_{k=1,\ldots,m_{i_2j}}
\end{equation*}
is a Jordan chain corresponding to the eigenvalue $\lambda_{i_1}=\overline{\lambda_{i_2}}$. This shows that the Jordan chains corresponding to $\lambda_{i_2}=\overline{\lambda_{i_1}}$ are all of type (\ref{chains2}). This implies (\ref{R2}). By collecting all the Jordan chains (\ref{chains2}) corresponding to $\lambda_{i_1}$, we obtain a Jordan
basis satisfying  (\ref{R3}).

The result about a real eigenvalue $\lambda_i$ follows from the next
two facts:

\begin{itemize}
\item the eigenspace of $\lambda_i$ in $\mathbb{C}^n$ has a basis of real
eigenvalues;

\item if $v^{(i,j,k)}$ is real and the linear system 
\begin{equation*}
(A-\lambda_iI)x=v^{(i,j,k)}
\end{equation*}
has a solution in $\mathbb{C}^n$, then it also has a solution in $\mathbb{R}%
^n$.
\end{itemize}
Thus, we can have Jordan chains corresponding to $\lambda_i$ constituted by real
generalized eigenvectors.
\end{proof}
In the following, in case of a real matrix $A$, we assume to have a Jordan
basis as that described in the previous proposition.

\subsection{The matrices $V^{(i)}$, $W^{(i)}$, $N^{(i,l)}$ and the vector $\alpha^{(i)}(u)$}

The formula of our interest for the matrix exponential $\mathrm{e}^{tA}$ is constructed by using the matrices $V^{(i)}$, $W^{(i)}$ and $N^{(i,l)}$ now introduced. Here,  $i\in\{1,\ldots,p\}$ and  $l\in\{0,\ldots,m_{i}-1\}$ (remind that $m_i$ is the ascent of $\lambda_i$ defined in (\ref{ascent})). We also introduce the vector $\alpha^{(i)}(u)$ of components of $u$ in the Jordan basis.

Remind that $V$ is the matrix whose columns (\ref{JB}) constitute a Jordan basis.

\begin{itemize}
\item For $i\in\{1,\ldots ,p\}$ and  $j\in\{1,\ldots ,d_{i}\}$, let
\begin{equation*}
	V^{(i,j)}:=\left[ v^{(i,j,1)}\ \cdots \ v^{(i,j,m_{ij})}\right] \in \mathbb{C%
	}^{n\times m_{ij}}
\end{equation*}
and let
\begin{equation}
V^{(i)}:=\left[ V^{(i,1)}\ \cdots \ V^{(i,d_{i})}\right] \in \mathbb{C}%
^{n\times \nu _{i}}.  \label{this1}
\end{equation}%
Observe that
\begin{equation*}
	V=\left[ V^{(1)}\ \cdots \ V^{(p)}\right].
	\end{equation*}

\item Let $W=V^{-1}$ and let 
\begin{equation}
w^{\left( i,j,k\right) },\ i\in\{1,\ldots ,p\},\ j\in\{1,\ldots ,d_{i}\}\text{\ and\ }%
k\in\{1,\ldots ,m_{ij}\},  \label{ws}
\end{equation}
be the rows of $W$ in the three-index notation. The $n$ row vectors in (\ref{ws}) are called \emph{left generalized eigenvectors} of $A$, whereas, as we have already seen, the $n$  columns vectors in (\ref{JB}) are called \emph{(right) generalized eigenvectors} of $A$. For $i\in\{1,\ldots ,p\}$ and $j\in\{1,\ldots ,d_{i}\}$, let
\begin{equation*}
	W^{(i,j)}:=\left[ 
	\begin{array}{c}
		w^{(i,j,1)} \\ 
		\vdots \\ 
		w^{(i,j,m_{ij})}%
	\end{array}%
	\right] \in \mathbb{C}^{m_{ij}\times n}
\end{equation*}
and let 
\begin{equation}
W^{(i)}:=\left[ 
\begin{array}{c}
W^{(i,1)} \\ 
\vdots \\ 
W^{(i,d_{i})}%
\end{array}%
\right] \in \mathbb{C}^{\nu _{i}\times n}.  \label{this}
\end{equation}%
Observe that
\begin{equation*}
	W=\left[ 
	\begin{array}{c}
		W^{(1)} \\ 
		\vdots \\ 
		W^{(p)}%
	\end{array}%
	\right].
\end{equation*}




\item For $u\in\mathbb{C}^n$, let 
\begin{equation*}
\alpha(u):=Wu.
\end{equation*}
Observe that $\alpha(u)$ is the vector of the components of $u$ in the
Jordan basis. In the three-index notation, the components of $\alpha(u)$
are 
\begin{equation*}
\alpha_{ijk}(u),\ i\in\{1,\ldots ,p\},\ j\in\{1,\ldots ,d_{i}\}\text{\ and\ }k\in\{1,\ldots
,m_{ij}\}.
\end{equation*}
$\alpha_{ijk}(u)$ is the component of $u$ along $v^{(i,j,k)}$.
For $i\in\{1,\ldots ,p\}$ and $j\in\{1,\ldots ,d_{i}\}$, let
\begin{equation*}
	\alpha^{(i,j)}(u):=\left[ 
	\begin{array}{c}
		\alpha_{ij1}(u) \\ 
		\vdots \\ 
		\alpha_{ijm_{ij}}(u)%
	\end{array}%
	\right] \in \mathbb{C}^{m_{ij}}.  \label{this3}
\end{equation*}
and let 
\begin{equation*}
\alpha^{(i)}(u):=\left[ 
\begin{array}{c}
\alpha^{(i,1)}(u) \\ 
\vdots \\ 
\alpha^{(i,d_{i})}(u)%
\end{array}%
\right] \in \mathbb{C}^{\nu _{i}}. \label{this2}
\end{equation*}%
Observe that
\begin{equation*}
	\alpha(u):=\left[ 
	\begin{array}{c}
		\alpha^{(1)}(u) \\ 
		\vdots \\ 
		\alpha^{(p)}(u)%
	\end{array}%
	\right].
\end{equation*}

\item For $i\in\{1,\ldots,p\}$, $l\in\{0,\ldots,m_{i}-1\}$ and $j\in\{1,\ldots,d_{i}\}$, let 
\begin{equation}
N^{(i,l,j)}:=\left\{
\begin{array}{l}
\left[ 
\begin{array}{ccccccc}
0 & . & 0 & 1 & 0 & . & 0 \\ 
& . & . & . & . & . & . \\ 
&  & . & . & . & . & 0 \\ 
&  &  & . & . & . & 1 \\ 
&  &  &  & . & . & 0 \\ 
&  &  &  &  & . & . \\ 
&  &  &  &  &  & 0%
\end{array}%
\right] \in \mathbb{C}^{m_{ij}\times m_{ij}}\text{ if }l\leq m_{ij}-1\\
\\
0\in \mathbb{C}^{m_{ij}\times m_{ij}}\text{ if }m_{ij}\leq
l\leq m_i-1,
\end{array}
\right.
\label{DA}
\end{equation}%
where the upper diagonal of elements equal to $1$ is the $l$-th upper
diagonal.
For $i\in\{1,\ldots,p\}$ and $l\in\{0,\ldots,m_i-1\}$, let 
\begin{equation}
N^{(i,l)}:=\mathrm{diag}\left( N^{(i,l,1)},\ldots
,N^{(i,l,d_i)}\right) \in \mathbb{C}^{\nu _{i}\times \nu _{i}}.  \label{A}
\end{equation}%
Observe that the matrix $N^{(i,l)}$ has the same dimensions $\nu
_{i}\times \nu _{i}$ of the Jordan block $J^{(i)}=\mathrm{diag}\left(
J^{(i,1)},\ldots ,J^{(i,d_{i})}\right) $ and the diagonal blocks $%
N^{(i,l,1)},$ $\ldots,$\ $N^{(i,l,d_{i})}$ have the same
dimensions of the Jordan mini-blocks $J^{(i,1)},\ldots ,$ $J^{(i,d_{i})}$, respectively. Thus, as it is illustrated in Figure \ref{matrixN}, the matrix $N^{(i,l)}$ has $1$ in the intersection of the $l$-th upper diagonal with the (frame of the) Jordan mini-blocks and $0$ in all the other
places.
\end{itemize}

