\subsubsection{The matrix $z A$}


When we replace $A$ by $z A$, $z\in\mathbb{C}\setminus\{0\}$, the number and the
dimensions of blocks and mini-blocks remain the same (remind Proposition \ref%
{Vfor-A}). Moreover, a Jordan basis for $z A$ is given in (\ref{vv}). Therefore, we know how it is transformed the matrix $V$ by replacing $A$ by $z A$. The next proposition says this and, in addition, how it is transformed the matrix $W=V^{-1}$.

\begin{proposition}
\label{PropWfor-A} 
Let $z\in\mathbb{C}\setminus\{0\}$. The matrix $V(zA)$
corresponding to $z A$ has columns 
\begin{equation}
	z^{-(k-1)}v^{\left( i,j,k\right) },\ i\in\{1,\ldots ,p\},\ j\in\{1,\ldots ,d_{i}\}
	\text{\ and\ }k\in\{1,\ldots ,m_{ij}\},  \label{w-11}
\end{equation}
and the matrix $W(zA)$
corresponding to $z A$ has rows 
\begin{equation}
z^{k-1}w^{\left( i,j,k\right) },\ i\in\{1,\ldots ,p\},\ j\in\{1,\ldots ,d_{i}\}
\text{\ and\ }k\in\{1,\ldots ,m_{ij}\}.  \label{w-1}
\end{equation}
\end{proposition}

\begin{proof}
The columns of the matrix $V(zA)$ are given in (\ref{vv}). For $i_1,i_2\in\{1,\ldots,p\}$, $j_1\in\{1,\ldots ,d_{i_1}\}$, $j_2\in\{1,\ldots ,d_{i_2}\}$, $k_1\in\{1,\ldots ,m_{i_1j_1}\}$ and $k_2\in\{1,\ldots ,m_{i_2j_2}\}$, we have 
\begin{equation*}
z^{k_1-1}w^{\left( i_1,j_1,k_1\right) }z^{-(k_2-1)}v^{\left(
i_2,j_2,k_2\right) }=\left\{ 
\begin{array}{l}
1\ \ \text{if}\ \ (i_1,j_1,k_1)=(i_2,j_2,k_2) \\ 
0\ \ \text{otherwise}%
\end{array}
\right.
\end{equation*}
since $W$, whose rows are (\ref{ws}), is the inverse of $V$, whose columns are (\ref{JB}). This shows that the matrix of rows (\ref{w-1}) is the inverse of the matrix of columns (\ref{w-11}).
\end{proof}

\subsubsection{The real case}

The next proposition describes, when the matrix $A$ and the vector $u$ are
real, the matrices $V^{(i)}$ and $W^{(i)}$ and the vector $\alpha^{(i)}(u)$
in terms of the real eigenvalues and the complex
conjugate pairs of eigenvalues of $A$.

\begin{proposition}
\label{conjVW} Assume $A\in\mathbb{R}^{n\times n}$ and $u\in\mathbb{R}^n$. Moreover, assume to have a Jordan basis as that described in Proposition \ref{Prop22}.

For $i\in\{1,\ldots,p\}$ such that $\lambda_i\in\mathbb{R}$, we have 
\begin{equation*}
V^{(i)}\in\mathbb{R}^{n\times\nu_i},\ W^{(i)}\in\mathbb{R}^{\nu_i\times n}%
\text{\ \ and\ \ }\alpha^{(i)}(u)\in\mathbb{R}^{\nu_i}.
\end{equation*}

For $i_1,i_2\in\{1,\ldots,p\}$ with $i_1\neq i_2$ such that $\lambda_{i_2}=%
\overline{\lambda_{i_1}}$, we have 
\begin{equation*}
V^{(i_2)}=\overline{V^{(i_1)}},\ W^{(i_2)}=\overline{W^{(i_1)}}\text{\ \
and\ \ }\alpha^{(i_2)}(u)=\overline{\alpha^{(i_1)}(u)}.
\end{equation*}
\end{proposition}

\begin{proof}
Since we are assuming to have a Jordan basis as that described in
Proposition \ref{Prop22}, we have $V^{(i)}\in\mathbb{R}^{n\times\nu_i}$ for  $i\in\{1,\ldots,p\}$ such that $\lambda_i\in\mathbb{R}$ and  $V^{(i_2)}=\overline{V^{(i_1)}}$ for $i_1,i_2\in\{1,\ldots,p\}$ with $i_1\neq i_2$ such that $\lambda_{i_2}=%
\overline{\lambda_{i_1}}$.

Now, we prove that for $i\in\{1,\ldots,p\}$ such that $\lambda_i\in\mathbb{R}$ we have $\alpha^{(i)}(u)\in\mathbb{R}$, and for $i_{1},i_{2}\in\{1,\ldots ,p\}$ such that $\lambda
_{i_{2}}=\overline{\lambda _{i_{1}}}$ with $\mathrm{Im}\left(\lambda_i\right)>0$ we have $\alpha ^{(i_{2})}(u)=%
\overline{\alpha ^{(i_{1})}(u)}$. By conjugating both sides of 
\begin{equation*}
u=V\alpha (u)=\sum\limits_{i=1}^{p}V^{(i)}\alpha ^{(i)}(u),
\end{equation*}%
we obtain 
\begin{equation*}
u=\sum\limits_{i=1}^{p}\overline{V^{(i)}}\ \overline{\alpha ^{(i)}(u)}.
\end{equation*}
So, by separating real eigenvalues and complex conjugate pairs of eigenvalues, we have%
\begin{equation*}
u=\sum\limits_{i=1}^{p}V^{(i)}\alpha ^{(i)}(u)=\sum\limits_{\lambda _{i}\in \mathbb{R}}V^{(i)}\alpha
^{(i)}(u)+\sum\limits _{\substack{ \lambda _{i_{1}}\in \mathbb{C}  \\ 
\mathrm{Im}\left( \lambda _{i_{1}}\right) >0}}\left( V^{(i_{1})}\alpha
^{(i_{1})}(u)+V^{(i_{2})}\alpha ^{(i_{2})}(u)\right),
\end{equation*}%
as well as%
\begin{equation*}
u=\sum\limits_{i=1}^{p}\overline{V^{(i)}}\ \ \overline{\alpha ^{(i)}(u)}%
=\sum\limits_{\lambda _{i}\in \mathbb{R}}V^{(i)}\ \overline{\alpha ^{(i)}(u)}%
+\sum\limits_{\substack{ \lambda _{i_{1}}\in \mathbb{C}  \\ \mathrm{Im}%
\left( \lambda _{i_{1}}\right) >0}}\left( V^{(i_{2})}\overline{\alpha
^{(i_{1})}(u)}+V^{(i_{1})}\overline{\alpha ^{(i_{2})}(u)}\right)
\end{equation*}%
by reminding that $V^{(i)}\in\mathbb{R}^{n\times \nu_i}$ for $\lambda_i\in\mathbb{R}$ and $V^{(i_{2})}=\overline{V^{(i_{1})}}$ for $\lambda_{i_1}\in\mathbb{C}$ with $\mathrm{Im}\left(\lambda_i\right)>0$. Since $u$ can be expressed as a linear combination of the Jordan
basis in a unique manner, we obtain $\alpha ^{(i)}(u)=\overline{\alpha
	^{(i)}(u)}$, i.e. $\alpha^{(i)}(u)\in\mathbb{R}$, for $\lambda_{i}\in\mathbb{R}$ and $\alpha ^{(i_{2})}(u)=\overline{\alpha
^{(i_{1})}(u)}$ for $\lambda _{i_{1}}\in\mathbb{C}$ with $\mathrm{Im}%
\left( \lambda _{i_{1}}\right) >0$.

Finally, we show that, for $i_{1},i_{2}\in\{1,\ldots ,p\}$ such that $\lambda
_{i_{2}}=\overline{\lambda _{i_{1}}}$, we have $W^{(i_{2})}=\overline{%
W^{(i_{1})}}$. This includes the case $i_{1}=i_{2}$ and $\lambda _{i_{1}}\in 
\mathbb{R}$, for which we can conclude that $W^{(i_{1})}$ is a real matrix. We have, with $e^{\left( 1\right)},\ldots,e^{\left(
n\right)} $ the real vectors of the canonical basis of $\mathbb{C}^n$, 
\begin{eqnarray*}
W^{(i_{2})} &=&W^{(i_{2})}\left[ e^{\left( 1\right) }\ \cdots\ e^{\left(
n\right) }\right] =\left[ \alpha ^{\left( i_{2}\right) }\left( e^{\left(
1\right) }\right) \ \cdots\ \alpha ^{\left( i_{2}\right) }\left(
e^{(n)}\right) \right] \\
&=&\left[ \overline{\alpha ^{\left( i_{1}\right) }\left( e^{\left( 1\right)
	}\right)} \ \cdots \ \overline{\alpha ^{\left( i_{1}\right) }\left( e^{(n)}\right)} \right]=\overline{\left[ \alpha ^{\left( i_{1}\right) }\left( e^{\left( 1\right)
}\right) \ \cdots \ \alpha ^{\left( i_{1}\right) }\left( e^{(n)}\right) \right]
}\\
&=&\overline{W^{(i_{1})}\left[ e^{\left( 1\right) }\ \cdots \ e^{\left(
n\right) }\right] }=\overline{W^{(i_{1})}}.
\end{eqnarray*}
\end{proof}

\subsection{The formula for $\mathrm{e}^{tA}$}

Next proposition provides the announced formula for the matrix exponential $\mathrm{e}%
^{tA}$. For taste of generality, we consider the general situation of a
function of matrix $f(A)$, where $f(z)$, $z\in\mathcal{D}\subseteq \mathbb{C}$,
is an analytic complex function of $z$. The domain $\mathcal{D}$ of $f$ is an open subset of $\mathbb{C}$ and we assume that the eigenvalues $\lambda_1,\ldots,\lambda_p$ of $A$ are contained in $\mathcal{D}$.


\begin{proposition}
\label{matrixexponential} \label{one} We have 
\begin{equation}
f(A)=\sum\limits_{i=1}^{p}\sum\limits_{l=0}^{m_{i}-1}\frac{f^{(l)}(\lambda_i)%
}{l!}P_{il},  \label{f(A)}
\end{equation}%
where, for $i\in\{1,\ldots ,p\}$ and $l\in\{0,\ldots,m_{i}-1\}$, 
\begin{equation}
P_{il}:=V^{\left( i\right) }N^{(i,l)}W^{\left( i\right) }\in\mathbb{C}%
^{n\times n}  \label{Pil}
\end{equation}%
with $V^{\left( i\right) }$, $W^{\left( i\right) }$ and $N^{(i,l)}$
defined in (\ref{this1}), (\ref{this}) and (\ref{A}), respectively.
\end{proposition}
\begin{proof}
By recalling the definition of function of matrix by the JCF (see, e.g., \cite%
{Higham2008}), we have 
\begin{equation}
f(A)=Vf(J)W=\sum\limits_{i=1}^{p}V^{\left( i\right) }f(J^{(i)})W^{\left(
i\right) },  \label{exp0}
\end{equation}%
where
\begin{equation}
	f\left(J\right)=\mathrm{diag}\left( f\left(J^{(1)}\right),\ldots
	,f\left(J^{(p)}\right)\right) \in \mathbb{C}^{n\times n}\notag  %\label{gamma}
\end{equation}
and 
\begin{equation}
f\left(J^{(i)}\right)=\mathrm{diag}\left( f\left(J^{(i,1)}\right),\ldots
,f\left(J^{(i,d_i)}\right)\right) \in \mathbb{C}^{\nu _{i}\times \nu _{i}},\
i\in\{1,\ldots,p\},  \notag  %\label{gamma}
\end{equation}%
with 
\begin{eqnarray*}
&&f\left(J^{(i,j)}\right):=\left[ 
\begin{array}{ccccc}
f(\lambda_i) & f^\prime(\lambda_i) & \frac{f^{\prime\prime}(\lambda_i)}{2} & 
\cdots & \frac{f^{(m_{ij}-1)}(\lambda_i)}{\left( m_{ij}-1\right) !} \\ 
& . & . & . & \vdots \\ 
&  & . & . & \frac{f^{\prime\prime}(\lambda_i)}{2} \\ 
&  &  & . & f^\prime(\lambda_i) \\ 
&  &  &  & f(\lambda_i)%
\end{array}%
\right] \in \mathbb{C}^{m_{ij}\times m_{ij}} \\
&&j\in\{1,\ldots,d_i\}.
\end{eqnarray*}
We can write 
\begin{equation*}
f\left(J^{(i,j)}\right)=\sum\limits_{l=0}^{m_{ij}-1}\frac{f^{(l)}(\lambda_i)%
}{l!}N^{(i,l,j)}=\sum\limits_{l=0}^{m_{i}-1}\frac{f^{(l)}(\lambda_i)%
}{l!}N^{(i,l,j)},
\end{equation*}%
where the matrices $N^{(i,l,j)}$, $l\in\{0,\ldots ,m_{i}-1\}$, are defined in (\ref%
{DA}).

We conclude that, for\ $i\in\{1,\ldots,p\}$, we have 
\begin{eqnarray*}
f\left(J^{(i)}\right)&=&\mathrm{diag}\left( \sum\limits_{l=0}^{m_{i}-1}\frac{%
f^{(l)}(\lambda_i)}{l!}N^{(i,l,1)},\ldots ,\sum\limits_{l=0}^{m_{i}-1}\frac{%
f^{(l)}(\lambda_i)}{l!}N^{(i,l,d_{i})}\right) \\
&=&\sum\limits_{l=0}^{m_{i}-1}\frac{f^{(l)}(\lambda_i)}{l!}N^{(i,l)}.
\end{eqnarray*}%
Now (\ref{f(A)}) follows by (\ref{exp0}).
\end{proof}


For the case $f(A)=\mathrm{e}^{tA}$ of our interest, formula (\ref{f(A)}) becomes 
\begin{equation}
\mathrm{e}^{tA}=\sum\limits_{i=1}^{p}\mathrm{e}^{\lambda
_{i}t}\sum\limits_{l=0}^{m_{i}-1}\frac{t^{l}}{l!}P_{il}.  \label{etA}
\end{equation}

\subsubsection{The matrices $P_{i0}$}  \label{matricesPi00}

For $i\in\{1,\ldots,p\}$, since $N^{(i,0)}=I_n$, we have
\begin{equation}
P_{i0}=V^{\left( i\right) }W^{\left( i\right) }=\sum\limits_{j=1}^{d_i}\sum\limits_{k=1}^{m_{ij}}v^{(i,j,k)}w^{(i,j,k)}. \label{Pi0}
\end{equation}

The matrix $P_{i0}$ is the projection onto the generalized eigenspace corresponding to the eigenvalue $\lambda _{i}$, i.e. the subspace spanned by the generalized eigenvectors corresponding to the eigenvalue $\lambda_i$. In fact, we have, for $u\in\mathbb{C}^n$,
$$
P_{i0}u=V^{\left( i\right) }W^{\left( i\right) }u=V^{\left( i\right) }\alpha^{\left( i\right) }(u)=\sum\limits_{j=1}^{d_i}\sum\limits_{k=1}^{m_{ij}}\alpha_{ijk}(u)v^{(i,j,k)}.
$$

\subsubsection{The case $A$ diagonalizable}

When $A$ is diagonalizable, the formula (\ref{f(A)}) simplifies to the well-known formula
\begin{equation}
f(A)=\sum\limits_{i=1}^{p}f(\lambda _{i})P_{i0}.  \label{fdiag}
\end{equation}
where, for $i\in\{1,\ldots,p\}$,
\begin{equation*}
P_{i0}=\sum\limits_{j=1}^{d_i}v^{(i,j,1)}w^{(i,j,1)}.
\end{equation*}
In this case of $A$ diagonalizable, the matrix $P_{i0}$ is the projection onto the eigenspace corresponding to the eigenvalue $\lambda _{i}$, i.e. the subspace spanned by the eigenvectors corresponding to the  eigenvalue $\lambda_i$.

For the case $f(A)=\mathrm{e}^{tA}$ of our interest, formula (\ref{fdiag}) becomes
\begin{equation*}
\mathrm{e}^{tA}=\sum\limits_{i=1}^{p}\mathrm{e}^{\lambda _{i}t}P_{i0}.
\label{etAdiag}
\end{equation*}


\subsection{The matrices $P_{il}$} \label{matricesPi0}

In this subsection, we see some properties of the matrices $P_{il}$
defined in (\ref{Pil}).

\subsubsection{An alternative expression for $P_{il}$}

Next proposition gives an alternative expression for $P_{il}$, more informative than the definition (\ref{Pil}).

\begin{proposition}  \label{lastexample}
For $i\in\{1,\ldots,p\}$ and $l\in\{0,\ldots,m_i-1\}$, we have 
\begin{equation}
P_{il}=\sum\limits
_{\substack{ j=1  \\ m_{ij}\geq l+1}}^{d_{i}}\sum\limits_{k=1}^{m_{ij}-l}v^{%
\left( i,j,k\right) }w^{\left( i,j,l+k\right) }.  \label{Pil=}
\end{equation}
Moreover, for $u\in\mathbb{C}^n$, we have
\begin{equation}
P_{il}u=\sum\limits
_{\substack{ j=1  \\ m_{ij}\geq l+1}}^{d_{i}}\sum\limits_{k=1}^{m_{ij}-l}\alpha_{ij\,l+k}(u)v^{%
\left( i,j,k\right) }.  \label{Pilu=}
\end{equation}
\end{proposition}

	The indeces $j$ in the outer sum
$$
\sum\limits
_{\substack{ j=1  \\ m_{ij}\geq l+1}}^{d_{i}}
$$
in (\ref{Pil=}) and (\ref{Pilu=}) are the indeces $j$ of the mini-blocks $J^{(i,j)}$ of $J^{(i)}$ having the $l$-th upper diagonal. The indeces $k$ in the inner sum 
$$
\sum\limits_{k=1}^{m_{ij}-l}
$$
are the row indeces of the elements of the mini-block $J^{(i,j)}$ on this $l$-th upper diagonal (see Figure \ref{Pil==}). The column indeces $l+k$ of these elements appear as third indeces in $w^{(i,j,l+k)}$ in (\ref{Pil=}) and  $\alpha_{ij\,l+k}(u)$ in (\ref{Pilu=}).  In other words, with reference to the previous Figure \ref{matrixN}, in the double sum in (\ref{Pil=}) and (\ref{Pilu=}) we are summing over all elements in the intersection of the $l$-th diagonal of $N^{(i,l)}$ with the mini-blocks: the three-index notation $(i,j,k)$ of the row of these elements appears in $v^{(i,j,k)}$ and the three-index notation $(i,j,l+k)$ of the columns appears in $w^{(i,j,l+k)}$ for  (\ref{Pil=}) and  in $\alpha_{ijl+k}(u)$ for (\ref{Pilu=}).

\begin{proof}
As for (\ref{Pil=}), by the definition (\ref{Pil}) we have
\begin{eqnarray*}
P_{il}&=&\sum\limits_{j=1}^{d_{i}}V^{%
\left( i,j\right) }N^{(i,l,j)}W^{\left( i,j\right) }\\
&=&\sum\limits_{\substack{ j=1  \\ m_{ij}\geq l+1}}^{d_{i}}V^{\left( i,j\right) }N^{(i,l,j)}W^{\left( i,j\right)}\\
&=&\sum\limits
_{\substack{ j=1  \\ m_{ij}\geq l+1}}^{d_{i}}\sum\limits_{k=1}^{m_{ij}-l}v^{%
\left( i,j,k\right) }w^{\left( i,j,l+k\right) }
\end{eqnarray*}
by reminding the form (\ref{DA}) of $N^{(i,l,j)}$.


As for (\ref{Pilu=}), we have
\begin{equation*}
P_{il}u=\sum\limits
_{\substack{ j=1  \\ m_{ij}\geq l+1}}^{d_{i}}\sum\limits_{k=1}^{m_{ij}-l}v^{%
\left( i,j,k\right) }\underset{=\alpha_{ij\,l+k}(u)}{\underbrace{w^{\left( i,j,l+k\right) }u}}.
\end{equation*}


\end{proof}

\begin{figure}[tbp]
\includegraphics[width=0.8\textwidth]{alphaAPil.png}
\caption{Indeces $j$ and $k$ in (\ref{Pil=}) and (\ref{Pilu=}): $j$ is an index of mini-blocks $J^{(i,j)}$ of $J^{(i)}$ having the $l$-th upper diagonal and $k$ is an index of row of elements in the $l$-th upper diagonal.}
\label{Pil==} 
\end{figure}



\begin{remark}\label{mi}
	\quad
	\begin{itemize}



		\item [1.] For $l=0$, formula (\ref{Pil=}) reduces to formula (\ref{Pi0}).
		\item[2.] If there exists an unique $j\in\{1,\ldots,d_i\}$ such that $m_i=m_{ij}$, then
\begin{equation*}
P_{i\,m_i-1}=v^{%
\left( i,j,1\right) }w^{\left( i,j,m_i\right) }
\end{equation*}
and, for $u\in\mathbb{C}^n$, 
\begin{equation*}
P_{i\,m_i-1}u=\alpha_{ijm_{i}}(u)v^{%
\left( i,j,1\right) }.
\end{equation*}
\item [3.] As we can see in (\ref{Pilu=}), $P_{il}u$ is not the projection of $u$ onto the subspace spanned by the vectors
$$
v^{(i,j,k)},\ j\in\{1,\ldots,d_i\}\text{\ with \ }m_{ij}\ge l+1\text{\ and\ }k\in\{1,\ldots,m_{ij}-l\},
$$
since these vectors are multiplied by coefficients different from the corresponding components $\alpha_{ijk}(u)$. The coefficients are the components $\alpha_{ijl+k}(u)$ shifted by $l$ in the third index.
\end{itemize}

\end{remark}

\subsubsection{The matrix $z A$}

The next proposition shows how the matrices $P_{il}$ are transformed when the matrix $A$ is replaced by $z A$, $z\in\mathbb{C}\setminus\{0\}$.
Observe that, when $A$ is replaced by $z A$, the number and the
dimensions of blocks and mini-blocks remain the same (remind Proposition \ref%
{Vfor-A}). Thus, the indeces $i$ and $l$ for the matrices $P_{il}(zA)$ corresponding to $z A$ are the same indeces $i\in\{1,\ldots,p\}$ and $l\in\{0,\ldots,m_i-1\}$ for the matrices $P_{il}$ corresponding to $A$.

\begin{proposition}\label{PropalphalPil}
Let $z\in\mathbb{C}\setminus\{0\}$. We have 
\begin{equation*}
P_{il}(zA)=z^{l}P_{il},\ i\in\{1,\ldots,p\}\text{\ and\ }l\in\{0,\ldots,m_{i}-1\}.  \label{alphalPil}
\end{equation*}
\end{proposition}

\begin{proof}
The columns of the matrix $V(zA)$ corresponding to $z A$ are given in (\ref{w-11}) and the rows of the matrix $W(zA)$ corresponding to $z A$ are given in (\ref{w-1}). Now, use the formula (\ref{Pil=}). 
\end{proof}
\subsubsection{The real case}

The next proposition describes the matrices $P_{il}$, when $A$ is real, in terms of real eigenvalues and complex conjugate pairs of eigenvalues of $A$.


\begin{proposition}
\label{complex} Assume $A\in\mathbb{R}^{n\times n}$.  Moreover, assume to have a Jordan basis as that described in Proposition \ref{Prop22}.

For $i\in\{1,\ldots ,p\}$ such that $\lambda _i\in\mathbb{R}$, we have%
\begin{equation*}
P_{il}\in\mathbb{R}^{n\times n},\ l\in\{0,\ldots,m_i-1\}.
\end{equation*}

For $i_{1},i_{2}\in\{1,\ldots ,p\}$ with $i_1\neq i_2$ such that $\lambda _{i_{2}}=%
\overline{\lambda _{i_{1}}}$, we have%
\begin{equation*}
P_{i_{2}l}=\overline{P_{i_{1}l}},\ l\in\{0,\ldots ,m_{i_2}-1\}.
\end{equation*}
Observe that $m_{i_2}=m_{i_1}$ holds by Proposition \ref{Prop22}.
\end{proposition}
\begin{proof}
We prove that, for $i_{1},i_{2}\in\{1,\ldots ,p\}$ such that $\lambda _{i_{2}}=%
\overline{\lambda _{i_{1}}}$, we have%
\begin{equation*}
P_{i_{2}l}=\overline{P_{i_{1}l}},\ l\in\{0,\ldots ,m_{i_2}-1\}.
\end{equation*}
This includes the case $i_1=i_2$ and $\lambda_{i_1}\in\mathbb{R}$, for which
we can conclude that $P_{i_1l}$, $%
l\in\{0,\ldots,m_{i_1}-1\} $, is a real matrix.

Since (see Proposition \ref{Prop22})
\begin{equation*}
d_{i_{2}}=d_{i_{1}}\text{\ and\ }m_{i_{2}j}=m_{i_{1}j},\ j\in\{1,\ldots ,d_{i_{1}}\},\text{\ and\ }m_{i_2}=m_{i_1}
\end{equation*}%
we obtain,  for $l\in\{0,\ldots,m_{i_2}-1\}$, 
\begin{equation*}
N^{(i_{2},l)}=N^{(i_{1},l)}
\end{equation*}%
and then (see Proposition \ref{conjVW}) 
\begin{equation*}
P_{i_{2}l}=V^{\left( i_{2}\right) }N^{(i_{2},l)}W^{\left( i_{2}\right)
} =\overline{V^{\left( i_{1}\right) }}N^{(i_{1},l)}\overline{W
^{\left( i_{1}\right) }}=\overline{V^{\left( i_{1}\right) }N^{(i_{1},l)}W^{\left( i_{1}\right) }} =\overline{P_{i_{1}l}}.
\end{equation*}

\end{proof}

\subsubsection{The kernel of the matrices $P_{il}$}

Next three propositions concern the kernel of the matrices $P_{il}$. The first proposition describes this kernel.

\begin{proposition}\label{eleven}
\label{Prop1} For $i\in\{1,\ldots ,p\}$ and $l\in\{0,\ldots ,m_{i}-1\}$, we have%
\begin{eqnarray*}
&&\mathrm{ker}\left(P_{il}\right)=\left\{u\in\mathbb{C}^n:\alpha_{ijk}(u)=0\ 
\text{for all }j\in\{1,\ldots ,d_{i}\}\ \text{with $m_{ij}\geq l+1$}\right. \\
&&\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \left.\ \text{and for
all }k\in\{l+1,\ldots ,m_{ij}\}\right\}.
\end{eqnarray*}
\end{proposition}
In other words, with reference to the previous Figure \ref{matrixN}, the proposition says that the kernel of $P_{il}$ is constituted by the vectors $u\in\mathbb{C}^n$ with zero component along all the generalized eigenvectors $v^{(i,j,k)}$ whose third index $k$ (in the three-index notation) is an index column of elements in the intersection of $l$-th diagonal  with mini-blocks.     
\begin{proof}
For $u\in\mathbb{C}^n$, we have 
\begin{eqnarray*}
P_{il}u=0 &\Leftrightarrow &V^{\left( i\right) }N^{(i,l)}\alpha
^{\left( i\right) }\left( u\right) =0 \\
&\Leftrightarrow &N^{(i,l)}\alpha ^{\left( i\right) }\left( u\right) =0
\\
&&\text{by the linear independence of the vectors $v^{(i,j,k)}$ in (\ref{JB})}\\
&\Leftrightarrow &N^{(i,l,j)}\alpha ^{\left( i,j\right) }\left( u\right) =0\ 
\text{for\ all\ }j=1,\ldots ,d_{i}, \\
&\Leftrightarrow &\alpha _{ijk}\left( u\right) =0\ \text{for\ all }%
j\in\{1,\ldots ,d_{i}\}\ \text{with $m_{ij}\geq l+1$} \\
&& \text{\ and\ for all\ }k\in\{l+1,\ldots ,m_{ij}\}.
\end{eqnarray*}
\end{proof}
Next two propositions are immediate consequences of the previous proposition.
\begin{proposition}
\label{Prop2A} For $i\in\{1,\ldots ,p\}$ and $l_{1},l_{2}\in\{0,\ldots ,m_{i}-1\}$, with $%
l_{1}<l_{2}$, we have%
\begin{equation*}
\mathrm{ker}\left(P_{il_{1}}\right)\subseteq \mathrm{ker}\left(P_{il_{2}}%
\right).
\end{equation*}
\end{proposition}
\begin{proposition}
\label{Prop3A} For $i\in\{1,\ldots ,p\}$ and $u\in \mathbb{C}^{n}$, we have%
\begin{equation*}
u\in\mathrm{ker}\left(P_{i0}\right)\ \ \Leftrightarrow \ \ \alpha ^{\left(
i\right) }\left( u\right) =0.
\end{equation*}
\end{proposition}
The Proposition \ref{Prop3A} confirms our previous observation in Subsection \ref{matricesPi0} that $P_{i0}$ is the projection on the generalized eigenspace corresponding to $\lambda_i$. 

\subsection{The index $l_i(u)$}

\label{sliu}

In view of the Propositions \ref{Prop2A} and \ref{Prop3A}, for $i\in\{1,\ldots ,p\}$ and $u\in 
\mathbb{C}^{n}$ such that $\alpha^{(i)}(u)\neq 0$, we define the
index 
\begin{equation*}
l_{i}\left( u\right) :=\max \left\{ l\in \left\{ 0,\ldots ,m_{i}-1\right\}
:u\notin \mathrm{ker}\left(P_{il}\right)\right\}  \label{liu}
\end{equation*}
(see Figure \ref{liufigure}).

Indeed, if  $\alpha^{(i)}(u)=0$, then
$$
\left\{ l\in \left\{ 0,\ldots ,m_{i}-1\right\}
:u\notin \mathrm{ker}\left(P_{il}\right)\right\}=\emptyset
$$
by Propositions \ref{Prop2A} and \ref{Prop3A}. In this case, the index $l_i(u)$ cannot be defined. On the other hand,  if  $\alpha^{(i)}(u)\neq 0$, then
$$\left\{ l\in \left\{ 0,\ldots ,m_{i}-1\right\}
:u\notin \mathrm{ker}\left(P_{il}\right)\right\}\neq\emptyset,
$$
since $u\notin \mathrm{ker}(P_{i0})$ by Proposition \ref{Prop3A}. In this case, the index $l_i(u)$ can be defined. By Proposition \ref{Prop2A}, we have
$$
u\notin\mathrm{ker}(P_{il}),\ l\in\{0,\ldots,l_i(u)\},
$$
and
$$
u\in\mathrm{ker}(P_{il}),\ l\in\{l_i(u)+1,\ldots,m_i\}.
$$

Observe that if $\lambda_i$ is a non-defective eigenvalue, i.e. $m_i=0$, then $l_{i}\left(
u\right) =0$.

