\caption{The index $l_i(u)$. $\mathrm{ker}(P_{il})^c$ denotes the
complementary set of $\mathrm{ker}(P_{il})$. We have $\mathrm{ker}\left(P_{i0}\right)^c\supseteq \mathrm{ker}\left(P_{i1}%
\right)^c\supseteq \mathrm{ker}\left(P_{i2}%
\right)^c\supseteq \mathrm{ker}\left(P_{i3}%
\right)^c\supseteq \cdots$. In this case $l_i(u)=2$, since $u\in\mathrm{ker}\left(P_{i2}\right)^c$ but $u\notin\mathrm{ker}\left(P_{i3}\right)^c$.}
\label{liufigure} 
\end{figure}

The following proposition gives $l_{i}\left( u\right) $ in terms of the zero
components of $\alpha ^{\left( i\right) }\left( u\right) $.



\begin{proposition} \label{number14}
\label{propliu} For $i\in\{1,\ldots ,p\}$ and $u\in \mathbb{C}^{n}$ such that $%
\alpha ^{\left( i\right) }\left( u\right) \neq 0$, we have 
\begin{eqnarray}
&&l_{i}\left( u\right)+1\notag\\
&&=\max \left\{ k\in \left\{ 1,\ldots ,m_{i}\right\}
:\alpha _{ijk}\left( u\right) \neq 0\text{ for some }j\in\{1,\ldots,d_{i}\}\text{\ with $m_{ij}\geq k$} \right\}.\notag \\
\label{liu222}
\end{eqnarray}
\end{proposition}
In other words, the proposition says that $l_i(u)+1$ is the maximum index $k$, in a Jordan chain
$$
(v^{(i,j,k)})_{k=1,\ldots,m_{ij}},\ j\in\{1,\ldots,d_i\},
$$
corresponding to the eigenvalue $\lambda_i$, such that $u$ has a non-zero component along the generalized eigenvector $v^{(i,j,k)}$. Alternatively, with reference to Figure \ref{matrixN}, the proposition says that $l_i(u)$ is the maximum index $l$ such that  $u$ has a non-zero component along some generalized eigenvector $v^{(i,j,k)}$ whose third index $k$ is an index column of elements  in the intersection of $l$-th diagonal  with mini-blocks.      



\begin{proof}
The proof is straightforward by recalling the interpretation of the statement of Proposition \ref{number14} from a few lines above, referencing Figure \ref{matrixN}, and the observation about $\mathrm{ker}(P_{il})$, also referencing Figure \ref{matrixN}, immediately following Proposition \ref{eleven}. However, a more formal proof is now presented below.

Suppose $l_{i}\left( u\right) =m_{i}-1$ and then $u\notin\mathrm{ker}%
\left(P_{im_{i}-1}\right)$. By Proposition \ref{Prop1}, there exists $%
\overline{j}\in\{1,\ldots ,d_{i}\}$ such that $m_{i\overline{j}}=m_{i}$ and $%
\alpha _{i\overline{j}m_i}(u)\neq 0$. Thus, we have 
\begin{eqnarray*}
&&m_{i}\\
&&=\max \left\{ k\in \left\{ 1,\ldots ,m_{i}\right\} :\alpha _{ijk}\left(
u\right) \neq 0\text{ for some }j\in\{1,\ldots ,d_{i}\}\text{\ with $m_{ij}\geq k$}%
\right\},
\end{eqnarray*}
i.e. (\ref{liu222}) holds.

Suppose $l_{i}\left( u\right) <m_{i}-1$ and then $u\notin\mathrm{ker}%
\left(P_{il_{i}(u)}\right)$ and $u\in\mathrm{ker}\left(P_{i\,l_{i}(u)+1}%
\right) $. By Proposition \ref{Prop1} and $u\notin\mathrm{ker}%
\left(P_{il_{i}(u)}\right)$, there exist $\overline{j}\in\{1,\ldots ,d_{i}\}$ with 
$m_{i\overline{j}}\geq l_i(u)+1$ and $\overline{k}\in\{l_{i}\left( u\right)
+1,\ldots,m_{i\overline{j}}\}$ such that $\alpha _{i\overline{j}\ \overline{k}%
}\neq 0$. Then
\begin{eqnarray*}
&&l_i(u)+1\\
&&\leq \max \left\{ k\in \left\{ 1,\ldots ,m_{i}\right\} :\alpha _{ijk}\left(
u\right) \neq 0\text{ for some }j\in\{1,\ldots ,d_{i}\}\text{\ with $m_{ij}\geq k$}%
\right\}.
\end{eqnarray*}
On the other hand, by Proposition \ref{Prop1} and $u\in\mathrm{ker}%
\left(P_{i\,l_{i}(u)+1}\right) $, we have $\alpha _{ijk}\left( u\right) =0\ $%
for all $j\in\{1,\ldots ,d_{i}\}$ with $m_{ij} \geq l_i(u)+2$ and for all $k\in\{l_{i}\left(
u\right) +2,\ldots ,m_{ij}\}$. Then 
\begin{eqnarray*}
&&l_i(u)+1\\
&&\geq \max \left\{ k\in \left\{ 1,\ldots ,m_{i}\right\} :\alpha _{ijk}\left(
u\right) \neq 0\text{ for some }j\in\{1,\ldots ,d_{i}\}\text{\ with $m_{ij}\geq k$}%
\right\}.
\end{eqnarray*}
Thus, (\ref{liu222}) holds.
\end{proof}


\subsection{Linear independence}

This subsection deals with the linear independence of the vectors $P_{il}u$
and the matrices $P_{il}$.

\begin{proposition}
\label{PropPilu} \label{Prop} For $u\in\mathbb{C}^n$, the vectors 
\begin{equation}
P_{il}u,\ i\in\{1,\ldots,p\}\text{\ such that $\alpha^{(i)}(u)\neq 0$ and\ }%
l\in\{0,\ldots,l_{i}\left( u\right)\},  \label{Pu}
\end{equation}
are linearly independent in the vector space $\mathbb{C}^n$.
\end{proposition}

\begin{proof}
Consider a zero linear combination of the vectors (\ref{Pu}): 
\begin{equation}
0 =\sum\limits_{\substack{i=1 \\ \alpha^{(i)}(u)\neq 0}}^{p}\sum\limits_{l=0}^{l_{i}\left( u\right)
}c_{il}P_{il}u=\sum\limits_{\substack{i=1 \\ \alpha^{(i)}(u)\neq 0}}^{p}V^{\left( i\right)
}\sum\limits_{l=0}^{l_{i}\left( u\right) }c_{il}N^{(i,l)}\alpha
^{\left( i\right) }\left( u\right),  \label{zlc}
\end{equation}
where the second inequality follows by (\ref{Pil}). Since $V$ has linearly independent columns, we obtain, for $i\in\{1,\ldots,p\}$ such that $\alpha^{(i)}(u)\neq 0$, 
\begin{eqnarray*}
0 &=&\sum\limits_{l=0}^{l_{i}\left( u\right) }c_{il}N^{(i,l)}\alpha
^{\left( i\right) }\left( u\right) =\sum\limits_{l=0}^{l_{i}\left( u\right)
}c_{il}\mathrm{diag}\left( N^{(i,l,1)},\ldots ,N^{(i,l,d_{i})}\right) \alpha
^{\left( i\right) }\left( u\right) \\
&=&\left( \sum\limits_{l=0}^{l_{i}\left( u\right) }c_{il}N^{(i,l,1)}\alpha
^{\left( i,1\right) }\left( u\right) ,\ldots ,\sum\limits_{l=0}^{l_{i}\left(
u\right) }c_{il}N^{(i,l,d_{i})}\alpha ^{\left( i,d_{i}\right) }\left(
u\right) \right)
\end{eqnarray*}%
and then, for $j\in\{1,\ldots,d_i\}$, 
\begin{equation*}
\sum\limits_{l=0}^{l_{i}\left( u\right) }c_{il}N^{(i,l,j)}\alpha ^{\left(
i,j\right) }\left( u\right) =0.
\end{equation*}%


Now, fix $i\in\{1,\ldots,p\}$ such that $\alpha^{(i)}(u)\neq 0$. By Proposition \ref{propliu}, there exists $%
\overline{j}\in\{1,\ldots,d_{i}\}$ with $m_{i%
\overline{j}}\geq l_{i}\left( u\right)+1$  such that $\alpha _{i\overline{j}\,l_{i}\left(
u\right)+1 }\left( u\right) \neq 0$ and $\alpha_{i\overline{j}k}(u)=0$ for $k\in\{l_i(u)+2,\ldots,m_{i%
\overline{j}}\}$. Thus%
\begin{eqnarray*}
&&0=\sum\limits_{l=0}^{l_{i}\left( u\right) }c_{il}N^{(i,l,\overline{j}%
)}\alpha ^{\left( i,\overline{j}\right) }\left( u\right) \\
&&=\left[ 
\begin{array}{ccccccccc}
c_{i0} & c_{i1} & \cdot & c_{il_{i}\left( u\right)-1 } & c_{il_{i}\left(
u\right)} & | & 0 & \cdot & 0 \\ 
0 & c_{i0} & c_{i1} & \cdot & c_{il_{i}\left( u\right)-1 } & | & 
c_{il_{i}\left( u\right) } & \cdot & \cdot \\ 
\cdot & \cdot & \cdot & \cdot & \cdot & | & c_{il_{i}\left( u\right)-1 } & 
\cdot & 0 \\ 
\cdot & \cdot & \cdot & c_{i0} & c_{i1} & | & \cdot & \cdot & 
c_{il_{i}\left( u\right)} \\ 
\cdot & \cdot & \cdot & \cdot & c_{i0} & | & c_{i1} & \cdot & 
c_{il_{i}\left( u\right)-1 } \\ 
- & - & - & - & - &  & - & - & - \\ 
\cdot & \cdot & \cdot & \cdot & \cdot & | & c_{i0} & \cdot & \cdot \\ 
\cdot & \cdot & \cdot & \cdot & \cdot & | & \cdot & \cdot & c_{i1} \\ 
0 & \cdot & \cdot & \cdot & \cdot & | & \cdot & 0 & c_{i0}%
\end{array}%
\right] \left[ 
\begin{array}{c}
\alpha _{i\overline{j}1}\left( u\right) \\ 
\alpha _{i\overline{j}2}\left( u\right) \\ 
\\ 
\cdot \\ 
\alpha _{i\overline{j}l_{i}\left( u\right)}\left( u\right) \\ 
\alpha _{i\overline{j}l_{i}\left( u\right)+1}\left( u\right) \\ 
- \\ 
0 \\ 
\cdot \\ 
0%
\end{array}%
\right]
\end{eqnarray*}
and then 
\begin{eqnarray*}
&&0=\left[ 
\begin{array}{ccccc}
c_{i0} & c_{i1} & \cdot & c_{il_{i}\left( u\right)-1 } & c_{il_{i}\left(
u\right)} \\ 
0 & c_{i0} & c_{i1} & \cdot & c_{il_{i}\left( u\right)-1 } \\ 
\cdot & \cdot & \cdot & \cdot & \cdot \\ 
0 & 0 & \cdot & c_{i0} & c_{i1} \\ 
0 & 0 & \cdot & 0 & c_{i0} \\ 
&  &  &  & 
\end{array}%
\right] \left[ 
\begin{array}{c}
\alpha _{i\overline{j}1}\left( u\right) \\ 
\alpha _{i\overline{j}2}\left( u\right) \\ 
\cdot \\ 
\alpha _{i\overline{j}l_{i}\left( u\right)}\left( u\right) \\ 
\alpha _{i\overline{j}\,l_{i}\left( u\right)+1}\left( u\right) \\ 
