\right].
\end{eqnarray*}


Now, since $\alpha _{i\overline{j}\,l_{i}\left( u\right)+1}\left( u\right)\neq
0$, we obtain $c_{il}=0$ successively for $l=0,1,\ldots,l_{i}\left( u\right) $.

We have proved that the coefficients of the zero linear combination (\ref{zlc}) are all zero. 
\end{proof}

\begin{proposition}
\label{PropPil} The matrices
\begin{equation}
P_{il},\ i\in\{1,\ldots,p\}\text{\ and \ }l\in\{0,\ldots,m_{i}-1\},  \label{P}
\end{equation}
are linearly independent in the vector space $\mathbb{C}^{n\times n}$.
\end{proposition}

\begin{proof}
Consider a zero linear combination of the matrices (\ref{P}): 
\begin{equation*}
0 =\sum\limits_{i=1}^{p}\sum\limits_{l=0}^{m_{i}-1 }c_{il}P_{il}.
\end{equation*}
Consider $u\in\mathbb{C}^n$ such that $\alpha_{ijk}(u)\neq 0$ for $%
i\in\{1,\ldots,p\}$, $j\in\{1,\ldots,d_i\}$ and $k\in\{1,\ldots,m_{ij}\}$. For example, one can take $%
u=Ve$, where $e=(1,\ldots,1)$, and then  $\alpha(u)=e$. We have $l_i(u)=m_i-1$
for $i\in\{1,\ldots,p\}$. Since 
\begin{equation*}
0 =\sum\limits_{i=1}^{p}\sum\limits_{l=0}^{m_{i}-1 }c_{il}P_{il}u=\sum\limits_{i=1}^{p}\sum\limits_{l=0}^{l_{i}(u) }c_{il}P_{il}u
\end{equation*}
and $P_{il}u$, $i\in\{1,\ldots,p\}$ and $l\in\{0,\ldots,l_i(u)\}$, are linearly independent (see
previous Proposition \ref{PropPilu}), we have $c_{il}=0$, $i\in\{1,\ldots,p\}$ and 
$l\in\{0,\ldots,m_i-1\}$.
\end{proof}

\subsubsection{Linear combinations depending on $t$}

In the present paper, we deal with linear combinations of some of the vectors $P_{il}u$ in (\ref{Pu}) or some of the
matrices $P_{il}$ in (\ref{P}), whose coefficients depend on time $t$ and they are not all zero. For a fixed $t$,
such a linear combination is not zero since the vectors and the matrices are
linearly independent (recall the two previous Propositions \ref{PropPilu} and \ref{PropPil}).

However, in the analysis of the asymptotic behavior of the condition numbers,
we require that the norm of the linear combination is away from zero,
uniformly with respect to $t$. This is the content of the next lemma.

\begin{lemma}
\label{Lemma0} Let $\mathcal{V}$ be a vector space on $\mathbb{C}$ equipped
by the norm $\left\Vert \ \cdot \ \right\Vert $, let $a_{1},\ldots ,a_{K}\in \mathcal{V}
$ and let $f:I\rightarrow \mathbb{C}^{K}$, where $I$ is an
arbitrary set. For any $t\in I$, the components $f_{1}(t),\ldots ,f_{K}(t)$ of $f(t)$ serve as
coefficients in the linear combination
$$
\sum\limits_{k=1}^{K}f_{k}\left( t\right)
a_{k}
$$
of $a_{1},\ldots ,a_{K}$.

If $a_{1},\ldots ,a_{K}$ are linearly independent and%
\begin{equation}
\inf_{t\in I}\Vert f\left( t\right)\Vert_\infty >0, \label{last}
\end{equation}%
then%
\begin{equation*}
\inf_{t\in I}\left\Vert \sum\limits_{k=1}^{K}f_{k}\left( t\right)
a_{k}\right\Vert >0. 
\end{equation*}
\end{lemma}


\begin{proof}
Suppose $a_1,\ldots,a_K$ linearly independent and (\ref{last}). Let 
\begin{equation*}
C=\left\{ z\in \mathbb{C}^{K}:\left\Vert z\right\Vert _{\infty }=1\right\} .
\end{equation*}%
Consider the function $g: \mathbb{C}^{K}\rightarrow \mathbb{R}$ given by%
\begin{equation*}
g\left( z\right) =\left\Vert \sum\limits_{k=1}^{K}z_{k}a_{k}\right\Vert ,\
z\in \mathbb{C}^K.
\end{equation*}%
Since $C$ is a compact subset of $\mathbb{C}^{K}$ and $g$ is a continuous
function, the extreme value theorem says that 
\begin{equation*}
m=\inf_{z\in C}g\left( z\right) =g\left( \overline{z}\right)
\end{equation*}%
for some $\overline{z}\in C$. Since $a_{1},\ldots ,a_{K}$ are linearly
independent, we have $m>0$.

Now, let $t\in I$. We have 
\begin{equation*}
\frac{f(t)}{\Vert f(t)\Vert_\infty}=\left(\frac{f_{1}\left( t\right) }{\Vert f(t)\Vert_\infty},\ldots,\frac{%
f_{K}\left( t\right) }{\Vert f(t)\Vert_\infty }\right)\in C,
\end{equation*}%
which implies 
\begin{equation*}
g\left(\frac{f(t)}{\Vert f(t)\Vert_\infty}\right)=\left\Vert \sum\limits_{k=1}^{K}\frac{f_{k}\left( t\right) }{\Vert f(t)\Vert_\infty}a_{k}\right\Vert \geq m
\end{equation*}%
and then%
\begin{equation*}
\left\Vert \sum\limits_{k=1}^{K}f_{k}\left( t\right) a_{k}\right\Vert \geq
m\Vert f(t)\Vert_\infty.
\end{equation*}
We conclude that 
\begin{equation*}
\inf_{t\in I}\left\Vert \sum\limits_{k=1}^{K}f_{k}\left( t\right)
a_{k}\right\Vert\geq m\inf_{t\in I}\Vert f(t)\Vert_\infty >0.
\end{equation*}
\end{proof}

In the paper, we apply this lemma to the case where $a_1, \ldots, a_K$ are some of the linearly independent vectors $P_{il}u$ in (\ref{Pu}), or some of the linearly independent matrices $P_{il}$ in (\ref{P}), and $f_1(t),\ldots,f_K(t)$ are of the form $\mathrm{e}^{\sqrt{-1}\omega t}$, with $\sqrt{-1}$ the imaginary unit and $\omega\in\mathbb{R}$, and then $\Vert f(t)\Vert_\infty=1$.











\section{Asymptotic forms}

In the next Section \ref{asymptoticbehavior}, we analyze the asymptotic (long-time) behavior of the three condition
numbers (\ref{Ktayz0}), (\ref{KAy0}) and (\ref{KA0}), i.e. what happens to (%
\ref{Ktayz0}), (\ref{KAy0}) and (\ref{KA0}) as $t$ approaches infinity (becomes large).


This analysis determines the asymptotic forms of $\mathrm{e}^{tA}%
\widehat{z}_{0}$ and $\mathrm{e}^{tA}%
\widehat{y}_{0}$ in (\ref{Ktayz0}), of $\mathrm{e}^{tA}$ and $\mathrm{e}^{tA}%
\widehat{y}_{0}$ in (\ref{KAy0}) and of $\mathrm{e}^{tA}$ and $\mathrm{e}^{-tA}$ in (\ref{KA0}). Then, the asymptotic behavior of the condition numbers is described by substituting  in (\ref{Ktayz0}), (\ref{KAy0}) and (\ref{KA0}) these asymptotic forms  and by defining asymptotic condition numbers the new expressions obtained by these substitutions. 


	All of this might seem straightforward, but from a mathematical perspective it is not a simple task. Specifically:

	\begin{itemize}
		\item It is necessary to precisely define what we mean by asymptotic form and how to determine it. This is particularly complicated in the non-diagonalizable case, where generalized eigenvectors are involved.
		\item We also want to quantify how dominant the asymptotic form is at finite times.
		\item The core of our analysis is the qualitative study of the asymptotic condition numbers. Understanding them requires significant mathematical effort in case of complex eigenvalues.
		\item If we are interested in defining asymptotic condition numbers for the problem (\ref{due}), the asymptotic condition numbers derived from (\ref{KAy0}) and (\ref{KA0}) as $t\rightarrow +\infty$ may not be appropriate, since they represent the \emph{asymptotic worst cases} of (\ref{Ktayz0}) and (\ref{KAy0}), respectively. Instead, we are concerned with the \emph{worst asymptotic cases} of (\ref{Ktayz0}) and (\ref{KAy0}) by varying $\widehat{z}_0$ and $y_0$. In other words: do \enquote{asymptotic} and \enquote{worst} commute? 
	\end{itemize}









In this section, we determine the asymptotic forms of $\mathrm{e}^{tA}$ and $\mathrm{e}^{tA}u$, where $u$ is a vector. In order to define them some preliminary notions and results need to be introduced.








\subsection{Notations $\sim$ and $\approx$} \label{firstsection}



In this subsection, we precise what we mean for asymptotic form.

Let $f(t)$ and $g(t)$ be scalar, vector or matrix functions of $%
t\in \mathbb{R}$. For $g$ such that $g(t)\neq 0$ for $t$ in a neighborhood of $+\infty$, we write
\begin{equation}
f\left( t\right) \sim g\left( t\right),\ t\rightarrow +\infty,  \label{sim}
\end{equation}
when
\begin{equation*}
\lim\limits_{t\rightarrow +\infty }\frac{\Vert f(t)-g(t)\Vert }{\Vert
g(t)\Vert }=0.
\end{equation*}
In case of scalars, vectors and matrices, $\Vert\;\cdot\;\Vert$ denotes, respectively, the modulus, a vector norm and a matrix norm.

We interpret (\ref{sim}) as indicating that $g$ is an \emph{asymptotic form} of $f$.

Observe that (\ref{sim}) means that the relative error of $f$ with respect to its asymptotic form $g$ asymptotically vanishes. At a finite time, one may ask how dominant the asymptotic form is, i.e., how large the relative error of $f$ with respect to $g$ is. Therefore, we introduce the following notation. For $t\in\mathbb{R}$ such that $g(t)\neq 0$ and $\epsilon\geq 0$, we write 
\begin{equation}
f\left( t\right) \approx g\left( t\right)\textit{\ with precision\ }\epsilon  \label{approx}
\end{equation}
when
\begin{equation*}
\frac{\Vert f\left( t\right) -g\left( t\right) \Vert }{\Vert g\left(
t\right) \Vert }\leq \epsilon.
\end{equation*}
Observe that (\ref{approx}) means that the relative error of $f$ with respect to $g$ at the time $t$ is not larger than $\epsilon$. The notation (\ref{approx}) serves to quantify how much dominant the asymptotic form $g$ of $f$ is at the finite time $t$. 

\begin{remark}
\label{Remark fg} Note that, for vector or matrix functions $f(t)$ and $%
g(t)$, 
$$
f\left( t\right)\sim g\left( t\right),\ t\rightarrow +\infty,
$$
implies 
$$
\Vert f\left( t\right) \Vert \sim \Vert g\left(
t\right) \Vert,\ t\rightarrow +\infty,
$$
and, for $\epsilon\geq 0$,
$$
f\left( t\right)\approx g\left( t\right)\text{\ with precision\ }\epsilon
$$
implies
$$
\Vert f\left( t\right) \Vert \approx \Vert g\left(
t\right) \Vert\text{\ with precision\ }\epsilon.
$$
This follows by
$$
\left\vert \left\Vert f(t)\right\Vert -\left\Vert g(t)\right\Vert\right\vert\leq \left\Vert f(t)-g(t)\right\Vert.
$$
\end{remark}


\subsection{Partition of the spectrum and formula for the matrix exponential} 

In this subsection, we introduce the tool for determining the asymptotic forms of $\mathrm{e}^{tA}$ and $\mathrm{e}^{tA}u$, $u\in\mathbb{C}^n$.  

The spectrum $\Lambda=\left\{\lambda _{1},\ldots ,\lambda _{p}\right\} $ of $A$,
where $\lambda _{1},\ldots ,\lambda _{p}$ are the distinct eigenvalues of $A$%
, is partitioned by decreasing real parts (see Figure \ref{Fig0}) in the
subsets $\Lambda_j$, $j\in\{1,\ldots,q\}$, given by 
\begin{eqnarray*}
&&\Lambda _{j}:=\{\lambda _{i_{j-1}+1},\lambda _{i_{j-1}+2},\ldots ,\lambda
_{i_{j}}\}  \label{Lambdaj} \\
&&\mathrm{Re}\left( \lambda _{i_{j-1}+1}\right) =\mathrm{Re}\left( \lambda
_{i_{j-1}+2}\right) =\cdots =\mathrm{Re}\left( \lambda _{i_j}\right) =r_{j}, 
\notag
\end{eqnarray*}
where the $q$ distinct real parts $r_j$, $j\in\{1,\ldots,q\}$, of the eigenvalues of $A$ satisfy $r_{1}>r_2>\cdots>r_{q}$.


\begin{figure}[tbp]
\includegraphics[width=1\textwidth]{fig2.png}
\caption{Partition of the eigenvalues $\protect\lambda_1,\ldots,\protect%
\lambda_p$ of $A$ by decreasing real part. The eigenvalues are marked by ``x''.}
\label{Fig0} 
\end{figure}


Now, we recall the formula (\ref{etA}) for the matrix exponential $\mathrm{e}^{tA}$:
\begin{equation*}
\mathrm{e}^{tA}=\sum\limits_{i=1}^{p}\mathrm{e}^{\lambda_{i}t}\sum\limits_{l=0}^{m_{i}-1}\frac{t^{l}}{l!}P_{il},
\end{equation*}%
where $m_i$ is the ascent of the eigenvalue $\lambda _{i}$ (maximum dimension of the mini-blocks corresponding to $\lambda_i$ in the JCF of $A$) and the matrices $P_{il}$ are defined and studied in Section \ref{JCFsection}. By using the partition of the spectrum given above, we have
\begin{equation}
\mathrm{e}^{tA}=\sum\limits_{j=1}^{q}\mathrm{e}^{r_{j}t}\sum\limits_{\lambda
_{i}\in \Lambda _{j}}\mathrm{e}^{\sqrt{-1}\ \omega
_{i}t}\sum\limits_{l=0}^{m_{i}-1}\frac{t^{l}}{l!}P_{il},  \label{exptA0}
\end{equation}%
where $\sqrt{-1}$ denotes the imaginary unit and $\omega _{i}$ denotes the imaginary part of the eigenvalue $\lambda _{i}$.


Now, by exchanging the two inner sums we can rewrite (\ref{exptA0})  as
\begin{equation}
\mathrm{e}^{tA}=\sum\limits_{j=1}^{q}\mathrm{e}^{r_{j}t}\sum%
\limits_{l=0}^{L_j}\frac{t^{l}}{l!}Q_{jl}(t),  \label{expexp}
\end{equation} 
where 
\begin{equation*}
L_j:=\max_{\lambda _{i}\in \Lambda _{j}}m_{i}-1,\ j\in\{1,\ldots,q\}, 
\end{equation*}
and 
\begin{equation}
Q_{jl}(t):=\sum\limits_{\substack{ \lambda _{i}\in \Lambda _j  \\ %
m_{i}\geq l+1}}\mathrm{e}^{\sqrt{-1}\ \omega _{i}t}P_{il},\ j\in\{1,\ldots,q\}%
\text{\ and\ }l\in\{0,\ldots,L_j\}.  \label{Qjl}
\end{equation}

The formula (\ref{expexp}) is used to determine the asymptotic forms in (\ref{Ktayz0}), (\ref{KAy0}) and (\ref{KA0}). %by looking to the dominant term as $t\rightarrow +\infty$.

\subsection{Notations for the asymptotic form of $\mathrm{e}^{tA}u$} 
The following notations are crucial for determining the asymptotic form of $\mathrm{e}^{tA}u$. 



For $j\in\{1,\ldots,q\}$ and $u\in\mathbb{C}^{n}$:
\begin{itemize}
\item Let
\begin{equation*}
	\Lambda_j(u) := \{\lambda_i \in \Lambda_j : \alpha^{(i)}(u) \neq 0\},
\end{equation*}
where $\alpha^{(i)}(u)$, defined in Section \ref{JCFsection}, is the vector of the Jordan basis components of $u$ along the generalized eigenvectors corresponding to $\lambda_i$. In other words, $\Lambda_j(u)$ is obtained from $\Lambda_j$ by including only the eigenvalues for which $u$ has a non-zero projection onto the corresponding generalized eigenspace. 

\item In the case where $\Lambda_j(u) \neq \emptyset$, let
\begin{equation*}
	L_j(u) := \max\{l_i(u) : \lambda_i \in \Lambda_j(u)\},
\end{equation*}
where
\begin{equation*}
	l_i(u) = \max\{ l \in \{0, \ldots, m_i - 1\} : P_{il}u \neq 0\}
\end{equation*}
is defined and studied in Section \ref{JCFsection}, and it is such that $l_i(u) + 1$ is the maximum index $k$, in a Jordan chain
\begin{equation*}
	(v^{(i,j,k)})_{k=1,\ldots,m{ij}}, \ j \in\{1, \ldots, d_j\},
\end{equation*}
corresponding to the eigenvalue $\lambda_i$, for which $u$ has a non-zero component along the generalized eigenvector $v^{(i,j,k)}$. In other words, $L_j(u) + 1$ is the maximum index $k$, in a Jordan chain corresponding to an eigenvalue in $\Lambda_j$, for which $u$ has a non-zero component along the $k$-th generalized eigenvector of the chain.
\end{itemize}

\subsubsection{Indeces of dominance}
For $u\in \mathbb{C}^{n}\setminus\{0\}$:
\begin{itemize}
\item Let 
\begin{equation*}
j(u):=\min\{j\in \left\{ 1,\ldots,q\right\}: \Lambda_j(u)\neq \emptyset\}.
\end{equation*}
In other words, $r_{j(u)}$ is the rightmost real part of an eigenvalue of $A$ such that $u$ has a non-zero projection on the corresponding generalized eigenspace. We call $j(u)$ the  \emph{primary index of dominance} of $u$.
\item Let 
\begin{equation*}
L(u):=L_{j(u)}(u).
\end{equation*}
In other words, $L(u)+1$ is the maximum index $k$, in a Jordan chain corresponding to an eigenvalue in $\Lambda_{j(u)}(u)$, for which $u$ has a non-zero component along the $k$-th generalized eigenvector of the chain.  We call $L(u)$  the \emph{secondary index of dominance} of $u$.
\end{itemize}


Similarly to Section \ref{JCFsection}, the next two subsections, \ref{lastsection} and \ref{sssQj0}, can be skipped and referred back to when necessary.


\subsection{Properties of the matrices $Q_{jl}(t)$}  \label{lastsection}


In our study of asymptotic forms and asymptotic condition numbers, the following properties of the matrices $Q_{jl}(t)$ in (\ref{Qjl}) are fundamental. We collect these properties in four propositions.




The first proposition relates the indices $j(u)$ and $L_j(u)$ to the condition $%
Q_{jl}(t)u=0$.

\begin{proposition}
\label{lemma2Qjl} Let $u\in\mathbb{C}^n$. We have:

\begin{itemize}
\item[1)] $Q_{jl}(t)u=0$ for $j\in\{1,\ldots,q\}$ with $\Lambda_j(u)=\emptyset$
and $l\in\{0,\ldots,L_j\}$;

\item[2)] $Q_{jl}(t)u=0$ for $j\in\{1,\ldots,j(u)-1\}$ and $l\in\{0,\ldots,L_j\}$;

\item[3)] $Q_{jl}(t)u=0$ for $j\in\{j(u),\ldots,q\}$ with $\Lambda_j(u)\neq
\emptyset$ and $l\in\{L_j(u)+1,\ldots,L_j\}$.
\end{itemize}
In 2) and 3), we assume $u\neq 0$ in order to have $j(u)$ defined.
\end{proposition}
\begin{proof}
For $j\in\{1,\ldots,q\}$ and $l\in\{0,\ldots,L_j\}$, we have
\begin{equation*}
Q_{jl}(t)u=\sum\limits_{\substack{ \lambda _{i}\in \Lambda _j  \\ %
m_{i}\geq l+1}}\mathrm{e}^{\sqrt{-1}\ \omega _{i}t}P_{il}u
\end{equation*}
by recalling (\ref{Qjl}).

Proof of point 1). Consider $j\in\{1,\ldots,q\}$ with $\Lambda_j(u)=\emptyset$
and $l\in\{0,\ldots,L_j\}$. $\Lambda_j(u)=\emptyset$ implies, for any $\lambda_i\in\Lambda_j$, $\alpha^{(i)}(u)=0$ and then, by Propositions \ref{Prop2A} and \ref{Prop3A}, for any $\lambda_i\in\Lambda_j$ we have $P_{ik}u=0$, $k\in\{0,\ldots,m_i-1\}$. In particular, for any $\lambda_i\in\Lambda_j$ with $m_i\geq l+1$, we have $P_{il}u=0$. 

Point 2) follows by point 1).

Proof of point 3).  Consider $j\in\{1,\ldots,q\}$ with $\Lambda_j(u)\neq
\emptyset$ and $l\in\{L_j(u)+1,\ldots,L_j\}$. For any $%
\lambda_i\in\Lambda_j$ with $m_i\geq l+1$ and $\alpha^{(i)}(u)=0$, we have $P_{il}u=0$,  since $P_{ik}u=0$, $k\in\{0,\ldots,m_i-1\}$. For any $\lambda_i\in\Lambda_j$ with $m_i\geq l+1$ and $\alpha^{(i)}(u)\neq 0$, we also have $P_{il}u=0$, since $P_{ik}u=0$, $k\in\{l_i(u)+1,\ldots,m_i-1\}$ by the definition of $l_i(u)$, and $l\geq L_j(u)+1\geq l_i(u)+1$.
\end{proof}
The second proposition says that the matrices $Q_{jl}(t)$ and their actions
on vectors remain bounded and away from zero, by varying $t$.

\begin{proposition}
\label{lemmaQjl} Let $j\in\{1,\ldots,q\}$, $l\in\{0,\ldots,L_j\}$ and $u\in\mathbb{C}^n$%
. We have:

\item[1)] $\sup\limits_{t\in \mathbb{R}} \left\Vert Q_{jl} (t)\right\Vert<+\infty$;

\item[2)] 
$\sup\limits_{t\in \mathbb{R}} \left\Vert Q_{jl} (t)u\right\Vert<+\infty$;

\item[3)] 
$
\inf\limits_{t\in \mathbb{R}} \left\Vert Q_{jl} (t)\right\Vert>0$;


\item[4)] $\inf\limits_{t\in \mathbb{R}} \left\Vert Q_{jl} (t)u\right\Vert>0$ if $\Lambda_j(u)\neq \emptyset$ and $l\leq L_j(u)$.
\end{proposition}

\begin{proof}
Since (see (\ref{Qjl}))
\begin{equation*}
\left\Vert Q_{jl} (t)\right\Vert\leq \sum\limits_{\substack{ \lambda _{i}\in
\Lambda _j  \\ m_{i}\geq l+1}}\left \Vert P_{il}\right\Vert\text{\ \ and\ \ }\left\Vert Q_{jl} (t)u\right\Vert\leq \sum\limits_{\substack{ \lambda
_{i}\in \Lambda _j  \\ m_{i}\geq l+1}}\left \Vert P_{il}u\right\Vert 
\end{equation*}
hold, the points 1) and 2) follow.

Proposition \ref%
{PropPil} and Lemma \ref{Lemma0}, as applied to the linear combination
$$
Q_{jl}(t)=\sum\limits_{\substack{ \lambda _{i}\in \Lambda _j  \\ %
		m_{i}\geq l+1}}\mathrm{e}^{\sqrt{-1}\ \omega _{i}t}P_{il},
$$


imply 3).

Finally, suppose $\Lambda_j(u)\neq \emptyset$ and $l\leq
L_j(u)$. We obtain 
\begin{equation*}
Q_{jl}(t)u=\sum\limits_{\substack{ \lambda _{i}\in \Lambda _j  \\ %
m_{i}\geq l+1}}\mathrm{e}^{\sqrt{-1}\ \omega _{i}t}P_{il}u=\sum\limits
_{\substack{ \lambda _{i}\in \Lambda _j(u)  \\ m_{i}\geq l+1}}\mathrm{e}^{%
\sqrt{-1}\ \omega _{i}t}P_{il}u=\sum\limits_{\substack{ \lambda _{i}\in
\Lambda _j(u)  \\ m_i\geq l+1 \\ l_i(u)\geq l}}\mathrm{e}^{\sqrt{-1}\ \omega _{i}t}P_{il}u, 
\end{equation*}
where the second equality holds since for any $\lambda_i\in\Lambda_j$ with $m_i\geq l+1$ and $\alpha^{(i)}(u)=0$ we have $P_{il}u=0$; and the third equality holds since for any $\lambda_i\in\Lambda_j$ with $m_i\geq l+1$, $\alpha^{(i)}(u)\neq 0$ and $l_i(u)<l$ we have $P_{il}u=0$ by the definition of $l_i(u)$. Now, Proposition \ref{PropPilu} and Lemma \ref{Lemma0} imply 4).
\end{proof}

The third proposition says how the matrices $Q_{jl}(t)$ are transformed when we
replace the matrix $A$ by $-A$. Observe that the matrix $-A$ has opposite eigenvalues, i.e. eigenvalues with opposite imaginary and real parts, with respect to the matrix $A$ and the dimensions of blocks and mini-blocks in the JCF of $-A$ are the same as in the JCF of $A$ (see Proposition \ref{Vfor-A} with $z=-1$). Therefore, we have the same number $q$ of different real parts for the eigenvalues of $-A$ and $A$. Moreover, the set $\Lambda_j(-A)$ and the numbers $r_j(-A)$ and $L_j(-A)$, $j\in\{1,\ldots,q\}$, corresponding to $-A$ are
\begin{equation}
\Lambda_j(-A)=-\Lambda_{q+1-j},\ r_j(-A)=-r_{q+1-j}\text{\ \ and\ \ }L_j(-A)=L_{q+1-j}, \label{q+1-}
\end{equation}
where $\Lambda_{q+1-j}$, $r_{q+1-j}$ and $L_{q+1-j}$ correspond to $A$.   The indeces $j$ and $l$ for the matrices $Q_{jl}(t,-A)$ corresponding to $-A$ range over  $j\in\{1,\ldots,q\}$ and $l\in\{0,\ldots,L_{q+1-j}\}$, respectively.
\begin{proposition}\label{-A}
\label{-QA} We have 
\begin{equation*}
Q_{jl}(t,-A)=(-1)^lQ_{q+1-j\ l}(-t),\ j\in\{1,\ldots,q\}\text{\ and\ }l\in\{0,\ldots,L_{q+1-j}\}.  \label{alphalQjl}
\end{equation*}
\end{proposition}
\begin{proof}
The matrix $Q_{jl}(t,-A)$, $j\in\{1,\ldots,q\}$ and $l\in\{0,\ldots,L_{q+1-j}\}$, is given by
\begin{equation*}
Q_{jl}(t,-A)=\sum\limits_{\substack{ \lambda _{i}\in \Lambda _{q+1-j}  \\ %
m_{i}\geq l+1}}\mathrm{e}^{\sqrt{-1}\ (-\omega _{i})t}P_{il}(-A).
\end{equation*}
 Now, use Proposition \ref{PropalphalPil} with $z=-1$.
\end{proof}



In the case of a real matrix $A$, the fourth proposition explains how to rewrite the expression (\ref{Qjl}) that defines $Q_{jl}(t)$ in terms of the real eigenvalues and complex conjugate pairs of eigenvalues of $A$. For
a matrix $Z$, we denote by $\mathrm{Re}(Z)$ the matrix given by the real parts of the elements of $Z$.
\begin{proposition}
\label{Pireal} Assume $A\in \mathbb{R}^{n\times n}$. For $j\in\{1,\ldots ,q\}$ and 
$l\in\{0,\ldots,L_j\}$, we have 
\begin{equation}
Q_{jl}(t)=\sum\limits_{\substack{ \lambda _{i}\in \Lambda _{j}  \\ \lambda
_{i}\mathrm{\ is\ real} \\ m_i\geq l+1}}P_{il} +2\sum\limits _{\substack{ %
\lambda _{i}\in \Lambda _{j}  \\ \omega _{i}>0 \\ m_i\geq l+1}}\mathrm{Re}%
\left( \mathrm{e}^{\sqrt{-1}\ \omega _{i}t}P_{il} \right) .  \label{expd0}
\end{equation}
\end{proposition}



\begin{proof}
For $\lambda_i\in\Lambda_j$ such that $\lambda_i$ is real, we have $\omega_i=0$. For a complex conjugate pairs $\lambda_{i_1},\lambda_{i_2}\in \Lambda_j$ with $\lambda _{i_{2}}=\overline{\lambda _{i_{1}}}$ and $\omega_{i_1}>0$,  by Proposition \ref{complex} we have 
\begin{eqnarray*}
\mathrm{e}^{\sqrt{-1}\omega _{i_{2}}t}P_{i_{2}l} &=&\mathrm{e}^{-\sqrt{-1}\
\omega _{i_{1}}t}\overline{P_{i_{1}l}}=\overline{\mathrm{e}^{\sqrt{-1}\
\omega _{i_{1}}t}P_{i_{1}l}}
\end{eqnarray*}%
and then 
\begin{equation*}
\mathrm{e}^{\sqrt{-1}\omega _{i_{1}}t}P_{i_{1}l}+\mathrm{e}^{\sqrt{-1}\
\omega _{i_{2}}t}P_{i_{2}l} =2\mathrm{Re}\left( \mathrm{e}^{\sqrt{-1}\omega
_{i_{1}}t}P_{i_{1}l} \right) .
\end{equation*}
\end{proof}

\begin{remark}
In (\ref{expd0}) the sum 
\begin{equation*}
\sum\limits_{\substack{ \lambda_i\in \Lambda _{j}  \\ \lambda _{i}\text{ is
real} \\ m_i \geq l+1}} P_{il}
\end{equation*}
has zero or one term $P_{il}$, which is real (see Proposition \ref{complex}). Moreover, in the other sum, each term
\begin{equation*}
\mathrm{Re}\left( \mathrm{e}^{\sqrt{-1}\omega _{i}t}P_{il}
\right)=\cos\omega_i t\cdot \mathrm{Re}(P_{il})-\sin\omega_i t\cdot \mathrm{%
Im}(P_{il})
\end{equation*}
is a periodic function of $t$ of period $\frac{2\pi}{\omega_i}$.
\end{remark}


\subsection{The matrices $Q^e_{j}(t)$} \label{sssQj0}

The contents of this section are used for defining in Subsection \ref {SoverKtA} the global asymptotic condition number of the problem (\ref{due}).  

For $j\in\{1,\ldots,q\}$, we introduce
\begin{equation*}
	Q^e_{j}(t):=\sum\limits_{\lambda _{i}\in \Lambda _j }\mathrm{e}^{\sqrt{-1}\
		\omega _{i}t}P_{i}^e,
\end{equation*}
where 
$$
P_{i}^e:=V^{(i)}_eW^{(i)}_e,
$$
is the projection onto the eigenspace corresponding to the eigenvalue $\lambda_i$, with
\begin{equation*}
	V^{(i)}_e:=\left[ v^{(i,1,1)}\ \cdots \ v^{(i,d_i,1)}\right] \in \mathbb{C%
	}^{n\times d_{i}}\text{\ \ and\ \ }W^{(i)}_e:=\left[ 
	\begin{array}{c}
		w^{(i,1,1)} \\ 
		\vdots \\ 
		w^{(i,d_i,1)}%
	\end{array}%
	\right] \in \mathbb{C}^{d_i\times n}
\end{equation*}
the matrices of the (right) eigenvectors and left eigenvectors, respectively, corresponding to $\lambda_i$ (see Section \ref{JCFsection}). The superscript or subscript $e$ in the notation denotes ``eigen''.



Let $U^e_{j}$ be the sum of the eigenspaces corresponding to eigenvalues in $\Lambda_j$. Observe that the linear operator $Q^e_{j}(t)$ maps $\mathbb{C}^n$ in the subspace $U^e_{j}$. Therefore, $Q^e_{j}(t)|_{U^e_{j}}:U^e_{j}\rightarrow U^e_{j}$. The next proposition states that the restriction $Q^e_{j}(t)|_{U^e_{j}}$ is invertible.
\begin{proposition}\label{Qj0}
	Let $j\in\{1,\ldots,q\}$. The linear operator $Q^e_{j}(t)|_{U^e_{j}}:U^e_{j}\rightarrow U^e_{j}$ is invertible and the inverse is
	\begin{equation*}
		\left(Q^e_{j}(t)|_{U^e_j}\right)^{-1}=Q^e_{j}(-t)|_{U^e_{j}}.
	\end{equation*}
\end{proposition}



\begin{proof}
	We have 
	\begin{eqnarray*}
		Q^e_{j}(-t)Q^e_{j}(t)&=&\left(\sum\limits_{\lambda _{i}\in \Lambda _j }\mathrm{%
			e}^{-\sqrt{-1}\ \omega _{i}t}P^e_{i}\right)\left(\sum\limits_{\lambda _{i}\in
			\Lambda _j }\mathrm{e}^{\sqrt{-1}\ \omega _{i}t}P^e_{i}\right) \\
		&=&\sum\limits_{\lambda _{i}\in \Lambda _j }P^e_{i}
	\end{eqnarray*}
	and then
	$$
	Q_j^e(-t)|_{U_j^e}Q_j^e(t)|_{U_j^e}=I_{U_j^e}.
	$$
\end{proof}
\begin{remark}
	\label{remQ00} 
	\quad
	\begin{itemize}
		\item [1.] As a consequence of the previous proposition, we have
		\begin{equation*}
			\min\limits_{\substack{\widehat{u}\in U^e_{j} \\ \left\Vert \widehat{u}\right\Vert=1}}\left\Vert Q^e_{j}(t)%
			\widehat{u}\right\Vert=\frac{1}{\left\Vert Q^e_{j}(-t)|_{U^e_{j}} \right\Vert}. 
		\end{equation*}
		\item [2.] In the case where $\Lambda_j$ consists of a real eigenvalue $\lambda_i$, we have 
		$$
		Q^e_{j}(t)|_{U^e_{j}}=P_i^e|_{U^e_j}=I_{U^e_{j}}.
		$$
	\end{itemize}
\end{remark}

Next proposition considers the linear operators $P_i^e|_{U^e_j}:U^e_j\rightarrow U^e_j$, $\lambda_i\in \Lambda_j$.

\begin{proposition}\label{PoverPi0}
	Let $j\in\{1,\ldots,q\}$. The linear operators
	\begin{equation}
		P_{i}^e|_{U^e_j},\ \lambda_i\in\Lambda_j,  \label{overPi0}
	\end{equation}
	are linearly independent in the vector space of the linear operators $U^e_j\rightarrow U^e_j$.
\end{proposition}

The proof of this proposition is similar to the proof of Proposition \ref{PropPil}.

\begin{proof}
	Consider a zero linear combination of the linear operators (\ref{overPi0}): 
	\begin{equation*}
		0 =\sum\limits_{i=1}^{p}c_{i}P_{i}^e|_{U^e_j}.
	\end{equation*}
	Consider $u\in U^e_j$ such that $\alpha_{ij^\prime 1}(u)\neq 0$ for $%
	\lambda_i\in\Lambda_j$ and $j^\prime\in\{1,\ldots,d_i\}$. Since $u\in U^e_j$, we have  $\alpha_{ij^\prime k}(u)=0$ for $%
	\lambda_i\in\Lambda_j$, $j^\prime\in\{1,\ldots,d_i\}$ and  $k\in\{2,\ldots,m_{ij^\prime}\}$. Thus $l_i(u)=0$
	for $\lambda_i\in\Lambda_j$, by Proposition \ref{propliu}. Since (recall Subsection \ref{matricesPi00})
	$$
	P_{i}^eu=P_{i0}u,\ \lambda_i\in\Lambda_j,
	$$
	we have the zero linear combination
	\begin{equation*}
		0 =\sum\limits_{\lambda_i\in \Lambda_j}c_{i}P_{i}^eu=\sum\limits_{\lambda_i\in \Lambda_j}c_{i}P_{i0}u=\sum\limits_{\lambda_i\in \Lambda_j}\sum\limits_{l=0}^{l_{i}(u)=0}c_{il}P_{il}u,
	\end{equation*}
	where we set $c_{i0}=c_{i}$, $i\in\{1,\ldots,p\}$. By using Proposition \ref{PropPilu}, we obtain $c_i=c_{i0}=0$, $\lambda_i\in\Lambda_j$.
\end{proof}

\begin{remark}\label{remQ0} 
	As a consequence of the previous proposition and Lemma \ref{Lemma0}, we obtain
	$$
	\inf\limits_{t\in\mathbb{R}}\left\Vert Q^e_{j}(t)|_{U^e_j}\right\Vert>0.
	$$
\end{remark}


\subsection{The asymptotic form of $\mathrm{e}^{tA}$} \label{ssexp}

By looking at the formula (\ref{expexp}), we immediately identify
\begin{equation}
\mathrm{e}^{r_1t}\frac{t^{L_1}}{L_{1}!}Q_{1L_1}(t) \label{af}
\end{equation}
as the asymptotic form of $\mathrm{e}^{tA}$, since it is the dominant term as $t\rightarrow +\infty$: it is the term with the highest order of infinite. Next proposition precises that (\ref{af}) is indeed an asymptotic form of $\mathrm{e}^{tA}$ in our definition (\ref{sim}) of asymptotic form and quantifies its dominance at a finite time.



\begin{proposition}
\label{Lemma2} We have 
\begin{equation*}
\mathrm{e}^{tA}\approx \mathrm{e}^{r_1t}\frac{t^{L_1}}{L_{1}!}Q_{1L_1}(t)
\end{equation*}%
with precision 
\begin{equation*}
\epsilon(t):=\sum\limits_{l=0}^{L_1 -1} \frac{L_1 !}{l!}t^{l-L_1}\frac{%
\left\Vert Q_{1l}(t)\right\Vert}{\left\Vert Q_{1L_1}(t)\right\Vert }%
+\sum\limits_{j=2}^{q}\mathrm{e}^{\left( r_{j}-r_{1}\right)
t}\sum\limits_{l=0}^{L_j}\frac{L_1!}{l!}t^{l-L_1}\frac{\left\Vert
Q_{jl}(t)\right\Vert }{\left\Vert Q_{1L_1}(t)\right\Vert }.
\end{equation*}
Moreover, we have
\begin{equation}
\epsilon(t)\rightarrow 0,\ t\rightarrow +\infty, \label{epsilon}
\end{equation}
and then
\begin{equation*}
\mathrm{e}^{tA}\sim \mathrm{e}^{r_1t}\frac{t^{L_1}}{L_{1}!} Q_{1L_1}(t),\
t\rightarrow +\infty.
\end{equation*}
\end{proposition}

\begin{proof}
By (\ref{expexp}), we can write 
\begin{eqnarray*}
\mathrm{e}^{tA}&=&\sum\limits_{j=1}^{q}\mathrm{e}^{r_{j}t}\sum%
\limits_{l=0}^{L_j}\frac{t^{l}}{l!}Q_{jl}(t) \\
&=&\mathrm{e}^{r_{1}t}\frac{t^{L_1}}{L_1!}Q_{1L_1}(t)+\mathrm{e}%
^{r_{1}t}\sum\limits_{l=0}^{L_1-1}\frac{t^{l}}{l!}Q_{1l}(t)+\sum%
\limits_{j=2}^{q}\mathrm{e}^{r_{j}t}\sum\limits_{l=0}^{L_j}\frac{t^{l}}{l!}%
Q_{jl}(t).
\end{eqnarray*}
The first part of the proposition regarding $\approx$ follows. By 1) and 3) in Proposition \ref{lemmaQjl}, we obtain (\ref{epsilon}) and then the second part regarding $\sim$ follows. 
\end{proof}




\begin{remark}
\label{etAAA}
If $A$ is diagonalizable, then we have
\begin{equation*}
\mathrm{e}^{tA}\approx \mathrm{e}^{r_1t}Q_{10}(t)
\end{equation*}
with precision 
\begin{equation*}
\epsilon(t)=\sum\limits_{j=2}^{q}\mathrm{e}^{\left( r_{j}-r_{1}\right)
t}\frac{\left\Vert Q_{j0}(t)\right\Vert }{\left\Vert Q_{10}(t)\right\Vert }
\end{equation*}
and
\begin{equation*}
\mathrm{e}^{tA}\sim \mathrm{e}^{r_1t}Q_{10}(t),\ t\rightarrow +\infty,
\end{equation*}
where
\begin{equation*}
Q_{j0}(t)=\sum\limits_{\lambda _{i}\in \Lambda _j}\mathrm{e}^{\sqrt{-1}\ \omega _{i}t}P_{i0},\ j\in\{1,\ldots,q\},
\end{equation*}
with $P_{i0}$ the projection onto the eigenspace corresponding to $\lambda_i$.
\end{remark}

\subsection{The asymptotic form of $\mathrm{e}^{tA}u$} \label{ssexpu}

Let $u\in\mathbb{C}^n\setminus\{0\}$. When we use the formula (\ref{expexp}) for $\mathrm{e}^{tA}$ in $\mathrm{e}^{tA} u$, we obtain
$$
\mathrm{e}^{tA}u=\sum\limits_{j=1}^{q}\mathrm{e}^{r_{j}t}\sum%
\limits_{l=0}^{L_j}\frac{t^{l}}{l!}Q_{jl}(t)u.
$$
By 2) and 3) in Proposition \ref{lemma2Qjl} we identify
\begin{equation}
\mathrm{e}^{r_{j\left( u\right) }t}\frac{t^{L(u)}}{%
L(u)!}Q_{j(u)L(u)}(t)u   \label{afu}
\end{equation}
as the asymptotic form of $\mathrm{e}^{tA} u$, since it is the dominant term as $t\rightarrow +\infty$. Next proposition precises that (\ref{afu}) is indeed an asymptotic form in our definition and quantifies its dominance.
\begin{proposition}
\label{Lemma1}For $u\in \mathbb{C}^{n}\setminus\{0\}$, we have 
\begin{equation*}
\mathrm{e}^{tA}u\approx \mathrm{e}^{r_{j\left( u\right) }t}\frac{t^{L(u)}}{%
L(u)!}Q_{j(u)L(u)}(t)u
\end{equation*}%
with precision 
\begin{eqnarray*}
\epsilon(t,u)&:=&\sum\limits_{l=0}^{L\left( u\right) -1} \frac{L\left(
u\right) !}{l!}t^{l-L\left( u\right) }\frac{\left\Vert
Q_{j(u)l}(t)u\right\Vert}{\left\Vert Q_{j(u)L(u)}(t)u\right\Vert } \\
&&+\sum\limits_{\substack{ j=j\left( u\right) +1 \\ \Lambda_j(u)\neq
\emptyset}}^{q}\mathrm{e}^{\left( r_{j}-r_{j\left( u\right) }\right)
t}\sum\limits_{l=0}^{L_j(u)}\frac{L(u)!}{l!}t^{l-L(u)}\frac{\left\Vert
Q_{jl}(t)u\right\Vert }{\left\Vert Q_{j(u)L(u)}(t)u\right\Vert}.
\end{eqnarray*}
Moreover, we have
\begin{equation}
\epsilon(t,u)\rightarrow 0,\ t\rightarrow +\infty,  \label{epsilonu}
\end{equation}
and then
\begin{equation*}
\mathrm{e}^{tA}u\sim \mathrm{e}^{r_{j\left( u\right) }t}\frac{t^{L(u)}}{L(u)!%
}Q_{j(u)L(u)}(t)u,\ t\rightarrow +\infty.
\end{equation*}
\end{proposition}

\begin{proof}
By (\ref{expexp}) and Proposition \ref{lemma2Qjl}, we can write 
\begin{eqnarray*}
\mathrm{e}^{tA}u&=&\sum\limits_{j=1}^{q}\mathrm{e}^{r_{j}t}\sum%
\limits_{l=0}^{L_j}\frac{t^{l}}{l!}Q_{jl}(t)u=\sum\limits_{j=j(u)}^{q}%
\mathrm{e}^{r_{j}t}\sum\limits_{l=0}^{L_j}\frac{t^{l}}{l!}Q_{jl}(t)u \\
&=&\sum\limits_{\substack{ j=j(u) \\ \Lambda_j(u)\neq \emptyset}}^{q}\mathrm{%
e}^{r_{j}t}\sum\limits_{l=0}^{L_j(u)}\frac{t^{l}}{l!}Q_{jl}(t)u \\
&=&\mathrm{e}^{r_{j(u)}t}\frac{t^{L(u)}}{L(u)!}Q_{j(u)L(u)}(t)u+\mathrm{e}%
^{r_{j(u)}t}\sum\limits_{l=0}^{L(u)-1}\frac{t^{l}}{l!}Q_{j(u)l}(t)u \\
&&+\sum\limits_{\substack{ j=j(u)+1 \\ \Lambda_j(u)\neq \emptyset}}^{q}%
\mathrm{e}^{r_{j}t}\sum\limits_{l=0}^{L_j(u)}\frac{t^{l}}{l!}Q_{jl}(t)u.
\end{eqnarray*}%
The first part of the proposition regarding $\approx$ follows. By 2) and 4) in Proposition \ref{lemmaQjl}, we obtain (\ref{epsilonu}) and then the second part regarding $\sim$ follows.
\end{proof}


\begin{remark} \label{etAAAu}
	\quad
	\begin{itemize}
		\item [1.]The asymptotic form (\ref{afu}) of $\mathrm{e}^{tA}u$ is determined by the primary and secondary indices of dominance of $u$. In particular, the smaller the primary index of dominance $j(u)$, the higher the order of infinity of (\ref{afu}), and for a fixed primary index, the larger the secondary index of dominance $L(u)$, the higher the order of infinity of (\ref{afu}). 
\item [2.]
	The contents of Propositions \ref{Lemma2} and \ref{Lemma1} are deeper than what might be apparent at first glance. We are not simply stating the obvious facts that (\ref{af}) and (\ref{afu}) are the dominant terms in $\mathrm{e}^{tA}$ and $\mathrm{e}^{tA}u$, respectively. Rather, we are asserting that they represent the asymptotic forms of $\mathrm{e}^{tA}$ and $\mathrm{e}^{tA}u$ according to our definition (\ref{sim}). In other words, the relative errors of $\mathrm{e}^{tA}$ and $\mathrm{e}^{tA}u$ with respect to (\ref{af}) and (\ref{afu}), respectively, approach zero asymptotically. Proving these deeper conclusions requires Propositions \ref{PropPilu} and \ref{PropPil} and Lemma \ref{Lemma0}, which were developed through the work in Section \ref{JCFsection}.
	\item [3.] If $A$ is diagonalizable, then we have
	\begin{equation*}
		\mathrm{e}^{tA}u\approx \mathrm{e}^{r_{j\left( u\right) }t}Q_{j(u)0}(t)u
	\end{equation*}
	with precision
	\begin{eqnarray*}
		\epsilon(t,u)=\sum\limits_{j=j\left( u\right) +1}^q\mathrm{e}^{\left( r_{j}-r_{j\left( u\right)
			}\right) t}\frac{\left\Vert Q_{j0}(t)u\right\Vert }{\left\Vert
			Q_{j(u)0}(t)u\right\Vert}
	\end{eqnarray*}
	and
	\begin{equation*}
		\mathrm{e}^{tA}u\sim \mathrm{e}^{r_{j\left( u\right) }t}Q_{j(u)0}(t)u,\ t\rightarrow +\infty.
	\end{equation*}
	\end{itemize} 
\end{remark}


\section{The asymptotic behavior of the condition numbers} \label{asymptoticbehavior}

This section forms the core of our analysis. Building on the preparatory work of the previous two sections, we can now easily describe the asymptotic behavior of the condition numbers.

\subsection{The asymptotic directional condition number $K_\infty\left( t,y_{0},\widehat{z}%
_{0}\right)$}  \label{ssccfirst}

We set 
\begin{equation*}
j^{\ast }:=j\left( \widehat{y}_{0}\right) =j\left( y_{0}\right)\text{\ \
and\ \ }L^{\ast }:=L\left( \widehat{y}_{0}\right) =L\left( y_{0}\right)
\end{equation*}
as well as 
\begin{equation*}
j^{\ast \ast }:=j\left( \widehat{z}_{0}\right)\text{\ \ and\ \ } L^{\ast
\ast }:=L\left( \widehat{z}_{0}\right),
\end{equation*}
i.e. $j^\ast$ and $j^{\ast\ast}$ are the primary indeces of dominance, and $L^\ast$ and $L^{\ast\ast}$ are the secondary indeces of dominance, of $y_0$ and $\widehat{z}_0$, respectively.

The next theorem describes the long-time behavior of the directional condition number $%
K\left( t,y_{0},\widehat{z}_{0}\right) $.

\begin{theorem}
\label{ThmKyz} We have 
\begin{equation*}
K\left( t,y_{0},\widehat{z}_{0}\right) \approx K_\infty\left( t,y_{0},%
\widehat{z}_{0}\right), 
\end{equation*}
where 
\begin{equation*}
K_\infty\left( t,y_{0},\widehat{z}_{0}\right):=\frac{L^{\ast}!}{%
L^{\ast\ast }!}\mathrm{e}^{\left( r_{j^{\ast \ast }}-r_{j^{\ast }}\right)
t}t^{L^{\ast \ast }-L^{\ast }}\frac{\left\Vert
Q_{j^{\ast\ast}L^{\ast\ast}}(t)\widehat{z}_{0}\right\Vert }{\left\Vert
Q_{j^{\ast}L^{\ast}}(t)\widehat{y}_{0}\right\Vert },  \label{sim11}
\end{equation*}
with precision 
\begin{equation*}
\frac{\epsilon(t,\widehat{z}_0)+\epsilon(t,\widehat{y}_0)}{%
1-\epsilon(t,\widehat{y}_0)},
\end{equation*}
whenever $\epsilon(t,\widehat{y}_0)<1$ ($\epsilon(t,u)$, $u=\widehat{z}_0,\widehat{y}_0$, defined in Proposition \ref{Lemma1}). Moreover, we have 
\begin{equation*}
K\left( t,y_{0},\widehat{z}_{0}\right) \sim K_\infty\left( t,y_{0},%
\widehat{z}_{0}\right),\ t\rightarrow +\infty.  \label{simKyz}
\end{equation*}
\end{theorem}

\begin{proof}
Proposition \ref{Lemma1} says what are the asymptotic forms of $\mathrm{e}^{tA}%
\widehat{z}_{0}$ and $\mathrm{e}^{tA}%
\widehat{y}_{0}$ in (\ref{Ktayz0}) and how much they are dominant at a finite time $t$: we have
\begin{equation*}
\mathrm{e}^{tA} \widehat{z}_{0}\approx \mathrm{e}^{r_{j^{\ast \ast }}t}\frac{%
t^{L^{\ast \ast }}}{L^{\ast \ast }!}Q_{j^{\ast\ast}L^{\ast\ast}}(t)\widehat{z%
}_{0}
\end{equation*}
with precision $\epsilon(t,\widehat{z}_0)$ and 
\begin{equation*}
\mathrm{e}^{tA} \widehat{y}_{0}\approx \mathrm{e}^{r_{j^{\ast }}t}\frac{%
t^{L^{\ast }}}{L^{\ast }!}Q_{j^{\ast}L^{\ast}}(t)\widehat{y}_{0}
\end{equation*}
with precision $\epsilon(t,\widehat{y}_0)$. The first part of the theorem regarding $\approx$ follows by using Remark \ref{Remark fg}. The second part regarding $\sim$ follows since $\epsilon(t,\widehat{y}%
_0)\rightarrow 0$ and $\epsilon(t,\widehat{z}_0)\rightarrow 0$, $%
t\rightarrow +\infty$.
\end{proof}

We define the function 
$$
t\rightarrow K_\infty\left(t,y_0,\widehat{z}%
_0\right),\ t\in\mathbb{R},
$$
as the \emph{asymptotic directional condition number} of the problem (\ref{due}%
).

\begin{remark}
\label{KtAyz} \quad

\begin{itemize}
\item[1.] The asymptotic directional condition number of the problem (\ref{due}):

\begin{itemize}
\item is bounded and away from zero as $t$ varies (remind 2) and 4) in Proposition \ref{lemmaQjl}) if $j^\ast=j^{\ast\ast}$ and $L^\ast=L^{\ast\ast}$;

\item decays polynomially to zero, as $t\rightarrow +\infty$, if $j^\ast=j^{\ast\ast}$ and $L^\ast>L^{\ast\ast}$;

\item diverges polynomially to infinite, as $t\rightarrow +\infty$, if $j^\ast=j^{\ast\ast}$ and $L^\ast<L^{\ast\ast}$;

\item decays exponentially to zero, as $t\rightarrow +\infty$, if $j^\ast<j^{\ast\ast}$;

\item diverges exponentially to infinite, as $t\rightarrow +\infty$, if $j^\ast>j^{\ast\ast}$.
\end{itemize}
Hence, whether the asymptotic condition number decreases to zero, diverges to infinity, or exhibits different behavior depends on which between $y_0$ and $\widehat{z}_0$ is more dominant. This is determined by which of $y_0$ and $\widehat{z}_0$  possesses the smaller primary index of dominance, or, in the case of equal primary indices, the larger secondary index of dominance.

\item[2.] The generic case for $y_0$ and $\widehat{z}_0$ is $j^{\ast
}=j^{\ast \ast }=1$ and $L^{\ast}=L^{\ast \ast }=L_1$. In this generic case, we have 
\begin{equation*}
K_\infty\left( t,y_{0},\widehat{z}_{0}\right) = \frac{\left\Vert
Q_{1L_1}(t)\widehat{z}_{0}\right\Vert }{\left\Vert Q_{1L_1}(t)\widehat{y}%
_{0}\right\Vert }.
\end{equation*}
\end{itemize}
\end{remark}

\subsection{The asymptotic condition number $K\left( t,y_{0}\right)$}


\bigskip

The next theorem describes the long-time behavior of the condition number $%
K\left( t,y_{0}\right) $, worst condition number $K(t,y_0,\widehat{z}_0)$ by varying $\widehat{z}_0$. 

\begin{theorem}
\label{ThmKy} We have 
\begin{equation*}
K\left( t,y_{0}\right) \approx K_\infty\left( t,y_{0}\right),
\end{equation*}
where 
\begin{equation*}
K_\infty\left( t,y_{0}\right) := \frac{L^{\ast }!}{L_{1}!}\mathrm{e}%
^{\left( r_{1}-r_{j^{\ast }}\right) t}t^{L_{1}-L^{\ast }}\frac{\left\Vert
Q_{1L_{1}}(t)\right\Vert }{\left\Vert Q_{j^\ast L^\ast}(t) \widehat{y}%
_{0}\right\Vert },  \label{sim2}
\end{equation*}
with precision 
\begin{equation*}
\frac{\epsilon(t)+\epsilon(t,\widehat{y}_0)}{1-\epsilon(t,%
\widehat{y}_0)}
\end{equation*}
whenever $\epsilon(t,\widehat{y}_0)<1$ ($\epsilon(t)$ defined in Proposition  \ref{Lemma2} and $\epsilon(t,\widehat{y}_0)$ defined in Proposition \ref{Lemma1}). Moreover, we have 
\begin{equation*}
K\left( t,y_{0}\right) \sim K_\infty\left( t,y_{0}\right),\ t\rightarrow
+\infty.  \label{simKy}
\end{equation*}
\end{theorem}

\begin{proof}
Proposition \ref{Lemma2} says what is the asymptotic form of $\mathrm{e}^{tA}$ and how much it is dominant: we have
\begin{equation*}
\mathrm{e}^{tA}\approx \mathrm{e}^{r_1t}\frac{t^{L_1}}{L_1!} Q_{1L_1}(t)
\end{equation*}
with precision $\epsilon(t)$. Proposition \ref{Lemma1} says what is the asymptotic form of $\mathrm{e}^{tA}\widehat{y}_0$ and how much it is dominant: we have
\begin{equation*}
\mathrm{e}^{tA} \widehat{y}_{0}\approx \mathrm{e}^{r_{j^{\ast }}t}\frac{%
t^{L^{\ast }}}{L^{\ast }!}Q_{j^\ast L^{\ast}}(t)\widehat{y}_{0}
\end{equation*}
with precision $\epsilon(t,\widehat{y}_0)$. The first part of the theorem regarding $\approx$ follows by using Remark \ref{Remark fg}. The second part regarding $\sim$ follows since $\epsilon(t)\rightarrow 0$ and $%
\epsilon(t,\widehat{y}_0)\rightarrow 0$, $t\rightarrow +\infty$.
\end{proof}

We define the function
$$
t\rightarrow K_\infty(t,y_0),\ t\in\mathbb{R},
$$
as the \emph{asymptotic condition number} of the problem (\ref{due}).

\begin{remark}
\label{KtAy} \quad

\begin{itemize}
\item[1.] The asymptotic condition number of the problem (\ref{due}):
\begin{itemize}
\item is bounded and away from zero as $t$ varies if $j^\ast=1$ and $L^\ast=L_1$;

\item diverges polynomially to infinite, as $t\rightarrow +\infty$, if $j^\ast=1$ and $L^\ast<L_1$;

\item diverges exponentially to infinite, as $t\rightarrow +\infty$, if $j^\ast>1$. 
\end{itemize}
Therefore, the asymptotic condition number does not diverge to infinity if and only if $y_0$ is as dominant as possible, meaning that $y_0$ has the smallest possible primary index of dominance (i.e. $j^\ast = 1$) and simultaneously the largest possible secondary index of dominance (i.e. $L^\ast = 1$).


\item[2.] The generic case for $y_0$ is $j^{\ast }=1$ and $L^{\ast }=L_{1}$. In this generic case, we have
\begin{equation*}
K_\infty\left( t,y_{0}\right) = \frac{\left\Vert Q_{1L_{1}}(t)\right\Vert 
}{\left\Vert Q_{1L_{1}}(t)\widehat{y}_{0}\right\Vert }.
\end{equation*}
\end{itemize}
\end{remark}

\subsection{Is $K_\infty\left( t,y_{0}\right)$ the worst $%
K_\infty\left( t,y_{0},\widehat{z}_0\right)$?}

\label{wcab} By definition, the condition number $K\left(
t,y_{0}\right)$ is the worst condition number $K\left( t,y_{0},%
\widehat{z}_0\right)$, by varying $\widehat{z}_0$. Hence, an interesting question is the following. Does this fact hold asymptotically as $t\rightarrow +\infty$? Specifically, is the asymptotic condition number $K_\infty\left(
t,y_{0}\right)$ the worst asymptotic condition number  $K_\infty\left( t,y_{0},%
\widehat{z}_0\right)$, by varying $\widehat{z}_0$? In other words, do 
\begin{equation*}
\max\limits_{\substack{ \widehat{z}_0\in \mathbb{C}^{n}  \\ \Vert \widehat{z}%
_0\Vert =1}}\ \text{(worst case) and }\ t\rightarrow +\infty\ \text{%
(asymptotic behavior)}
\end{equation*}
commute? The answer is YES and it is given by the next theorem, which considers the ratio
\begin{equation}
\frac{K_\infty\left( t,y_{0},\widehat{z}_{0}\right)}{K_\infty\left(
t,y_{0}\right)}=\frac{L_1!}{L^{\ast\ast }!}\mathrm{e}^{\left( r_{j^{\ast
\ast }}-r_{1}\right) t}t^{L^{\ast \ast }-L_1}\frac{\left\Vert
Q_{j^{\ast\ast}L^{\ast\ast}}(t)\widehat{z}_{0}\right\Vert }{\left\Vert
Q_{1L_1}(t)\right\Vert } \label{rat}
\end{equation}
independent of $y_0$.
\begin{theorem} \label{wcy}
We have
\begin{equation}
\max\limits_{\substack{ \widehat{z}_0\in \mathbb{C}^{n}  \\ \Vert \widehat{z}%
_0\Vert =1}}\limsup\limits_{t\rightarrow +\infty}\frac{K_\infty\left(
t,y_{0},\widehat{z}_{0}\right)}{K_\infty\left( t,y_{0}\right)}=1.  \label{limsup}
\end{equation}
In particular:
\begin{itemize}
\item [a)] For any direction of perturbation $\widehat{z}_0$ such that $j^{\ast\ast}<1$ or $j^{\ast\ast}=1$ and $L^{\ast\ast}<L_1$, we have
$$
\lim\limits_{t\rightarrow +\infty}\frac{K_\infty\left(
t,y_{0},\widehat{z}_{0}\right)}{K_\infty\left( t,y_{0}\right)}=0.
$$
\item [b)] For any direction of perturbation $\widehat{z}_0$ such that $j^{\ast\ast}=1$ and $L^{\ast\ast}=L_1$, we have
$$ 
\frac{K_\infty\left(
t,y_{0},\widehat{z}_{0}\right)}{K_\infty\left( t,y_{0}\right)}\leq 1.
$$
\item [c)] There exists a direction of perturbation $\widehat{z}_0$, independent of $y_0$ and with $j^{\ast\ast}=1$ and $L^{\ast\ast}=L_1$, and a sequence $\{t_m\}_m$ with $t_m\rightarrow +\infty$, as $m\rightarrow \infty$, such that
$$
\lim\limits_{m\rightarrow \infty}\frac{K_\infty\left(
t_m,y_{0},\widehat{z}_{0}\right)}{K_\infty\left( t_m,y_{0}\right)}=1.
$$ 
\end{itemize}
\end{theorem}
\begin{proof}
Points a), b) and c) imply (\ref{limsup}). Points a) and b) immediately follows by (\ref{rat}). Now, we prove c). 

Consider a sequence $\{t_k\}_k$ such that $t_k\rightarrow +\infty$, $%
k\rightarrow \infty$, and a sequence $\{\widehat{z}_{0k}\}_k$ such that $\widehat{z}_{0k}\in\mathbb{C}^n$, $\left\Vert \widehat{z}%
_{0k}\right\Vert=1$ and
\begin{equation*}
\left\Vert Q_{1L_1}(t_k)\right\Vert=\left\Vert Q_{1L_1}(t_k)\widehat{z}%
_{0k}\right\Vert. 
\end{equation*}
By the compactness of
the unit sphere in $\mathbb{C}^n$, there exists a subsequence $\{\widehat{z}%
_{0k_m}\}_m$ of $\{\widehat{z}_{0k}\}_k$ converging to some $\widehat{z}%
_{0\infty}\in\mathbb{C}^n$ with $\left\Vert \widehat{z}_{0\infty}\right%
\Vert=1$.

By Proposition \ref{lemma2Qjl} (points 2) and 3)) and Proposition \ref{lemmaQjl} (points 1) and 3)), we obtain $j\left(\widehat{z}_{0\infty}\right)=1$ and $L_1\left(\widehat{z}%
_{0\infty}\right)=L_1$. In fact, for any index $m$, we have
$$
\left\vert\ \left\Vert Q_{1L_1}(t_{k_m})\widehat{z}%
_{0\infty}\right\Vert-\left\Vert Q_{1L_1}(t_{k_m})\right\Vert\ \right\vert \leq \sup\limits_{t\in \mathbb{R}} \left\Vert Q_{1L_1} (t)\right\Vert\left\Vert \widehat{z}_{0\infty}-\widehat{z}_{0k_m}\right\Vert,
$$
where the right-hand side goes to zero as $m\rightarrow \infty$. Therefore, there exists an index $m$ such that
$$
\left\Vert Q_{1L_1}(t_{k_m})\widehat{z}%
_{0\infty}\right\Vert\geq \frac{1}{2}\inf\limits_{t\in \mathbb{R}} \left\Vert Q_{1L_1} (t) \right\Vert,
$$ 
where the right-hand side is positive. Since
$
Q_{1L_1}(t_{k_m})$\ $\widehat{z}_{0\infty}\neq 0,
$
we cannot have  $j\left(\widehat{z}_{0\infty}\right)>1$, otherwise $Q_{1L_1}(t_{k_m})\widehat{z}_{0\infty}=0$. Hence, $j\left(\widehat{z}_{0\infty}\right)=1$. Once again since
$
Q_{1L_1}(t_{k_m})\widehat{z}_{0\infty}\neq 0,
$
we cannot have  $L_1\left(\widehat{z}_{0\infty}\right)<L_1$, otherwise $Q_{1L_1}(t_{k_m})\widehat{z}_{0\infty}=0$. Hence, $L_1\left(\widehat{z}%
_{0\infty}\right)=L_1$.



By using as direction of perturbation $\widehat{z}_{0\infty}$, we have $%
j^{\ast\ast}=1$ and $L^{\ast\ast}=L_1$. So 
\begin{eqnarray*}
\left\vert \frac{K_\infty\left( t_{k_m},y_{0},\widehat{z}_{0\infty}\right)%
}{K_\infty\left( t_{k_m},y_{0}\right)}-1\right\vert&=&\left\vert \frac{%
\left\Vert Q_{1L_1}(t_{k_m})\widehat{z}_{0\infty}\right\Vert }{\left\Vert
Q_{1L_1}(t_{k_m})\right\Vert }-1\right\vert \\
&\leq& \left\Vert \widehat{z}_{0\infty}-\widehat{z}_{0k_m}\right\Vert.
\end{eqnarray*}
We conclude that 
\begin{equation*}
\lim\limits_{m\rightarrow \infty}\frac{K_\infty\left( t_{k_m},y_{0},%
\widehat{z}_{0\infty}\right)}{K_\infty\left( t_{k_m},y_{0}\right)}=1.
\end{equation*}
\end{proof}


\begin{remark}\label{realeigen1}
In the case where $\Lambda_1$ consists of a real eigenvalue, the point c) is modified to:
\begin{itemize}
	\item [$c^{\prime}$)] There exists a direction of perturbation $\widehat{z}_0$, independent of $y_0$ and with $j^{\ast\ast}=1$ and $L^{\ast\ast}=L_1$, such that
\begin{equation}
K_\infty\left(t,y_{0},\widehat{z}_{0}\right)=K_\infty\left(t,y_{0}\right). \label{K=K}
\end{equation}
\end{itemize}
In fact, in this case $Q_{1L_1}(t)=Q_{1L_1}$ is independent of $t$ and so there exists $\widehat{z}_{0}\in\mathbb{C}^n$, $\left\Vert \widehat{z}%
_{0}\right\Vert=1$, independent of $t$ such that 
\begin{equation*}
\left\Vert Q_{1L_1}\right\Vert=\left\Vert Q_{1L_1}\widehat{z}%
_{0}\right\Vert. 
\end{equation*}
By using as direction of perturbation $\widehat{z}_{0}$, we have $%
j^{\ast\ast}=1$ and $L^{\ast\ast}=L_1$ and then  we obtain (\ref{K=K}) by (\ref{rat}).

\end{remark}
\subsection{The asymptotic global condition number $K_\infty^{+}\left(t,\right) $}

\label{SKtA}



Next theorem describes the long-time behavior of the global condition number $K\left( t\right) $, worst condition number $K\left( t,y_0\right) $ by varying $y_0$.

\begin{theorem}
\label{ThmK} We have 
\begin{equation*}
K\left( t\right) \approx K_\infty^{+}(t),
\end{equation*}
where 
\begin{equation}  \label{sim3}
K_\infty^{+}\left( t\right) := \frac{1}{L_1!L_{q}!}\mathrm{e}^{\left(
r_{1}-r_{q}\right) t}t^{L_{1}+L_q} \left\Vert Q_{1L_{1}}(t) \right\Vert\
\cdot \left\Vert Q_{qL_{q}}(-t)\right\Vert
\end{equation}
with precision 
\begin{equation*}
\epsilon(t)+\epsilon(t,-A)+\epsilon(t)\epsilon(t,-A),
\end{equation*}
where $\epsilon(t,-A)$ is $\epsilon(t)$ for the matrix $-A$. Moreover, we have 
\begin{equation*}
K\left( t\right) \sim K^{+}_\infty(t),\ t\rightarrow +\infty.  \label{simK}
\end{equation*}
\end{theorem}

\begin{proof}
Propositions \ref{Lemma2} says what are the asymptotic forms of $\mathrm{e}^{tA}$ and $\mathrm{e}^{-tA}$ and how much they are dominant: we have
\begin{equation*}
\mathrm{e}^{tA}\approx \mathrm{e}^{r_1t}\frac{t^{L_1}}{L_1!} Q_{1L_1}(t)
\end{equation*}
with precision $\epsilon(t)$ and 
\begin{equation*}
\mathrm{e}^{-tA} =\mathrm{e}^{t(-A)}\approx \mathrm{e}^{-r_qt}\frac{t^{L_{q}}}{L_{q}!}(-1)^{L_q}
Q_{qL_{q}}(-t)
\end{equation*}
with precision $\epsilon(t,-A)$. For the latter, remind (\ref{q+1-}) and Proposition \ref{-A}. The first part of the theorem regarding $\approx$ follows by using
Remark \ref{Remark fg}. The second part regarding $\sim$ follows since $%
\epsilon(t)\rightarrow 0$ and $\epsilon(t,-A)\rightarrow 0$, $%
t\rightarrow +\infty$.
\end{proof}

We  define the function
$$
t\rightarrow K^{+}_\infty(t),\ t\in\mathbb{R},
$$
as the \emph{asymptotic global condition number} of the problem (\ref{due}).
%This term is reserved to another function $K_\infty(A)$ defined in Subsection \ref{SoverKtA} below.






\subsection{Is $K^+_\infty\left( t\right)$ the worst $K_\infty\left(
t,y_{0}\right)$?}

\label{sss}

By definition, the condition number $K\left(
t\right)$ is the worst condition number $K\left( t,y_{0}\right)$, by varying $y_0$. Hence, as in Subsection \ref{wcab}, an interesting question is the following. Does this fact hold asymptotically as $t\rightarrow +\infty$? Specifically, is the asymptotic condition number $%
K^+_\infty\left( t\right)$ the worst asymptotic condition number $K_\infty\left(
t,y_{0}\right)$, by varying $y_0$? In other words, do 
\begin{equation*}
\max\limits_{\substack{ y_0\in \mathbb{C}^{n}  \\ y_0\neq 0}}\ \text{(worst case) and }\ t\rightarrow +\infty\ \text{(asymptotic
behavior)}
\end{equation*}
commute? Unlike Subsection \ref{wcab}, here the answer is NO and it is given by the next theorem, which considers
\begin{equation}
K_\infty\left( t\right) := \frac{1}{L_{1}!}\mathrm{e}^{\left(
r_{1}-r_{q}\right) t}t^{L_{1}}\left\Vert
Q_{1L_{1}}(t)\right\Vert\cdot\left\Vert Q^e_{q}(-t)|_{U^e_{q}}\right\Vert,  \label{Kover}
\end{equation}
where $Q^e_{q}(-t)|_{U^e_{q}}$ is defined in Subsection \ref{sssQj0}, and the ratio
\begin{equation}
\frac{K_\infty\left( t,y_{0}\right)}{K_\infty\left( t\right)}%
=L^{\ast}!\mathrm{e}^{\left( r_{q}-r_{j^\ast}\right) t}t^{-L^{\ast}}\frac{1}{%
\left\Vert Q_{j^{\ast}L^{\ast}}(t)\widehat{y}_{0}\right\Vert\left\Vert
Q^e_{q}(-t)|_{U^e_{q}}\right\Vert}.  \label{rat2}
\end{equation}



\begin{theorem}
\label{asworst2} We have
\begin{equation}
\max\limits_{\substack{ y_0\in \mathbb{C}^{n}  \\ y_0\neq 0}}%
\limsup\limits_{t\rightarrow +\infty}\frac{K_\infty\left( t,y_{0}\right)}{%
K_\infty\left( t\right)}=1.   \label{limsup2}
\end{equation}
In particular:
\begin{itemize}
\item [a)] For any initial value $y_0$ such that $j^{\ast}<q$ or $j^{\ast}=q$ and $L^{\ast}>0$, we have
$$
\lim\limits_{t\rightarrow +\infty}\frac{K_\infty\left(
t,y_{0}\right)}{K_\infty\left( t\right)}=0.
$$
\item [b)] For any initial value $y_0$ such that $j^{\ast}=q$ and $L^{\ast}=0$, we have
$$ 
\frac{K_\infty\left(
t,y_{0}\right)}{K_\infty\left( t\right)}\leq 1.
$$
\item [c)] There exist an initial value $y_0$, with $j^\ast=q$ and $L^\ast=0$, and a sequence $\{t_m\}_m$ with $t_m\rightarrow +\infty$, as $m\rightarrow \infty$, such that
$$
\lim\limits_{m\rightarrow \infty}\frac{K_\infty\left(
t_m,y_{0}\right)}{K_\infty\left( t_m\right)}=1.
$$
\item [d)] For the initial value $y_0$ at point c), there exists a direction of perturbation $\widehat{z}_0$ with $j^{\ast\ast}=1$ and $L^{\ast\ast}=L_1$, and a subsequence $\{t_{m_s}\}_s$ of the sequence $\{t_{m}\}_m$ at point c), such that
$$
\lim\limits_{s\rightarrow \infty}\frac{K_\infty\left(
t_{m_s},y_{0},\widehat{z}_{0}\right)}{K_\infty\left( t_{m_s}\right)}=1.
$$
\end{itemize} 
\end{theorem} 
\begin{proof}
Points a), b) and c) imply (\ref{limsup2}). Point a) follows by (\ref{rat2}) (remind point 4 in Proposition \ref{lemmaQjl} and Remark \ref{remQ0}).

Point b) follows by point 1 in Remark \ref{remQ00} and by observing that, for such $y_0$, we have $y_0\in U^e_{q}$ and then
$$
Q_{q0}(t)\widehat{y}_0=Q^e_{q}(t)\widehat{y}_0.
$$

For the point c), we proceed as in the proof of Theorem \ref{wcy}. Consider a
sequence $\{t_k\}_k$ such that $t_k\rightarrow +\infty$, $k\rightarrow
\infty$, and a sequence $\{\widehat{y}_{0k}\}_k$, where $\widehat{y}_{0k}\in U^e_{q}$ and $\left\Vert \widehat{y}_{0k}\right\Vert=1$, such that
\begin{equation}
\left\Vert Q_{q0}(t_k)\widehat{y}_{0k}\right\Vert=\left\Vert Q^e_{q}(t_k)\widehat{y}_{0k}\right\Vert=\frac{1}{\left\Vert Q^e_{q}(-t_k)|_{U^e_{q}}
\right\Vert}  \label{K/K-1}
\end{equation}
(recall point 1 in Remark \ref{remQ00}).  There exists a
subsequence $\{\widehat{y}_{0k_m}\}_m$ of $\{\widehat{y}_{0k}\}_k$ converging to some $%
\widehat{y}_{0\infty}\in U^e_q$ with $\left\Vert \widehat{y}_{0\infty}\right\Vert=1$. By using $%
\widehat{y}_{0\infty}$ as initial value, we have $j^\ast=q$ and $L^\ast=0$ (we have $l_i(\widehat{y}_{0\infty})=0$ for any $\lambda_i\in\Lambda_q$, see Proposition \ref{propliu}). Therefore,
\begin{eqnarray*}
\left\vert \frac{K_\infty\left( t_{k_m},\widehat{y}_{0\infty}\right)}{K%
_\infty\left( t_{k_m}\right)}-1\right\vert&=&\left\vert \frac{1}{%
\left\Vert Q_{q0}(t_{k_m})\widehat{y}_{0\infty}\right\Vert\left\Vert
Q^e_{q}(-t_{k_m})|_{U^e_{q}}\right\Vert}-1\right\vert \\
&=&\left\vert\frac{\Vert Q_{q0}(t_{k_m})\widehat{y}_{0k_m}\Vert}{\Vert Q_{q0}(t_{k_m})\widehat{y}_{0\infty}\Vert}-1\right\vert\\
&\leq& \frac{\left\Vert Q_{q0}(t_{k_m})\right\Vert}{\left\Vert Q_{q0}(t_{k_m})\widehat{y}_{0\infty}\right\Vert}\left\Vert \widehat{y}_{0k_m}-\widehat{y}_{0\infty}\right\Vert  \ \ \ \text{(use (\ref{K/K-1}))}\\
&\rightarrow& 0,\ m\rightarrow \infty\ \ \ \text{(use 2) and 4) in Proposition \ref{lemmaQjl}).}
\end{eqnarray*}
We conclude that 
\begin{equation*}
\lim\limits_{m\rightarrow \infty}\frac{K_\infty\left(
t_m,\widehat{y}_{0\infty}\right)}{K_\infty\left( t_m\right)}=1.
\end{equation*}

For the point d), repeat the proof of point c) in Theorem \ref{wcy} with the sequence $\{t_k\}_k$  replaced by the sequence $\{t_m\}_m$ above in point c) of this proof. In this way, we show that there exists a direction of perturbation $\widehat{z}_0$ with $j^{\ast\ast}=1$ and $L^{\ast\ast}=L_1$, and a subsequence $\{t_{m_s}\}_s$ of the sequence $\{t_{m}\}_m$, such that
$$
\lim\limits_{s\rightarrow \infty}\frac{K_\infty\left(
	t_{m_s},\widehat{y}_{0\infty},\widehat{z}_{0}\right)}{K_\infty\left( t_{m_s},\widehat{y}_{0\infty}\right)}=1
$$
and then
$$
\lim\limits_{s\rightarrow \infty}\frac{K_\infty\left(
	t_{m_s},\widehat{y}_{0\infty},\widehat{z}_{0}\right)}{K_\infty\left( t_{m_s}\right)}=\lim\limits_{s\rightarrow \infty}\frac{K_\infty\left(
	t_{m_s},\widehat{y}_{0\infty}\right)}{K_\infty\left( t_{m_s}\right)}\cdot \lim\limits_{s\rightarrow \infty}\frac{K_\infty\left(
	t_{m_s},\widehat{y}_{0\infty},\widehat{z}_{0}\right)}{K_\infty\left( t_{m_s},\widehat{y}_{0\infty}\right)}=1.
$$

\end{proof}

\begin{remark}\label{realeigen2}
In the case where $\Lambda_q$ consists of real eigenvalue, by recalling (\ref{rat2}) and point 2 in Remark \ref{remQ00}, the point c) is modified to:
\begin{itemize}
	\item [$c^{\prime}$)] For any initial value $y_0\in U^e_{q}$, we have
\begin{equation*}
K_\infty\left(t,y_{0}\right)=K_\infty\left(t\right). \label{KK=KK}
\end{equation*}
\end{itemize}
In addition, in the case where $\Lambda_1$ consists of a real eigenvalue, the point d) is modified to:
\begin{itemize}
	\item [$d^{\prime}$)]There exist a direction of perturbation $\widehat{z}_0$ with $j^{\ast\ast}=1$ and $L^{\ast\ast}=L_1$ such that, for any initial value $y_0\in U^e_{q}$, we have
\begin{equation*}
K_\infty\left(t,y_{0},\widehat{z}_0\right)=K_\infty\left(t,y_{0}\right)=K_\infty\left(t\right).
\end{equation*}
\end{itemize}
See Remark \ref{realeigen1}.

\end{remark}

\subsection{The global asymptotic condition number $K_\infty\left(t\right) $} \label{ssss}

\label{SoverKtA}

Theorem \ref{asworst2} says that $K_\infty\left( t\right)$ in (\ref{Kover}), %i.e.
not $K^+_\infty\left( t\right)$ in (\ref{sim3}), is the worst asymptotic
condition number $K_\infty\left( t,y_0\right)$, by varying $y_0$,
namely the worst asymptotic condition $K_\infty\left( t, y_0,%
\widehat{z}_0\right)$, by varying both $y_0$ and $\widehat{z}_0$.

We define the function
$$
t\rightarrow K_\infty(t),\ t\in\mathbb{R},
$$
as the \emph{global asymptotic condition number} of the problem (\ref{due}).

\begin{remark} \label{KtA}
	\quad
	\begin{itemize}
	\item [1.] Observe that $K_\infty(t)$ is the global asymptotic condition number, i.e. the worst-case asymptotic condition number $K_\infty(t, y_0)$ as $y_0$ varies. In contrast, $K_\infty^+(t)$ is the \textit{asymptotic global condition number}, i.e. the asymptotic form of the worst-case condition number $K(t, y_0)$ as $y_0$ varies.   

	\item [2.] Both the global asymptotic condition number and the asymptotic global condition number of the problem (\ref{due}):

	\begin{itemize}
		\item 
		are bounded and away from zero as $t$ varies if $q=1$ and $L_1=0$;

		\item  diverge polynomially to infinite, as $t\rightarrow +\infty$, if $q=1$ and $L_1>0$;

		\item diverge exponentially to infinite, as $t\rightarrow +\infty$, if $q>1$.
	\end{itemize}
	Therefore, the they do not diverges to infinite if and only if all the eigenvalues of $A$ have the same real part, i.e. they lie in a vertical line of the complex plane, and are simple.
	\end{itemize}
\end{remark}



Observe that $K^+_\infty(t)$ can be significantly larger than $K%
_\infty(t)$: we have 
\begin{equation*}
\frac{K_\infty\left( t\right)}{K^+_\infty\left( t\right)}=L_q!
t^{-L_q}\frac{\left\Vert Q^e_{q}(-t)|_{U^e_{q}}\right\Vert}{\left\Vert
Q_{qL_q}(-t)\right\Vert}
\end{equation*}
and then 
\begin{equation*}
\lim\limits_{t\rightarrow +\infty}\frac{K_\infty\left( t\right)%
}{K^+_\infty\left( t\right)}=0
\end{equation*}
for $L_q>0$ and
$$
\frac{K_\infty\left( t\right)}{K^+_\infty\left(
t\right)}=\frac{\left\Vert Q^e_{q}(-t)|_{U^e_{q}}\right\Vert}{\left\Vert
Q_{q0}(-t)\right\Vert}=\frac{\left\Vert Q_{q0}(-t)|_{U^e_{q}}\right\Vert}{\left\Vert
Q_{q0}(-t)\right\Vert}\leq 1
$$
for $L_q=0$.







In the next example, we illustrate the difference between $K^+_\infty(A)$ and $K_\infty(A)$.
\begin{example}
 Consider the one Jordan block matrix
$$
A_1=V
\left[
\begin{array}{rr}
1 & 1\\
0 & 1
\end{array}
\right]W
$$
and the diagonalizable matrix
$$
A_2=V
\left[
\begin{array}{rr}
1 & 0\\
0 & -1
\end{array}
\right]W,
$$
where
$$
V=\left[
\begin{array}{rr}
1 & \frac{1}{2}\\
1 &  1
\end{array}
\right]\text{\ \ and\ \ }
W=V^{-1}=2\left[
\begin{array}{rr}
1 &  -\frac{1}{2}\\
-1 & 1
\end{array}
\right].
$$

For the matrix $A_1$, we have
$$
\Lambda=\{1\},\ q=1\text{\ \ and\ \ }L_1=L_q=1
$$
and then
\begin{eqnarray*}
&&K_\infty(t)=t\left\Vert Q_{11}(t)\right\Vert \left\Vert Q^e_{1}(-t)|_{U^e_{1}}\right\Vert\\
&&K^+_\infty(t)=t^2\left\Vert Q_{11}(t)\right\Vert \left\Vert Q_{11}(-t)\right\Vert
\end{eqnarray*}
where 
\begin{eqnarray*}
&&Q_{11}(t)=Q_{11}(-t)=P_{11}=v^{(1,1,1)}w^{(1,1,2)}=\left[
\begin{array}{rr}
-2 & 2\\
-2 & 2
\end{array}
\right]\\
&&\text{(remind point 2 in Remark \ref{mi})}\\
&&Q^e_{1}(-t)|_{U^e_{1}}=I|_{U^e_{1}}\\
&&\text{(remind point 2 in Remark \ref{remQ00}).}
\end{eqnarray*}
Thus, for the Euclidean norm as vector norm, we have, since $\Vert P_{11}\Vert_2=4$, 
\begin{eqnarray*}
&&K_\infty(t)=4t\\
&&K^+_\infty(t)=16t^2.
\end{eqnarray*}


For the matrix $A_2$, we have
$$
\Lambda=\{1,-1\},\ q=2\text{\ \ and\ \ }L_1=L_q=0
$$
and then
\begin{eqnarray*}
&&K_\infty(t)=\mathrm{e}^{2t}\left\Vert Q_{10}(t)\right\Vert \left\Vert Q^e_{2}(-t)|_{U^e_2}\right\Vert\\
&&K^+_\infty(t)=\mathrm{e}^{2t}\left\Vert Q_{10}(t)\right\Vert \left\Vert Q_{20}(-t)\right\Vert,
\end{eqnarray*}
where
\begin{eqnarray*}
&&Q_{10}(t)=P_{10}=v^{(1,1,1)}w^{(1,1,1)}=\left[
\begin{array}{rr}
2 & -1\\
2 &  -1
\end{array}
\right]\\
&&Q_{20}(-t)=P_{20}=v^{(2,1,1)}w^{(2,1,1)}=\left[
\begin{array}{rr}
-1 &  1\\
-2 &  2
\end{array}
\right]\\
&&Q^e_{2}(-t)|_{U^e_2}=I|_{U^e_2}.
\end{eqnarray*}
Thus, for the Euclidean norm as vector norm, we have, since $\Vert P_{10}\Vert_2=\Vert P_{20}\Vert_2=\sqrt{10}$, 
\begin{eqnarray*}
&&K_\infty(t)=\sqrt{10}\mathrm{e}^{2t}\\
&&K^+_\infty(t)=10\mathrm{e}^{2t}.
\end{eqnarray*}

In Figure \ref{KKoverline} for the matrix $A_1$, we see in logarithmic scale the condition numbers $K(t)$ (blu dashed line) , $K^+_\infty(t)$ (red dashed line) and $K_\infty(t)$ (red dashed line), $t\in[0,100]$. From the beginning, $K(t)$ is  not distinguishable from its asymptotic version $K^+_\infty(t)$.

