\begin{proposition}
	The branches $h_i$, $i\in I$, are either monotonically increasing or decreasing.
\end{proposition}

\begin{proof}

Let $i\in I$. We show that there are no interiors points of $D_i$ where the derivative $h_i^\prime$ is zero.

For $\beta$ interior point of $D_i$, we have 
\begin{eqnarray}
h_i^\prime(\beta)&=&\frac{d}{d\beta}H(x_i(\beta),\beta)\notag \\
&=&\frac{\partial H}{\partial x}(x_i(\beta),\beta)x_i^{\prime}(\beta)+\frac{\partial H}{\partial \beta}(x_i(\beta),\beta)\notag \\
&=&\frac{\partial H}{\partial \beta}(x_i(\beta),\beta)\notag \\
&=&\frac{V_1\sin(x_i(\beta)+\beta)}{(1+V_1\cos(x_i(\beta)+\beta))^2}f^{\max}_{V_1,W_1}(x_i(\beta)),\notag  \\
\label{dbeta}
\end{eqnarray}
where $f^{\max}_{V_1,W_1}(x_i(\beta))>0$ (see Lemma \ref{maxminf}, or the definition (\ref{fVW}), by reminding $V_1,W_1\in[0,1)$). Then, for $h^\prime_i(\beta)=0$, we have
\begin{eqnarray}	
		&&-V_1\sin(x+\alpha)-W_1\sin \alpha+V_1W_1\sin x=0\notag \\
		&&-\sin(x+\alpha)+\sin(x+\beta)-V_1\sin(\alpha-\beta)=0\notag \\
		&&\sin(x+\beta)=0,\notag\\
		\label{systemthree}
\end{eqnarray}
where $x=x_i(\beta)$ and $\alpha=\alpha^{\max}_{V_1W_1}(x_i(\beta))$.

Regarding the equations in (\ref{systemthree}), observe that:
\begin{itemize}
	\item The first equation is the equation for the stationary points $\alpha$ of $f_{V_1W_1}(\cdot,x_i(\beta))$ (recall (\ref{sinsin})): $\alpha=\alpha^{\max}_{V_1W_1}(x_i(\beta))$ is a stationary point of $f_{V_1W_1}(\cdot,x_i(\beta))$.
	\item The second equation is the equation for the stationary points of $H(\cdot,\beta)$ (recall (\ref{eq})): $x=x_i(\beta)$ is a stationary point of $H(\cdot,\beta)$.
	\item The third equation is the equation $h_i^{\prime}(\beta)=0$ (recall (\ref{dbeta})).
\end{itemize} 


	It is not difficult to show that $(\alpha,x,\beta)\in\mathbb{R}^3$ is a solution of these three equations if and only $\alpha$, $x$ and $\beta$ are multiplies of $\pi$. Thus,
\begin{equation}
	h_i(\beta)\neq 0,\ \beta\in (0,\pi). \label{hprimeneq0}
\end{equation}



\end{proof}

Now, we show that the functions $H^{\max}(\beta)$ and $H^{\min}(\beta)$, $\beta\in[0,\pi]$, are monotonically increasing and descreasing, respectively.


\begin{proposition}
$H^{\max}$ and $H^{\min}$ are continuous functions.
\end{proposition}
\begin{proof}
	The proof is given for $H^{\max}$. The proof for $H^{\min}$ is similar.

	Let $\beta\in\mathbb{R}$ and let $\beta_n$ be a sequence in $\mathbb{R}$ such that $\lim\limits_{n\rightarrow \infty}\beta_n=\beta$. We show that
	\begin{equation}
	\lim\limits_{n\rightarrow \infty}H^{\max}(\beta_n)=H^{\max}(\beta). \label{limitH}
\end{equation}

	For any index $n$, let $x_n\in\mathbb{R}$ be such that $H(x_n,\beta_n)=H^{\max}(\beta_n)$. Moreover, let $x\in\mathbb{R}$ be such that $H(x,\beta)=H^{\max}(\beta)$. We have
	\begin{eqnarray*}
		H^{\max}(\beta_n)-H^{\max}(\beta)&=&H(x_n,\beta_n)-H(x,\beta)\\
		&=&H(x_n,\beta_n)-H(x,\beta_n)+H(x,\beta_n)-H(x,\beta)\\
		&\geq&H(x,\beta_n)-H(x,\beta),
	\end{eqnarray*}
	since $H(x_n,\beta_n)-H(x,\beta_n)\geq 0$. Moreover, we also have
	\begin{eqnarray*}
		H^{\max}(\beta_n)-H^{\max}(\beta)&=&H(x_n,\beta_n)-H(x,\beta)\\
		&=&H(x_n,\beta_n)-H(x_n,\beta)+H(x_n,\beta)-H(x,\beta)\\
		&\leq&H(x_n,\beta_n)-H(x_n,\beta),
	\end{eqnarray*}
	since $H(x_n,\beta)-H(x,\beta)\leq 0$. Thus
	\begin{equation}
		H(x,\beta_n)-H(x,\beta)\leq H^{\max}(\beta_n)-H^{\max}(\beta)\leq H(x_n,\beta_n)-H(x_n,\beta). \label{<DH<}
	\end{equation}

	Since the function $H(y,\cdot)$ is continuous uniformly with respect to $y\in\mathbb{R}$ (we have
	$$
	\vert H(y,\beta_1)-H(y,\beta_2)\vert \leq \max\limits_{(z,\beta)\in\mathbb{R}^2}\left\vert \frac{\partial H}{\partial \beta}(z,\beta)\right\vert \vert \beta_1-\beta_2\vert 
	$$
	for $\beta_1,\beta_2\in\mathbb{R}$), we obtain (\ref{limitH}), by letting $n\rightarrow \infty$ in (\ref{<DH<}).
\end{proof}

By (\ref{Hmaxmin}), we see that the continuous functions $H^{\max}$ and $H^{\min}$, considered in $[0,\pi]$, are the union of branches $h_i$ attached one after the other as in Figure \ref{Hmin}, where we see the junction of two consecutive branches $h_i$ and $h_j$.

