\begin{proposition}\label{monbr0}
The first branch for $H^{\max}$ in $[0,\pi]$ is increasing and the first branch for $H^{\min}$ in $[0,\pi]$ is decreasing.
\end{proposition}
\begin{proof}
Let $H^{\max}(0)=H(x_0^{\max},0)$ and  $H^{\min}(0)=H(x_0^{\min},0)$, where  $x_0^{\max}$ and $x_0^{\min}$ are given in the last theorem of Appendix B. Moreover, let $i^\ast\in I$ be the index of the first branch of $H^{\max}$ or $H^{\min}$. We have $x_{i^{\ast}}(0)=x^{\max}$ or $x_{i^\ast}(0)=x^{\min}$. 







First, we consider $H^{\max}$ and the case $V_1<\frac{2W_1}{1+W_1}$, where $\cos x_0^{\max}=-Q_1$, with $0<Q_1<1$. By (\ref{dbeta}), we have
\begin{equation*}
	h_{i^\ast}^\prime(0)=\frac{V_1\sin  x_0^{\max}}{(1-Q_1V_1)^2}f^{\max}_{V_1,W_1}( x_0^{\max}),\notag  \\
\end{equation*}
where $f^{\max}_{V_1,W_1}( x_0^{\max})>0$. There are two values $x_0^{\max}$ with $\cos x_0^{\max}=-Q_1$, one in $(-\pi,-\frac{\pi}{2})$ and the other in $(\frac{\pi}{2},\pi)$, corresponding to two branches $x_i(\beta)$ and two branches $h_i(\beta)$ such that $H(x_i(0),0)=h_i(0)=H^{\max}(0)$ (see the first two rows of Figure \ref{branches}, where $V_1<\frac{2W_1}{1+W_1}$ holds). By taking $x_0^{\max}\in(\frac{\pi}{2},\pi)$, we have $\sin x_0^{\max}>0$ and then $h_i^\prime(0)>0$. This shows that the the first branch of $H^{\max}$ is increasing.


When we consider $H^{\max}$ in the case $V_1\geq \frac{2W_1}{1+W_1}$ or $H^{\min}$, we have that $x_0^{\max}$ and $x_0^{\min}$ are multiple of $\pi$ and then $h_i^\prime(0)=0$. Therefore, we now look at the sign of $\sin(x_{i^\ast}(\beta)+\beta)$ in (\ref{dbeta}) for $\beta$ in a right neighborhood of zero.

By taking into account the value of $x_{i^\ast}(0)$, this sign is determined by the sign of
$$
\frac{d}{d\beta}\left(x_{i^\ast}(\beta)+\beta\right)|_{\beta=0}=x_{i^\ast}^\prime(0)+1.
$$
By (\ref{odexi}), we have
\begin{equation}
	\frac{\partial^2 H}{\partial x^2}(x_{i^\ast}(0),0)x_{i^\ast}^\prime(0)+\frac{\partial^2 H}{\partial \beta\partial x}(x_{i^\ast}(0),0)=0. \label{odexi0}
\end{equation}
Observe that, for $x_{i^\ast}(0)=x_0^{\max}$, we have
\begin{equation}
	\frac{\partial^2 H}{\partial x^2}(x_{i^\ast}(0),0)<0 \label{max<0}
\end{equation}
since $x_0^{\max}$ is a maximum of $H(\cdot,0)$, and, for $x_{i^\ast}(0)=x_0^{\min}$, we have
\begin{equation}
	\frac{\partial^2 H}{\partial x^2}(x_{i^\ast}(0),0)>0 \label{min>0}
\end{equation}
since $x_0^{\min}$ is a minimum of $H(\cdot,0)$. By (\ref{odexi0}), we have
\begin{equation}
x_{i^\ast}^\prime(0)+1=\frac{\frac{\partial^2 H}{\partial x^2}(x_{i^\ast}(0),0)-\frac{\partial^2 H}{\partial \beta\partial x}(x_{i^\ast}(0),0)}{\frac{\partial^2 H}{\partial x^2}(x_{i^\ast}(0),0)}. \label{xiprime+1}
\end{equation}
where (see Appendix C)
\begin{equation}
\frac{\partial^2 H}{\partial x^2}(x_{i^\ast}(0),0)-\frac{\partial^2 H}{\partial \beta\partial x}(x_{i^\ast}(0),0)=\frac{\left(f^{\max}_{V_1W_1}\right)^{\prime\prime}(x_{i^\ast}(0))}{\left(1+V\cos x_{i^\ast}(0)\right)^2}, \label{partialminus}
\end{equation}

Now, consider $H^{\max}$ in the case $V_1\geq \frac{2W_1}{1+W_1}$, where $x_{i^\ast}(0)=x_0^{\max}$ is an odd multiple of $\pi$. Since the odd multiples of $\pi$ are minimum values of $f^{\max}_{V_1W_1}$ (recall Lemma \ref{maxminf}), we have
$$
\left(f^{\max}_{V_1W_1}\right)^{\prime\prime}(x_{i^\ast}(0))>0.
$$
Then. by (\ref{max<0}) and (\ref{xiprime+1}), we obtain
$$
x_{i^\ast}^\prime(0)+1<0
$$
and, then, $x_{i^\ast}(\beta)+\beta$ is decreasing for $\beta$ in a right neighborhhod of zero. Since $x_{i^\ast}(0)=x_0^{\max}$ is an odd multiples of $\pi$, this means that $\sin(x_{i^\ast}(\beta)+\beta)$ is positive for $\beta$ in a right neighborhhod of zero. Therefore $h_{i^\ast}^\prime(\beta)$ is positive for $\beta$ in a right neighrborhhod of zero, , i.e. $h_{i^\ast}$ is increasing.

Finally, consider $H^{\min}$, where $x_{i^\ast}(0)=x_0^{\min}$ is an even multiple of $\pi$. Since the even multiple of $\pi$ are maximum values of $f^{\max}_{V_1W_1}$ (recall Lemma \ref{maxminf}), we have
$$
\left(f^{\max}_{V_1W_1}\right)^{\prime\prime}(x_{i^\ast}(0))<0.
$$
Then. by (\ref{min>0}) and (\ref{xiprime+1}), we obtain
$$
x_{i^\ast}^\prime(0)+1<0
$$
and, then, $x_{i^\ast}(\beta)+\beta$ is decreasing for $\beta$ in a right neighborhhod of zero. Since $x_{i^\ast}(0)=x_0^{\min}$ is an even multiple of $\pi$, this means that $\sin(x_{i^\ast}(\beta)+\beta)$ is negative for $\beta$ in a right neighborhhod of zero. Therefore $h_{i^\ast}$ is decreasing. 

Observe that for $V_1<W_1$, $x_0^{\min}$ can be also an odd multiple of $\pi$. Therefore, for $V_1<W_1$, there are  two branches $x_i(\beta)$ and only one branch $h_i(\beta)$ such that $H(x_i(0),0)=h_i(0)=H^{\min}(0)$ (see the first row of Figures \ref{branches} and \ref{branchespartial}).

\end{proof}

\begin{proposition} \label{monbr}
The branches forming the functions $H^{\max}$ in $[0,\pi]$ are all increasing and the branches forming the functions $H^{\min}$ in $[0,\pi]$ are all decreasing.  
\end{proposition}

\begin{proof}
	The proof is given for $H^{\max}$. The proof for $H^{\min}$ is similar.

	We show that if a branch forming $H^{\max}$ is increasing, then the successive branch is also increasing. Since  the previous Proposition \ref{monbr0} states that the first branch of $H^{\max}$ is increasing, it follows that all the branches of $H^{\max}$ are increasing. 

	Consider two consecutive branches $h_i$ and $h_j$ of $H^{\max}$, with $h_i$ being increasing. Let $\beta^{\ast}\in(0,\pi)$ denote the point where these two branches meet. By reminding   (\ref{dbeta}), we have
	$$
	\frac{\partial H}{\partial \beta}(x_i(\beta^\ast),\beta^\ast)=h_i^\prime(\beta^\ast).
	$$
	By (\ref{hprimeneq0}) and the fact that $h_i$ is increasing, we obtain
	$$
	\frac{\partial H}{\partial \beta}(x_i(\beta^\ast),\beta^\ast)=h_i^\prime(\beta^\ast)>0.
	$$
This shows that, for $\beta$ in a right neighborhood of $\beta^\ast$, we have
$$
H(x_i(\beta^\ast),\beta)>H(x_i(\beta^\ast),\beta^\ast)
$$
and then
$$
H^{\max}(\beta)\geq H(x_i(\beta^\ast),\beta)>H(x_i(\beta^\ast),\beta^\ast)=H^{\max}(\beta^\ast).
$$
This shows that the branch $h_j$ is increasing. 


\end{proof}

By the previous Proposition \ref{monbr}, we conclude that the functions $H^{\max}$ and $H^{\min}$, considered in $[0,\pi]$, are monotonically increasing and descreasing, respectively.





Therefore, in $[0,\pi]$, $H^{\max}$ is monotonically increasing from the minimum value $H^{\max}(0)$ to the maximum value $H^{\max}(\pi)$ (see (\ref{MAXMAX}): the maximum is obtained for $\beta$ odd multiple of $\pi$) and $H^{\min}$ is monotonically decreasing from the maximum value $H^{\min}(0)$ to the minimum value $H^{\min}(\pi)$ (see (\ref{MINMIN}): the minimum is obtained for $\beta$ odd multiple of $\pi$). Thus, we have
\begin{equation}
\min\limits_{\beta\in\mathbb{R}}H^{\max}(\beta)=\min\limits_{\beta\in\mathbb{R}}\max\limits_{x\in\mathbb{R}}H(x,\beta)=H^{\max}(0)=\left\{
\begin{array}{l}
	\frac{1}{1-W_1}\cdot\frac{1-V_1^2}{1-Q_1V_1}\text{\ if\ }V_1\leq\frac{2W_1}{1+W_1}\\
	\\
	\frac{1}{1+W_1}\cdot\frac{1+V_1}{1-V_1}\text{\ if\ }\frac{2W_1}{1+W_1}\leq V_1
\end{array}
\right.\label{MMAX}
\end{equation}
and
\begin{equation}
\max\limits_{\beta\in\mathbb{R}}H^{\min}(\beta)=\max\limits_{\beta\in\mathbb{R}}\min\limits_{x\in\mathbb{R}}H(x,\beta)=H^{\min}(0)=\frac{1}{1-W_1}\label{MMIN}
\end{equation}
by (\ref{Hmax0}) and (\ref{Hmin0}). 


Thus, by (\ref{fourmax}) and (\ref{MMAX}), we have (\ref{MINMAX}) with the minimum value achieved if and only if $\gamma_1(\widehat{y}_0)-\theta_1=\frac{\Delta_1(\widehat{y}_0)}{2}=\frac{\beta}{2}$ is a multiple of $\pi$. Moreover,  by (\ref{fourmax}) and (\ref{MMIN}), we have (\ref{MAXMIN}) with the maximum value achieved if and only if $\gamma_1(\widehat{y}_0)-\theta_1$ is a multiple of $\pi$.

The inequality (\ref{minmax<=}) follows by the inequality (\ref{H<=}).  

\end{proof}





\begin{remark} \label{69}
\quad
\begin{itemize}
	\item [1.]  If $V_1$ is not close to $1$, then, for any $y_0$, $\mathrm{OT}(t,y_0)$  does not assume large values,  as $t$ varies. In fact, we have
