\section{The generic real case. Part V: the onset of the asymptotic behavior}

In this brief final section, we examine how quickly the asymptotic behavior described in Sections from 6 to 9 is established.

By Theorems \ref{ThmKyz} and \ref{ThmKy}, we know that:

\begin{itemize}
\item 
$
K\left( t,y_{0},\widehat{z}_{0}\right) \approx K_\infty\left( t,y_{0},%
\widehat{z}_{0}\right)\text{\ with precision\ } \frac{\epsilon(t,%
\widehat{z}_0)+\epsilon(t,\widehat{y}_0)}{1-\epsilon(t,\widehat{y}%
_0)}; 
$

\item 
$
K\left( t,y_{0}\right) \approx K_\infty\left( t,y_{0}\right)\text{\ with
precision\ }\frac{\epsilon(t)+\epsilon(t,\widehat{y}_0)}{%
1-\epsilon(t,\widehat{y}_0)}.
$

\end{itemize}

The onset of the asymptotic behavior, i.e., when a condition number begins to be close to its asymptotic value, is determined by how quickly $%
\epsilon(t,\widehat{z}_0)$, $\epsilon(t,\widehat{y}_0)$ and $%
\epsilon(t)$ decay to zero as $t \rightarrow +\infty$. The following
theorem addresses this question in a generic situation for the real matrix $A$, the initial value $y_0$ and the direction of perturbation 
$\widehat{z}_0$.

\begin{theorem}\label{onset}
Assume that $A$ is a real matrix and, for any $j\in\{1,\ldots,q\}$, $\Lambda_j$ consists of either a real simple eigenvalue (i.e. $\Lambda_1$ is real) or a single pair of complex conjugate simple eigenvalues (i.e. $\Lambda_1$ is complex). For $u\in\mathbb{R}^n$ such that $%
\widehat{w}^{(1)}u\neq 0$, we have 
\begin{equation*}
\epsilon(t,u)=\sum\limits_{j=2}^{q}\mathrm{e}^{\left( r_{j}-r_{1
}\right) t}\frac{f_j}{f_1}\cdot\frac{\left\vert \widehat{w}^{(j)}u\right\vert%
}{\left\vert \widehat{w}^{(1)}u\right\vert}G_j(t,u),
\end{equation*}
where
$$
G_j(t,u):=\frac{g_j\left(t,u\right)}{%
	g_1\left(t,u\right) }.
$$
Moreover, we have 
\begin{eqnarray*}
&&\epsilon(t)=\sum\limits_{j=2}^{q}\mathrm{e}^{\left( r_{j}-r_{1
}\right) t}\frac{f_j}{f_1}G_j(t),
\end{eqnarray*}
where
$$
G_j(t):=\frac{g_j\left(t\right)}{g_1\left(t\right) }.
$$
\end{theorem}

\begin{proof}
The projection of $u$ on the eigenspace corresponding to $\lambda_1$ is 
\begin{equation*}
v^{(1)}w^{(1)}u=\left( w^{(1)}u\right) v^{(1)}\neq 0 \\
\end{equation*}%
and then $j(u)=1$. Since $A$ is diagonalizable, point 3 of Remark \ref{etAAAu} and Remark \ref{etAAA} state that
\begin{equation*}
\epsilon(t,u)=\sum\limits_{ j=2}^{q}\mathrm{e}^{\left( r_{j}-r_{1}\right)
t}\frac{\left\Vert
Q_{j0}(t)u\right\Vert }{\left\Vert Q_{10}(t)u\right\Vert}
\end{equation*}
and
\begin{equation*}
	\epsilon(t)=\sum\limits_{j=2}^{q}\mathrm{e}^{\left( r_{j}-r_{1}\right)
		t}\frac{\left\Vert
		Q_{j0}(t)\right\Vert }{\left\Vert Q_{10}(t)\right\Vert }.
\end{equation*}
Now, use (\ref{normQJ0ureal}) and (\ref{normQJ0}).
\end{proof}


Regarding the ratios $G_j(t,u)$ and $G_j(t)$, $j\in\{2,\ldots,q\}$, in Theorem \ref{onset} we can make the following observations by recalling Lemma \ref{Lemmareal} and Lemma \ref{Lemmacomplex}. 

Let $j\in\{2,\ldots,q\}$.
\begin{itemize}
\item If both $\Lambda_j$ and $\Lambda_1$ are real, then 
\begin{equation*}
G_j(t,u)=1\text{\ \ and\ \ }G_j(t)=1.
\end{equation*}
\item If $\Lambda_j$ is complex and $\Lambda_1$ is real, then 
\begin{equation*}
G_j(t,u)=2\left\Vert \widehat{\Theta}%
_j(t,u)\right\Vert\text{\ \ and\ \ }G_j(t)=2\left\Vert \widehat{\Theta}_j(t)\right\Vert.
\end{equation*}
When the vector norm is a $p$-norm, we have
\begin{equation*}
G_j(t,u)\leq 2\text{\ \ and\ \ }%
G_j(t)\leq 2
\end{equation*}
by point 2 and 3 in Remark \ref{remTheta}.
\item If $\Lambda_j$ is real and $%
\Lambda_1$ is complex, then 
\begin{equation*}
G_j(t,u)=\frac{1}{2\left\Vert 
\widehat{\Theta}_1(t,u)\right\Vert}\text{\ \ and\ \ }G_j(t)=\frac{1}{2\left\Vert \widehat{\Theta}_1(t)\right\Vert}.
\end{equation*}
When the vector norm is the Euclidean norm, we have 
\begin{equation*}
G_j(t,u)\leq \sqrt{\frac{1}{2(1-V_1)}}
\end{equation*}
and
\begin{equation*}
G_j(t)\leq\sqrt{\frac{1}{a(V_1,W_1)}}  \label{jk}
\end{equation*}
by (\ref{mintheta}) and (\ref{minTheta}).
\item If both $\Lambda_j$ and $\Lambda_1$ are complex, then 
\begin{equation*}
G_j(t,u)=\frac{\left\Vert \widehat{%
\Theta}_j(t,u)\right\Vert}{\left\Vert \widehat{\Theta}_1(t,u)\right\Vert}%
\text{\ \ and\ \ }G_j(t)=\frac{%
\left\Vert \widehat{\Theta}_j(t)\right\Vert}{\left\Vert \widehat{\Theta}%
_1(t)\right\Vert}.
\end{equation*}
When the vector norm is the Euclidean norm, we have
\begin{equation*}
G_j(t,u)\leq\sqrt{\frac{1+V_j}{1-V_1}}
\end{equation*}
and
\begin{equation*}
G_j(t)\leq\sqrt{\frac{(1+W_j)(1+V_j)}{a(V_1,W_1)}} \label{jk2}
\end{equation*}
by (\ref{maxtheta}), (\ref{mintheta}), (\ref{maxTheta}) and (\ref{minTheta}).
\end{itemize}


The previous Theorem \ref{onset} addresses several factors influencing the decay rate of $\epsilon(t,u)$ and $\epsilon(t)$ as $t \rightarrow +\infty$. These factors are, for $j \in \{2, \ldots, q\}$:
\begin{itemize}
	\item the decreasing exponentials $\mathrm{e}^{(r_j-r_1)t}$;
	\item the ratios $\frac{f_j}{f_1}$;
	\item the ratios $\frac{\vert \widehat{w}^{(j)}u\vert}{\vert \widehat{w}^{(1)}u\vert}$;
	\item the ratios $G_j(t,u)$ and $G_j(t)$.
\end{itemize}
A discussion about these factors can be found in \cite{Maset2022}.

