\section{ }
In this appendix, we prove (\ref{AppA}). Recall that we are supposing  $V,W\neq 0$. Observe that
$$
U(x)=V\mathrm{e}^{\sqrt{-1} x}+W=V\cos x+W+\sqrt{-1}V\sin x
$$
has squared modulus
$$
\vert U(x) \vert^2=V^2+2VW\cos x+W^2.
$$
Hence, (\ref{AppA}) is equivalent to
$$
V^2W^2\sin^2 x<V^2+2VW\cos x+W^2
$$
i.e.
$$
V^2W^2\cos^2 x+2VW\cos x+V^2+W^2-V^2W^2>0.
$$

The trinomial in the variable $y$
$$
V^2W^2y^2+2VWy+V^2+W^2-V^2W^2
$$
has discriminant
$$
\frac{\Delta}{4}=V^2W^2-V^2W^2(V^2+W^2-V^2W^2)=V^2W^2(1-V^2)(1-W^2)>0
$$
and then it has positive values for
\begin{equation}
y< y_{-}\text{\ \ or\ \ }y> y_{+},  \label{posval}
\end{equation}
where
$$
y_{-}=\frac{1}{VW}\left(-1-\sqrt{(1-V^2)(1-W^2)}\right)
$$
and
$$
y_{+}=\frac{1}{VW}\left(-1+\sqrt{(1-V^2)(1-W^2)}\right).
$$
are the zeros of the trinomial.

We have
$$
y_{-}<y_{+}\leq -1.
$$
In fact, the condition $y_{+}\leq -1$ is equivalent to
$$
\sqrt{(1-V^2)(1-W^2)}\leq 1-VW
$$
i.e.
$$
(1-V^2)(1-W^2)\leq (1-VW)^2
$$
that reduces to
$$
0\leq (V-W)^2.
$$
Now, the condition (\ref{posval}), in particular $y> y_{+}$,  is satisfied for $y=\cos x$. In fact, $y=\cos x\geq -1\geq y_{+}$ and $y=\cos x=y_{+}=-1$ when $V=W$ and $x$ an odd multiple of $\pi$, i.e. when $U_{VW}(x)=0$, which is excluded. 

\section{ }

In this appendix, we prove (\ref{Hmax0}), (\ref{Hmin0}) and (\ref{H<=}). This is accomplished by solving the equation (\ref{eq}) for $\beta=0$, i.e. the equation
\begin{equation*}
	-\sin(x+\alpha^{\max}_{V_1W_1}(x))+\sin x-V_1\sin \alpha^{\max}_{V_1W_1}(x)=0. 
\end{equation*}
The solutions of this equation are the stationary points of the function $H(\cdot,0):\mathbb{R}\rightarrow \mathbb{R}$ defined in (\ref{Halphax}) by setting $\beta=0$. Remind that we are assuming $V_1,W_1\neq 0$ and $V_1\neq W_1$.

Since $ \alpha^{\max}_{V_1W_1}(x)$ is a stationary point of the function $f_{V_1W_1}(\cdot,x)$, we solve the two equations
\begin{equation*}
	\left\{
	\begin{array}{l}
	-V_1\sin(x+\alpha)-W_1\sin \alpha+V_1W_1\sin x=0\\
	-\sin(x+\alpha)+\sin x-V_1\sin\alpha=0
	\end{array}
	\right.
\end{equation*}
in the unknowns $x$ and $\alpha$, where the first equation is the equation for the stationary points $\alpha$ of $f_{V_1W_1}(\cdot,x)$ (see (\ref{sinsin})).

By multiplying the second equation by $V_1$ and performing some subsequent algebraic manipulations, the previous system of equations is transformed into the equivalent system
\begin{equation}
	\left\{
	\begin{array}{l}\sin x=L\sin \alpha\\
	\sin(x+\alpha)=-K\sin\alpha,
\end{array}
\right.  \label{sys}
\end{equation}
where
\begin{equation}
L:=\frac{V_1^2-W_1}{V_1(1-W_1)}\text{\  \ and\ \ }K:=V_1-L=\frac{W_1(1-V_1^2)}{V_1(1-W_1)}. \label{LK}
\end{equation}
Observe that $L$ can be negative, zero or positive, whereas $K$ is positive.

About the solutions of (\ref{sys}), we have the following result.

\begin{lemma} \label{Lemmasolutions}
Let
\begin{equation}
Q_1:=\frac{K^2-L^2+1}{2K}=\frac{1}{2}\cdot\frac{V_1}{W_1}(1+W_1). \label{QQ}
\end{equation}
If $Q_1>1$, then the set of solutions of (\ref{sys}) is given by the pairs $(x,\alpha)$ such that $x$ and $\alpha$ are multiplies of $\pi$. If $Q_1\leq 1$, then the set of solutions also includes the pairs $(x, \alpha)$ such that
$$
\cos x=-Q_1\text{\ \ and\ \ }\cos\alpha=\frac{Q_1-K}{L}
$$
with $\mathrm{sign}(\sin x)=-\mathrm{sign}(\sin \alpha)$.
\end{lemma}

\begin{proof}

To prove the second equality in (\ref{QQ}), observe that
$$
K^2-L^2+1=V_1^2-2V_1L+1=\frac{(1-V_1^2)(1+W_1)}{1-W_1}.
$$

Consider the case $L=0$. The first equation in (\ref{sys}) is $\sin x=0$. If $\sin x=0$, then $\sin(x+\alpha)=\pm \sin \alpha$ in the second equation, which becomes $(\pm 1+V_1)\sin \alpha=0$, i.e. $\sin \alpha=0$. Therefore, in the case $L=0$, the solutions of (\ref{sys}) are $x$ and $\alpha$ multiple of $\pi$. 

Consider the case $L\neq 0$. The solutions of  (\ref{sys}) with $\sin x=0$ have also $\sin \alpha=0$ and then they are $x$ and $\alpha$ multiple of $\pi$.

Now, in the case $L\neq 0$, we look for solutions of (\ref{sys}) with $\sin x\neq 0$. Such solutions have $\sin \alpha\neq 0$. By expanding $\sin(x+\alpha)$ as
$$
\sin(x+\alpha)=\sin x\cos\alpha+\cos x\sin\alpha,
$$
the second equation in (\ref{sys}) provides
\begin{equation}
\sin x \cos\alpha=-(\cos x+K)\sin \alpha. \label{xplusalpha}
\end{equation}
By squaring and by using the first equation, we obtain
$$
\sin^2 x\left(1-\frac{\sin^2 x}{L^2}\right)=(\cos x+K)^2 \frac{\sin^2 x}{L^2}
$$
and then, since $\sin x\neq 0$,
\begin{equation*}
1-\frac{\sin^2 x}{L^2}=\frac{(\cos x+K)^2}{L^2} \label{1-}
\end{equation*}
equivalent to
\begin{equation}
	\cos x=\frac{L^2-K^2-1}{2K}=-Q_1. \label{Q1A}
\end{equation}
Concerning the other unknown $\alpha$ in case of $\cos x=-Q_1$, by using  (\ref{xplusalpha}) and the first equation in (\ref{sys}), we obtain
\begin{equation*}
	L\sin\alpha \cos\alpha=(Q_1-K)\sin\alpha. \label{alphaA}
\end{equation*}
Since $\sin \alpha\neq 0$, we have
\begin{equation}
	\cos \alpha=\frac{Q_1-K}{L}. \label{alphaB}
\end{equation}



Therefore, we conclude that if $Q_1>1$, then the system (\ref{sys}) has only the solutions with $\sin x=0$, i.e. $x$ and $\alpha$ multiplies of $\pi$.

On the other hand, if $Q_1\leq 1$, and then $L<0$ (see point 2 of Remark \ref{remApp} below), in addition to the solutions such that $x$ and $\alpha$ are multiple of $\pi$, we have the additional solutions $(x,\alpha)$ satisfying (\ref{Q1A}) and (\ref{alphaB})  with $\mathrm{sign}(\sin x)=-\mathrm{sign}(\sin \alpha)$.

In fact, (\ref{Q1A}) and (\ref{alphaB}) imply
\begin{equation}
	L^2\cos^2\alpha=(\cos x+K)^2  \label{L2cos2}
\end{equation}
and
\begin{equation}
	L^2-\sin^2x=(\cos x+K)^2. \label{L2sin2}
\end{equation}
By comparing (\ref{L2cos2}) and (\ref{L2sin2}), we obtain
$$
\sin^2x=L^2\sin^2\alpha,
$$
i.e.
$$
\sin x=L\sin \alpha\text{\ \ or\ \ }\sin x=-L\sin \alpha.
$$
Therefore, by taking $(x,\alpha)$ satisfying (\ref{Q1A}) and (\ref{alphaB})  with $\mathrm{sign}(\sin x)=-\mathrm{sign}(\sin \alpha)$, we have
$
\sin x=L\sin \alpha,
$
by reminding that $L<0$. Now, (\ref{Q1A}), (\ref{alphaB}) and $\sin x=L\sin \alpha$ imply (\ref{xplusalpha}), equivalent to the second equation in (\ref{sys}).

There are no other solutions of (\ref{sys}) in the case $Q_1\leq 1$, since, as we have proved, each solution $(x,\alpha)$ with $\sin x\neq 0$ satisfies (\ref{Q1A}), (\ref{alphaB})  and $\mathrm{sign}(\sin x)=-\mathrm{sign}(\sin \alpha)$ (remind that $L<0$).  


\end{proof}

\begin{remark} \label{remApp}
	\quad
\begin{itemize}
\item [1.]
$$
Q_1\leq 1 \Longleftrightarrow V_1\leq\frac{2W_1}{1+W_1} \Longleftrightarrow W_1\geq \frac{V_1}{2-V_1},
$$
with
$$
\frac{2W_1}{1+W_1}<1\text{\ \ and\ \ }\frac{V_1}{2-V_1}<1;
$$
\item  [2.] If $Q_1\leq 1$, then $L<0$. To prove this, use the upper bound of $V_1$ at point 1 in the numerator $V_1^2-W_1$ of the fraction defining $L$.
\item [3.] If $Q_1\leq 1$, then
$$
\left(\frac{Q_1-K}{L}\right)^2\leq 1.
$$
To prove this, observe that
\begin{eqnarray*}
(Q_1-K)^2&=&Q_1^2-2KQ_1+K^2=Q_1^2-(K^2-L^2+1)+K^2\\
&=&Q_1^2+L^2-1.
\end{eqnarray*}
\item [4.] 
$$
Q_1-K\geq 0 \Longleftrightarrow V_1^2\geq \frac{2W_1^2}{1+W_1^2},
$$
with
$$
\frac{2W_1^2}{1+W_1^2}<1.
$$
To prove the equivalence $\Longleftrightarrow$, use
$$
Q_1=\frac{1}{2}\cdot\frac{V_1}{W_1}(1+W_1)\text{\ \ and\ \ }K=\frac{W_1(1-V_1^2)}{V_1(1-W_1)}
$$
\end{itemize}
\end{remark}

Starting from the parameters $V_1$ and $W_1$, we have defined the quantities $L$ and $K$ in (\ref{LK}) and $Q_1$ in (\ref{QQ}). The next lemma shows how $K$, $L$ and $W_1$ can be expressed in terms of $V_1$ and $Q_1$.
\begin{lemma} \label{LemmaLKW}
	We have
	\begin{equation*}
	L=-\frac{V_1^2-2Q_1V_1+1}{2(Q_1-V_1)},\ K=\frac{1-V_1^2}{2(Q_1-V_1)}\text{\ \ and\ \ }W_1=\frac{V_1}{2Q_1-V_1}=\frac{V_1}{Q_1-V_1+Q_1}
	\label{formula}
	\end{equation*}
	with
	\begin{equation*}
		Q_1-V_1=V_1\frac{1-W_1}{2W_1}>0.
		\end{equation*}
\end{lemma}
\begin{proof}
	By using the definitions
	\begin{equation*}
	Q_1=\frac{K^2-L^2+1}{2K}\text{\ \ and\ \ }K=V_1-L,
	\end{equation*}
	we obtain
	$$
	Q_1=\frac{V_1^2-2V_1L+1}{2(V_1-L)}
	$$
	and then
	$$
	2(V_1-Q_1)L=V_1^2-2Q_1V_1+1
	$$
	with
	$$
	V_1-Q_1=V_1-\frac{1}{2}\cdot \frac{V_1}{W_1}(1+W_1)=-V_1\frac{1-W_1}{2W_1}<0.
	$$
	The expression for $L$ follows. Then, the expression for $K$ follows:
	$$
	K=V_1-L=V_1+\frac{V_1^2-2Q_1V_1+1}{2(Q_1-V_1)}=\frac{1-V_1^2}{2(Q_1-V_1)}.
	$$
	Finally, by
	$$
	Q_1=\frac{1}{2}\cdot\frac{V_1}{W_1}(1+W_1)
	$$
	we obtain the expression for $W_1$.
\end{proof}


Now, it of interest to determine which solutions $(x,\alpha)$ of (\ref{sys}) corresponds to $\alpha=\alpha^{\max}_{V_1W_1}(x)$, i.e. $\alpha$ is a maximum point of $f_{V_1W_1}(\cdot,x)$, and then $x$ is a stationary point of $H(\cdot,0)$. 

\begin{proposition}\label{propxalpha}
The solutions $(x,\alpha)$ of (\ref{sys}) such that $\alpha$ is a maximum point of $f_{V_1W_1}(\cdot,x)$, are:
\begin{itemize}
	\item $x$ and $\alpha$ even multiples of $\pi$;
	\item $x$ odd multiple of $\pi$ and $\alpha$ even multiple of $\pi$ when $V_1<W_1$;
	\item $x$ odd multiple of $\pi$ and $\alpha$ odd multiple of $\pi$ when $V_1>W_1$;
	\item the solutions of
	\begin{equation}
	\cos x=-Q_1\text{\ \ and\ \ }\cos\alpha=\frac{Q_1-K}{L} \label{coscos}
	\end{equation}
	with $\mathrm{sign}(\sin x)=-\mathrm{sign}(\sin \alpha)$, when $Q_1\leq 1$. 
\end{itemize}
\end{proposition}

\begin{proof}
The condition under which $\alpha$ is a maximum point of $f_{V_1W_1}(\cdot,x)$ is
\begin{equation}
V_1\cos(x+\alpha)+W_1\cos \alpha>0.  \label{V1W1geq0}
\end{equation}
This condition is obtained by $\frac{\partial^2 f_{V_1W_1}}{\partial \alpha^2}(\alpha,x)$ given in (\ref{delta2fVW}) for $\alpha$ stationary point of $f_{V_1W_1}(\cdot,x)$.

For a solution $(x,\alpha)$ such that $x$ and $\alpha$ are multiples of $\pi$, the values of $V_1\cos(x+\alpha)+W_1\cos \alpha$ are given in the next table
\begin{equation*}
	\begin{tabular}{|c|c|c|}
		\hline
		& $x$ even  multiple of $\pi$             & $x$ odd multiple of $\pi$\\
		\hline
		$\alpha$ even multiple of $\pi$ & $V_1+W_1$  &  $-V_1+W_1$\\
		\hline
		$\alpha$ odd  multiple of $\pi$ & $-V_1-W_1$ & $V_1-W_1$ \\
		\hline
	\end{tabular} 
\end{equation*}
Positive values are obtained in the following cases:
\begin{itemize}
	\item [a)] $x$ and $\alpha$ even multiples of $\pi$;
	\item [b)] $x$ odd multiple of $\pi$ and $\alpha$ even multiple of $\pi$, for $V_1<W_1$;
	\item [c)] $x$ odd multiple of $\pi$ and $\alpha$ odd multiple of $\pi$, for $V_1>W_1$.
	\end{itemize}
%In b) and c) we also include the case $V_1=W_1$, since $f_{V_1W_1}(\cdot,x)$ is constant of value $1$ when $x$ is an multiple of $\pi$. 

Regarding the additional solutions (\ref{coscos}) in case of $Q_1\leq 1$ given in Lemma \ref{Lemmasolutions}, by expanding $\cos(x+\alpha)$ as
\begin{eqnarray}
\cos(x+\alpha)&=&\cos x\cos \alpha-\sin x\sin \alpha  \notag\\
&=&-Q_1\cos\alpha-L\sin^2\alpha \notag\\
&=&L\cos^2\alpha-Q_1\cos\alpha-L \notag\\
&=&L\left(\frac{Q_1-K}{L}\right)^2-Q_1\frac{Q_1-K}{L}-L \notag\\
&=&\frac{K^2-Q_1K-L^2}{L}\notag \\
&=&\frac{Q_1K-1}{L}, \notag \\
\label{cosxplusalpha}
\end{eqnarray}
where the last equality follows by
$$
L^2=K^2-2Q_1K+1
$$
(see (\ref{QQ})), we obtain, since $L<0$ (remind point 2 in Remark \ref{remApp}), that the condition (\ref{V1W1geq0}) is equivalent to
\begin{equation}
V_1(Q_1K-1)+W_1(Q_1-K)<0. \label{cV1W1}
\end{equation}
By using the expressions for $K$ and $W_1$ given in Lemma \ref{LemmaLKW}, we obtain
$$
V_1(Q_1K-1)=\frac{V_1}{2(Q_1-V_1)}\cdot\left(-(1+V_1^2)Q_1+2V_1\right)
$$
and
$$
W_1(Q_1-K)=\frac{V_1}{2(2Q_1-V_1)(Q_1-V_1)}\cdot\left(2Q_1^2-2V_1Q_1-1+V_1^2\right)
$$
and then
\begin{eqnarray*}
&&V_1(Q_1K-1)+W_1(Q_1-K)\\
&&=\frac{V_1}{2(2Q_1-V_1)(Q_1-V_1)}\\
&&\ \ \ \ \cdot\left(-2V_1^2Q_1^2+(V_1^3+3V_1)Q_1-(1+V_1^2)\right).
\end{eqnarray*}
The trinomial 
$$
-2V_1^2Q_1^2+(V_1^3+3V_1)Q_1-(1+V_1^2),
$$
in $Q_1$, which is the left-hand side of (\ref{cV1W1}), is a downward parabola with vertex at
$$
-\frac{V_1^3+3V_1}{2(-2V_1^2)}=\frac{V_1^2+3}{4V_1}>1.
$$
Therefore, by confining to $Q_1\leq 1$, the maximum value of the trinomial is at $Q_1=1$ and such maximum value is
$$
(V_1-1)^3<0.
$$
We conclude that, for $Q_1\leq 1$, we have (\ref{cV1W1}).

Consequently, the solutions $(x,\alpha)$ given by (\ref{coscos}) have $\alpha$ as a maximum point of $f_{V_1W_1}(\cdot,x)$.
\end{proof}


The following proposition, which follows from the previous one, specifies the stationary points of the function $H(\cdot,0):\mathbb{R}\rightarrow \mathbb{R}$ and their corresponding values.
\begin{proposition}\label{lastprop}
	The stationary points of the function $H(\cdot,0):\mathbb{R}\rightarrow \mathbb{R}$ are:
	\begin{itemize}
		\item The even multiples $x$ of $\pi$ with value
		$$
		H(x,0)=\frac{1}{1-W_1}.
		$$
		\item The odd multiplies $x$ of $\pi$ with values
		$$
		H(x,0)=\left\{
		\begin{array}{l}
			\frac{1}{1-W_1}	\text{\ if\ }V_1<W_1\\
			\\
			\ \frac{1}{1+W_1}\cdot\frac{1+V_1}{1-V_1}	\text{\ if\ }V_1>W_1.
		\end{array}
		\right.
		$$
		\item If $Q_1\leq 1$, the solutions $x$ of $\cos x=-Q_1$ with values
		\begin{equation}
		H(x,0)=\frac{1}{1-W_1}\cdot\frac{1-V_1^2}{1-Q_1V_1}, \label{Hx0}
		\end{equation}
		with
		\begin{equation}
		1<\frac{1-V_1^2}{1-Q_1V_1}\leq 1+V_1. \label{1leq}
		\end{equation}		
	\end{itemize}
	\end{proposition}
	\begin{proof}
		We have that $x\in\mathbb{R}$ is a stationary point of $H(\cdot,0)$ if and only if $x$ is the first component of the pairs $(x,\alpha)$ in Proposition \ref{propxalpha}. Regarding the values at the stationary points, we utilize  
	\begin{equation}
	H(x,0)=\frac{f_{V_1W_1}^{\max}(x)}{1+V_1\cos x}=\frac{1+V_1\cos(x+\alpha)}{1-W_1\cos \alpha}\cdot\frac{1}{1+V_1\cos x}  \label{H0}
	\end{equation}
	with $\alpha=\alpha_{V_1W_1}^{\max}(x)$.

	For the cases $x$ even multiple of $\pi$ and $x$ odd multiple of $\pi$, the computations in (\ref{H0}) are straightforward.

	For the case $Q_1\leq 1$, use in (\ref{H0})
	$$
	\cos x=-Q_1,\ \cos\alpha=\frac{Q_1-K}{L}\text{\ \ and\ \ }\cos(x+\alpha)=\frac{Q_1K-1}{L}
	$$
	(for the last one, refer to (\ref{cosxplusalpha})). We obtain
	\begin{eqnarray*}
	H(x,0)&=&\frac{L+V_1Q_1K-V_1}{L-W_1(Q_1-K)}\cdot\frac{1}{1-V_1Q_1}\\
	&=&\frac{V_1Q_1K-K}{L-W_1(Q_1-K)}\cdot\frac{1}{1-V_1Q_1}\text{\ \ (use $L-V_1=-K$ in the numerator)}\\
	&=&\frac{-K}{L-W_1(Q_1-K)}\\
	&=&\frac{-K}{L-W_1(Q_1-V_1+L)}\text{\ \ (use $-K=-V_1+L$ in the denominator)}\\
	&=&\frac{-K}{(1-W_1)L-W_1(Q_1-V_1)}\\
	&=&\frac{1}{1-W_1}\cdot\frac{K}{-L+\frac{W_1}{1-W_1}(Q_1-V_1)}.
	\end{eqnarray*}
By using the expression for $W_1$ in Lemma \ref{LemmaLKW}, we have
$$
\frac{W_1}{1-W_1}=\frac{V_1}{2(Q_1-V_1)}
$$
and then
$$
H(x,0)=\frac{1}{1-W_1}\cdot\frac{K}{-L+\frac{V_1}{2}}=\frac{1}{1-W_1}\cdot\frac{K}{K-\frac{V_1}{2}}
$$
(use $-L=K-V_1$ in the denominator). By using the expression for $K$ in Lemma \ref{LemmaLKW}, we obtain (\ref{Hx0}).

	Finally, the left inequality in (\ref{1leq}) follows by $Q_1>V_1$ (see Lemma \ref{LemmaLKW}) and the right inequality by 	$Q_1\leq 1$.  
	\end{proof}

Here is our final result concerning the values $H^{\max}(0)$ and $H^{\min}(0)$. It follows from the previous proposition regarding the stationary points of $H(\cdot, 0)$. 
	\begin{theorem}	
We have
\begin{equation*}
	H^{\max}(0)=\left\{
	\begin{array}{l}
		\frac{1}{1-W_1}\cdot\frac{1-V_1^2}{1-Q_1V_1}\text{\ if\ }V_1\leq\frac{2W_1}{1+W_1}\\
		\\
		\frac{1}{1+W_1}\cdot\frac{1+V_1}{1-V_1}\text{\ if\ }\frac{2W_1}{1+W_1}\leq V_1,
	\end{array}
	\right.
\end{equation*}
where $Q_1$ is defined in (\ref{QQ}), and
\begin{equation*}
	H^{\min}(0)=\frac{1}{1-W_1}. 
\end{equation*}
	Moreover, we have $H^{\max}(0)=H(x_0^{\max},0)$ for
	$$
	\left\{
	\begin{array}{l}
		\cos x_0^{\max}=-Q_1\text{\ if\ }V_1\leq\frac{2W_1}{1+W_1}\\
		\\
		x_0^{\max}\text{\ odd multiple of $\pi$\ if\ }V_1\geq\frac{2W_1}{1+W_1},
	\end{array}
	\right.
	$$
	and $H^{\min}(0)=H(x_0^{\min},0)$ for
	$$
	\left\{
	\begin{array}{l}
		x_0^{\min}\text{\ multiple of $\pi$\ if\ }V_1<W_1\\
		\\
		x_0^{\min}\text{\ even multiple of $\pi$\ if\ }V_1>W_1,
	\end{array}
	\right.
	$$
	Finally, in the case $V_1\leq \frac{2W_1}{1+W_1}$, we have
	\begin{equation}
	H^{\max}(0)\leq \frac{1}{1-W_1}\cdot(1+V_1). \label{Hmax0<=}
	\end{equation}
	\end{theorem}

	\begin{proof}
	We distinguish the three cases:
	\begin{equation}
	a):V_1<W_1,\ b):W_1< V_1\leq\frac{2W_1}{1+W_1}\text{\ \ and\ \ }c):\frac{2W_1}{1+W_1}< V_1. \label{abc}
	\end{equation}

	In point 1 of Remark \ref{remApp}, we observed that $Q_1\leq 1$ is equivalent to
	$$
	V_1\leq\frac{2W_1}{1+W_1}.
	$$
Therefore, in the cases a) and b), we have $Q_1\leq 1$ and, in the case c), we have $Q_1>1$. Moreover, the case b) is well-defined since 
	$$
	\frac{2W_1}{1+W_1}>W_1
	$$
	holds.



	Case a). For $V_1<W_1$, we have the following stationary points of $H(\cdot,0)$ (see Proposition \ref{lastprop}). 
	\begin{itemize}
		\item The multiplies $x$ of $\pi$ with value
	$$
	H(x,0)=\frac{1}{1-W_1};
	$$
		\item  Since $Q_1\leq 1$, the solutions $x$ of $\cos x=-Q_1$ with value
	$$
	H(x,0)=\frac{1}{1-W_1}\cdot\frac{1-V_1^2}{1-Q_1V_1}>\frac{1}{1-W_1},
	$$
	where the inequality $>$ holds by the left inequality in (\ref{1leq}).
	\end{itemize}
	We conclude that
	$$
	H^{\max}(0)=\frac{1}{1-W_1}\cdot\frac{1-V_1^2}{1-Q_1V_1} \text{\ \ and\ \ }H^{\min}(0)=\frac{1}{1-W_1},
	$$
	with $H^{\max}(0)=H(x_0^{\max},0)$ for $\cos x_0^{\max}=-Q_1$ and $H^{\min}(0)=H(x_0^{\min},0)$ for
	$x_0^{\min}$ multiple of $\pi$.

	Case b). For $W_1<V_1\leq\frac{2W_1}{1+W_1}$, we have the following stationary points of $H(\cdot,0)$ (see Proposition \ref{lastprop}).
	\begin{itemize}
	\item The even multiples $x$ of $\pi$ with value
	$$
	H(x,0)=\frac{1}{1-W_1};
	$$
	\item The odd multiples $x$ of $\pi$ with value
	$$
	H(x,0)=\frac{1}{1+W_1}\cdot \frac{1+V_1}{1-V_1}> \frac{1}{1-W_1},
	$$
	where the inequality $>$ follows by $V_1> W_1$;
	\item Since $Q_1\leq 1$, the solutions $x$ of $\cos x=-Q_1$ with value
	$$
	H(x,0)=\frac{1}{1-W_1}\cdot\frac{1-V_1^2}{1-Q_1V_1}\geq \frac{1}{1+W_1}\cdot\frac{1+V_1}{1-V_1},
	$$
	where the inequality $\geq$ is now proved. We rewrite the inequality as
	\begin{equation}
		\frac{(1-V_1)^2}{1-Q_1V_1}\geq \frac{1-W_1}{1+W_1}.\label{ineqrew}
	\end{equation}
	Using the expression for $W_1$ in Lemma \ref{LemmaLKW}, we obtain
	$$
	\frac{1-W_1}{1+W_1}=\frac{Q_1-V_1}{Q_1}
	$$
	and then (\ref{ineqrew}) is equivalent to
	$$
	(1-V_1)^2Q_1\geq(1-Q_1V_1)(Q_1-V_1),
	$$
	that reduces to
	$$
	Q_1^2-2Q_1+1=(Q_1-1)^2\geq 0.
	$$
\end{itemize}
	We conclude that
	$$
	H^{\max}(0)=\frac{1}{1-W_1}\cdot\frac{1-V_1^2}{1-Q_1V_1}\text{\ \ and\ \ }H^{\min}(0)=\frac{1}{1-W_1},
	$$
	with $H^{\max}(0)=H(x_0^{\max},0)$ for $\cos x_0^{\max}=-Q_1$ and $H^{\min}(0)=H(x_0^{\min},0)$ for
	$x_0^{\min}$ even multiple of $\pi$.


	Case c). For $\frac{2W_1}{1+W_1}<V_1$, since $Q_1>1$, we have the following stationary points of $H(\cdot,0)$ (see Proposition \ref{lastprop}).
	\begin{itemize}
		\item 
	The even multiples $x$ of $\pi$ with value
	$$
	H(x,0)=\frac{1}{1-W_1};
	$$
	\item The odd multiples $x$ of $\pi$ with value
	$$
	H(x,0)=\frac{1}{1+W_1}\cdot \frac{1+V_1}{1-V_1}>\frac{1}{1-W_1},
	$$
	where the inequality follows by $V_1>W_1$.
\end{itemize}
	We conclude that
	$$
	H^{\max}(0)=\frac{1}{1+W_1}\cdot\frac{1+V_1}{1-V_1}\text{\ \ and\ \ }H^{\min}(0)=\frac{1}{1-W_1}
	$$
	with $H^{\max}(0)=H(x_0^{\max},0)$ for $x_0$ odd multiple of $\pi$ and $H^{\min}(0)=H(x_0^{\min},0)$ for
	$x_0^{\min}$ even multiple of $\pi$.

	Observe that in the transition case between b) and c), i.e. $V_1=\frac{2W_1}{1+W_1}$, formulas in b) and c) for $H^{\max}(0)$ give the same value, since $Q_1=1$.

	The inequality (\ref{Hmax0<=}) follows by the right inequality in (\ref{1leq}).
	\end{proof}



