In this appendix, we compute some partial derivatives of the function (see (\ref{Halphax}))
$$
H(x,\beta)=\frac{f^{\max}_{V_1W_1}(x)}{1+V_1\cos(x+\beta)},\ (x,\beta)\in\mathbb{R}^2.
$$
These partial derivatives are used in the proof of Theorem \ref{formOTyz}.

We are interested in the partial derivative $\frac{\partial^2 H}{\partial x^2}(x,0)$. Since
$$
H(x,0)=\frac{f^{\max}_{V_1W_1}(x)}{1+V_1\cos x},
$$
we obtain
$$
\frac{\partial H}{\partial x}(x,0)=\frac{\left(f^{\max}_{V_1W_1}\right)^\prime(x)\left(1+V_1\cos x\right)+f^{\max}_{V_1W_1}(x)V_1\sin x}{(1+V_1\cos x)^2}
$$
and then
\begin{eqnarray*}
&&\frac{\partial^2 H}{\partial^2 x}(x,0)\\
&&=\frac{1}{(1+V_1\cos x)^4}\\
&&\quad \cdot\left(\left(\left(f^{\max}_{V_1W_1}\right)^{\prime\prime}(x)\left(1+V_1\cos x\right)+f^{\max}_{V_1W_1}(x)V_1\cos x\right)\cdot (1+V_1\cos x)^2\right.\\
\\
&&\quad\quad \text{inside the first parentheses, where we derive}\\
&&\quad\quad \text{$\left(f^{\max}_{V_1W_1}\right)^\prime(x)\left(1+V_1\cos x\right)+f^{\max}_{V_1W_1}(x)V_1\sin x$,}\\
&&\quad\quad\text{there are two further terms $-\left(f^{\max}_{V_1W_1}\right)^{\prime}(x)V_1\sin x$ and $\left(f^{\max}_{V_1W_1}\right)^{\prime}(x)V_1\sin x$}\\
&&\quad\quad \text{which cancel each other}\\
\\
&&\quad \quad \left.+\ \left(\left(f^{\max}_{V_1W_1}\right)^\prime(x)\left(1+V_1\cos x\right)+f^{\max}_{V_1W_1}(x)V_1\sin x\right)\cdot 2\left(1+V_1\cos x\right)V_1\sin x\right)\\
&&=\frac{1}{(1+V_1\cos x)^3}\\
&&\quad \cdot\left(\left(\left(f^{\max}_{V_1W_1}\right)^{\prime\prime}(x)\left(1+V_1\cos x\right)+f^{\max}_{V_1W_1}(x)V_1\cos x\right)(1+V_1\cos x)\right.\\
&&\quad\quad \left.+\ \left(\left(f^{\max}_{V_1W_1}\right)^\prime(x)\left(1+V_1\cos x\right)+f^{\max}_{V_1W_1}(x)V_1\sin x\right)2V_1\sin x\right)\\
&&=\frac{1}{(1+V_1\cos x)^3}\\
&&\quad \cdot\left(\left(f^{\max}_{V_1W_1}\right)^{\prime\prime}(x)\left(1+V_1\cos x\right)^2+\left(f^{\max}_{V_1W_1}\right)^\prime(x)2V_1\left(1+V_1\cos x\right)\sin x\right.\\
&&\quad\quad \left. + f^{\max}_{V_1W_1}(x)V_1\left(\cos x+V_1+V_1\sin^2 x\right)\right).
\end{eqnarray*}
When $x$ is multiple of $\pi$, we have
\begin{equation}
\frac{\partial^2 H}{\partial^2 x}(x,0)=\frac{\left(f^{\max}_{V_1W_1}\right)^{\prime\prime}(x)\left(1+V_1\cos x\right)+f^{\max}_{V_1W_1}(x)V_1(\cos x+V_1)}{(1+V_1\cos x)^3}. \label{H2x}
\end{equation}

We are also interested in the partial derivative $$\frac{\partial^2 H}{\partial x \partial \beta}(x,0)=\frac{\partial^2 H}{\partial \beta \partial x}(x,0).$$ We have
$$
\frac{\partial H}{\partial \beta}(x,\beta)=\frac{f^{\max}_{V_1W_1}(x)V_1\sin (x+\beta)}{(1+V_1\cos(x+\beta))^2}
$$
and, for $\beta=0$,
$$
\frac{\partial H}{\partial \beta}(x,0)=\frac{f^{\max}_{V_1W_1}(x)V_1\sin x}{(1+V_1\cos x)^2}.
$$
Then
\begin{eqnarray*}
	&&\frac{\partial^2 H}{\partial x \partial \beta}(x,0)\\
	&&=\frac{1}{(1+V_1\cos x)^4}\\
	&&\quad \cdot\left(\left(\left(f^{\max}_{V_1W_1}\right)^{\prime}(x)V_1\sin x+f^{\max}_{V_1W_1}(x)V_1\cos x\right)\cdot (1+V_1\cos x)^2\right.\\
	&&\quad \quad \left.+f^{\max}_{V_1W_1}(x)V_1\sin x\cdot 2\left(1+V_1\cos x\right)V_1\sin x\right)\\
	&&=\frac{1}{(1+V_1\cos x)^3}\\
	&&\quad \cdot\left(\left(\left(f^{\max}_{V_1W_1}\right)^{\prime}(x)V_1\sin x+f^{\max}_{V_1W_1}(x)V_1\cos x\right)(1+V_1\cos x)\right.\\
	&&\quad\quad \left.+\ f^{\max}_{V_1W_1}(x)2V_1^2\sin^2 x\right)\\
	&&=\frac{1}{(1+V_1\cos x)^3}\\
	&&\quad \cdot\left(\left(f^{\max}_{V_1W_1}\right)^{\prime}(x)V_1\sin x(1+V_1\cos x)+f^{\max}_{V_1W_1}(x)V_1(\cos x +V_1+V_1\sin^2 x)\right).
\end{eqnarray*}
When $x$ is multiple of $\pi$, we have
\begin{equation}
\frac{\partial^2 H}{\partial x \partial \beta}(x,0)=\frac{f^{\max}_{V_1W_1}(x)V_1(\cos x+V_1)}{(1+V_1\cos x)^3}. \label{H2xbeta}
\end{equation}

Now, by (\ref{H2x}) and (\ref{H2xbeta}),  we obtain (see (\ref{partialminus}))
$$
\frac{\partial^2 H}{\partial^2 x}(x,0)-\frac{\partial^2 H}{\partial x \partial \beta}(x,0)=\frac{\left(f^{\max}_{V_1W_1}\right)^{\prime\prime}(x)}{(1+V_1\cos x)^2}
$$
for $x$ multiple of $\pi$.

