	\mathbf{1} & B_{I_0}^{J_1} & \overline{B_{I_0}^{J_0}} \\
\end{bmatrix}\\&\end{array}.$$

We now relate the two cases $B_i^j=0$ and $B_i^j=1$ with the cases $A_{i+1}^{j+1}=1$ and $A_{i+1}^{j+1}=-1$, respectively.

