 \hline
 Girth $16$ & $m \geq 1 + w_r(w_c-1) + w_r(w_r-1)(w_c-1)^2 + w_r(w_r-1)^2(w_c-1)^3 + (w_r-1)^3(w_c-1)^4$ \\
