We define a base graph $H_\text{base}$ as a three-layer tree rooted at a check node, in which each check node has degree $w_r$, and each variable node has degree $w_c$, except those located in the final layer. The structure is illustrated in Fig. $1$. To obtain the final layer variable nodes with degree $w_c$, we employ a recursive process that introduces additional sets of check nodes, progressively extending the structure. This construction is described in Algorithm 1.

% \begin{definition}
% For given \( w_r \geq w_c \geq 2 \), the \((w_c, w_r)\)-regular graph \(H_{\text{reg}}\) is constructed as follows:
{\small
\begin{algorithm}
\label{reg-def}
\caption{\((w_c, w_r)\)-regular graph \(H_{\text{reg}}\) with girth $8$}
\begin{algorithmic}[1]

\State \textbf{Input:} Column weight $w_c$, row weight $w_r$
\State \textbf{Output:} \(H_{\text{reg}}\)
\State \textbf{Level 1: Base Graph Construction}
\State Construct base tree $H_{\text{base}}$ with parameters $w_r$ and $w_c$.
\State Define first layer variable nodes as $v_{1,0}, v_{2,0}, \dots, v_{w_r,0}$.
\For{$i = 1$ to $w_r$}
    \State Denote second-layer variable nodes rooted at $v_{i,0}$ by:
    \[
        \{v_{i,1}, \dots, v_{i,(w_c - 1)(w_r - 1)}\}
    \]
\EndFor
\State \textbf{Level 2: Adding Extra Check Nodes}
\For{$j = 1$ to $(w_c - 1)(w_r - 1)$}
    \State Add check node $c_j$ connecting $\{v_{1,j}, \dots, v_{w_r,j}\}$
\EndFor

\If{$w_c \geq 3$}
    \State \textbf{Level 3: Recursive Expansion}
    \For{$s = 1$ to $w_c - 2$}
        \State Create $w_r$ copies of the current graph
        \State Label variable nodes in the $t$-th copy as $v^{(s,t)}_{i,j}$
        \For{$j = 1$ to $w_r^s(w_c-1)(w_r-1)$}
            \State Add check node $c^{(s)}_j$ connecting
            \[
                \{v^{(s,1)}_{i,j}, v^{(s,2)}_{i,j}, \dots, v^{(s,w_r)}_{i,j}\}
            \]
        \EndFor
    \EndFor
\EndIf

\end{algorithmic}
\end{algorithm}
}
