	\includegraphics[width=0.9\textwidth]{Cone0.9}
	\caption{The modulus $|u(x,x,t)|$ is plotted. The inhomogeneity $u$ satisfies the fully nonlinear \eqref{eq:inhomalb1} with $\Gamma$ given in \eqref{eq:gamma} and $C=0.9.$ The initial condition $u_0$ is given in \eqref{eq:u0}. Observe that the solution does not grow significantly from its initial magnitude.}
