\bibliography{CollectionSupervised.bib}

\appendix

\section{Derivation of invariants}\label{app:A}

The following invariants for \eqref{eq:inhomalb1} were introduced in \cite{Ribal2013AlberEquation}. We include them here, along with their derivation in our notation, for completeness.


\begin{lemma}\label{lm:inva} Let $u$  satisfy equation \eqref{eq:inhomalb1} with Hermitian initial data, and denote
\begin{align}
I_1[u] &:= \int\limits_x u(x,y,t)\Big|_{y=x} dx , \\
I_2[u] &:=  \int\limits_x (\partial_x - \partial_y)u(x,y,t)\Big|_{y=x} dx , \\
I_3[u] &:= \left( \frac{q}p \int\limits_x u^2(x,y,t)\Big|_{y=x} dx + \int\limits_x (\partial_x - \partial_y)^2u(x,y,t)\Big|_{y=x} dx \right) .
\end{align}
 Then, 
\begin{equation}\label{eq:lmstconcs12}
\frac{d}{dt} I_j[u] = 0 \qquad \mbox{ for } j\in \{1,2,3\}.	
\end{equation}

\end{lemma}

\medskip


\noindent {\bf Remark:} The function $u(x,x,t)$ is real-valued by the symmetry of the problem, but not non-negative. Thus the conservation of $I_1[u]$ is compatible with potentially large values of $u,$ but there will have to be positive and negative values so that the total integral is preserved. 

\medskip

\noindent {\bf Proof:} To prove this lemma, it is helpful to use the
change of variables
\begin{equation}
	\left\{
	\begin{array}{c}
		X=\frac{x+y}2 \\
		r = x-y
	\end{array}
	\right\} 
	\iff 
	\left\{
	\begin{array}{c}
	x = X+\frac{r}2 \\
	y = X - \frac{r}2
	\end{array}
	\right\}.
\end{equation}
Originally $x,y$ are two position variables,  and $X$ has the physical meaning of ``mean position'' while $r$ of ``lag'' between the two positions.  For any $j=1,2,\dots,$ observe that $\partial_x^j = (\partial_X + \frac{1}2\partial_r)^j,$ $\partial_x^j = (\partial_X - \frac{1}2\partial_r)^j.$  

Now denote
\begin{equation}\label{eq:chngvra}
	f=f(X,r,t) = u(x,y,t), \qquad n(X,t):= f(X,0,t).
\end{equation}
So if $u(x,y,t)$ satisfies equation \eqref{eq:inhomalb1},
then $f$ satisfies
\begin{equation}\label{eq:alberXr}
	i f_t  - p \partial_X \cdot \partial_r f - q \Bigl(n(X+\frac{r}2)-n(X-\frac{r}2)\Bigr) \, \Bigl( 
	\Gamma(r) + f 	\Bigr)=0.
\end{equation}

In this formalism, equation \eqref{eq:lmstconcs12} is elaborated to
\begin{align}
	&\frac{d}{dt} \int\limits_X n(X,t) dX = 0, \label{eq:I1consb} \\
	&\frac{d}{dt} \int\limits_X \partial_r f(X,r,t)\Big|_{r=0} dX = 0, \label{eq:I2consb}\\
	&\frac{d}{dt} \left( \frac{q}p \int\limits_X n^2(X,t) dX + \int\limits_X \partial_r^2 f(X,r,t)\Big|_{r=0} dX \right) = 0 \label{eq:I3consb}
\end{align}

\medskip 

Proof of equation \eqref{eq:I1consb}: setting $r=0$ in equation \eqref{eq:chngvra} and integrating in $X$ leads to
\[
\int\limits_X\Bigl( if_t(X,0,t) - p \partial_X \partial_r f(X,0,t) \Bigr)dX = 0 \implies \frac{d}{dt} \int\limits_X f(X,0,t) dX =0
\]
by performing integration by parts in $X.$


\medskip 

Proof of equation \eqref{eq:I2consb}: differentiating equation \eqref{eq:alberXr} with respect to $r_j$ yields
\begin{equation}\label{eq:derralb}
\begin{array}{c}
		i \partial_{t}f_{r_j}  - p \partial_X \cdot \partial_r f_{r_j} - \frac{q}2 \Bigl(n_{X_j}(X+\frac{r}2,t)+n_{X_j}(X-\frac{r}2,t)\Bigr) \, \Bigl( 
	\Gamma(r) + f 	\Bigr)  \hfill \\
	\hfill - q \Bigl(n(X+\frac{r}2)-n(X-\frac{r}2)\Bigr) \, \Bigl( 
	\partial_{r_j}\Gamma(r) + f_{r_j} 	\Bigr) =0.
\end{array}
\end{equation}
%where we used
%\[
%\partial_{r_j} n(X\pm\frac{r}2,t) = \pm\frac{1}2n_{X_j}(X+\frac{r}2)
%\]
%since the position density $n(X,t)$
Now setting $r=0$ this becomes
\[
i\,\partial_t f_{r_j}(X,0,t)-p\,\partial_X\!\cdot\!\partial_r f_{r_j}(X,0,t)
-q\bigl(\Gamma(0)+n(X,t)\bigr)\,n_{X_j}(X,t)=0.
\]
Integrating over \(X\)  gives
\[
\begin{array}{c}
i\frac{\mathrm d}{\mathrm dt}\int\limits_X f_{r_j}(X,0,t)\,\mathrm dX
-q\int\limits_X\!\bigl(\Gamma(0)+n(X,t)\bigr)\,n_{X_j}(X,0,t)\,\mathrm dX=0, \\[8pt]

i\frac{\mathrm d}{\mathrm dt}\int\limits_X f_{r_j}(X,0,t)\,\mathrm dX
-q\Gamma(0)\int\limits_X\,n_{X_j}(X,t)\,\mathrm dX +\frac{q}2\int\limits_X\,\partial_{X_j}n^2(X,t)\,\mathrm dX=0. \\
\end{array}
\]
Equation \eqref{eq:I2consb} follows by  integration by parts in the two last terms.





\medskip 

Proof of equation \eqref{eq:I3consb}: by differentiating twice in $r,$ equation \eqref{eq:alberXr} becomes
\[
\begin{array}{r}
i\partial_t \Delta_r f - p \partial_X \cdot \partial_r \Delta_r f - \frac{q}4 \Bigl( \Delta_X n(X+\frac{r}2) - \Delta_X n(X-\frac{r}2) \Bigr) \Bigl( \Gamma(r) + f(X,r,t) \bigr)  \\
-q \nabla_X\Bigl( n(X+\frac{X}2) + n(X-\frac{n}2) \Bigr) \cdot \nabla_r \Bigl( \Gamma(r) + f(X,r,t) \Bigr) \\
-q \Bigl( n(X+\frac{r}{2}) - n(X-\frac{r}2) \Bigr) \Delta_r\Bigl( \Gamma(r) + f(X,r,t) \Bigr)=0.
\end{array}
\]
By setting $r=0$  we get
\[
\begin{array}{r}
i\partial_t \Delta_r f(X,0,t) - p \partial_X \cdot \partial_r \Delta_r f(X,0,t) \hfill \\
-q \nabla_X\Bigl( n(X+\frac{X}2) + n(X-\frac{n}2) \Bigr) \cdot \nabla_r \Bigl( \Gamma(r) + f(X,0,t) \Bigr) =0;
\end{array}
\]
by integrating in $X$ and some obvious integrations by parts
\begin{equation}\label{eq:last3a}
\begin{array}{r}
i\frac{d}{dt}\int\limits_X \Delta_r f(X,0,t) dX 
-2q \int\limits_X \nabla_X n(X,t)  \cdot  \nabla_rf(X,0,t)  dX =0.
\end{array}
\end{equation}
Moreover, by multiplying equation \eqref{eq:alberXr} with $f,$  setting $r=0$ and integrating in $X$ we get
\begin{equation}\label{eq:last23a}
\begin{array}{c}
\int\limits_X f(X,0,t) \Bigl( 
	i f_t(X,0,t)  - p \partial_X \cdot \partial_r f(X,0,t) \Bigr) dX=0 \implies \hfill \\
	\hfill \implies -\frac{i}{p} \frac{1}2 \frac{d}{dt} \int\limits_X n^2(X)dX =  \int\limits_X \nabla_X n(X,t) \cdot \nabla_r f(X,0,t) dX
\end{array}
\end{equation}
By combining equations \eqref{eq:last3a} and \eqref{eq:last23a}, relation \eqref{eq:I3consb} follows.
\qed 


