\begin{algorithm*}[t]
\caption{Patch-Autoregressive Mechanism}
\label{alg: dynpatch}
\begin{algorithmic}[1]
\Require{
    Damaged image $X_d$ with damage detection boxes $B=\{b_1, b_2, \dots \}$, 
    Patch size $P$, Stride $S$
}
\Ensure{
    Restored image $X_r$
}
\State $X_r \gets \text{Copy}(X_d)$
\State Initialize each $b_i \in B$ with $\mathrm{restored\_flag}(b_i) \leftarrow \text{False}$ 
\While{there exists an unrestored box $b_i \in B$ with $\mathrm{restored\_flag}(b_i) = \text{False}$}
    \State $\mathcal{U} \gets \{\,b_i \mid \mathrm{restored\_flag}(b_i)=\text{False}\}$ \Comment{Collect unrestored boxes}
    \State $(x_\mathrm{min}, y_\mathrm{min}, x_\mathrm{max}, y_\mathrm{max}) \gets \text{ComputeExtent}(\mathcal{U})$
    \State $\mathcal{C} \gets \text{DefineCorners}(x_\mathrm{min},y_\mathrm{min},x_\mathrm{max},y_\mathrm{max})$ 
       \Comment{Four corners for patch placement}
    \For{corner $c \in \mathcal{C}$}
        \State $\mathrm{cnt}(c) \gets \text{CountUnrestoredInPatch}(c, \mathcal{U}, P)$
        \Comment{Compute the number of unrestored boxes in the patch at corner $c$}
    \EndFor
    \State $c^* \gets \arg\min_{c \in \mathcal{C}} \bigl(\mathrm{cnt}(c)\bigr)$ 
       \Comment{Select corner with minimal damage}
    \For{(startX, startY) in SlidingWindow($c^*, S, P$)}
        \State $(x_s, y_s, x_e, y_e) \gets \text{ClipToBounds}(startX, startY, X_r, P)$
        \State $B_\mathrm{inside} \gets \text{FindFullyContainedBoxes}(x_s,y_s,x_e,y_e,\mathcal{U})$
        % \State $B_\mathrm{partial} \gets \text{FindPartialBoxes}(x_s,y_s,x_e,y_e,\mathcal{U})$
        \State $x_c, x_m \gets \text{RenderContentMask}(X_r,B_\mathrm{inside})$
        \State $x_r \gets \text{InpaintPatch}(X_r, x_c, x_m)$ 
           \Comment{Restore this patch}
        \State $\text{Paste}(x_r \text{ into } X_r \text{ at } (x_s,y_s,x_e,y_e))$
        \State \textbf{Mark} each box in $B_\mathrm{inside}$ \textbf{as restored} 
           $\bigl(\mathrm{restored\_flag}(b)\leftarrow\text{True}\bigr)$
    \EndFor
\EndWhile
% \State $\hat{x} \gets \text{FinalRefine}(x_r)$ 
\State \Return $X_r$
\end{algorithmic}
\end{algorithm*}



