\begin{theorem}\label{thm:ilj}
Let $C_U$ be a control-$U$ gate on a $n$-qubit system with $i$-th qubit as the control qubit and $j$-th qubit as target qubit, $1\leq i<j\leq n.$ Then $C_U$ takes the form given by equation (\ref{cum}) where $\widehat{U}=\diag\{\underbrace{\widehat{U}^{(1)}, \hdots, \widehat{U}^{(1)}}_{2^{j-i-1}\,\mbox{-blocks}}\}$ and $\widehat{U}^{(1)}\in\C^{2^{n-j+1}\times 2^{n-j+1}}$ is given by equation (\ref{eqn:upq}). A Hermitian matrix $H\in\C^{2^n\times 2^n}$ such that $C_U=e^{-\iota H}$ is given by equation (\ref{eqn:H1}).
\end{theorem}

\pf Note that $C_U$ acts non-trivially on an $n$-qubit input $\ket{k_1\hdots k_i\hdots k_j\hdots k_n}$ if $\ket{k_i}=\ket{1},$ otherwise the input remains invariant. 
%It follows from $\QT_n$ that number of $n$-qubit basis states with control qybut $\ket{1}$ equals the number of nodes of order $i-1$ in $\QT_n.$ Further, the two nodes of order $i$ that stem from each node of order $i-1$ with edge labels $0$ and $1$ correspond to $i$-qubit states with $i$-th qubit $\ket{0}$ and $\ket{1}$ respectively and $C_U$ acts nontrivially on the $n$-qubits that are stemmed from the later. Since there are $2^{n-i}$ terminal nodes that are stemmed from any node of order $i$ in $\QT_n,$ $C_U$ acts nontrivially on every alternative collection of consecutive $2^{n-i}$ $n$-qubit states starting from $(2^{n-i}+1)$-th $n$-qubit basis state. Hence, $C_U=\diag\{U_l\in\C^{2^{n-i}}\times 2^{n-i} : 1\leq l\leq 2^{i}\}$ where $U_l=I_{2^{n-i}}$ if $l=1+2{\alpha},$ $\alpha=0,1,\hdots,2^{i-1}-1,$ and otherwise if $l=2\beta,$ $\beta=1,\hdots, 2^{i-1}$ then $U_l$ can be derived as follows.
A basis element  $\ket{k_1\hdots k_i\hdots k_j\hdots k_n}$ corresponds to the non-negative integer $k=\sum_{\alpha=1}^n k_\alpha 2^{n-\alpha},$  $k_\alpha\in\{0,1\}.$ Thus the ordered basis of the $2^n$ dimensional Hilbert space can be written as $\{\ket{k} : 0\leq k\leq 2^{n-1}\}$ with the one-one correspondence $\ket{k} \leftrightarrow \ket{k_1\hdots k_i\hdots k_j\hdots k_n}.$ Then from equation (\ref{cu1}) we obtain \begin{equation}
    \bra{k}C_U\ket{k} = u_{11}, \,\,
    \bra{k}C_U\ket{k+2^{n-j}} = u_{12},\,\,  
    \bra{k+2^{n-j}}C_U\ket{k} = u_{21}, \,\, 
    \bra{k+2^{n-j}}C_U\ket{k+2^{n-j}} = u_{22} 
\end{equation} when $\ket{k_i}=\ket{1}.$ Further, $2^{n-j}<2^{n-i}$ since $i<j,$ and hence $C_U$ takes the form as mentioned in equation (\ref{cum}).

%Let $B_i$ denote the ordered set of consecutive ordered $2^{n-i}$ basis states that corresponds to terminal nodes of $\QT_n$ and $C_U$ acts on them non-trivially, each of which is originated from a node of order $i$ which corresponds to an $i$-qubit state with the last state $\ket{1}.$ Besides, from equation (\ref{cu}) it follows that output of each $n$-qubit state with $i$-th qubit $\ket{1}$ under $C_U$ can be written as a linear combination of itself and the state that places $2^{n-j}$ after it in the standard order of the basis when the $j$-th qubit of is $\ket{0},$ and if the $j$-th qubit is $\ket{1}$ the the output is a linear combination of itself and a basis state which is placed before $2^{n-j}$ in the standard order of the basis. This process repeats for each set $B_i$ and we need to construct the matrix representation of $C_U$ when its action is restriced to the basis elements of $B_i,$ that its, $U_l, l=2\beta.$ However, it can further be observed that this  

Observe that $\widehat{U}$ acts similarly in each set $B_l,$ and the matrix representation of the action of $\widehat{U}$ on the first $2\times 2^{n-j}=2^{n-j+1}$ elements of $B_l,$  is enough for the construction of $\widehat{U}$ since $\widehat{U}$ acts similarly periodically on the remaining states in $B_l.$ The number of blocks of basis elements of $B_l$ on which $\widehat{U}$ acts on identical fashion is $2^{n-i}/(2\times 2^{n-j})=2^{j-i-1}.$ 
%$2^{n-i}/(1+2^{n-j}+2^{n-j}-1)=2^{n-i}/2^{n-j+1}=2^{j-i-1}.$ 
Therefore, $\widehat{U}$ is a block diagonal matrix with repeating diagonal blocks which are unitary matrices of order $2^{n-j+1}$ (see Figure \ref{Uform1}). Then  
\begin{equation}\label{eqn:uhatc1}\widehat{U}=\diag\{\underbrace{\widehat{U}^{(1)}, \hdots, \widehat{U}^{(1)}}_{2^{j-i-1}\,\mbox{-blocks}}\}\end{equation} with  
$\widehat{U}^{(1)}=\bmatrix{u_{pq}^{(1)}}\in \C^{2^{n-j+1} \times 2^{n-j+1}}$ and
\begin{equation}\label{eqn:upq}
u_{pq}^{(1)}=\left\{
  \begin{array}{ll}
u_{11} & \hbox{$1\leq p=q \leq 2^{n-j}$} \\
u_{12} & \hbox{$p=r, q=r+2^{n-j}, r\in\{1,\hdots,2^{n-j}\}$}\\
u_{21} & \hbox{$p=r+2^{n-j}, q=r, r\in \{1,\hdots,2^{n-j}\}$}\\
u_{22} & \hbox{$1+2^{n-j}\leq p= q\leq 2^{n-j+1}$}\\
0 & \hbox{otherwise.}
\end{array}
\right.\end{equation} Thus $\widehat{U}^{(1)}$ is a two-sparse matrix with the following structure $$\widehat{U}^{(1)}=\bmatrix{u_{11}&&&&u_{12}&&& \\ & u_{11}&&&&u_{12}&& \\ &&\ddots&&&&\ddots& \\
&&&u_{11}&&&&u_{12} \\ u_{21}&&&&u_{22}&&& \\ & u_{21}&&&&u_{22}&& \\ &&\ddots&&&&\ddots& \\
&&&u_{21}&&&&u_{22}}.$$
Consequently, the expression of $\widehat{U}$ follows.
This concludes the proof of the first part of the theorem about the construction of $C_U$.

Next we consider finding a Hermitian matrix $H$ such that $C_U=e^{-\iota H}.$ Using Proposition \ref{prop:eigexp}, it is enough to determine a complete set of eigenpairs of $C_U$ that enables to derive eigendecomposition of $H$ and consequently an explicit formula for $H$ can be obtained. First observe that the one-qubit gate $U$ is embedded in $\widehat{U}^{(1)}\in \C^{2^{n-j+1}\times 2^{n-j+1}}$ as submatrix corresponding to the indices $\{r,r+2^{n-j}\}\times \{r,r+2^{n-j}\}$ for any $r\in \{1,\hdots,2^{n-j}\}.$ Let $\ket{u_1}=\bmatrix{\widehat{u}_{11} & \widehat{u}_{12}}^T$ and $\ket{u_2}=\bmatrix{\widehat{u}_{21} & \widehat{u}_{22}}^T$ be the orthonormal eigenvectors of $U$ corresponding to the eigenvalues $\lam_1$ and $\lam_2$ respectively. Then for any $r,$ the vector $\ket{v_r^{(1)}}_s=[v_{s,r}]_{l=1}^{2^{n-j+1}}\in \C^{2^{n-j+1}}$ given by 
\begin{equation}\label{eqn:upq1}
[v_{s,r}]_l=\left\{
  \begin{array}{ll}
\widehat{u}_{s1} & \hbox{if $l=r$} \\
\widehat{u}_{s2} & \hbox{if $l=r+2^{n-j}$}\\
0 & \hbox{otherwise.}
\end{array}
\right.\end{equation} is an eigenvector of $\widehat{U}^{(1)}$ corresponding to the eigenvalue $\lam_s, s=1,2.$ Thus $\left(\lam_s,\ket{v_r^{(1)}}_s\right), s=1,2,$  $r\in\{1,\hdots,2^{n-j}\}$ provide a complete list of eigenpairs of $\widehat{U}^{(1)}.$  

Now since $\widehat{U}$ is a diagonal block matrix with $2^{j-i-1}$ blocks $\widehat{U}^{(1)},$ by Lemma \ref{lem:ep} a complete list of orthonormal eigenvectors of $\widehat{U}$ are given by $$\left(\lam_s, \ket{v_{l,s,r}}=\ket{e_l}\otimes \ket{v_r^{(1)}}_s\right)$$ for any $\ket{e_l}$ belongs to the standard ordered basis of $\C^{2^{j-i-1}}$, $1\leq l\leq 2^{j-i-1}$ $s=1,2$, and $r\in \{1,\hdots,2^{n-j}\}.$ Note that eigenvalues of $U$ are eigenvalues of $\widehat{U}$ and each eigenvalue of $U$ has algebraic multiplicity $2^{n-i-1}$ as an eigenvalue of $\widehat{U}.$

Further, since $C_U=\diag\{\underbrace{I_{2^{n-i}}, \widehat{U}, I_{2^{n-i}},\widehat{U},\hdots,I_{2^{n-i}}, \widehat{U}}_{2^i\,\mbox{-blocks}} \},$ by Lemma \ref{lem:ep} it follows that the complete list of eigenpairs of $C_U$ is $$(1,\ket{f_{m_1}}\otimes \ket{e_{m_2}} ), (\lam_s,\ket{f_{m_3}}\otimes \ket{v_{l,s,r}})$$ where $\{\ket{f_{m_1}} \in\C^{2^i}: m_1=1+2\alpha, \alpha=0,1,\hdots,2^{i-1}-1 \}$ is the subset of the standard ordered basis $F_m=\{\ket{f_m} : 1\leq m\leq 2^i\}$ of $\C^{2^i}$, $\{\ket{e_{m_2}} : 1\leq m_2 \leq 2^{n-i}\}$ is the standard ordered basis of $\C^{2^{n-i}},$ $\{\ket{f_{m_3}} : m_3=2\beta, \beta=1,2,\hdots,2^{i-1}\}$ is a subset of $F_m$, and $(\lam_s,\ket{v_{l,s,r}})$ are eigenpairs of $\widehat{U}.$ Thus the eigendecomposition of $C_U$ is given by $$C_U=\sum_{m_1,m_2} (\ket{f_{m_1}}\otimes \ket{e_{m_2}})(\bra{f_{m_1}}\otimes \bra{e_{m_2}}) + \sum_{m_3,l,s,r} \lam_s (\ket{f_{m_3}}\otimes \ket{v_{l,s,r}})(\bra{f_{m_3}}\otimes \bra{v_{l,s,r}}).$$

Finally, by Proposition \ref{prop:eigexp} observe that eigenvalues of a desired $H$ are given by $z$ which correspond to the eigenvalues $\lam$ of $C_U$ such that $e^{-\iota z}=\lam,$ and the eigenvectors of $H$ are same as the corresponding eigenvectors of $C_U.$ Since some of the eigenvalues of $C_U$ are $1,$ the corresponding eigenvalues of $H$ are $0,$ and hence they do not contribute to the construction of $H,$ the remaing eigenvalues of $H$ are $z_s$ such that $\lam_s=e^{-\iota z_s}.$ Thus we conclude that \begin{equation}\label{eqn:H1}
    H=\sum_{m_3,l,s,r} z_s \, (\ket{f_{m_3}}\bra{f_{m_3}}\otimes \ket{v_{l,s,r}}\bra{v_{l,s,r}}).
\end{equation}
This completes the proof. $\hfill{\square}$






\begin{example}\label{exp1}
Now we consider an example of $n=5$-qubit system. We assume that $i$-th qubit is control and $j$-th qubit is the target. In the following we determine explicit formula for $\widehat{U}.$
\begin{itemize}
    \item[(a)] Let $i=2$ and $j=3.$ Then $$\widehat{U}=\bmatrix{u_{11} & 0&0&0&u_{12}&0&0&0\\ 0 & u_{11} & 0& 0& 0& u_{12} &0&0\\ 0 & 0 & u_{11} & 0&0&0& u_{12} &0\\ 0 & 0&0& u_{11} &0&0&0& u_{12} \\ u_{21}&0&0&0&u_{22}&0&0&0 \\ 0& u_{21} &0&0&0& u_{22} &0&0 \\ 0&0& u_{21} &0&0&0& u_{22} &0 \\ 0&0&0& u_{21} &0&0&0& u_{22}}$$ and consequently $C_U=\diag\{I_{2^3},\widehat{U},I_{2^3},\widehat{U}\}.$



\item[(b)] Let $i=2$ and $j=4.$ Then $\widehat{U}=\diag\{\widehat{U}^{(1)},\widehat{U}^{(1)}\}$ where $$\widehat{U}^{(1)}=\bmatrix{u_{11}&0&u_{12}&0 \\ 0&u_{11}&0&u_{12}\\ u_{21}&0&u_{22}&0 \\ 0&u_{21}&0&u_{22}}$$ and hence $C_U=\diag\{I_{2^3},\widehat{U}^{(1)},\widehat{U}^{(1)},I_{2^3},\widehat{U}^{(1)},\widehat{U}^{(1)}\}.$ 
\end{itemize}
\end{example}

Now we describe algorithms based on the proof of Theorem \ref{thm:ilj} for generation of the unitary matrix $C_U$ and the Hermitian matrix $H$ such that $C_U=e^{-\iota H}.$ Algorithm \ref{alg:widehat1_u} describes construction of $\widehat{U}^{(1)}$, which is then used in Algorithm \ref{alg:MatRep_CU} for the construction of $C_U.$ Next, Algorithm \ref{alg:eigvec_widehat1_u} delivers symbolic expression of eigenpairs of $\widehat{U}^{(1)},$ which is further used to derive a Hermition matrix $H$ in Algorithm \ref{alg:oneConnMatrix} such that $C_U=e^{-\iota H}.$





\begin{algorithm}
    \caption{Construction of $\widehat{U}^{(1)}$}
    \label{alg:widehat1_u}
    \begin{algorithmic}[1]
      	\Require The fixed variables $n,i,j,$ and $1\leq i<j\leq n.$ A unitary matrix $U=\bmatrix{u_{11} & u_{12} \\ u_{21} & u_{22}}.$  
		\Ensure Generation of the symbolic unitary matrix $\widehat{U}^{(1)}=\left[u_{pq}^{(1)}\right]\in \C^{2^{n-j+1}\times 2^{n-j+1}}$.
        \Statex
        \Procedure{Uhat1}{$U$}
            %\State $\mathcal{C} \gets $\Call{Cycles}{$\calD$}
            %\State $\mathcal{S} \gets $ all pairwise vertex disjoint subsets of $\mathcal{C}$
            \State $\widehat{U}^{(1)} \gets 0$
            \ForAll{$1 \leq p,q \leq 2^{n-j}$}
            \For{$r\gets 1$ to $2^{n-j}$}
	\If{$p=r$ \, and \, $q=r+2^{n-j}$}
	\State $u^{(1)}_{pq}\gets u_{12} $
	\EndIf
	%\For{$r\gets 1$ to $2^{n-j}$}
	\If{$q=r$ \, and \, $p=r+2^{n-j}$}
	\State $u^{(1)}_{pq}\gets u_{21} $
	\EndIf
	\EndFor
	  	\If{$p=q$ \, and \, $1\leq p\leq 2^{n-j}$}
	\State $u^{(1)}_{pq} \gets u_{11}$
	\EndIf
    	\If{$p=q$ \, and \, $1+2^{n-j}\leq p\leq 2^{n-j+1}$}
	\State $u^{(1)}_{pq} \gets u_{22}$
	\EndIf
	%{$p=q$ $\&\& p\geq 1+2^{n-j} || p\leq 2^{n-j+1}$ }
%	\State $u^{(1)}[p][q] \gets 0$
	%\Endelse
	\EndFor
    \State \Return $\widehat{U}^{(1)}$
        \EndProcedure
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}
    \caption{Matrix representation of $C_U$}
    \label{alg:MatRep_CU}
    \begin{algorithmic}[1]
      	\Require The fixed variables $n,i,j,$ and $1\leq i<j\leq n.$ A unitary matrix $U=\bmatrix{u_{11} & u_{12} \\ u_{21} & u_{22}}.$  
		\Ensure The matrix representation of the control two-qubit gate $C_U$ with $i$th qubit as control and $j$th qubit as target in an $n$-qubit system, $(i< j)$
        \Statex
        \Procedure{MRep}{$C_U$}
            %\State $\mathcal{C} \gets $\Call{Cycles}{$\calD$}
            %\State $\mathcal{S} \gets $ all pairwise vertex disjoint subsets of $\mathcal{C}$
            \State $M \gets \Call{Uhat1}{U}$
           \State $\widehat{U}\gets \diag\{\underbrace{M,\hdots,M}_{2^{j-i-1}-\mbox{copies}}\}$
    \State \Return $C_U=\diag\{\underbrace{I_{2^{n-i}}, \widehat{U}, I_{2^{n-i}}, \widehat{U}, \hdots, I_{2^{n-i}}, \widehat{U}}_{2^{j}\mbox{- blocks}}\}$
        \EndProcedure
    \end{algorithmic}
\end{algorithm}




\begin{algorithm}
    \caption{Computation of eigenpairs of $\widehat{U}^{(1)}$}
    \label{alg:eigvec_widehat1_u}
    \begin{algorithmic}[1]
      	\Require The fixed variables $n,i,j,$ and $1\leq i<j\leq n.$ Eigenairs $\left(\lam_s,\bmatrix{\widehat{u}_{s1} \\ \widehat{u}_{s2}}\right)$, $s=1,2$ of the one-qubit gate $U.$
		\Ensure Construction of eigenpairs $\left(\lam_s, v_{r,s}=[v_{r,s}]_{l=1}^{2^{n-j+1}}\right),$ $s=1,2$ and $r=1,\hdots, 2^{n-j}.$ 
        \Statex
        \Procedure{EigVec}{$\widehat{U}^{(1)}$}
            %\State $\mathcal{C} \gets $\Call{Cycles}{$\calD$}
            %\State $\mathcal{S} \gets $ all pairwise vertex disjoint subsets of $\mathcal{C}$
            \For{$s \gets 1$ to $2$}
            \For{$r \gets 1$ to $2^{n-j}$}
            \State $v_{r,s} \gets 0$
            \For{$l \gets 1$ to $2^{n-j+1}$}
            \If{$l=r$}
            \State $[v_{r,s}]_l\gets \widehat{u}_{s1}$
            \EndIf
            \If{$l=r+2^{n-j}$}
             \State $[v_{r,s}]_l\gets \widehat{u}_{s2}$
            \EndIf
            \EndFor
            \EndFor
            \EndFor
           \State \Return $v_{r,s}$
        \EndProcedure
    \end{algorithmic}
\end{algorithm}



\begin{algorithm}
    \caption{Finding a Hamiltonian $H$ for the two-qubit control gate $C_U.$ }
    \label{alg:oneConnMatrix}
    \begin{algorithmic}[1]
      	\Require The fixed variables $n,i,j,$ and $1\leq i<j\leq n.$ Standard ordered bases $\{e_l : 1\leq l\leq 2^{j-i-1}\},$ $\{f_m : 1\leq m\leq 2^{i}\}$ of $\C^{2^{j-i-1}}$ and $\C^{2^i}$ respectively. The eigenvalues $\lam_s=e^{-\iota z_s}, s=1,2$ of $U.$ 
		\Ensure Construction of a Hermitian matrix $H$ such that $C_U=e^{-\iota H}$
        \Statex
        \Procedure{Hamiltonian}{$C_U$}
            %\State $\mathcal{C} \gets $\Call{Cycles}{$\calD$}
            %\State $\mathcal{S} \gets $ all pairwise vertex disjoint subsets of $\mathcal{C}$
            \For{$s\gets 1$ to $2$}
            \For{$r \gets 1$ to $2^{n-j}$}
            \For{$l \gets $ to $2^{j-i-1}$}
            \State $v_{l,r,s} \gets e_l\otimes \Call{EigVec}{\widehat{U}^{(1)}}$
            \EndFor
            \EndFor
            \EndFor
           \State \Return $H=\sum_{\beta=1}^{2^{i-1}} z_s \, \left(f_{2\beta} \otimes v_{l,r,s}\right) \left(f_{2\beta} \otimes v_{l,r,s}\right)^T$
        \EndProcedure
    \end{algorithmic}
\end{algorithm}


