\begin{theorem}\label{thm:igj}
Let $C_U$ denote a control-$U$ gate on an $n$-qubit system with $i$-th qubit as the control qubit and $j$-th qubit as target qubit, $1\leq j<i\leq n.$ Then $C_U$ takes the form given by equation (\ref{cu2}) where $\widehat{U}$ is given by equations (\ref{eqn:uwide})-(\ref{eqn:dpq}). A Hermitian matrix $H\in\C^{2^n\times 2^n}$ such that $C_U=e^{-\iota H}$ is given by equation (\ref{eqn:Hamil2}).
\end{theorem}

\pf From the discussion above, $C_U$ acts non-trivially on alternative blocks of $2^{n-i}$ ordered basis states in $2^n$-dimensional Hilbert space. Each of these blocks contains $2^{n-i}$ terminal nodes in $\QT_n$ that are originated from a node of order $i.$ Let us denote the blocks as $B_l, 1\leq l\leq 2^i,$ where each $B_l$ contains $2^{n-i}$ standard ordered basis elements of $\C^{2^n}.$ The matrix $C_U$ acts nontrivially on the elements of $B_l$ for alternative $l$ (when $l$ is even) starting from $l=2.$ 

%when when Thus $C_U$ acts as identity operator for all the states belonging to $B_{2l_1+1}, 0\leq l_1 \leq 2^{i-1}-1$, and otherwise $C_U$ acts non-trivially following equation (\ref{cu}) for all the basis states belonging to $B_{2l_2}, 1\leq l_2\leq 2^{i-1}.$ 

%Thus $C_U$ is given by equation (\ref{cu2}), where $\widehat{U}$ acts on all the states in $B_{l_2}$ for all $l_2.$

Let $\ket{k}\in B_{l}$ for some even $l.$ Then $C_U\ket{k}=u_{11}\ket{k}+u_{21}\ket{k_+}$ or $C_U\ket{k}=u_{12}\ket{k_-}+u_{22}\ket{k}$ where $\ket{k_+}$ and $\ket{k_-}$ denote the state which is placed after and before $2^{n-j} >2^{n-i}$ states from the state $\ket{k}$ in the standard ordered basis of the $2^n$-dimensional Hilbert space respectively, as follows from equation (\ref{cu}). The number of blocks $B_l$ that lie in between $\ket{k}$ and $\ket{k_+}$ or $\ket{k_-}$ is $\alpha = 2^{n-j}/2^{n-i}=2^{i-j},$ and $C_U$ acts non-trivially on each such block alternatively. Thus $\widehat{U}$ is of the form \begin{equation}\label{eqn:uwide}\widehat{U}=\bmatrix{\widehat{U}^{(1)} \\ \widehat{U}^{(2)}\\ %\widehat{U}^{(3)} \\ 
%\widehat{U}^{(4)} \\ 
\vdots \\ \widehat{U}^{(2^{i-j}-1)} \\ \widehat{U}^{(2^{i-j})}\\ \hline \\ \underline{\widehat{U}}^{(1)} \\ \underline{\widehat{U}}^{(2)} \\ %\underline{\widehat{U}}^{(3)} \\ 
%\underline{\widehat{U}}^{(4)} \\ 
\vdots \\ \underline{\widehat{U}}^{(2^{i-j}-1)} },\end{equation} where $\widehat{U}^{(l)} =[u_{pq}^{(l)}]\in \C^{2^{n-i}\times (2^{n-j+1}-2^{n-i})}, \, \underline{\widehat{U}}^{(l)}=[\underline{u}_{pq}^{(l)}] \in \C^{2^{n-i}\times (2^{n-j+1}-2^{n-i})}, 1\leq l\leq 2^{i-j}-1,$ if $l$ is odd, and $\widehat{U}^{(l)}= [d_{pq}^{(l)}]\in \C^{2^{n-i}\times (2^{n-j+1}-2^{n-i})}$ and $\underline{\widehat{U}}^{(l)}=[\underline{d}_{pq}^{(l)}]\in \C^{2^{n-i}\times (2^{n-j+1}-2^{n-i})}$ if $l$ is even, with  
\begin{equation}\label{eqn:upq2}
u_{pq}^{(l)}=\left\{
  \begin{array}{ll}
u_{11}, & \hbox{if $q=p+(l-1)2^{n-i}, 1\leq p\leq 2^{n-i}$} \\
u_{12}, & \hbox{if $q=p+(l-1)2^{n-i}+2^{n-j}, 1\leq p\leq 2^{n-i}$}\\
0, & \hbox{otherwise.}
\end{array}
\right.\end{equation} 
\begin{equation}\label{eqn:lupq}
\underline{u}_{pq}^{(l)}=\left\{
  \begin{array}{ll}
u_{21}, & \hbox{if $q=p+(l-1)2^{n-i}, 1\leq p\leq 2^{n-i}$} \\
u_{22}, & \hbox{if $q=p+(l-1)2^{n-i}+2^{n-j}, 1\leq p\leq 2^{n-i}$}\\
0, & \hbox{otherwise.}
\end{array}
\right.\end{equation}

\begin{eqnarray}
   d_{pq}^{(l)} &=&\left\{
  \begin{array}{ll}
1, & \hbox{if $q=p+(l-1)2^{n-i}, 1\leq p\leq 2^{n-i}$} \\
%u_{12} & \hbox{if $q=p+2^{n-j}, (l-1)2^{n-i}\leq p\leq l2^{n-i}$}\\
0, & \hbox{otherwise.}
\end{array}
\right. \label{eqn:dpq} \\ 
\underline{d}_{pq}^{(l)} &=& \left\{
