%Now from equation (\ref{cu2}) we have \beano C_U &=& \diag\{\underbrace{I_{2^{n-i}}, \widehat{U}, I_{2^{n-i}}, \widehat{U}, \hdots, I_{2^{n-i}}, \widehat{U}}_{2^{j}\mbox{- blocks}}\} \\  &=& \diag\{\underbrace{\bmatrix{I_{2^{n-i}} & \\ & \widehat{U}}, \bmatrix{I_{2^{n-i}} & \\ & \widehat{U}}, \hdots, \bmatrix{I_{2^{n-i}} & \\ & \widehat{U}}}_{2^{j-1}\mbox{- blocks}}\},\eeano where $ \bmatrix{I_{2^{n-i}} & \\ & \widehat{U}}$ is of order $2^{n-j+1}\times 2^{n-j+1}$ having eigenvalue  $\lam_r$ with multiplicities $2^{n-j-1}$ corresponding to the orthonormal eigenvectors $\ket{.;\ket{\widehat{u}_{r,l}}} =\bmatrix{0_{2^{n-i}} \\ \ket{\widehat{u}_{r,l}}}$; and eigenvalue $1$ with multiplicity $2^{n-j}$ corresponding to orthogonal eigenvectors $\ket{e_{m_1};.} =\bmatrix{e_{m_1} \\ 0_{2^{n-j+1}-2^{n-i}}}$ and $\ket{.;\ket{\widehat{u}_{1,l}}}=\bmatrix{0_{2^{n-i}} \\ \ket{\widehat{u}_{1,l}}}$ respectively, $r=1,2$. Thus $\lam_r$ is an eigenvalue of $C_U$ with multiplicity $2^{n-j-1}\times 2^{j-1}=2^{n-2}$ corresponding to the eigenvector $\ket{e_{m_2}}\otimes \ket{.;\ket{\widehat{u}_{r,l}}}; r=1,2$ and $1$ is an eigenvalue with multiplicity $2^{n-j}\times 2^{j-1}=2^{n-1}$ corresponding to the eigenvectors $\ket{e_{m_2}}\otimes \ket{e_{m_1};.}$ and $\ket{e_{m_2}}\otimes \ket{.;\ket{\widehat{u}_{1,l}}},$ where $\{\ket{e_{m_2}} : 1\leq m_2\leq 2^{j-1}\}$ is the canonical basis of $\C^{2^{j-1}}.$ Therefore, the spectral decomposition of $C_U$ is given by \beano C_U &=& \sum_{m_2,m_1} (\ket{e_{m_2}}\bra{e_{m_2}}\otimes \ket{e_{m_1};.}\bra{e_{m_1};.}) + \sum_{r,m_2, 1\leq l\leq 2^{i-j}, l \, \mbox{is odd}} \lam_r (\ket{e_{m_2}}\bra{e_{m_2}}\otimes \ket{.;\widehat{u}_{r,l}}\bra{.;\widehat{u}_{r,l}}) \\ && +  \sum_{m_2, 1\leq l\leq 2^{i-j}-1, l \, \mbox{is even}}  (\ket{e_{m_2}}\bra{e_{m_2}}\otimes \ket{.;\widehat{u}_{1,l}}\bra{.;\widehat{u}_{1,l}}). \eeano

%Finally, by Proposition \ref{prop:eigexp} we conclude that \begin{equation}\label{eqn:Hamil2} H=\sum_{r,m_2, 1\leq l\leq 2^{i-j}, l \, \mbox{is odd}} \iota \mbox{Arg}(\lam_r) (\ket{e_{m_2}}\bra{e_{m_2}}\otimes \ket{.;\widehat{u}_{r,l}}\bra{.;\widehat{u}_{r,l}}),\end{equation} where $\mbox{Arg}(z)$ denotes the principal argument of $z.$This completes the proof. 



