Now we describes the algorithms based on the proof of Theorem \ref{thm:igj}. First, Algorithm \ref{alg:widehatl_u} gives the construction of $\widehat{U}^{(l)}$ based on whether $l$ is odd or even, and Algorithm \ref{alg:widehatl_under_u} gives the construction of $\underline{\widehat{U}}^{(l)}$, These are employed to determine symbolic derivation of $C_U$ in Algorithm \ref{alg:MatRep_i>j}. Symbolic computation of eigenpairs of $\widehat{U}$ is given in Algorithm \ref{alg:ep_Uhat}, which is used in Algorithm \ref{alg:HamMat} to determine a Hamiltonian corresponding to $C_U.$

%The first part of the proof is straightforward just by writing $C_U=\bmatrix{I_2 & 0\\ 0 & U}.$ Next, for the second part, from Proposition \ref{prop:eigexp} the eigenvalues of $H$ for which $C_U=e^{-iH}$ are given by $\log 1=0, \log 1=0,$ $\log\lam_1=i\mathrm{Arg}(\lam_j),$ $j=1,2$ since $|\lam_1|=1=|\lam_2|$ and the corresponding orthogonal eigenvectors of $H$ are $\ket{00},$ $\ket{01},$ $\ket{1}\otimes\ket{u_j}$ respectively. Then the desired result follows from the eigendecomposition of $H.$ $\hfill{\square}$







\begin{algorithm}
    \caption{Construction of $\widehat{{U}}^{(l)}$ }
    \label{alg:widehatl_u}
    \begin{algorithmic}[1]
      	\Require The fixed variables $n,i,j,$ and $1\leq j < i\leq n.$ A unitary matrix $U=\bmatrix{u_{11} & u_{12} \\ u_{21} & u_{22}}.$  
		\Ensure Generation of $\widehat{U}^{(1)} \in \C^{2^{n-i}\times (2^{n-j+1}-2^{n-i})}$.
        \Statex
        \Procedure{$\widehat{U}^{(l)}$}{$U$}
        \State $\widehat{U}^{(l)} \gets 0$
        \If{$l \gets odd$}
            \For{$1 \le p \le 2^{n-i} $}
                \For{$1 \le q \le 2^{n-i+1}-2^{n-i}$}
                    \If{$q = p+(l-1)2^{n-i}$}
                        \State $u_{pq} \gets 1$
                    \EndIf
                \EndFor
            \EndFor
        \EndIf
        \If{$l \gets even$}
            \For{$1 \le p \le 2^{n-i} $}
                \For{$1 \le q \le 2^{n-i+1}-2^{n-i}$}
                    \If{$q = p+(l-1)2^{n-i}$}
                        \State $u_{pq} \gets u_{11}$
                    \EndIf
                    \If{$q = p+(l-1)2^{n-i}+2^{n-j}$}
                        \State $u_{pq} \gets u_{12}$
                    \EndIf
                \EndFor
            \EndFor
        \EndIf
        \State \Return  $\widehat{U}^{(l)}$
        \EndProcedure
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}
    \caption{Construction of  $\underline{\widehat{U}}^{(l)}$}
    \label{alg:widehatl_under_u}
    \begin{algorithmic}[1]
      	\Require The fixed variables $n,i,j,$ and $1\leq j < i\leq n.$ A unitary matrix $U=\bmatrix{u_{11} & u_{12} \\ u_{21} & u_{22}}.$  
		\Ensure Generation of $\underline{\widehat{U}}^{(l)} \in \C^{2^{n-i}\times (2^{n-j+1}-2^{n-i})}$.
        \Statex
        \Procedure{$\underline{\widehat{U}}^{(l)}$}{$U$}
        \State $\underline{\widehat{U}}^{(l)} \gets 0$
        \If{$l \gets odd$}
            \For{$1 \le p \le 2^{n-i} $}
                \For{$1 \le q \le 2^{n-i+1}-2^{n-i}$}
                    \If{$q = p+(l-1)2^{n-i}+2^{n-j}$}
                        \State $\underline{u}_{pq} \gets 1$
                    \EndIf
                \EndFor
            \EndFor
        \EndIf
        \If{$l \gets even$}
            \For{$1 \le p \le 2^{n-i} $}
                \For{$1 \le q \le 2^{n-i+1}-2^{n-i}$}
                    \If{$q = p+(l-1)2^{n-i}$}
                        \State $\underline{u}_{pq} \gets u_{21}$
                    \EndIf
                    \If{$q = p+(l-1)2^{n-i}+2^{n-j}$}
                        \State $\underline{u}_{pq} \gets u_{22}$
                    \EndIf
                \EndFor
            \EndFor
        \EndIf
        \State \Return $\underline{\widehat{U}}^{(l)}$
        \EndProcedure
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}
    \caption{Matrix representation of $C_U$}
    \label{alg:MatRep_i>j}
    \begin{algorithmic}[1]
      	\Require The fixed variables $n,i,j,$ and $1\leq j<i\leq n.$ A unitary matrix $U=\bmatrix{u_{11} & u_{12} \\ u_{21} & u_{22}}.$  
		\Ensure The matrix representation of the control two-qubit gate $C_U$ with $i$th qubit as control and $j$th qubit as target in an $n$-qubit system, $(j<i)$
        \Statex
        \Procedure{MRep}{$C_U$}
            %\State $\mathcal{C} \gets $\Call{Cycles}{$\calD$}
            %\State $\mathcal{S} \gets $ all pairwise vertex disjoint subsets of $\mathcal{C}$
            % \State $M \gets \Call{Uhat1}{U}$
           \State $\widehat{U}\gets vstack\{\widehat{U}^{1},\hdots, \widehat{U}^{2^{i-j}}, \underline{\widehat{U}}^{(1)}, \hdots, \underline{\widehat{U}}^{(2^{i-j}-1)} \}$ 
    \State \Return $C_U=\diag\{\underbrace{I_{2^{n-i}}, \widehat{U}, I_{2^{n-i}}, \widehat{U}, \hdots, I_{2^{n-i}}, \widehat{U}}_{2^{j}\mbox{- blocks}}\}$
        \EndProcedure
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}
    \caption{Computation of eigenpair of $\widehat{U}$}
    \label{alg:ep_Uhat}
    \begin{algorithmic}[1]
        \Require The fixed variables $n,i,j,$ and $1\leq i>j\leq n.$Standard ordered bases $\{e_l : 1\leq l\leq 2^{n-j+1}-2^{n-i}\}$, Eigenpairs $\left(\lam_s,\bmatrix{\widehat{u}_{s1} \\ \widehat{u}_{s2}}\right)$, $s=1,2$ of the one-qubit gate $U.$
        \Ensure Construction of eigenpairs $\left(\lam_s, \ket{v_{l,p}}^{s}\right),$ $s=1,2$ , $p=1,\hdots, 2^{n-i}.$ and $l=1,\hdots, 2^{i-j}-1.$
        \Statex
        \Procedure{EigVec}{$\widehat{U}$}
        \State $\ket{v_{l,p}} \gets 0$
            \For{$s \gets 1$ to $2$}
                \For{$p \gets 1$ to $2^{n-i}$}
                    \For{$l \gets 1$ to $2^{i-j}-1$}
                        \If{$l \gets odd$}
                       \State $ \ket{v_{l,p}^{s}} \gets \widehat{u}_{s1}\ket{e_{p+(l-1)2^{n-i}}} + \widehat{u}_{s2}\ket{e_{p+(l-1)2^{n-i}+2^{n-j}}} $
                       \EndIf
                    \EndFor
                \EndFor
            \EndFor
        \State \Return $\ket{v_{l,p}}$
        \EndProcedure
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}
    \caption{Finding a Hamiltonian $H$ for the two-qubit control gate $C_U.$}
    \label{alg:HamMat}
    \begin{algorithmic}[1]
      \Require The fixed variables $n,i,j,$ and $1\leq j < i\leq n.$ Standard ordered bases $\{\ket{f_{k}} : 1\leq k\leq 2^{j-1}\}$, zero vector $\{\ket{\bold{0}}: 1\leq l\leq 2^{n-j+1}-2^{n-i}\}$  The eigenvalues $\lam_s=e^{-\iota z_s}, s=1,2$ of $U.$ 
      \Ensure Construction of a Hermitian matrix $H$ such that $C_U=e^{-\iota H}$
      \Statex
      \Procedure{Hamiltonian}{$C_{U}$}
      \State $H \gets 0$
        \For{$s \gets 1$ to $2$}
            \For{$p \gets 1$ to $2^{n-i}$}
                \For{$l \gets 1$ to $2^{i-j}-1$}
                    \If{$l \gets$ odd}
                   \State $ v_{l,p,s} \gets vstack(\ket{\textbf{0}},\ket{v_{l,p}^s}) $
                    \EndIf
                \EndFor
            \EndFor
        \EndFor
      \State $H=\sum_{s,l,p,k} z_s \, \left(\ket{f_k}\otimes v_{l,p,s} \right)\left(\ket{f_k}\otimes v_{l,p,s}\right)^\star$
      \State \Return H
      \EndProcedure
    \end{algorithmic}
\end{algorithm}

