&& (u_{11}a_{29}+u_{12}a_{31}) \ket{29} + (u_{11}a_{30}+u_{12}a_{32}) \ket{30} +(u_{21}a_{29}+u_{22}a_{31}) \ket{31}  + (u_{21}a_{29}+u_{22}a_{32}) \ket{32}.
\end{eqnarray*}


    \end{itemize}
\end{example}


Similarly, we can obtain direct formulae for probability amplitudes for $C_{ij}\ket{\psi}$ when $i>j$, and for output state of an input under a string of one-qubit gates. However, it is not immediate what gain is achieved from these expressions. Thus we develop algorithms for the generation of the output states corresponding to an input state when it undergoes these gates in a quantum circuit setup. Then we analyze the complexity of these algorithms.   

%Now incorporating the approach proposed in Figure .. we can derive the probability amplitudes of the output of any $n$-qubit input state for a quantum circuit comprising one-qubit and two-qubit control gates can be derived as follows. 



First, we provide Algorithm(\ref{alg:cpg}) in order to determine output states of an input state for a two-qubit control gate. Next, in Algorithm \ref{alg:sqg} we determine output state for a string of one-qubit gates. Note that these algorithms exploit the sparsity pattern of the $2$-sparse unitary matrices of order $2^n$ corresponding to single-qubit and two-qubit control gates derived in Theorem \ref{thm:ilj}, Theorem \ref{thm:igj} and Theorem \ref{thm:sgate}.

\begin{algorithm}
\caption{Algorithm for applying a control gate on a quantum state}
\label{alg:cpg}
\begin{algorithmic}[1]
\Require The fixed variables n,i,j and $1 \le i,j \le n$ , $i \ne j$. An input quantum state $inp \in \C^{2^{n}}$. A unitary matrix $U=\bmatrix{u_{11} & u_{12} \\ u_{21} & u_{22}}.$
\Ensure Quantum State after the application of control gate $out \in \C^{2^{n}}$
\Procedure{ControlGate}{$\text{inp}, n, i, j, U$}
    \State $out \gets inp$
    \If{$i < j$}
        \State $state \gets 1$
        \For{$x \gets 1$ to $2^i$}
            \If{$x$ is odd}
                \State $state \gets state + 2^{(n-i)}$
            \EndIf
            \If{$x$ is even}
                \For{$a \gets 1$ to $2^{(j-i-1)}$}
                    \For{$b \gets 1$ to $2^{(n-j)}$}
                        \State $\text{out}_{state} \gets u_{11} \cdot \text{inp}_{state} + u_{12} \cdot \text{inp}_{state+2^{(n-j)}}$
                        \State $state \gets state + 1$
                    \EndFor
                    \For{$b \gets 1$ to $2^{(n-j)}$}
                        \State $\text{out}_{state} \gets u_{21} \cdot \text{inp}_{state-2^{(n-j)}} + u_{22} \cdot \text{inp}_{state}$
                        \State $state \gets state + 1$
                    \EndFor
                \EndFor
            \EndIf
        \EndFor
    \Else
        \For{$r \gets 1$ to $2^{(j-1)}$}  % r <- 1
            \For{$l \gets (2r-2) \cdot 2^{(i-j-1)}$ to $(2r-1) \cdot 2^{(i-j-1)}$}
                \For{$k \gets (2l+1) \cdot 2^{(n-i)}+1$ to $(2l+2) \cdot 2^{(n-i)}$}
                    \State $\text{out}_{k} \gets u_{11} \cdot \text{inp}_{k} + u_{12} \cdot \text{inp}_{k+2^{(n-j)}}$
                \EndFor
            \EndFor
        \EndFor
        \For{$r \gets 1$ to $2^{(j-1)}$}
            \For{$l \gets (2r-1) \cdot 2^{(i-j-1)}$ to $(2r) \cdot 2^{(i-j-1)}$}
                \For{$k \gets (2l+1) \cdot 2^{(n-i)}+1$ to $(2l+2) \cdot 2^{(n-i)}$}
                    \State $\text{out}_{k} \gets u_{21} \cdot \text{inp}_{k-2^{(n-j)}} + u_{22} \cdot \text{inp}_{k}$
                \EndFor
            \EndFor
        \EndFor
    \EndIf
    \State \textbf{return} $out$
\EndProcedure
\end{algorithmic}
\end{algorithm}



\begin{algorithm}
    \caption{Algorithm for applying a single qubit gate on a quantum state}
    \label{alg:sqg}
    \begin{algorithmic}
        \Require The fixed variables $n,j$. An input quantum state $inp \in \C^{2^{n}}$. A unitary matrix $U=\bmatrix{u_{11} & u_{12} \\ u_{21} & u_{22}}.$
        \Ensure Quantum State after the application of single qubit gate $out \in \C^{2^{n}}$
        \Procedure{SingleQubitGate}{$\text{inp}, n, j, U$}
        \State $out \gets inp$
        \State $state \gets 1$
        \For{$x \gets 1$ to $2^{j}$}
            \If{$x$ is odd}
                \For{$a \gets 1$ to $2^{(n-j)}$}
                    \State $out_{state} \gets u_{11} \cdot \text{inp}_{state} + u_{12} \cdot \text{inp}_{state + 2^{(n-j)}}$
                    \State $state \gets state + 1$
                \EndFor
            \EndIf
            \If{$x$ is even}
                \For{$a \gets 1$ to $2^{(n-j)}$}
                    \State $out_{state} \gets u_{21} \cdot \text{inp}_{state - 2^{(n-j)}} + u_{22} \cdot \text{inp}_{state}$
                    \State $state \gets state + 1$
                \EndFor
            \EndIf
        \EndFor
        \State \textbf{return} $out$
        \EndProcedure
    \end{algorithmic}
\end{algorithm}



\subsection{Complexity of the algorithms}

%\textbf{For Single Qubit gate:} \newline
% To apply a single qubit gate U on qubit j in an n qubit circuit with initial state $\ket{\psi}$ we first need to calculate 
% $$S_j = \underbrace{I\otimes \cdots \otimes I}_{(j-1)-times} \otimes U \otimes \underbrace{I\otimes \cdots \otimes I}_{(n-j)-times}$$
% $S_j$ is $\C^{2^{n} \times 2^{n}}$ and $\ket{\psi}$ is $\C^{2^{n}}$ calculating $\ket{\psi}' = S_{j}\psi$ takes $O((2^{n})^{2})$ operations and the construction of $S_j$ takes $O(2^{n})$ \cite{Vidal_Romero_2023} hence the total operations will be $O(2^{2n})$+$O(2^{n})$ and time complexity of the operation will be $O(2^{2n})$\newline

To apply a single-qubit gate using Algorithm(\ref{alg:sqg}) we need to iterate over all $2^{n}$ values in the input quantum state and to update every state we need $O(1)$ operations. Thus  the time complexity of the Algorithm \ref{alg:sqg} is $O(2^{n}).$ Next, to apply a control gate using Algorithm (\ref{alg:cpg}) we need to iterate over all $2^{n}$ values in the input quantum state and it either remains the same or changes in $O(1)$ number of entries. Thus the time complexity of this  algorithm is $O(K\, 2^{n}),$ where $K$ is the total number of single-qubit and two-qubit control gates.   


