 \subsection{Completely Determined \texorpdfstring{$(4,g)$}{(4,g)}-Spectra}\label{sect4} 
 \begin{description} 
\item {\bf $(4,3)$-Spectrum:}\label{sect4_3}
  The $(4,3)$-spectrum consists of all positive integers greater than or equal to $5$: 
  \[ \{5, 6, 7, 8, \dots\}, \]   
  starting with the order of the $(4,3)$-cage, the complete graph $K_5$. Starting with the $Graph(4,4,11)$, we repeatedly applied Construction \ref{tec4} to generate the required graphs: $Graph(4,3,6)$, $Graph(4,3,7)$, $Graph(4,3,8)$, $Graph(4,3,9)$ and $Graph(4,3,10)$.

  \item {\bf $(4,4)$-Spectrum:}\label{sect40}
  The $(4,4)$-spectrum consists of 8 and all positive integers greater than or equal to 10 
  \[ \{8, 10, 11, 12, \dots\}, \]   
  starting with the order of the $(4,4)$-cage. Notably, there is no $(4,4)$-graph of order 9 \cite{meringer1999fast}, marking the first instance of a \textit{hole} in a $(4,g)$-spectrum. We obtained $(4,4)$-graphs of order 10 and above using the Circulant Construction \ref{circ1} described in Section~\ref{sec:Comp}. These include $Graph(4,4,10)$, $Graph(4,4,11)$, $Graph(4,4,12)$, $Graph(4,4,13)$, $Graph(4,4,14)$, $Graph(4,4,15)$ and $Graph(4,4,16)$.
  All members of the $(4,4)$-spectrum were obtained as circulant graphs described in Subsection \ref{circ1}. As
  mentioned before, $n(4,4) < N(4,4) = 10$, as for $n=9$ the construction yields a graph of girth $3$.

  \item {\bf $(4,5)$-Spectrum:}\label{sec:Comp2}
  The $(4,5)$-spectrum consists of all positive integers greater than or equal to 19  
  \[ \{19, 20, 21, \dots\}, \]  
  starting with the order of the $(4,5)$-cage, known as the Robertson graph. Although a $(4,5)$-graph of order $20$ can be found in \cite{housegraph2023}, we also obtained $Graph(4,5,20)$ using Construction \ref{tec2}. The $(4,5)$-graph of order $21$ is the Brinkmann graph, as documented in \cite{housegraph2023}. 
  Starting with $Graph(4,6,39)$, we iteratively applied Construction \ref{tec4} to generate graphs: $Graph(4,5,27;1)$, $Graph(4,5,28)$, $Graph(4,5,29)$, $Graph(4,5,30)$, $Graph(4,5,31)$, $Graph(4,5,32)$, $Graph(4,5,33)$, $Graph(4,5,34)$, $Graph(4,5,35)$, $Graph(4,5,36)$, $Graph(4,5,37)$ and $Graph(4,5,38)$. $Graph(4,5,23)$, $Graph(4,5,24)$, $Graph(4,5,25)$, $Graph(4,5,26)$ and $Graph(4,5,27;2)$ were constructed by Construction \ref{tec4} from the $Graph(4,6,28)$. $Graph(4,5,22)$ was obtained by Construction \ref{tec4} from graph $Graph(4,5,24)$.
   Thus, $N(4,5) = n(4,5)$.

\end{description}


