	\subsection{Algorithm design}\label{sec:alg}

	This subsection will provide an algorithm that generates an approximate solution to the problem \eqref{eq:op_follower}. 

	We write $P$ and $\mathbf{p}_0$ as $P(\s)$ and $\mathbf{p}_0(\s)$ to emphasize their dependence on $\s$. The following propositions prove that $\mathrm{sp}_0(\s)$ is monotonically increasing and submodular with $\s$, respectively. 

	\begin{proposition}\label{prop:monotone}
		Let Assumption \ref{assum:str_con} hold. For any $\s\subset \V$ and $i\notin \s$, it holds $\sop_0(\s\cup \{i\})>\sop_0(\s)$.
	\end{proposition}

	\begin{proposition}\label{prop:submodular}
		Let Assumption \ref{assum:str_con} hold. The social power $\sop_0$ is a submodular function of $\s$.
	\end{proposition}

	The proof of Propositions \ref{prop:monotone} and \ref{prop:submodular} are in Appendix \ref{ap:1}.

	With Propositions \ref{prop:monotone} and \ref{prop:submodular}, a greedy algorithm can be designed to find an approximated solution to the problem \eqref{eq:op_follower}, which is given as Algorithm \ref{alg:1}. The following Theorem \ref{th:greedy} is then obtained as a direct application of well-known properties of monotone submodular functions \cite{nemhauser1978analysis}. 

	\begin{algorithm}[H]
		\caption{Greedy Algorithm for Social Power Maximization}\label{alg:1}
		\hspace*{\algorithmicindent} \textbf{Input:} A strongly connect graph $\G=(\V, \mathcal{E}, W)$; maximum number of new links $K$; a diagonal matrix of stubbornness $\Theta$; link weight $\omega$ \\
		\hspace*{\algorithmicindent} \textbf{Output:} A subset of nodes $\s\subset\V$ with $|\s|=K$
		\begin{algorithmic}[1]
			\State Initialization: $\s\gets \emptyset, \s^c\gets \V\backslash \s$
			\For{$k= 1$ to $K$}
			\State $\sop_\text{max}\gets 0, i_\text{max}\gets 0$
			\For{$i=1$ to $n$}
			\State Compute $\sop_0(\s\cup \{i\}) $ by using Eqs. \eqref{eq:sol_FJ} and \eqref{eq:def_sop0}
			\If{$\sop_0(\s\cup \{i\})> \sop_\text{max}$}
			\State $\sop_\text{max}\gets \sop_0(\s\cup \{i\})$, $i_\text{max}\gets i$
			\EndIf
			\EndFor
			\State Update: $\s\gets \s\cup\{i_\text{max}\}$
			\EndFor
		\end{algorithmic}
	\end{algorithm}

	\begin{theorem}\label{th:greedy}
		Consider the problem \eqref{eq:op_follower} for the graph $\mathcal{G}$. Let $\s^\ast$ be a solution and $\s^\text{gd}$ be the output of Algorithm \ref{alg:1}. It then holds
		\[\sop_0(\s^\text{gd})\geq (1-\frac{1}{e})\sop_0(\s^\ast), \]
		where $e$ is the natural logarithm.
	\end{theorem}

	Note that in Algorithm \ref{alg:1}, the computation of each $\sop_0(\s\cup\{i\})$ (in Step 5) requires the inverse of $I-(I-\omega\sum_{j\in\s}\mathbf{e}_j\mathbf{e}_j^\top)(I-\Theta)W$, for which the complexity is $O(n^3)$. Therefore, the computational complexity of Algorithm \ref{alg:1} is $O(K(n-\frac{K-1}{2})n^3)$. The computation of matrix inverse can be impractical when the dimension $n$ is large. To reduce computational complexity, we can make use of random walks generated by the augmented Markov chain corresponding to the FJ model, and compute an approximation of $\sop_0(\s)$ by the following algorithm.

	\begin{algorithm}[H]\label{alg:2}
		\caption{Approximation of $\sop_0(\s)$}\label{alg:2}
		\hspace*{\algorithmicindent} \textbf{Input:} $\G=(\V, \mathcal{E}, W)$; $\s$; $\Theta$; $\omega$; number and length of random walks $r, \ell$ \\
		\hspace*{\algorithmicindent} \textbf{Output:} An approximation of the absorbing probability of the state $0$, $\sop_0^\text{apx}(\s)$
		\begin{algorithmic}[1]
			\State Initialization: $\sop_0^\text{apx}(\s)\gets 0$
			\For{$k= 1$ to $r$}
			\State Generate a random walk $\mathcal{Y}^{(k)}$ from the transition matrix \eqref{eq:trans_mat} with length no larger than $\ell$, and the starting state is uniformly distributed over $[n]$
			\If{the $\mathcal{Y}^{(k)}$ is absorbed by $0$}
			\State $\sop_0^\text{apx}(\s)\gets \sop_0^\text{apx}(\s)+1$
			\EndIf
			\EndFor
			\State Update: $\sop_0^\text{apx}(\s)\gets \sop_0^\text{apx}(\s)/r$
		\end{algorithmic}
	\end{algorithm}

	For Algorithm \ref{alg:2}, a natural question is how large $r$ and $\ell$ are required to guarantee that $\sop_0^\text{apx}(\s)$ is close to $\sop_0(\mathcal{S})$. For the cases that all the agents have positive stubbornness, a high probability bound of $|\sop_0^\text{apx}(\s)-\sop_0(\mathcal{S})|$ can be given as follows, in which 
	\[\sop_0^\ell(\s):=\frac{1}{n}\mathbf{1}^\top \sum_{k=0}^\ell H(\s)^k(I-\Theta)\omega\sum_{j\in\s}\mathbf{e}_j<\sop_0(\s). \]

	\begin{theorem}\label{th:high_probability}
		Let Assumption \ref{assum:str_con} hold. Suppose that $\theta_i\geq\theta>0$ hold for all $i\in\V$. In Algorithm \ref{alg:2}, given $\epsilon, \delta\in(0,1)$ and $\sigma\in(0,1)$, let 
		\begin{equation*}
			\begin{aligned}
				r &\geq \frac{3}{\sigma^2 \epsilon^2 \sop_0^\ell(\s)}  \log (\frac{2}{\delta}), \\ 
				\ell&\geq \frac{\log(\theta(1-\sigma)\epsilon \sop_0^\ell(\s))-\log \omega}{\log(1-\theta)}-2.
			\end{aligned}
		\end{equation*}
		% with $b$ defined as $b:=1-\frac{\sum_{i\in\V}\theta_i}{n}-\frac{\omega(1-\theta_{\max})}{n}$ and $\theta_{\max}:=\max_{i\in\V}\theta_i$. 
		Then, for any $\s$ with $|\s|\geq 1$, it holds
		\[ \mathbb{P}(|\sop_0^\text{apx}(\s)-\sop_0(\mathcal{S})|< \epsilon \sop_0^\ell(\s))\geq 1-\delta. \]
	\end{theorem}

	The proof of Theorem \ref{th:high_probability} is given in Appendix \ref{ap:1}.

	\begin{remark}
		From \eqref{eq:sp_truncate} in the proof, it can be seen that $\sop_0^\ell(\s)\geq \frac{\omega(1-\theta_{\max})}{n}$, where $\theta_{\max}:=\max_{i\in\V}\{\theta_i|\theta_i<1\}<1$ (we only need to consider that for any $i\in\s$, it holds $\theta_i<1$). This means that $r= O(n)$ and $\ell = O(\log(n))$. Moreover, the complexity of one-step random walk is $O(d_{\max})$, with $d_{\max}$ the maximum degree of graph $\G$. Therefore, the complexity of Algorithm \ref{alg:2} is $O(n^2\log(n))$, which indicates that if $n$ is large, Algorithm \ref{alg:2} can reduce the computational complexity and obtain value of $\sop_0(\s)$ in a relatively high accuracy.  
	\end{remark}

