	\subsection{Influence of stubbornness and link weight $\omega$}\label{subsec:homo_stub}
	In this subsection we directly consider the problem \eqref{prob:markov}, under the assumption that all the agents have homogenous stubbornness, i.e., for some $\theta\in(0,1)$ it holds that $\theta_i=\theta, \forall i\in\V$. For this case, the problem \eqref{prob:markov} is in fact to minimize hitting time of the augmented Markov chain to the absorbing states. 

	\begin{lemma}\label{le:equiv_markov}
		For the augmented Markov chain $\bar{\mathcal{Y}}=\{\bar{Y}_t:t\in\mathbb{Z}_{\geq 0}\}$ with $\theta_i=\theta\in(0,1), \forall i\in\V$ and $\mathbb{P}(\bar{Y}_0=i)=\frac{1}{n}, \forall i\in\V$, define $\bar{\tau}=\min_{t\geq 0} \{t: \bar{Y}_t\in \mathcal{A}\}$. The optimization problem \eqref{prob:markov} is equivalent to 
		\begin{equation}\label{prob:hitting_time}
			\mathrm{Minimize}_{|\s|= K} \quad \mathbb{E}_{\bar{\mathcal{Y}}}[\bar{\tau}],
		\end{equation}
		where the subscript is to specify the Markov chain.
	\end{lemma}

	\noindent\textbf{Proof}. Define 
	\begin{equation}\label{eq:def_f}
		f(\s;\theta,\omega):= \frac{1}{n}\mathbf{1}^\top \big(I-(1-\theta)(I-\omega\sum_{j\in\s}\mathbf{e}_j\mathbf{e}_j^\top) W\big)^{-1}\mathbf{1}.
	\end{equation}
	According to the monotonicity of the cost function and that $\mathbf{1}^\top \mathbf{p}_0+\mathbf{1}^\top P\mathbf{1}=n$, the problem \eqref{prob:markov} then becomes 
	\begin{equation}
		\mathrm{Minimize}_{|\s|= K} \quad   \frac{n\theta}{n+1}f(\s;\theta,\omega)+\frac{1}{n+1},
	\end{equation}
	that is
	\begin{equation}\label{prob:homo_stub}
		\mathrm{Minimize}_{|\s|= K} \quad   f(\s;\theta,\omega).
	\end{equation}
	On the other hand, $f(\s;\theta,\omega)$ is the expected number of times that the Markov chain $\bar{\mathcal{Y}}$ visits the transient states $\V$ \cite{chen2008expected} before being absorbed, which is equal to the expected hitting time of $\bar{\mathcal{Y}}$ to the absorbing states $\mathcal{A}$ (i.e., $\{0',1',\dots,n'\}$), i.e., $\mathbb{E}_{\bar{\mathcal{Y}}}[\bar{\tau}]$. The desired conclusion then holds. \hfill$\square$


	\begin{remark}
		In the literature \cite{adriaens2023minimizing} and \cite{haddadan2021repbublik}, similar problems of reducing hitting time for absorbing Markov chains are studied, under the scenario of reducing the so-called ``structural bias" of networks. Compared to the literature, the problem \eqref{prob:hitting_time} considers a more general network structure, in the sense that the transition probabilities from each node (or state) to its neighbors do not need to be equal. Moreover, the parameters $\theta$ and $\omega$, not considered in \cite{adriaens2023minimizing} and \cite{haddadan2021repbublik}, can affect the solution of the optimization problem \eqref{prob:markov} (or \eqref{prob:hitting_time}), as discussed in what follows.  
	\end{remark}

	As seen in \eqref{eq:def_f}, the value of $f(\s;\theta,\omega)$ depends on $\theta$ and $\omega$ nonlinearly due to the matrix inverse, which makes it hard to disentangle the influence of the parameters on the optimal selection of $\s$. Nevertheless, for specific range of the parameters, we can still obtain some intuitive conclusions. Specifically, in the remaining part of this subsection, we make a further assumption that $K=1$, i.e., only one agent is selected by agent $0$ to which a link is added. For this case, any $f(\{i\};\theta,\omega)$ is simply written as $f(i;\theta,\omega)$.

	We at first consider the case that $\theta$ is small, as specified by the following assumption.

	\begin{assumption}\label{assum:small_stub}
		Given $\omega>0$, $\theta$ is small enough such that $f(i;\theta,\omega)-f(i_\ast;\theta,\omega)>0$ holds for all $i\not= i_\ast$, where $i_\ast=\mathop{\arg\min}_{j\in\V} f(j;0,\omega)$.
	\end{assumption}

	\noindent Assumption \ref{assum:small_stub} requires that $i_\ast$ is the only solution to the problem $\mathrm{Minimize}_{i\in\V} f(i;0,\omega)$. As $f(i;\theta,\omega)$ is continuous with $\theta$, there exists $\tilde{\theta}\in(0,1)$ such that for any $\theta<\tilde{\theta}$, Assumption~\ref{assum:small_stub} holds.

	For the augmented Markov chain $\mathcal{Y}(\G, \mathbf{0})=\{Y_t:t\in\mathbb{Z}_{\geq 0}\}$ of the FJ model without agent $0$, define
	\[\tau_{ji}=\min\{t>0: Y_t=i|Y_0=j\} \]
	as the first time that the Markov chain hits $i\in\V$, given that the initial state is $j\in\V$. 
	% \begin{lemma}\label{le:f_0}
		%     Let Assumption \ref{assum:str_con} hold. Given $\omega>0$, consider $f(i;0,\omega)$ defined in \eqref{eq:def_f} for $i\in\V$. It holds
		%     \[f(i;0,\omega)=\frac{1}{n}\sum_{j\not= i}\mathbb{E}_{\mathcal{Y}(\G, \mathbf{0})}[\tau_{ji}]+\frac{1-\omega}{\omega}\mathbb{E}_{\mathcal{Y}(\G, \mathbf{0})}[\tau_{ii}]+1. \]
		% \end{lemma}

	% The proof of Lemma \ref{le:f_0} is given in Appendix \ref{ap:equiv_markov}. 

	% With Lemmas \ref{le:equiv_markov} and \ref{le:f_0}, the following lemma is obtained.

	\begin{proposition}\label{prop:equiv_single}
		Consider the FJ model over the graph $\G$ with $\theta_i=\theta,\forall i\in\V$. Let Assumptions \ref{assum:str_con} and \ref{assum:small_stub} hold. The optimization problem \eqref{prob:markov} with $K=1$ is equivalent to 
		\begin{equation}\label{prob:single}
			\mathrm{Minimize}_{i} \quad   \frac{1}{n}\sum_{j\not= i}\mathbb{E}_{\mathcal{Y}(\G, \mathbf{0})}[\tau_{ji}]+\frac{1-\omega}{\omega}\mathbb{E}_{\mathcal{Y}(\G, \mathbf{0})}[\tau_{ii}]
		\end{equation}
	\end{proposition}

	The proof of Proposition \ref{prop:equiv_single} is given in Appendix \ref{ap:equiv_markov}. 

	\begin{remark}\label{re:small_stub}
		The cost function of \eqref{prob:single} is a weighted combination of two terms: the first term $\frac{1}{n}\sum_{j\not= i}\mathbb{E}_{\mathcal{Y}(\G, \mathbf{0})}[\tau_{ji}]$ represents the average expected time for a random walk from the other agents to reach $i$, and the second term $\mathbb{E}_{\mathcal{Y}(\G, \mathbf{0})}[\tau_{ii}]$ is the expected time from $i$ to come back. Both terms only depend on the graph $\G$. For the problem \eqref{prob:single} with a large $\omega$ (i.e., close to $1$), it is more important to minimize the first term, which can be regarded as a measurement of the overall reachability to $i$ in the graph; on the other hand, if $\omega$ is small (i.e., close to $0$), the local structure of each agent in the graph affects more on the solution of \eqref{prob:single}. This is illustrated by Example \ref{ex:homo_stub} in Section \ref{sec:example}.
	\end{remark}

	Now consider the case that $\theta$ is close to $1$. Denote
	\[g_i:=(1-\omega)W_{ii}+\sum_{j\not= i}W_{ji}. \]
	We make the following assumption. 

	\begin{assumption}\label{assum:big_stub}
		There exists only one agent $i^\ast$ such that $g_{i^\ast}=\max_{i\in\V}g_i$. Moreover, for $\delta_g:=\min_{i\in\V}\{g_{i^\ast}-g_i:i\not=i^\ast\}$, it holds $\theta>\frac{n}{\delta_g+n}$.
	\end{assumption}

	\begin{proposition}\label{prop:big_stub}
		Consider the FJ model over the graph $\G$ with $\theta_i=\theta,\forall i\in\V$. Let Assumptions \ref{assum:str_con} and \ref{assum:big_stub} hold. For the optimization problem \eqref{prob:markov} with $K=1$, the solution is $\s^\ast=\{i^\ast\}$.
	\end{proposition}

	The proof of Proposition \ref{prop:big_stub} is given in Appendix \ref{ap:equiv_markov}. From Proposition \ref{prop:big_stub}, it can be seen that if $\theta$ is close to $1$, agent $0$ will choose an agent $i$ with the largest weighted sum of the weights on all the outgoing links, with $1-\omega$ as the weight assigned to $W_{ii}$. 

	% \begin{remark}
		%     Similarly to the cost function of \eqref{prob:single}, $g_i$ is decomposed of two terms, with $\omega$ determining the weight assigned to the term that reflects how easy a random walk (with length $1$) starting from the targeted agent returns to itself (i.e., $W_{ii}$), given that $\theta$ is close to $1$. 
		% \end{remark}

	\begin{remark}
		Combining Propositions \ref{prop:equiv_single} and \ref{prop:big_stub}, it can be seen that for small stubbornness $\theta$, the influencer (i.e., agent $0$) cares more about the long-term behaviour of random walks over $\mathcal{G}$, which is reflected in \eqref{prob:single}; while for large stubbornness, the influencer only considers the one-hop structure of the graph, encoded by the $g_i$'s. Such a difference is illustrated in Example \ref{ex:homo_stub}. This can also be explained from the mathematical form of the cost function $f(i;\theta,\omega)$: if we expand the right-hand term of \eqref{eq:def_f}, the weights assigned to high-order terms (i.e., $(1-\theta)^k$ for $k\geq 3$), determined by the multi-hop structures of $\G$, decreases rapidly as $\theta$ grows from $0$ to $1$. 
	\end{remark}


