	\section{Results for complete and ring graphs}\label{sec:special}

	This section will provide accurate solution to the optimization problem \eqref{eq:op_follower} for two special graphs. The first is a compete graph with a rank-$1$ weight matrix, and the second one is a ring graph with a symmetric and circulant weight matrix. 

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Rank-$1$ complete graph}\label{sec:complete}

	In this subsection, we assume that the weight matrix $W$ is of rank-$1$, i.e., $W=\mathbf{1c}^\top$ for some $\mathbf{c}\in\mathbb{R}_+^n$ with $\mathbf{c}^\top \mathbf{1}=1$. For this case, by calculation, the following lemma is obtained.

	\begin{lemma}\label{le:sp_complete}
		Consider the FJ model with $W=\mathbf{1c}^\top$. It holds 
		\begin{equation}\label{eq:sp_rank1}
			\begin{aligned}
				&\sop_0=\frac{1}{n+1}\\
				&+ \frac{\omega\left\{\sum\limits_{j\in\V}c_j\theta_j\sum\limits_{j\in\mathcal{S}}(1-\theta_j)+\sum\limits_{j\in\V}(1-\theta_j)\sum\limits_{j\in\mathcal{S}}c_j(1-\theta_j)\right\}}{(n+1)\left\{\sum\limits_{j\in \V}c_j\theta_j+\omega\sum\limits_{j\in\mathcal{S}}c_j(1-\theta_j)\right\}},
			\end{aligned}
		\end{equation}
	\end{lemma}

	The proof of Lemma \ref{le:sp_complete} is in Appendix \ref{ap:3}. According to Lemma \ref{le:sp_complete}, the solution to the problem \eqref{eq:op_follower} for special parameter settings can be given explicitly, as shown in the following corollary.

	\begin{corollary}\label{prop:rank1-special}
		Consider the problem \eqref{eq:op_follower} with $W=\mathbf{1c}^\top$. Let $\theta_{i_1},\dots, \theta_{i_n}$ and $c_{j_1},\dots, c_{j_n}$ be permutations of $\{\theta_i:i\in\V\}$ and $\{c_j:j\in\V\}$, such that $\theta_{i_1}\leq\theta_{i_2}\leq\dots<\theta_{i_n}$ and $c_{j_1}\geq c_{j_2}\geq \dots\geq c_{j_n}$. The following statements holds.
		\begin{enumerate}
			\item\label{case:same_stub} If $\theta_1=\dots=\theta_n$, $\{c_{j_1},c_{j_2},\dots,c_{j_K}\}$ is a solution to the problem \eqref{eq:op_follower};
			\item\label{case:same_centr} If $c_1=\dots=c_n$, $\{\theta_{i_1},\theta_{i_2},\dots,\theta_{i_K}\}$ is a solution to the problem \eqref{eq:op_follower};
			\item\label{case:same_prod} If $c_1(1-\theta_1)=\dots=c_n(1-\theta_n)$, $\{\theta_{i_1},\theta_{i_2},\dots,\theta_{i_K}\}$ is a solution to the problem \eqref{eq:op_follower}.
		\end{enumerate}
	\end{corollary}

	The proof of Corollary \ref{prop:rank1-special} is simply by checking the monotonicity of $\sop_0$ w.r.t $\sum_{j\in\mathcal{S}}(1-\theta_j)$ or $\sum_{j\in\mathcal{S}}c_j$ for the special cases, and is omitted here.

	\begin{remark}
		The first two cases in Corollary \ref{prop:rank1-special} are intuitive: 1) When the agents in $\V$ have same stubbornness, they are equally willing to listen to the opinion of agent $0$, and as such, agent $0$ needs to choose the agents with highest network centralities (i.e., $c_i$) as her followers to maximize her influence. 2) When the network centralities of agent in $\V$ are homogenous, agent $0$ need to choose followers who are the easiest to be influenced, i.e., the ones with lowest stubbornness.  
	\end{remark}

	\begin{remark}
		Case~\ref{case:same_prod}) in Corollary~\ref{prop:rank1-special} corresponds to the scenario where agents with higher network centrality are more stubborn—a pattern supported by empirical studies, as opinion leaders (typically centrally positioned) are less susceptible to peer influence \cite{van2011opinion}. Interestingly, in this case, it is more effective for agent~$0$ to link to easily influenced agents rather than those with high centrality.
	\end{remark}

	For generic parameters $\{\theta_i\}$ and $\{c_j\}$, the problem \eqref{eq:op_follower} is in fact a constrained hyperbolic $0-1$ programming problem \cite{hansen1991hyperbolic}. To be more clear, define
	\begin{equation}\label{eq:parameters}
		\begin{aligned}
			b_i&=[\sum_{j\in\V}c_j\theta_j+c_i\sum_{j\in\V}(1-\theta_j)](1-\theta_i),\quad i\in[n],\\
			a_0&=\sum_{j\in\V}c_j\theta_j, \quad a_i=\omega (1-\theta_i), \quad i\in[n].
		\end{aligned}
	\end{equation}
	With \eqref{eq:sp_rank1}, the problem \eqref{eq:op_follower} becomes
	\begin{equation}\label{eq:op_rank1}
		\begin{aligned}
			&\mathrm{Maximize}_{\mathcal{S}}\quad\frac{\sum_{i\in\mathcal{S}}b_i}{a_0+\sum_{i\in\mathcal{S}}a_i}\\
			&\quad\mathrm{s.t.} \quad \quad |\mathcal{S}|= K
		\end{aligned}
	\end{equation}
	Here, the constraint becomes equality due to the monotonicity of $\sop_0$ w.r.t $\mathcal{S}$. By borrowing some techniques from \cite{hansen1991hyperbolic}, we can prove that the problem \eqref{eq:op_rank1} can be solved in polynomial time, as shown in the following theorem.

	\begin{theorem}\label{th:complete}
		Consider the optimization problem \eqref{eq:op_rank1} with the parameters defined in \eqref{eq:parameters}. There is an algorithm to solve the problem in $O(n^3\log n)$ time.
	\end{theorem}

	The proof of Theorem \ref{th:complete} is given in Appendix \ref{ap:3}. Equivalently, Theorem \ref{th:complete} means that for rank-$1$ compete graphs, an accurate solution of the problem \eqref{eq:op_follower} can be found in $O(n^3\log n)$ time. Note that the solution-seeking algorithm in fact follows the procedures 1)-5) in the proof.


