	\end{itemize}
	We also assume that all agents have the same stubbornness, i.e., $\theta_i=\theta\in(0,1), \forall i\in\V$. Moreover, we consider that case that $K=2$. 

	Due to the symmetry of the graph $\G$ encoded in $W$, and that all the agents have same stubbornness, without loss of generality, we can let $1\in\mathcal{S}^\ast$, where $\mathcal{S}^\ast$ is a solution to the optimization problem \eqref{eq:op_follower}. The problem then boils down to finding the other agent in $\s^\ast$. Utilizing the Sherman-Morrison formula, the following lemma is obtained.

	\begin{lemma}\label{le:circu}
		Consider the FJ model with $\theta_i=\theta\in(0,1),\forall i\in\V$. The weight matrix $W$ is assumed to be a symmetric circlulant matrix. For this case, the inverse of the matrix $M:=I-(1-\theta)W$ exists and is circulant, denoted as $M^{-1}:=C(m_0,m_1,\dots,m_{n-1})\in\mathbb{R}^{n\times n}$. Let 
		\[j^\ast \in\mathop{\arg\min}_{j\in\V} m_{j-1},\]
		the set $\s^\ast=\{1,j^\ast\}$ is then a solution to the problem \eqref{eq:op_follower} with $K=2$.
	\end{lemma}

	The proof of Lemma \ref{le:circu} is given in Appendix \ref{ap:4}. Based on Lemma \ref{le:circu}, if we further assume that the link weights of $\G$ decrease with the distance between the nodes in the cycle where the nodes are located, the solution of \eqref{eq:op_follower} can be explicitly shown as follows.

	\begin{theorem}\label{th:cycle}
		Consider the FJ model with $\theta_i=\theta\in(0,1), \forall i\in\V$. For the optimization problem \eqref{eq:op_follower} with $K=2$, let $\mathcal{S}^\ast=\{1,j^\ast\}$ be a solution. 
		\begin{enumerate}
			\item \textbf{Odd}. If $W=C(w_0,w_1,\dots,w_{s-1},w_{s-1},\dots,w_1)$, with $w_0\geq w_1\geq  w_2\geq  \dots\geq w_{s-1}\geq 0$, $w_1>w_{s-1}$ and $w_0+2\sum_{\ell=1}^{s-1}w_\ell=1$, then $j^\ast=s$ or $s+1$;
			\item \textbf{Even}. If $W=C(w_0,w_1,\dots,w_{s-1},w_s,w_{s-1},\dots,w_1)$, with $w_0\geq w_1\geq w_2\geq  \dots\geq w_{s-1}\geq 0$, $w_1>w_{s-1}$ and $w_0+w_s+2\sum_{\ell=1}^{s-1}w_\ell=1$, then $j^\ast=s+1$.
		\end{enumerate}
	\end{theorem}

	The proof of Theorem \ref{th:cycle} is given in Appendix \ref{ap:4}.

	Theorem \ref{th:cycle} means that for the symmetric ring graph $\G$, the optimal strategy for agent $0$ to maximize her social power is to add links to two agents that have the largest distance from each other on the graph. 

	\begin{remark}
		The monotonicity requirement of the link weights is necessary for Theorem \ref{th:cycle}. This can be seen by considering the graph with $\V=[12]$ and $W=C(0.16,0.14,0.28,\mathbf{0}_7^\top,0.28,0.14)$, for which the monotonicity is not satisfied. Let $\theta=0.1$ and $\omega=0.2$. Then, the solution of \eqref{eq:op_follower} with $K=2$ is $\{1,6\}$, instead of $\{1,7\}$ implied by Theorem $\ref{th:cycle}$. 
	\end{remark}

	\begin{remark}\label{re:ring_multi}
		From Theorem \ref{th:cycle}, a conjecture could be drawn for the case of $K\geq 2$: to maximize the social power, agent $0$ should choose agents that are sufficiently dispersed over the cycle. This conjecture is supported by Example \ref{ex:ring_multi}. Note that in Example \ref{ex:ring_multi}, the monotonicity assumption in Theorem \ref{th:cycle} is no longer required, which indicates that choosing agents that are maximally dispersed over the cycle of a symmetric ring graph (with homogenous stubbornness of agents) might be at least a near-optimal strategy for agent $0$.    
	\end{remark}

	% \begin{remark}
		%     In the ring graph considered in Theorem \ref{th:cycle}, the agents are equally distributed in the network, i.e., no agent has a higher centrality than other agents. For this case, Theorem \ref{th:cycle} implies that in order to maximize social power by adding two links to the stubborn agents, the external influencer needs to choose two agents that are farthest from each other over the network.
		% \end{remark}

