	The last example provides numerical evidence to support Theorem \ref{th:cycle} and Remark \ref{re:ring_multi}.

	\begin{figure}[t]
		\centering
		\includegraphics[trim=0cm 0cm 0cm 0cm,clip=true,width=8cm]{ring_multi_node.jpg}
		\caption{Results for Example \ref{ex:ring_multi}. Each scatter plot point corresponds to a subset $\mathcal{S}$ chosen by agent $0$ (different subsets with the same $R$ and $\sop_0$ are merged into one point).}
		\label{fig:ring_multi}
	\end{figure}

	\begin{example}\label{ex:ring_multi}
		Consider the social power optimization problem \eqref{eq:op_follower} with $n=26$ and $K=5$. The stubbornness of all agents are $0.1$. The weights of links added by agent $0$ are $\omega=0.2$. The graph $\G$ is a ring, and the weight matrix is $C(0.02,\mathbf{w}^\top,\mathbf{0}_{17}^\top,\mathbf{w}^\top)$, with $\mathbf{w}^\top=[0.17,0.11,0.09,0.12]$. Each agent $i$ is associated with a coordinate $(\cos(\phi_i), \sin(\phi_i))$ on the unit circle, where $\phi_i = \frac{2\pi(i-1)}{26}$, reflecting its position on the cycle graph. For any subset $\mathcal{S} \subseteq \{1,\dots,n\}$ with $|\mathcal{S}| = 5$, let the circular variance be defined as
		\[
		R(\mathcal{S}) = 1 - \frac{1}{|\mathcal{S}|} \sqrt{\left( \sum_{i \in \mathcal{S}} \cos(\phi_i) \right)^2 + \left( \sum_{i \in \mathcal{S}} \sin(\phi_i) \right)^2}.
		\]
		This quantity measures how evenly the agents in $\mathcal{S}$ are distributed around the cycle. We evaluate all possible subsets $\mathcal{S}$ of size 5, compute their circular variances, and determine the corresponding social power $\sop_0(\mathcal{S})$ of agent 0 when selecting $\mathcal{S}$. The results, shown in Fig.~\ref{fig:ring_multi}, indicate a positive correlation between $R(\mathcal{S})$ and $\sop_0(\mathcal{S})$: the more dispersed the selected agents are, the greater the social power of agent 0.
		Similar trends are observed for other symmetric circulant weight matrices $W$. This suggests that agent 0 benefits from selecting followers that are spatially well-dispersed over the cycle---i.e., local clustering should be avoided. This observation aligns with Theorem~\ref{th:cycle} and Remark~\ref{re:ring_multi}.
	\end{example}

