	\section{Proofs for Subsection \ref{sec:alg}}\label{ap:1}

	\noindent\textbf{Proof of Proposition \ref{prop:monotone}}. In \eqref{eq:sol_FJ},  it is easy to see that $H(\s)$ is strictly sub-stochastic. Moreover, it holds $\mathbf{0}\leq H(\s\cup\{i\})\leq H(\s)$. Therefore, it holds
	\[P(\s)=\sum_{k=0}^\infty H(\s)^k\Theta\geq \sum_{k=0}^\infty H(\s\cup \{i\})^k\Theta=P(\s\cup \{i\}). \]
	Due to the fact that $\bar{P}(\s)$ and $\bar{P}(\s\cup \{i\})$ are both stochastic, it must be $\mathbf{p}_0(\s)\leq \mathbf{p}_0(\s\cup \{i\})$. Notice that $P(\s)\not= P(\s\cup \{i\})$, the inequality must hold strictly, which gives the desired conclusion.\hfill$\square$ 
	\hfill\break

	Before going to the proof of Proposition \ref{prop:submodular}, some notations need to be given. Consider a square matrix $A\in\mathbb{R}^{|\V|\times|\V|}$. Let $\mathcal{P}=i_0\to i_1\to \dots \to i_\ell$ be a path on the graph $\G$. Denote $v_k(\mathcal{P})=i_k$ as the $(k+1)$-th node that $\mathcal{P}$ goes through, and specially, $v_0(\mathcal{P})=i_0$ as the starting node of $\mathcal{P}$. Denote $A_{\mathcal{P}}:=A_{i_\ell i_{\ell-1}}\dots A_{i_2 i_1}A_{i_1i_0}$ as the product of the entries corresponding to all edges (counted with multiplicity) on the path $\mathcal{P}$. For any $i\in\V$, denote $A_{\mathcal{P}\cap i}=\Pi_{\substack{k\in [\ell]\\ i_k=i} }A_{i_ki_{k-1}}$ as the product of the entries corresponding to all edges (counted with multiplicity) on the path $\mathcal{P}$ that start from $i$, and denote $A_{\mathcal{P}\backslash i}=A_\mathcal{P}/A_{\mathcal{P}\cap i}$ as the entry product corresponding to all edges on the path $\mathcal{P}$ with its starting point not being $i$. 
	\hfill\break

	\noindent\textbf{Proof of Proposition \ref{prop:submodular}}. Consider two arbitrary set $\s, \mathcal{T}$ such that $\mathcal{T}\subset\s$. We need to prove that for any $i\in \V\backslash\s$, it holds 
	\[\sop_0(\s\cup\{i\})-\sop_0(\s)\leq \sop_0(\T\cup \{i\})-\sop_0(\T). \]
	Due to the stochasticity of $\bar{P}(\s), \bar{P}(\s\cup \{i\}), \bar{P}(\T)$ and $\bar{P}(\T\cup \{i\})$, it suffices to prove that for any $j,h\in\V$, it holds
	\begin{equation}
		[P(\s)]_{jh}-[P(\s\cup \{i\})]_{jh}\leq [P(\T)]_{jh}-[P(\T\cup \{i\})]_{jh}.
	\end{equation}
	% Note that 
	% \begin{equation*}
		%     \begin{aligned}
			%         \mathbf{e}_i^\top H(\s)&=\mathbf{e}^\top P(\T), \quad \mathbf{e}_i^\top H(\s\cup \{i\})=\mathbf{e}^\top P(\T\cup \{i\}),\\
			%         \mathbf{e}_{i'}^\top  H(\s)&=\mathbf{e}_{i'}^\top P(\s\cup \{i\}), \quad  \mathbf{e}_{i'}^\top H(\T)=\mathbf{e}_{i'}^\top P(\T\cup \{i\}), \quad \forall i'\not= i.
			%     \end{aligned}
		% \end{equation*}
	Observe that
	\begin{equation}\label{eq:margi_es}
		\begin{aligned}
			&\sum_{k=0}^\infty ([H(\s)^k]_{jh}-[H(\s\cup \{i\})^k]_{jh})\\
			&=\sum_{k=0}^\infty\sum_{\substack{|\mathcal{P}|=k\\ v_0(\mathcal{P})=h, v_k(\mathcal{P})=j}} \left([H(\s)]_\mathcal{P}-[H(\s\cup \{i\})]_\mathcal{P}\right)\\
			&= \sum_{k=0}^\infty\sum_{\substack{|\mathcal{P}|=k\\ v_0(\mathcal{P})=h\\ v_k(\mathcal{P})=j}}\left([H(\s)]_{\mathcal{P}\cap i}-[H(\s\cup \{i\})]_{\mathcal{P}\cap i}\right)[H(\s)]_{\mathcal{P}\backslash i}\\
			&= \sum_{k=0}^\infty\sum_{\substack{|\mathcal{P}|=k\\ v_0(\mathcal{P})=h\\ v_k(\mathcal{P})=j}}\left([H(\T)]_{\mathcal{P}\cap i}-[H(\T\cup \{i\})]_{\mathcal{P}\cap i}\right)[H(\s)]_{\mathcal{P}\backslash i}\\
			&\leq \sum_{k=0}^\infty\sum_{\substack{|\mathcal{P}|=k\\ v_0(\mathcal{P})=h\\ v_k(\mathcal{P})=j}}\left([H(\T)]_{\mathcal{P}\cap i}-[H(\T\cup \{i\})]_{\mathcal{P}\cap i}\right)[H(\T)]_{\mathcal{P}\backslash i}\\
			&= \sum_{k=0}^\infty ([H(\T)^k]_{jh}-[H(\T\cup \{i\})^k]_{jh}).
		\end{aligned}
	\end{equation}
	Therefore, we have 
	\begin{equation*}
		\begin{aligned}
			&[P(\s)]_{jh}-[P(\s\cup \{i\})]_{jh}\\
			&= \sum_{k=0}^\infty ([H(\s)^k]_{jh}-[H(\s\cup \{i\})^k]_{jh})\theta_h\\
