	To prove Theorem \ref{th:high_probability}, the Chernoff bound needs to be introduced at first.

	\begin{lemma}[Chernoff bound]\label{le:chernoff}
		Suppose that $X_1$, $\dots$, $X_n$ are independent Bernoulli random variables such that $\mathbb{P}\{X_i = 1\} = p_i = 1 - \mathbb{P}\{X_i=0\}$. Let $X := \sum_{i=1}^n X_i$ and $\mu := \mathbb{E}\{X\} = \sum_{i=1}^n p_i$. Then for $0< \epsilon < 1$,
		\begin{align*}
			\mathbb{P}\{|X - \mu| \ge \epsilon \mu\} \le 2 e^{-\mu\epsilon^2/3},
		\end{align*}
	\end{lemma}

	\noindent\textbf{Proof of Theorem \ref{th:high_probability}}. Note that $\sop_0=\sop_0^\ell (\s)+\sop_0^{\ell c}(\s)$, with
	\begin{equation}\label{eq:sp_truncate}
		\begin{aligned}
			% \sop_0^\ell(\s)&:=\frac{1}{n}\mathbf{1}^\top \sum_{k=0}^\ell H(\s)^k(I-\Theta)\omega\sum_{j\in\s}\mathbf{e}_j,\\
			\sop_0^{\ell c}(\s)&:= \frac{1}{n}\mathbf{1}^\top \sum_{k=\ell+1}^\infty H(\s)^k(I-\Theta)\omega\sum_{j\in\s}\mathbf{e}_j.
		\end{aligned}
	\end{equation}
	Consider a finite-length random walk $\mathcal{Y}=\{Y_t: t=0,1,\dots, \ell\}$ generated by the Markov chain with the transition matrix as $T$ (defined by \eqref{eq:trans_mat}), and the starting state is selected uniformly from $\V$. Note that $\sop_0^\ell(\s)$ is in fact the probability that $\mathcal{Y}$ is absorbed by the state $0$, i.e., 
	\[\sop_0^\ell(\s)=\mathbb{P}(\exists t\leq \ell \text{ s.t. } Y_t=0)=\mathbb{E}[\mathbf{1}\{\exists t\leq \ell \text{ s.t. } Y_t=0\}]. \]
	Therefore, due to the fact the random walks $\mathcal{Y}^{(k)}$ in Algorithm \ref{alg:2} are $i.i.d$, we can obtained from the Lemma \ref{le:chernoff}
	that
	\begin{equation*}\label{eq:hpd_1}
		\mathbb{P}(|r \sop_0^\text{apx}(\s)-r \sop_0^\ell(\s)|\geq \epsilon r\sop_0^\ell(\s) )\leq 2 e^{-r  \sop_0^\ell(\s) \epsilon^2/3}.
	\end{equation*}
	Hence, for $r \geq 3 \log (2/\delta) / ( \sigma^2 \epsilon^2 \sop_0^\ell(\s))$,
	\begin{equation*}\label{eq:hpd_1}
		\mathbb{P}(|\sop_0^\text{apx}(\s)- \sop_0^\ell(\s)|\geq \sigma \epsilon \sop_0^\ell(\s) )\leq 2 e^{-r  \sop_0^\ell(\s) \sigma^2 \epsilon^2/3} \le \delta.
	\end{equation*}
	On the other hand, for $\ell \geq  [\log(\theta(1-\sigma)\epsilon \sop_0^\ell(\s))-\log \omega]/[\log(1-\theta)]-2$,
	\begin{equation}\label{eq:hpd_2}
		\begin{aligned}
			&\sop_0^{\ell c}(\s)\leq \frac{1}{n}\|\mathbf{1}^\top\|_{\infty}\sum_{k=\ell+1}^\infty \|H(\s)\|_\infty^k\|I-\Theta\|_\infty \omega\|\sum_{j\in\s}\mathbf{e}_j\|_\infty\\
			&\leq \omega\sum_{k=\ell+1}^\infty (1-\theta)^{k+1}=\frac{\omega(1-\theta)^{\ell+2}}{\theta}\leq (1-\sigma)\epsilon \sop_0^\ell(\s),
		\end{aligned}
	\end{equation}
	where the first inequality is from 
	\[\|H(\s)\|_\infty\leq \|I-\omega\sum_{j\in\s}\mathbf{e}_j\mathbf{e}_j^\top\|_\infty \|I-\Theta\|_\infty \|W\|_{\infty}\leq 1-\theta. \]
	Therefore,
	\begin{equation*}
		\begin{aligned}
			&\mathbb{P}(|\sop_0^\text{apx}(\s)-\sop_0(\s)|< \epsilon \sop_0^\ell(\s))\geq 1 \\
			& -\mathbb{P}(|\sop_0^\text{apx}(\s)-\sop_0^\ell(\s)|+|\sop_0^\ell(\s)-\sop_0(\s)|\geq \epsilon \sop_0^\ell(\s))\\
			&\geq 1-\mathbb{P}(|\sop_0^\text{apx}(\s)-\sop_0^\ell(\s)|\geq \sigma \epsilon \sop_0^\ell(\s))\geq 1-\delta.
		\end{aligned}
	\end{equation*}
	The proof is then completed.


