	\noindent\textbf{Proof of Proposition \ref{prop:equiv_single}}. If suffices to prove that for $\forall i\in\V$,
	\begin{equation}\label{eq:f_0}
		f(i;0,\omega)=\frac{1}{n}\sum_{j\not= i}\mathbb{E}_{\mathcal{Y}(\G, \mathbf{0})}[\tau_{ji}]+\frac{1-\omega}{\omega}\mathbb{E}_{\mathcal{Y}(\G, \mathbf{0})}[\tau_{ii}]+1.
	\end{equation}
	We simply use $\mathcal{Y}, \bar{\mathcal{Y}}$ to represent the augmented Markov chains $\mathcal{Y}(\mathcal{G},\mathbf{0})$ and $\bar{\mathcal{Y}}(\bar{\G},\mathbf{0})$. Consider $\bar{\mathcal{Y}}=\{\bar{Y}_t:t\in\mathbb{Z}_{\geq 0}\}$ with $\s=\{i\}$. Note that with probability $1$, $\bar{\mathcal{Y}}$ will be  absorbed by the state $i'$. For each $j\in\V$, define
	\[\bar{\tau}_j:=\min\{t:\bar{Y}_t=i', \bar{Y}_0=j\}. \]
	According to the proof of Lemma \ref{le:equiv_markov}, 
	\begin{equation}\label{eq:exp_sum}
		f(i;0,\omega)=\frac{1}{n}\sum_{j\in\V}\mathbb{E}_{\bar{\mathcal{Y}}}[\bar{\tau}_{j}].
	\end{equation}
	We now consider $\bar{\mathcal{Y}}$ with $\bar{Y}_0=j$. Let $N$ be the number of times that $\bar{\mathcal{Y}}$ hits $i$ before absorbed by $i'$, and for $k\in [N]$ define
	\[t_k:=\min\{t-t_{k-1}: t>t_{k-1}, \bar{Y}_t=i\} \]
	as time interval between the $(k-1)$th and $k$th hitting at $i$, where $t_0:=0$. We then have $\tau_j=\sum_{k=1}^Nt_k+1$
	By the law of total expectation,
	\begin{equation}
		\begin{aligned}
			\mathbb{E}[\bar{\tau}_j]&=\mathbb{E}_N[\mathbb{E}[\bar{\tau}_j|N]]\\
			&=\sum_{k=1}^\infty \mathbb{P}(N=k)\left(\sum_{\ell=1}^k \mathbb{E}[t_{\ell}|N=k]+1\right). 
		\end{aligned}
	\end{equation}
	Note that $\bar{\mathcal{Y}}$ is an homogenous Markov chain, and under the condition $N=k$, for any $\ell_1,\ell_2\in\{2,\dots,N\}$, the distribution of $t_{\ell_1}$ is the same as that of $t_{\ell_2}$. In fact, for any $\ell\in\{2,\dots,N\}$, the distribution of $t_\ell$ on condition that $N=k\geq 2$ is the same as that of $\tau_{ii}$, which is defined over the Markov chain $\mathcal{Y}$. Moreover, if $j\not=i$, the distribution of $t_1$ is the same as that of $\tau_{ji}$; otherwise if $j=i$, $t_1=0$. Therefore, for $j\not=i$, 
	\begin{equation}\label{eq:sum_1}
		\begin{aligned}
			\mathbb{E}[\bar{\tau}_j]&=\sum_{k=1}^\infty \mathbb{P}(N=k)(\mathbb{E}[\tau_{ji}]+(k-1)\mathbb{E}[\tau_{ii}]+1)\\
			&=\mathbb{E}[\tau_{ji}]+\sum_{k=1}^\infty (k-1)\mathbb{P}(N=k)\mathbb{E}[\tau_{ii}]+1\\
			&=\mathbb{E}[\tau_{ji}]+\sum_{k=1}^\infty (k-1)(1-\omega)^{k-1}w\mathbb{E}[\tau_{ii}]+1\\
			&=\mathbb{E}[\tau_{ji}]+\frac{1-\omega}{\omega}\mathbb{E}[\tau_{ii}]+1,
		\end{aligned}
	\end{equation}
	where the third equality is because
	\begin{equation*}
		\begin{aligned}
			\mathbb{P}(N=k)&=\mathbb{P}(\bar{Y}_{t_k+1}=i')\Pi_{\ell=1}^{k-1}\mathbb{P}(\bar{Y}_{t_\ell+1}\not=i')\\
			&=\omega(1-\omega)^{k-1}.
		\end{aligned}
	\end{equation*}
	On the other hand, if $j=i$, it holds
	\begin{equation}\label{eq:sum_2}
		\begin{aligned}
			\mathbb{E}[\bar{\tau}_i]&=\sum_{k=1}^\infty \mathbb{P}(N=k)((k-1)\mathbb{E}[\tau_{ii}]+1)\\
			&= \frac{1-\omega}{\omega}\mathbb{E}[\tau_{ii}]+1.
		\end{aligned}
	\end{equation}
	Combining \eqref{eq:exp_sum} with \eqref{eq:sum_1}-\eqref{eq:sum_2}, the equation \eqref{eq:f_0} is obtained. Then from Lemma \ref{le:equiv_markov}, the desired conclusion is reached.
	\hfill$\square$
