	\noindent\textbf{Proof of Proposition \ref{prop:big_stub}}. Denote $H_i:=(I-\omega \mathbf{e}_i\mathbf{e}_i^\top)W$. It holds
	\begin{equation}
		\begin{aligned}
			&f(i;\theta,\omega)=\frac{1}{n}\sum_{k=0}^\infty (1-\theta)^k \mathbf{1}^\top H_i^k\mathbf{1} \\
			&\quad= 1+(1-\theta)(1-\frac{\omega}{n})+\frac{1}{n}\sum_{k=2}^\infty (1-\theta)^k \mathbf{1}^\top H_i^k\mathbf{1},
		\end{aligned}
	\end{equation}
	where the second equality is due to the fact that $W\mathbf{1}=\mathbf{1}$. From the equivalence between the problems $\eqref{prob:markov}$ and $\eqref{prob:homo_stub}$, the problem becomes 
	\begin{equation}\label{prob:big_stub}
		\mathrm{Minimize}_{i\in\V} \quad   \mathbf{1}^\top H_i^2\mathbf{1}+\sum_{k=1}^\infty (1-\theta)^k \mathbf{1}^\top H_i^{k+2}\mathbf{1}. 
	\end{equation}
	By calculation,
	\begin{equation*}
		\begin{aligned}
			\mathbf{1}^\top H_i^2\mathbf{1}&=\mathbf{1}^\top W\mathbf{1}-\omega\mathbf{1}^\top W\mathbf{e}_i-\omega\mathbf{e}_i^\top W\mathbf{1}+\omega^2\mathbf{e}_i^\top W\mathbf{e}_i \\
			&=n-\omega-\omega\sum_{j\in\V}W_{ji}+\omega^2 W_{ii}\\
			&=n-\omega-\omega g_i.
		\end{aligned}
	\end{equation*}
	Therefore, the optimization problem \eqref{prob:big_stub} is equivalent to
	\begin{equation}\label{prob:big_stub2}
		\mathrm{Minimize}_{i\in\V} \quad   -g_i+ \sum_{k=1}^\infty (1-\theta)^k \mathbf{1}^\top H_i^{k+2}\mathbf{1}.
	\end{equation}
	The problem to \eqref{prob:big_stub2} is $i^\ast$. This is because for any $i\not= i^\ast$, it holds
	\begin{equation*}
		\begin{aligned}
			&g_{i^\ast}-g_i+ \sum_{k=1}^\infty (1-\theta)^k \mathbf{1}^\top H_i^{k+2}\mathbf{1}- \sum_{k=1}^\infty (1-\theta)^k \mathbf{1}^\top H_{i^\ast}^{k+2}\mathbf{1}\\
			&> g_{i^\ast}-g_i- \sum_{k=1}^\infty (1-\theta)^k \mathbf{1}^\top H_{i^\ast}^{k+2}\mathbf{1}\\
			&\geq g_{i^\ast}-g_i-\|\mathbf{1}^\top\|_\infty\sum_{k=1}^\infty (1-\theta)^k\|H_i\|_{\infty}^{k+2}\|\mathbf{1}\|_\infty\\
			&\geq \delta_g-\frac{n(1-\theta)}{\theta}>0.
		\end{aligned}
	\end{equation*}
	The proof is then completed.\hfill$\square$



