	\begin{equation}
		\begin{aligned}
			\sop_0&=\frac{1}{n+1}+\frac{\omega}{n+1}\left\{\sum_{j\in\mathcal{S}}(1-\theta_j)\right.\\
			&+\left. \frac{\sum\limits_{j\in\mathcal{S}}c_j(1-\theta_j)[\sum\limits_{j\in\V}(1-\theta_j)-\omega\sum\limits_{j\in\mathcal{S}}(1-\theta_j)]}{\sum\limits_{j\in \V}c_j\theta_j+\omega\sum\limits_{j\in\mathcal{S}}c_j(1-\theta_j)}\right\},\\
