	\section{Proofs for Subsection \ref{sec:ring}}\label{ap:4}

	\noindent\textbf{Proof of Lemma \ref{le:circu}}. For any $\mathcal{S}=\{1,j\}$, it holds
	\[\sop_0(\mathcal{S})=\frac{(1-\theta)\omega}{n+1}\mathbf{1}^\top H(\s)^{-1}(\mathbf{e}_1+\mathbf{e}_j)+\frac{1}{n+1},\]
	with 
	\[H(\s)=I-(1-\theta)W+\omega(1-\theta)(\mathbf{e}_1\mathbf{w}_1^\top+\mathbf{e}_j\mathbf{w}_j^\top), \]
	where $\mathbf{w}_1, \mathbf{w}_j$ are the first and $j$th column of $W$, respectively. Moreover, the optimization problem \eqref{eq:op_follower} becomes
	\begin{equation}\label{eq:op_cycle}
		\begin{aligned}
			&\mathrm{Maximize}_{j\in\V} \quad   \mathbf{1}^\top H(\s)^{-1}(\mathbf{e}_1+\mathbf{e}_j)  \\
			&\quad\mathrm{s.t.} \quad \quad j\not= 1
		\end{aligned}
	\end{equation}
	Note that $M:=I-(1-\theta)W$ is a strictly diagonally dominant circulant matrix, thus non-singular. According to the Sherman-Morrison formnula, it holds
	\begin{equation*}
		\begin{aligned}
			H(\s)^{-1}&=M^{-1}-\left.\omega(1-\theta)M^{-1}[\mathbf{e}_1,\mathbf{e}_j]\cdot\right(I+\\
			&\left.\omega(1-\theta)\left[\begin{array}{c}
				\mathbf{w}_1^\top  \\
				\mathbf{w}_j^\top
			\end{array}\right]M^{-1}[\mathbf{e}_1,\mathbf{e}_j]\right)^{-1}\left[\begin{array}{c}
				\mathbf{w}_1^\top  \\
				\mathbf{w}_j^\top
			\end{array}\right]M^{-1}
		\end{aligned}
	\end{equation*}
	From conclusions in literature \cite{searle1979inverting}, $M^{-1}$ is a circulant matrix. Let 
	\[M^{-1}=C(m_0,m_1,\dots,m_{n-1}). \]
	It then holds 
	\[\mathbf{1}^\top M^{-1}\mathbf{e}_1=\mathbf{1}^\top M^{-1}\mathbf{e}_j=\sum_{\ell=0}^{n-1}m_\ell, \]
	which is irrelevant of the choice of $\mathcal{S}$.
	Therefore, the optimization problem \eqref{eq:op_cycle} is equivalent to the following problem
	\begin{equation}\label{eq:op_cycle2}
		\begin{aligned}
			&\mathrm{Minimize}_{j\in\V} \quad   \mathbf{1}^\top \left(I+
			\omega(1-\theta)\left[\begin{array}{c}
				\mathbf{w}_1^\top  \\
				\mathbf{w}_j^\top
			\end{array}\right]M^{-1}[\mathbf{e}_1,\mathbf{e}_j]\right)^{-1}\\
			&\qquad\qquad\qquad\cdot\omega(1-\theta)\left[\begin{array}{c}
				\mathbf{w}_1^\top  \\
				\mathbf{w}_j^\top
			\end{array}\right]M^{-1}[\mathbf{e}_1,\mathbf{e}_j]\mathbf{1}   \\
			&\quad\mathrm{s.t.} \quad \quad j\not= 1
		\end{aligned}
	\end{equation}
	% In the following of this subsection, for the simplicity of notation, we define $\mathbf{s}_{\ell}:=\mathbf{e}_{\ell}$ for $\ell=0,1,\dots, n-1$, and let $\mathbf{s}_{\ell}=\mathbf{s}_{\ell+n}$ for all $\ell\in\mathbb{Z}$. 
	Define  
	\[B_j:=\omega(1-\theta)\left[\begin{array}{c}
		\mathbf{w}_1^\top  \\
		\mathbf{w}_j^\top
	\end{array}\right]M^{-1}[\mathbf{e}_1,\mathbf{e}_j]\in\mathbb{R}^{2\times 2}. \]
	Note that $(I+B_j)^{-1}B_j=I-(I+B_j)^{-1}$. The optimization problem \eqref{eq:op_cycle2} is then equivalent to
	\begin{equation}\label{eq:op_cycle3}
		\begin{aligned}
			&\mathrm{Maximize}_{j\in\V} \quad   \mathbf{1}^\top (I+B_j)^{-1}\mathbf{1}   \\
			&\quad\mathrm{s.t.} \quad \quad j\not= 1
		\end{aligned}
	\end{equation}
	Due to the fact that $(I-(1-\theta)W)M^{-1}=I$, i.e., $WM^{-1}=\frac{1}{1-\theta}(M^{-1}-I)$, it must be 
	\begin{equation*}
		\begin{aligned}
			\left[\begin{array}{c}
				\mathbf{w}_1^\top  \\
				\mathbf{w}_j^\top
			\end{array}\right]M^{-1}[\mathbf{e}_1,\mathbf{e}_j]&=\frac{1}{1-\theta}\left\{\left[\begin{matrix}
				[M^{-1}]_{11} &  [M^{-1}]_{1j} \\
				[M^{-1}]_{j1} & [M^{-1}]_{jj}
			\end{matrix}\right]-I\right\}\\
			&=\frac{1}{1-\theta}\left[\begin{matrix}
				m_0-1 &  m_{j-1} \\
				m_{1-j} & m_0-1
			\end{matrix}\right]
		\end{aligned}
	\end{equation*}
	Therefore,
	\[B_j=\omega\left[\begin{array}{cc}
		m_0-1 & m_{j-1}  \\
		m_{1-j} & m_0-1
	\end{array}\right]. \]
	Note that the matrix $M$ is symmetric. Therefore, $M^{-1}$ is also symmetric, which gives that $m_\ell=m_{n-\ell}, \forall \ell\in\{0,1,\dots, n\}$, and then $m_{1-j}=m_{j-1}, \forall j\in [n]$. Moreover, for the reason that 
	$M^{-1}=\sum_{k=0}^\infty (1-\theta)^kW^k$, it is $m_\ell>0, \ell=0,1,\dots, n-1$.
	As a result,
	\begin{equation*}
		\begin{aligned}
			\mathbf{1}^\top (I+B_j)^{-1}\mathbf{1} &=\frac{2\left(1+\omega (m_0-1)-\omega m_{j-1}\right)}{\left(1+\omega(m_0-1)\right)^2-\left(\omega m_{j-1}\right)^2}\\
			&= \frac{2}{1+\omega(m_0+m_{j-1}-1)}>0
		\end{aligned}
	\end{equation*}
	The optimization problem \eqref{eq:op_cycle3} then becomes
	\begin{equation}\label{eq:op_cycle4}
		\begin{aligned}
			&\mathrm{Minimize}_{j\in\V} \;\;   m_{j-1} \quad\mathrm{s.t.} \;\; j\not= 1
		\end{aligned}
	\end{equation}
	The proof is then completed.\hfill$\square$
