	To prove Theorem \ref{th:cycle}, some properties on product of symmetric circulant matrices are required. To make the main proof more clear, we only introduce the lemmas here, and leave their proofs to the next subsection. 

	\begin{lemma}\label{le:monotone}
		Given two real number sequences $u_0,u_1,\dots,u_{s-1}$ and $v_0,v_1,\dots,v_{s-1}$, such that $0\leq u_{h+1}\leq u_h$ and $0\leq u_{h+1}\leq u_h$ hold for all $h\in\{0,1,\dots,s-2\}$. The following statements then hold.
		\begin{enumerate}
			\item Define $U=C(u_0,u_1,\dots,u_{s-1},u_{s-1},\dots,u_1)$ and $V=C(v_0,v_1,\dots,v_{s-1},v_{s-1},\dots,v_1)$. Let $n=2s-1$ $R=UV\in\mathbb{R}^{n\times n}$. The matrix $R$ is a circulant matrix, denoted as $R=C(r_0,r_1,\dots,r_{s-1},r_{s-1},\dots,r_1)$. It holds $0\leq r_{h+1}\leq r_h, \forall h=0,1,\dots, s-2$. 
			\item Define $U=C(u_0,u_1,\dots,u_{s-1},0,u_{s-1},\dots,u_1)$ and $V=C(v_0,v_1,\dots,v_{s-1},0,v_{s-1},\dots,v_1)$. Let $n=2s$ $R=UV\in\mathbb{R}^{n\times n}$. The matrix $R$ is a circulant matrix, denoted as $R=C(r_0,r_1,\dots,r_{s-1},r_s,r_{s-1},\dots,r_1)$. It holds $0\leq r_{h+1}\leq r_h, \forall h=0,1,\dots,s-1$.
		\end{enumerate}
	\end{lemma}

	\begin{lemma}\label{le:strict_monotone}
		Consider two real number sequences $u_0,u_1,\dots,u_{s-1}$ and $v_0,v_1,\dots,v_{s-1}$, with $u_0\geq u_1\geq \dots\geq u_{s-1}$ and $v_0\geq v_1\geq \dots\geq v_{s-1}$. The following statements then hold.
		\begin{enumerate}
			\item Define $U=C(u_0,u_1,\dots,u_{s-1},u_{s-1},\dots,u_1)$ and $V=C(v_0,v_1,\dots,v_{s-1},v_{s-1},\dots,v_1)$. Let $R=UV=C(r_0,r_1,\dots,r_{s-1},r_{s-1},\dots,r_1)$. Suppose that $u_i>u_{i+1}$, $v_j>v_{j+1}$ and $i\geq j$ hold for some $i,j=0,1,\dots,s-2$. Then, for $h^\ast=\min\{i+j,2s-3-i-j\}$, it holds that $r_{i-j}>r_{i-j+1}>\dots>r_{h^\ast}>r_{h^\ast+1}$.
			\item Define $U=C(u_0,u_1,\dots,u_{s-1},u_s,u_{s-1},\dots,u_1)$ and $V=C(v_0,v_1,\dots,v_{s-1},v_s,v_{s-1},\dots,v_1)$. Let $R=UV=C(r_0,r_1,\dots,r_{s-1},r_s,r_{s-1},\dots,r_1)$. Suppose that $u_i>u_{i+1}$, $v_j>v_{j+1}$ and $i\geq j$ hold for some $i,j=0,1,\dots,s-1$. Then, for $h^\ast=\min\{i+j,2s-1-i-j\}$, it holds that $r_{i-j}>r_{i-j+1}>\dots>r_{h^\ast}>r_{h^\ast+1}$. 
		\end{enumerate}
	\end{lemma}

	Basically, Lemmas \ref{le:monotone} and \ref{le:strict_monotone} are saying that for two symmetric circulant matrices with monotone patterns in their rows (i.e., $u_h\geq u_{h+1}$ and $v_h\geq v_{h+1}$, the monotonicity is preserved in their product. 
	\hfill\break

	\noindent \textbf{Proof of Theorem \ref{th:cycle}}. We only prove the conclusion 1), and 2) can be obtained similarly. Consider 
	\[M^{-1}=\sum_{k=0}^\infty (1-\theta)^kW^k. \]
	From Lemma \ref{le:monotone}, and by induction, $W^k$ is a circulant matrix of the form $C(m_{0}^{(k)}, m_{1}^{(k)},\dots, m_{s-1}^{(k)},m_{s-1}^{(k)},\dots, m_{1}^{(k)})$, with $m_{0}^{(k)}\geq m_{1}^{(k)}\geq \dots\geq m_{s-1}^{(k)}$. As $w_0>w_{s-1}$, there exists $h\in\{1,\dots,s-2\}$ such that $w_h>w_{h+1}$. Applying Lemma~\ref{le:strict_monotone} to $W^2$ (with $i=j=h$), we obtain $h^\ast=\min\{2h,2s-2h-3\}\geq 1$. Define $\bar{h}_1=\min\{2h,2s-2h-3\}$, then
	\[m_0^{(2)}>m_1^{(2)}>m_2^{(2)}>\dots>m_{\bar{h}_1}^{(2)}>m_{\bar{h}_1+1}^{(2)}.\] 
	Again applying Lemma \ref{le:strict_monotone} to $W^4$ (with $U=W^2, V=W^2, i=j=1,2,\dots,\bar{h}_1$), we obtain 
	\[m_0^{(4)}>m_1^{(4)}>m_2^{(4)}>\dots>m_{\bar{h}_2}^{(4)}>m_{\bar{h}_2+1}^{(4)},  \]
	where $\bar{h}_2=\max_{\ell\in\{0,\dots,\bar{h}_1\}}\min\{2\ell, 2s-2\ell-3\}$. This process can be iterated, and we can obtain
	\[m_0^{(2^k)}>m_1^{(2^k)}>m_2^{(2^k)}>\dots>m_{\bar{h}_k}^{(2^k)}>m_{\bar{h}_k+1}^{(2^k)},  \]
	with $\bar{h}_k$ iteratively defined as
	\[\bar{h}_{k+1}:=\max_{\ell\in\{0,\dots,\bar{h}_k\}}\min\{2\ell, 2s-2\ell-3\}. \]
	Note that $\bar{h}_{k+1}=2\bar{h}_{k}$ if $2\bar{h}_{k}\leq s-2$. Therefore, there exists $k'$ such that $\bar{h}_{k'}=s-2$ (when $s-2$ is even) or $\bar{h}_{k'}=s-3$ (when $s-2$ is odd), and for the latter case it is $\bar{h}_{k'+1}=2s-3-2\cdot \frac{s-1}{2}=s-2$. As a result, we either have 
	\[m_0^{(2^{k'})}>m_1^{(2^{k'})}>m_2^{(2^{k'})}>\dots>m_{s-2}^{(2^{k'})}>m_{s-1}^{(2^{k'})}  \]
	or 
	\[m_0^{(2^{k'+1})}>m_1^{(2^{k'+1})}>\dots>m_{s-2}^{(2^{k'+1})}>m_{s-1}^{(2^{k'+1})}.  \]
	Note that $m_\ell =\sum_{k=0}^\infty m_{\ell}^{(k)}, \ell\in\{0,1,\dots, s-1\}$. Therefore, for both cases, it must be $m_0>m_1>\dots>m_{s-1}$. The proof is then completed.\hfill$\square$ 



