	\section{Proofs of Lemmas \ref{le:monotone} and \ref{le:strict_monotone}}

	\noindent\textbf{Proof of Lemma \ref{le:monotone}}. Due to the fact that circulant matrices commute under multiplication \cite{searle1979inverting} and $U,V$ are both symmetric matrices, $R$ is also symmetric. Moreover, from the statement (iv) in \cite{searle1979inverting}, $R$ is a circulant matrix.
	\begin{enumerate}
		\item Let $\mathbf{u}=(u_0,u_1,\dots,u_{s-1},u_{s-1},\dots,u_1)^\top$, $\mathbf{v}=(v_0,v_1,\dots,v_{s-1},v_{s-1},\dots,v_1)^\top$, and $\mathbf{r}=(r_0,r_1,\dots,\allowbreak r_{s-1},r_{s-1},\dots,r_1)^\top$. We use $u(\ell), v(\ell)$ and $r(\ell)$ to denote the $(\ell+1)$th element of $\mathbf{u}, \mathbf{v}$ and $\mathbf{r}$, respectively. Again from the statement (iv) of \cite{searle1979inverting}, it holds $r(h)=\sum_{\ell=0}^{n-1}u(\ell) v(n+h-\ell),\forall h=0,1,\dots, n-1$. Here we make a convention that $u(n+h)=u(h), v(n+h)=v(h), \forall h\in\mathbb{Z}$. Note that $u(\ell)=u(-\ell), v(\ell)=v(-\ell), \forall \ell\in\mathbb{Z}$. We then have 
		\[r(h)=\sum_{\ell=0}^{n-1}u(\ell) v(h-\ell)=\sum_{\ell=0}^{n-1}u(\ell) v(\ell-h)  \]
		for all $h=0,1,\dots, n-1$. As a result, for $h=0,1,\dots, s-2$, it holds
		\begin{equation}
			\begin{aligned}
				r_h&=u_0v_{-h}+u_1v_{1-h}+\dots+u_hv_0\\
				&+u_{h+1}v_1+\dots+u_{s-1}v_{s-h-1}\\
				&+u_{-1}v_{-1-h}+\dots+u_{2-s+h}v_{2-s}+u_{1-s+h}v_{1-s}\\
				&+u_{-s+h}v_{-s}+\dots+u_{1-s}v_{1-s-h}\\
				&=u_0v_{h}+u_1v_{h-1}+\dots+u_hv_0\\
				&+u_{h+1}v_1+\dots+u_{s-1}v_{s-h-1}\\
				&+u_{1}v_{h+1}+\dots+u_{s-h-2}v_{s-2}+u_{s-h-1}v_{s-1}\\
				&+u_{s-h}v_{s-1}+\dots+u_{s-1}v_{s-h},\\
				r_{h+1}&=u_0v_{h+1}+u_1v_h+\dots+u_hv_1\\
				&+u_{h+1}v_0+\dots+u_{s-1}v_{s-h-2}\\
