			\begin{aligned}
				&r_h-r_{h+1}\\
				&=\sum_{\ell=1}^{s-h-1}\Big\{u_{h-\ell+1}(v_{\ell-1}-v_{\ell})+u_{h+\ell}(v_{\ell}-v_{\ell-1})\Big\}\\
