			\begin{aligned}
				&r_h-r_{h+1}= \sum_{\ell=1}^{s-h-1}(u_{h-\ell+1}-u_{h+\ell})(v_{\ell-1}-v_{\ell})+\\
				&\sum_{\ell=1}^{s-h-2}(u_{s-h-1-\ell}-u_{s-h-1+\ell})(v_{s-1-\ell}-v_{s-1-\ell+1})\\
				&+u_0v_h+u_1v_{h-1}+\dots +u_{2h-s+1}v_{s-h-1}\\
				&-u_0v_{h+1}-u_1v_h-\dots-u_{2h-s+1}v_{s-h}\\
