				&-u_{2s-2h-2}v_{h}-u_{2s-2h-1}v_{h-1}-\dots-u_{s-1}v_{s-h-1}\\
				&=\sum_{\ell=1}^{s-h-1}(u_{h-\ell+1}-u_{h+\ell})(v_{\ell-1}-v_{\ell})+\\
				&\sum_{\ell=1}^{s-h-2}(u_{s-h-1-\ell}-u_{s-h-1+\ell})(v_{s-1-\ell}-v_{s-1-\ell+1})\\
				&+ \sum_{\ell=0}^{2h-s+1}(u_{\ell}-u_{2s-2h-2+\ell})(v_{h-\ell}-v_{h-\ell+1})\geq 0.
			\end{aligned}
		\end{equation}
