				&+ u_{2h+2}v_{h+2}+u_{2h+3}v_{h+3}+\dots+u_{s-1}v_{s-h-1}\\
				&-u_{2h+2}v_{h+1}-u_{2h+3}v_{2h+2}-\dots-u_{s-1}v_{s-h-2}\\
				&+u_1v_{h+1}+u_2v_{h+2}+\dots+u_{s-2h-2}v_{s-h-2}\\
				&-u_1v_{h+2}-u_2v_{h+3}-\dots-u_{s-2h-2}v_{s-h-1}\\
				&=\sum_{\ell=1}^{h+1}(u_{h-\ell+1}-u_{h+\ell})(v_{\ell-1}-v_{\ell})+\\
				&\sum_{\ell=1}^{h}(u_{s-h-1-\ell}-u_{s-h+1-\ell})(v_{s-\ell-1}-v_{s-\ell})\\
				&+\sum_{\ell=1}^{s-2h-2}(u_{\ell}-u_{2h+1+\ell})(v_{h+\ell}-v_{h+\ell+1})\geq 0.
