	\noindent\textbf{Proof of Lemma \ref{le:strict_monotone}}. We only prove 1), and 2) can be proved similarly. 

	\emph{Step 1}. Let
	\begin{equation*}
		\begin{aligned}
			\bar{U}&:=C(u_i\mathbf{1}_{i+1}^\top, u_{i+1}\mathbf{1}_{s-1-i}^\top,u_{i+1}\mathbf{1}_{s-1-i}^\top,u_i\mathbf{1}_{i}^\top),\\
			\bar{V}&:=C(v_i\mathbf{1}_{i+1}^\top, v_{i+1}\mathbf{1}_{s-1-i}^\top,v_{i+1}\mathbf{1}_{s-1-i}^\top,v_i\mathbf{1}_{i}^\top),\\
			\bar{R}&:=\bar{U}\bar{V}=C(\bar{r}_0,\bar{r}_1,\dots,\bar{r}_{s-1},\bar{r}_{s-1},\dots, \bar{r}_1).
		\end{aligned}
	\end{equation*}
	We prove that if $\bar{r}_h>\bar{r}_{h+1}$ for some $h=0,1,\dots,s-2$, it must be $r_h>r_{h+1}$. From \eqref{eq:sorting_ineq1}-\eqref{eq:sorting_ineq3}, it can be seen that if $\bar{r}_h>\bar{r}_{h+1}$, at least one term in the summation (corresponding to the value of $h$) is strictly positive, say, $h+1>s-h-1$ and $(\bar{u}_{h-\ell+1}-\bar{u}_{h+\ell})(\bar{v}_{\ell-1}-\bar{v}_\ell)>0$ hold for some $\ell=1,\dots,s-h-1$ (here we let $(\bar{u}_0,\bar{u}_1,\dots,\bar{u}_{s-1})=(u_i\mathbf{1}_{i+1}^\top,u_{i+1}\mathbf{1}_{s-1-i}^\top)$ and $(\bar{v}_0,\bar{v}_1,\dots,\bar{v}_{s-1})=(v_i\mathbf{1}_{i+1}^\top,v_{i+1}\mathbf{1}_{s-1-i}^\top)$). Then, it must be $\ell=j+1$ and $0\leq h-\ell+1\leq i<h+\ell\leq s-1$, which further gives $u_{h-\ell+1}\geq u_{i}> u_{i+1}= u_{h+\ell}$ and $v_{\ell-1}=v_{j}>v_{j+1}=v_\ell$. Again from \eqref{eq:sorting_ineq2}, we obtain $r_h>r_{h+1}$. The argument also holds if \eqref{eq:sorting_ineq1} or \eqref{eq:sorting_ineq3} holds for $h$. The claim is then proved.

	\emph{Step 2}. Let $u:=u_{i}-u_{i+1}>0$, $v:=v_i-v_{i+1}>0$, and 
	\begin{equation*}
		\begin{aligned}
			\tilde{U}&=C(u\mathbf{1}_{i+1}^\top,\mathbf{0}_{s-1-i}^\top,\mathbf{0}_{s-1-i}^\top,u\mathbf{1}_{i}^\top ),\\
			\tilde{V}&=C(v\mathbf{1}_{i+1}^\top,\mathbf{0}_{s-1-i}^\top,\mathbf{0}_{s-1-i}^\top,v\mathbf{1}_{i}^\top ),\\
			\tilde{R}&:=\tilde{U}\tilde{V}=C(\tilde{r}_0,\tilde{r}_1,\dots,\tilde{r}_{s-1},\tilde{r}_{s-1},\dots, \tilde{r}_1).
		\end{aligned}
	\end{equation*}
	We prove that if $\tilde{r}_h>\tilde{r}_{h+1}$ holds for some $h=0,1,\dots,s-2$, it must be $\bar{r}_h>\bar{r}_{h+1}$. Note that $\tilde{U}=\bar{U}-u_{i+1}\mathbf{1}\mathbf{1}^\top$ and $\tilde{V}=\bar{V}-v_{i+1}\mathbf{1}\mathbf{1}^\top$. We then have $\tilde{R}=\bar{R}-n(u_{i+1}+v_{i+1}-u_{i+1}v_{i+1})\mathbf{11}^\top$. Therefore, $\tilde{r}_h>\tilde{r}_{h+1}$ is equivalent to $\bar{r}_h>\bar{r}_{h+1}$.

	\emph{Step 3}. Consider $\tilde{R}$. We prove that 
	\begin{equation}\label{eq:ineq_rtilde}
		\tilde{r}_{i-j}>\dots>\tilde{r}_{h^\ast}>\tilde{r}_{h^\ast+1}.
	\end{equation}
	Without loss of generality, let $j\leq i$. 
	\begin{itemize}
		\item If $i+j\leq s-2$, by calculation,
		\begin{equation*}
			\begin{aligned}
				&\tilde{r}_0=\tilde{r}_1=\dots=\tilde{r}_{i-j}=(2j+1)uv,\\ 
				&\tilde{r}_{i-j+1}=2juv,\dots,\tilde{r}_{i+j}=uv,\\
				&\tilde{r}_{i+j+1}=\tilde{r}_{i+j+2}=\dots=\tilde{r}_{s-1}=0,
			\end{aligned}
		\end{equation*}
		which gives \eqref{eq:ineq_rtilde}.
		\item If $i+j=s-1$, by calculation, 
		\begin{equation*}
			\begin{aligned}
				&\tilde{r}_0=\tilde{r}_1=\dots=\tilde{r}_{i-j}=(2j+1)uv,\\ 
				&\tilde{r}_{i-j+1}=2juv,\dots,\tilde{r}_{s-1}=uv,
			\end{aligned}
		\end{equation*}
		which gives \eqref{eq:ineq_rtilde}.
		\item If $i+j\geq s$, by calculation,
		\begin{equation*}
			\begin{aligned}
				&\tilde{r}_0=\tilde{r}_1=\dots=\tilde{r}_{i-j}=(2j+1)uv,\\ 
				&\tilde{r}_{i-j+1}=2juv,\dots,\tilde{r}_{2s-3-i-j}=(2i+2j-2s+4)uv,\\
				&\tilde{r}_{2s-2-i-j}=\dots=\tilde{r}_{s-1}=(2i+2j-2s+3)uv,
			\end{aligned}
		\end{equation*}
		which again gives \eqref{eq:ineq_rtilde}.
	\end{itemize}
	Combining all the arguments above, the desired conclusion is obtained. \hfill$\square$ 


