\section{Problem Formulation}

Consider an active learning setup where the learner $\mathcal{L}$ must learn a function $\mathcal{V}: (\Sigma^I)^*\rightarrow \mathbb{Q}$ exactly as a deterministic quantitative automaton $\mathcal{A}=\langle Q,q_0,\Sigma^I,\Sigma^O,\delta,L,\mathbf{Val}\rangle$. The learner can only obtain information about $\mathcal{V}$ by asking the teacher $\mathcal{T}$ preference and equivalence queries. The learner is aware of the algebraic form of $\mathcal{V}$, and sets $\mathbf{Val}$ to have equivalent form. The teacher is assumed to have preferences consistent with $\mathcal{V}$, and responds to the preference query as follows:
\begin{align}
    \textbf{prefQ}(s_1,s_2) = \mathcal{P}(s_1,s_2|\mathcal{V})=\left\{\begin{array}{rl}
    1 & \text{ if } \mathcal{V}(s_1) > \mathcal{V}(s_2)\\
    0 & \text{ if } \mathcal{V}(s_1) = \mathcal{V}(s_2)\\
    -1& \text{ if } \mathcal{V}(s_1) < \mathcal{V}(s_2)
\end{array}\right.
\end{align} For equivalence queries, the teacher responds with a 3-tuple as follows:
\begin{align}
    \mathbf{equivQ}(\mathcal{A})=\langle \forall s: \mathcal{A}(s)=\mathcal{V}(s), c: \mathcal{A}(c)\neq\mathcal{V}(c), f(c,\mathcal{A},\mathcal{V})\rangle
\end{align} where feedback is represented by $f(c,\mathcal{A},\mathcal{V})$. If the provided feedback is \emph{strong}, then the learner acquires the constraint $\mathbf{Val}(c)=\mathcal{V}(c)$ from $f(c,\mathcal{A},\mathcal{V})$, indicating that the concrete value of $c$ is $\mathcal{V}(c)$. If the feedback is \emph{weak}, then the learner obtains $\mathbf{Val}(c)\neq\mathcal{A}(c)$ from $f(c,\mathcal{A},\mathcal{V})$, indicating that the concrete value of $c$ is not $\mathcal{A}(c)$ for the current hypothesis $\mathcal{A}$. Figure \ref{fig:prefq-equivq-example} depicts examples constraints obtained from preference queries and equivalence queries under non-discounted summation $\mathbf{Val}$ and $\mathcal{V}$ functions.

Thus, given a teacher $\mathcal{T}$ capable of answering \textbf{prefQ} and \textbf{equivQ} asked by a learner $\mathcal{L}$, the learner must infer the minimal deterministic quantitative automaton $\mathcal{A}$ equivalent to $\mathcal{V}$. We now describe how \ouralgorithm{} solves this problem.

\begin{algorithm}[t!]
\caption{\textbf{Qu}antitative Automata \textbf{In}ference from \textbf{T}heory and \textbf{I}ncremental \textbf{C}onstraints}
\label{alg:quintic-pseudo}
\textbf{Input}: Alphabets $\Sigma^I$ (input) and $\Sigma^O$ (output), teacher $\mathcal{T}$ utilizing valuation function $\mathcal{V}$\\
\textbf{Output}: Deterministic Quantitative Automaton $\mathcal{A} = \langle \hat{Q}, \Sigma^I, \Sigma^O, \hat{q}_0, \hat{\delta}, \hat{L}, \mathbf{Val}\rangle$\\
\textbf{Assumptions}: A formal theory $\mathbf{T}$ for which there exists an $\mathcal{R}\in\{=,\neq\}$ such that $\mathcal{V}(s)\mathbf{R}\mathbf{Val}(s)$ is valid in $\mathbf{T}$. A recursive definition of $\mathbf{Val}$ exists. $\mathcal{L}$ is a stack, where each element is a pair of observation table and equivalence class set. $\mathcal{S}$ is an SMT solver.\\
\textbf{Remarks:} Due to the recursive definition of $\mathbf{Val}$, the set $(S\cup(S\cdot\Sigma^I))\cdot E$ must be prefix-closed. This means $E$ must now also be prefix-closed: during a consistency fix operation, if $e$ is added to $E$, then all prefixes of $e$ are also added to $E$.\\
\begin{algorithmic}[1]
\STATE Initialize $\mathcal{O} = \obstable$ with $S=\{\varepsilon\},E=\{\varepsilon\}$, $\mathcal{C}=\{\}$, $\Gamma=\emptyset$\\
\STATE \textit{sat?}$=$\textit{UNSAT}, \textit{iscorrect} $=$ False, $\mathcal{L}=$ \textsc{Stack}(), $\mathcal{S}=$ \textsc{Solver}()
\STATE $\mathcal{O,L,S}\longleftarrow$ \textsc{SymbolicFill}$\left(\mathcal{O,L,S,T},\Sigma^I, \Sigma^O,\text{backtrack=False}\right)$
\REPEAT
\WHILE{\textit{sat?} is \textit{UNSAT}}
\STATE $\mathcal{O,L,S} \longleftarrow$ \textsc{MakeClosedAndConsistent}$\left(\mathcal{O,L,S,T},\Sigma^I, \Sigma^O\right)$
\STATE \textit{sat?}, $\mathcal{H}\longleftarrow$\textsc{MakeSymbolicHypothesis}$\left(\mathcal{O,S}, \Sigma^I, \Sigma^O\right)$
\IF{\textit{sat?} is \textit{UNSAT}}
    \STATE $\mathcal{O,L,S}\longleftarrow$ \textsc{SymbolicFill}$\left(\mathcal{O,L,S,T},\Sigma^I, \Sigma^O,\text{backtrack=True}\right)$
\ENDIF
\ENDWHILE
\STATE $\mathcal{S}$.\textsc{Push}()
\STATE Exhaustively test all concrete hypotheses $h$ under symbolic hypothesis $\mathcal{H}$ and constraints $\mathcal{C}$ using \textsc{EquivQ}$(h)$ and record counterexamples and symbolic constraints into $\mathcal{C}$ until an $h$ is found to be correct or there exist no more valid $h$ under $\mathcal{H}$ and the updated constraints $\mathcal{C}$.
\STATE $\mathcal{S}$.\textsc{Pop}()
\IF{$h$ is correct}
\RETURN $h$
\ELSE
\STATE $\mathcal{O,L,S}\longleftarrow$ \textsc{SymbolicFill}$\left(\mathcal{O,L,S,T},\Sigma^I, \Sigma^O,\text{backtrack=True}\right)$
\STATE Expand $\mathcal{O}$ with prefixes of all counterexamples obtained from Line 13
\STATE $\mathcal{O,L,S}\longleftarrow$ \textsc{SymbolicFill}$\left(\mathcal{O,L,S,T},\Sigma^I, \Sigma^O,\text{backtrack=False}\right)$
\ENDIF
\UNTIL{\textit{iscorrect} $=$ True}
\end{algorithmic}
\end{algorithm}

\section{\ouralgorithm{}}

\ouralgorithm{}, shown in Algorithm \ref{alg:quintic-pseudo}, is an \lstar{}-based algorithm \cite{Angluin87} for actively learning quantitative automata from constraints collected through preference and equivalence queries. Given a pair $\mathbf{Val}$ and $\mathcal{V}$ such that $\mathcal{V}(s)\mathbf{R}\mathbf{Val}(s)$ is always a statement contained in a formal theory $\mathbf{T}$ for a relation $\mathbf{R}\in\{=,\neq\}$, and a set of collected constraints $\mathcal{C}$ contained in $\mathbf{T}$, \ouralgorithm{} applies deductive reasoning using $\mathbf{T}$, as well as an informed search encoded as a maximum satisfiability (MaxSMT) problem to arrive at the correct deterministic quantitative automaton. Iterative deepening depth first search (IDS) guarantees completeness and minimalism, since the learner is unaware of the minimum number of states required to represent $\mathcal{V}$.

\ouralgorithm{}, similar to \textsc{Remap} \cite{remap}, employs a symbolic observation table $\mathcal{O} =\obstable$, and executes requisite preference queries and table expansions in order to obtain a unified, closed, and consistent table, from which an automaton hypothesis can be constructed.

The constraints obtained from preference queries are determined by $\mathcal{V}$ and $\mathbf{Val}$ via $\mathcal{V}(s_1)\,\mathbf{R}\,\mathcal{V}(s_2)\implies\mathbf{Val}(s_1)\,\mathbf{R}\,\mathbf{Val}(s_2)$ for the relation $\mathbf{R}\in\{>,<,=\}$. In order to apply deductive reasoning to arrive at a valid quantitative automaton, a suitable theory must also be supplied to the learner. We consider four forms of the valuation function, based on the automaton type. Below, we illustrate the corresponding forms for $\mathcal{A}(s)$ and the recursive form of $\mathbf{Val}$, where $T$ is the empirical observation function from the observation table:
\begin{itemize}
    \item Non-Discounted Summation $\mathcal{A}(s)=\sum_{i=0}^{|s|} L(\delta(q_0,s_{:i}))$ and $\mathbf{Val}(s\cdot\sigma) = T(s\cdot\sigma) + \mathbf{Val}(s)$ with $\mathbf{Val}(\varepsilon)=T(\varepsilon)=0$ 
    \item Discounted Summation $\mathcal{A}(s)=\sum_{i=0}^{|s|} \gamma^iL(\delta(q_0,s_{:i}))$ and\\$\mathbf{Val}(s\cdot\sigma)=\gamma^{|s\cdot\sigma|}T(s\cdot\sigma)+\mathbf{Val}(s)$ with $\mathbf{Val}(\varepsilon)=T(\varepsilon)=0$ 
    \item Product $\mathcal{A}(s)=\prod_{i=0}^{|s|} L(\delta(q_0,s_{:i}))$ and\\$\mathbf{Val}(s\cdot\sigma)=T(s\cdot\sigma)\mathbf{Val}(s)$ with $\mathbf{Val}(\varepsilon)=T(\varepsilon)=1$
    \item Classification: $\mathcal{A}(s)=L(\delta(q_0,s))$ and $\mathbf{Val}(s)=T(s)$ 
\end{itemize}
Determining whether a pair of variables in the table are equivalent is a critical operation in \ouralgorithm{}, since equivalence underscores closed and consistency checks, and this must be accomplished for each \textbf{Val} supported by \ouralgorithm{}. Conjecturing variable equivalences occurs within the \textsc{SymbolicFill} call, so we organize our discussion of \ouralgorithm{} on how variable equivalences are conjectured, and how a complete search over chains of alternating \textsc{SymbolicFill} calls and table expansions occurs in order to arrive at the correct hypothesis.

\subsection{Inferring Variable Equivalences}
Given a recursive form of $\mathbf{Val}$, inference rules can be derived to determine certain variable equivalences. Importantly, variable equivalence is not decidable for all forms of $\mathbf{Val}$. By this, we mean that the learner simply making a requisite number of preference queries is not guaranteed to determine variable equivalence from preference constraints alone. Below, we present the inference rules required each \textbf{Val} definition. In particular, we require inference rules which map from a set preference queries to a conclusion \begin{equation}\label{eq:2}T(s\cdot\sigma)~\mathbf{R}~T(s'\cdot\sigma')\text{ where }\mathbf{R}\in\{<,>,=\}.\end{equation} The inference rules can be obtained by writing Equation \ref{eq:2} in terms of $\mathbf{Val}$, and considering what combinations of preference queries would satisfy Equation \ref{eq:2}. As a result, the inference rules can be concisely encoded into a decision tree with inputs as specific preference queries. For succinctness, we denote the following when encoding the decision tree:
\begin{align*}
(X,Y)&=(\mathbf{prefQ}(s\cdot\sigma,s'\cdot\sigma'), \mathbf{prefQ}(s,s'))\\
(X',Y')&=(\mathbf{prefQ}(s\cdot\sigma, s), \mathbf{prefQ}(s'\cdot\sigma', s'))\\
z(x,y)&=\mathbf{1}_{[x>y]}-\mathbf{1}_{[x<y]} \text{ for } x,y\in\{1,0,-1\}\\
Z(x,y)&=\left\{\begin{array}{rl}
    > & \text{ if } z(x,y)=1\\
    = & \text{ if } z(x,y)=0\\
    < & \text{ if } z(x,y)=-1
\end{array}\right.
\end{align*}
\begin{itemize}
    \item Non-Discounted Summation: If $|X+Y|=2$ and $|X'+Y'|=2$, then the relation $\mathbf{R}$ in $T(s\cdot\sigma)\mathbf{R}T(s'\cdot\sigma')$ cannot be determined. Otherwise, if $|X+Y|=2$ and $|X'+Y'|\neq2$, then $\mathbf{R}=Z(X',Y')$. Otherwise, if $|X+Y|\neq2$, then $\mathbf{R}=Z(X,Y)$.
    \item Product: Identical to non-discounted summation.
    \item Discounted Summation: If $|s|=|s'|$, then use non-discounted summation. Otherwise, if $|s|\neq|s'|$ and $|X'+Y'|=2$, then the relation $\mathbf{R}$ in $T(s\cdot\sigma)\mathbf{R}T(s'\cdot\sigma')$ cannot be determined. Otherwise, if $|s|\neq|s'|$ and $|X'+Y'|\neq2$, then $\mathbf{R}=Z(X',Y')$.
    \item Classification: $\mathbf{R}$ is determined directly from $\mathbf{prefQ}(s\cdot\sigma,s'\cdot\sigma')$, so no inference is needed.

\end{itemize}

