\subsection{2.3. The Ancestral Grothendieck Topology}

\begin{definition}[Ancestral Covering Sieves and Grothendieck Topology]\label{def:gtop}
For $M_w \in \mathcal{M}$, a \emph{sieve} $S$ on $M_w$ is a set of morphisms $f: M_{w'} \to M_w$ closed under precomposition.

The \emph{ancestral Grothendieck topology} $J$ is generated by declaring that, for each $M_w$, the family of all inclusion morphisms from ancestors $M_{w'}$ (with $w'$ a prefix of $w$) to $M_w$ form a covering sieve:
\[
S_{\mathrm{anc}}(M_w) = \{f_u: M_{w'} \to M_w \mid w' \prec w,\, w = u w'\}
\]
A sieve $S$ on $M_w$ is covering if $S_{\mathrm{anc}}(M_w) \subseteq S$.
\end{definition}

\begin{proposition}[Grothendieck Topology Axioms]\label{prop:gtop-axioms}
$J$ is a Grothendieck topology on $\mathcal{M}$:
\begin{enumerate}
    \item \textbf{Maximality:} The maximal sieve is covering.
    \item \textbf{Stability:} For any $g: N \to M_w$, the pullback $g^*S_{\mathrm{anc}}(M_w) = S_{\mathrm{anc}}(N)$.
    \item \textbf{Transitivity:} If $S$ covers $M_w$ and $R$ covers each $M_{w'}$ in $S$, the sieve generated by $\{f \circ g\}$ covers $M_w$.
\end{enumerate}
\end{proposition}
\begin{proof}
See \cite{maclanemoerdijk}*{II.1--2} for proof; the free structure ensures strict stability and transitivity.
\end{proof}

\begin{remark}
This topology is the canonical “ancestral” or “prefix” topology, strictly generated by sequence extension.
\end{remark}

\subsection{2.4. Sheaves, Gluing, and the Internal Logic of Paths}

\begin{definition}[Sheaf and Presheaf]\label{def:sheaf}
A \emph{presheaf} on $\mathcal{M}$ is a functor $F: \mathcal{M}^{op} \to \mathbf{Set}$. $F$ is a \emph{sheaf} for $J$ if, for every $M_w$ and every covering sieve $S_{\mathrm{anc}}(M_w)$, any compatible family of sections $(s_{w'}) \in \prod_{w' \prec w} F(M_{w'})$ (compatible on overlaps: for $w'' \prec w' \prec w$, $F(f_{w', w''}) s_{w'} = s_{w''}$) arises uniquely as the family of restrictions of a section $s \in F(M_w)$.
\end{definition}

\begin{example}[Sheaf Gluing over $M_2$]
Let $D = \{a, b\}$, $M_2 = (b, (a, M_0))$. The covering sieve includes morphisms from $M_0$ and $M_1^a$ to $M_2$. A compatible family $s_0 \in F(M_0)$, $s_1 \in F(M_1^a)$, compatible under restriction, determines a unique $s \in F(M_2)$ such that $F(f_{2,0})s = s_0$, $F(f_{2,1})s = s_1$.
\end{example}

\begin{proposition}[Sheaf Condition Holds]\label{prop:sheaf-condition}
The representable $yM_w$ is a sheaf for $J$, and every presheaf satisfying the gluing property is a sheaf.
\end{proposition}

\subsection{2.5. Subobject Lattices, Internal Heyting Algebra, and Logical Paths}

\begin{definition}[Subobject Lattice]\label{def:subobject-lattice}
For $M_w$ (with $w$ of length $n$), the set of ancestral sub-mnēmata $S(M_w) = \{M_{w'} : w' \prec w\}$, ordered by prefix, forms a finite chain.
\end{definition}

\begin{proposition}[Heyting Structure]\label{prop:heyting}
$(S(M_w), \subseteq)$ is a finite distributive lattice (a Heyting algebra), with
\begin{align*}
    M_{w'} \wedge M_{w''} &= \text{greatest common ancestor (longest common prefix)} \\
    M_{w'} \vee M_{w''} &= \text{least common descendant (shortest extension containing both)} \\
    M_{u} \to M_{v} &= \bigvee \{M_x \mid M_u \wedge M_x \leq M_v\}
\end{align*}
and negation $\neg M_{w'} = M_0$ for $M_{w'} \ne M_0$, $\neg M_0 = M_w$.
\end{proposition}
\begin{proof}
See \cite{daveypriestley}*{Ch.\ 5}, \cite{maclanemoerdijk}*{VI.7}; the path structure ensures distributivity, and implication is as in any finite chain.
\end{proof}

\begin{center}
\begin{tikzcd}[column sep=large]
& M_2^{ab} \\
M_1^a \ar[ur, "b"] & \\
M_0 \ar[u, "a"]
\end{tikzcd}

\textit{Figure 2.2. Chain of symbolic memory extensions realizing the Heyting lattice of $M_2^{ab}$ subobjects.}
\end{center}



\textbf{Remark.} This lattice is the subobject lattice of $yM_w$ in $\mathbf{Sh}(\mathcal{M})$ and models the internal propositional logic of symbolic memory.

\subsection{2.6. Strict Pullbacks and Pushouts in $\mathcal{M}$}

\begin{theorem}[\texorpdfstring{Pullbacks in $\mathcal{M}$}{Pullbacks in M}]\label{thm:strict-pullback}


Let $A = (d_A, X)$, $B = (d_B, X)$ with common base $X$. The pullback of $A \to X \leftarrow B$ is strictly $X$:
\[
\begin{tikzcd}
& X \ar[dl, "p_A"'] \ar[dr, "p_B"] & \\
A \ar[dr, "g_A"'] & & B \ar[dl, "g_B"] \\
& X &
\end{tikzcd}
\]
where $p_A$, $p_B$ are given by the unique morphisms corresponding to $(d_A)$, $(d_B)$, respectively.
\end{theorem}

\begin{theorem}[Pushouts in $\mathcal{M}$]\label{thm:strict-pushout}
Let $M \xrightarrow{(d_A)} A = (d_A, M)$, $M \xrightarrow{(d_B)} B = (d_B, M)$. The pushout is strictly
\[
C := (d_B, (d_A, M))
\]
with $j_A := (d_B): A \to C$, $j_B := (d_A): B \to C$.
\[
\begin{tikzcd}
& M \ar[dl, "(d_A)"'] \ar[dr, "(d_B)"] & \\
A \ar[dr, "(d_B)"'] & & B \ar[dl, "(d_A)"] \\
& C &
\end{tikzcd}
\]
\end{theorem}

\begin{proof}
Given any $Z$ with $k_A: A \to Z$, $k_B: B \to Z$ such that $k_A \circ (d_A) = k_B \circ (d_B)$, let $u: C \to Z$ be the unique morphism corresponding to extension by $(d_B, d_A)$ followed by the common morphism from $M$. Uniqueness is strict by Lemma~\ref{lem:unique-extension}. Commutativity follows by associativity of composition.
\end{proof}

\subsection{2.7. Uniqueness and Universality of the single generative rule}

\begin{theorem}[Uniqueness of Derivation from the Generative Axiom]
Let $\mathcal{T}$ be any category or topos whose structure is functorially generated from recursive application of a labeled unary operation $d \in D$ to a base object $M_0$, without additional generators or relations. Then $\mathcal{T}$ admits a unique (up to equivalence) functor from the category $\mathcal{M}$ defined by the Foundational Axiom.
\end{theorem}
\begin{proof}
This follows by the universal property of the free category on a unary $D$-signature. See also Proposition~\ref{prop:free-category}.
\end{proof}

\subsection{2.8. Comparative Positioning in the Categorical Landscape}

\textbf{Comparative Remark.} The category $\mathcal{M}$ differs fundamentally from other familiar categories:

- Unlike \textbf{simplicial} or \textbf{cubical} categories, $\mathcal{M}$ is not Reedy and has no degeneracy/face maps.
- Unlike \textbf{dendroidal categories} (\cite{moerdijkweiss2007dendroidal}), $\mathcal{M}$ encodes histories as \emph{linear or forked symbolic difference chains}, not operadic trees.
- Unlike \textbf{realizability categories}, $\mathcal{M}$ has no computational/partiality content; its combinatorics are strictly symbolic and recursive.
- Unlike the \textbf{Kripke categories} of modal logic, $\mathcal{M}$ is not built from arbitrary accessibility relations but from the free extension of difference labels.

In summary, $\mathcal{M}$ is a minimal, strict, and combinatorially explicit category whose universality and recursive structure underlie all subsequent topos-theoretic results—**all derived from a single generative axiom**.


\subsection{2.9. Formal Verification: Minimality, Smallness, and Yoneda Full Faithfulness}

\begin{lemma}[Minimality, Smallness, and Structural Soundness of $\mathcal{M}$]\label{lem:formal-verification}
Let $\mathcal{M}$ be the recursive difference category generated by the Foundational Axiom. Then:
\begin{enumerate}
    \item \textbf{Smallness and Combinatorial Explicitness.} $\mathcal{M}$ is a small category: its objects are in bijection with finite sequences (words) $w \in D^*$, and its morphisms are inclusively generated by prefix extension, giving at most one morphism between any pair of objects. Thus, both $\operatorname{Ob}(\mathcal{M})$ and $\operatorname{Mor}(\mathcal{M})$ are countable (if $D$ is countable) or of cardinality $|D|^{<\omega}$ otherwise, making $\mathcal{M}$ a concretely combinatorial category in the strict sense of \cite{leinster2014higher}.
    \item \textbf{Locally Finitely Generated.} For any pair $M_{w}, M_{v}$, the set $\Hom_{\mathcal{M}}(M_{w}, M_{v})$ is nonempty if and only if $M_{v}$ extends $M_{w}$ by a (finite) sequence $u$, i.e., $v = uw$ for some $u \in D^*$. Thus, every morphism factors uniquely as a finite chain of generating extensions, and the Hom-sets are either singleton or empty; $\mathcal{M}$ is locally finitely generated, in the sense that all morphisms are generated by (finite) iteration of the basic extension maps.
    \item \textbf{Full Faithfulness of Yoneda.} The Yoneda embedding $y: \mathcal{M} \hookrightarrow \widehat{\mathcal{M}} = [\mathcal{M}^{op}, \mathbf{Set}]$ is fully faithful: for any $M_{w}, M_{v}$,
    \[
      \Hom_{\mathcal{M}}(M_{w}, M_{v}) \cong \operatorname{Nat}(yM_{w}, yM_{v}),
    \]
    where $\operatorname{Nat}$ denotes natural transformations of functors. This follows by direct calculation:
    \begin{align*}
        \operatorname{Nat}(yM_{w}, yM_{v}) &\cong yM_{v}(M_{w}) \\
        &= 
        \begin{cases}
            \{\ast\} & \text{if $M_{w} \to M_{v}$ in $\mathcal{M}$ (i.e., $w \prec v$);} \\
            \varnothing & \text{otherwise.}
        \end{cases}
    \end{align*}
    This is the strict Yoneda Lemma. The fully faithfulness thus confirms that every structure and property of $\mathcal{M}$ is reflected in the presheaf topos, and all subsequent topos-theoretic or logical constructions (e.g., subobject lattices, sheaf conditions, modal operators) are *combinatorially determined* and faithfully preserved.
\end{enumerate}
\end{lemma}

\begin{proof}
\emph{(1) and (2):} Immediate from the explicit recursive definition (Def.~\ref{def:mnema-category}): objects are sequences $w \in D^*$; morphisms correspond to postfix extension. As no identification or additional relations are imposed, the set-theoretic sizes are explicit, and the category is both small and locally finitely generated.
\emph{(3):} The Yoneda Lemma (\cite{maclanemoerdijk}*{I.2}, \cite{leinster2014higher}, Ch.~1) applies verbatim, as every Hom-set is either singleton or empty, and representables preserve all combinatorial structure by construction.
\end{proof}

\begin{remark}
The minimality and explicit construction of $\mathcal{M}$ sharply contrasts with the far greater structural complexity of typical test categories (simplicial, cubical, dendroidal, etc.) and guarantees that all higher topos-theoretic and logical machinery is grounded in this transparent symbolic core.
\end{remark}

\section{The Canonical Topology of Ancestral Recursion: Sheaves on the Mnēmaic Site}

\subsection{3.1. The Ancestral Grothendieck Topology: Definition, Minimality, and Generating Properties}

Let $\mathcal{M}$ denote the recursively generated category of mnēmata, whose objects are finite sequences over $D$, with morphisms corresponding to difference-sequence extension (see Section~2). Our aim is to endow $\mathcal{M}$ with the \emph{minimal} Grothendieck topology whose sheaves encode the recursive ancestry logic of symbolic difference. In this precise sense, the topology constructed below is canonical for the entire internal logic and semantics that follow.

\begin{definition}[Ancestral Grothendieck Topology]\label{def:ancestral-topology}
For each object $M_w$ (where $w \in D^*$), the \emph{ancestral covering sieve} $S_{\mathrm{anc}}(M_w)$ is the set of all morphisms $f_v : M_{w'} \to M_w$ such that $w'$ is a prefix of $w$ (that is, $w = w' v$ for some $v \in D^*$). The \emph{ancestral Grothendieck topology} $J$ is the smallest topology for which $S_{\mathrm{anc}}(M_w)$ is a covering sieve for all $M_w$.
\end{definition}

\begin{proposition}[Minimality, Separation, and Generating Basis of $J$]\label{prop:ancestral-minimal}
The topology $J$ is the canonical coverage for $(\mathcal{M},J)$: it is the minimal Grothendieck topology such that, for each $M_w$, the family of all ancestral inclusions $M_{w'} \to M_w$ ($w'$ prefix of $w$) forms a basis of covering sieves. Any additional coverage would strictly add redundant structure.

Moreover, by \cite{maclanemoerdijk}*{II.2.6}, $J$ is generated by these ancestral sieves: any covering sieve for $J$ contains such a basis. Since representables are separated for $J$, the sieves $S_{\mathrm{anc}}(M_w)$ detect all distinctions needed for sheafification.
\end{proposition}

\begin{proof}
Suppose a Grothendieck topology $J'$ on $\mathcal{M}$ recognizes as covering a sieve $S$ on $M_w$ that does not contain all ancestral inclusions. Then the local data of recursive ancestry would fail to glue in $J'$—contradicting the goal of encoding precisely the ancestry logic. Thus, $J$ is minimal. That these sieves form a basis and generate $J$ in the sense of \cite{maclanemoerdijk}*{II.2.6} is by construction.

Since the representable presheaves $yM_{w'}$ are separated for $J$ (as in any canonical site), the ancestral sieves detect all possible distinctions in the structure; no finer or coarser coverage can serve for the purposes of internal logic and gluing. $\hfill\qed$
\end{proof}

\begin{remark}
This construction is analogous to the cellular sites of Joyal (\cite{joyal1977cellular}) and Johnstone’s “generating sites,” but with strictly symbolic, prefix-based ancestry in place of any simplicial or cubical face/degeneracy structure.
\end{remark}

\subsection{3.2. The Mnēmaic Sheaf Topos: Topos-Theoretic Properties}

\begin{definition}[Sheaf on the Mnēmaic Site]\label{def:sheaf2}
A presheaf $F: \mathcal{M}^{op} \to \mathbf{Set}$ is a \emph{sheaf} for $J$ if, for every $M_w$ and every covering sieve $S_{\mathrm{anc}}(M_w)$, any compatible family of local sections $\{ s_{w'} \in F(M_{w'}) : w' \prec w \}$ (compatible under all further restriction maps) arises uniquely from a global section $s \in F(M_w)$ whose restrictions are $s_{w'}$.
\end{definition}

\begin{proposition}[Grothendieck Topos Structure]\label{prop:topos-properties}
The category $\mathbf{Sh}(\mathcal{M})$ of sheaves for $J$ is a Grothendieck topos: it possesses all finite limits and colimits, exponentials, a subobject classifier, and supports full higher-order intuitionistic logic.

\emph{Reference:} This follows directly from the standard theorem for sheaf topoi on a site (\cite{maclanemoerdijk}, Theorem II.2.6).
\end{proposition}

\begin{remark}
The internal logic, modal operators, and topological semantics of $\mathbf{Sh}(\mathcal{M})$ are thus inherited immediately from the universal theory of Grothendieck topoi.
\end{remark}

\subsection{3.3. Visualization, Gluing, and Lattice Structure}

\paragraph{Example (Covering and Gluing).}
Let $D = \{a, b\}$ and $M_{(a, b)}$. The ancestral subobjects are $M_0$, $M_{(a)}$, $M_{(a, b)}$; covering sieves correspond to all ancestral inclusions $M_{w'} \to M_{(a, b)}$ with $w'$ a prefix of $(a, b)$. For the representable sheaf $yM_{(a, b)}$, the subobject lattice is:

\[
M_0 \subseteq M_{(a)} \subseteq M_{(a, b)}
\]

—a chain of length 3 (a finite Heyting algebra).

\begin{center}
\begin{tikzcd}[row sep=2.2em, column sep=2.2em]
M_0 \ar[r, "a"] \ar[dr, "b"'] & M_{(a)} \ar[r, "b"] & M_{(a, b)} \\
 & M_{(b)} \ar[ur, "a"'] &
\end{tikzcd}
\end{center}
\emph{Figure 3.1. Gluing over ancestral covers: every compatible family along the ancestry tree uniquely determines a global section.}

\subsection{3.4. Logical Interpretation, Canonical Sheafification, and Outlook}

\begin{theorem}[Canonical Sheafification and Internal Logic]\label{thm:minimal-sheafification}
The sheafification functor $\mathrm{Sh}(\mathcal{M})$ for the topology $J$ is minimal and canonical: it imposes only those identifications required by the ancestry relations. The subobject lattices $\Sub(yM_w)$ are distributive Heyting algebras; Boolean logic emerges precisely at objects admitting nontrivial forking (see Section~4).
\end{theorem}

\begin{proof}
Immediate from the minimality of $J$ and the universal properties of sheafification. By \cite{maclanemoerdijk}*{II.2.6, VI.7}, the topos structure and Heyting property follow from canonical sheafification over $J$.
\end{proof}

\begin{remark}
This minimal site underlies the universality of the modal closure operators (Lawvere–Tierney topologies) that will be classified in Section~5: every such operator corresponds to a submonoid of difference-sequences compatible with $J$, confirming that $J$ indeed forms the foundation for the full internal modal logic of the framework.
\end{remark}

\subsection{3.5. Summary and Forward Link}

The ancestral topology $J$ is both necessary and sufficient to encode the full recursive ancestry logic of symbolic memory. The resulting sheaf topos is the minimal, universal environment for the internal logic, modal operators, and all subsequent categorical and logical constructions of this framework.

