\section{\texorpdfstring{Modal Fixed-Point Logic and the Infinite-Branching $\mu$-Calculus}{Modal Fixed-Point Logic and the Infinite-Branching mu-Calculus}}


\subsection{6.1. Internal $\mu$-Calculus: Syntax and Sheaf-Theoretic Semantics}

The internal modal logic of $\mathbf{Sh}(\mathcal{M})$, based on modalities $\{\Box_d\}_{d \in D}$ (see Section~4), admits a natural extension to the modal $\mu$-calculus, enabled by the completeness and distributivity of the subobject lattices $\Sub(yM)$.

\begin{definition}[Internal Modal $\mu$-Calculus Formulas]
Let $D$ be any set (finite or infinite). The formulas $\varphi$ are generated inductively by
\[
\varphi ::= \top \mid \bot \mid \varphi_1 \wedge \varphi_2 \mid \varphi_1 \vee \varphi_2 \mid \Box_d \varphi \mid \Diamond_d \varphi \mid X \mid \mu X.\varphi(X) \mid \nu X.\varphi(X)
\]
where $d \in D$, $X$ is a fixpoint variable, and $\varphi(X)$ is positive in $X$.
\end{definition}

\begin{definition}[Sheaf-Theoretic Semantics of Fixpoints]
For any representable $yM$:
\begin{align*}
\llbracket \mu X.\varphi(X) \rrbracket_M &= \bigwedge \{S \subseteq yM \mid \llbracket \varphi(S) \rrbracket_M \subseteq S\}, \\
\llbracket \nu X.\varphi(X) \rrbracket_M &= \bigvee \{S \subseteq yM \mid S \subseteq \llbracket \varphi(S) \rrbracket_M\},
\end{align*}
where $S$ ranges over subobjects of $yM$ and meets/joins are computed in the complete Heyting algebra $\Sub(yM)$. (See Kozen~\cite{kozen1983results}, Bekič~\cite{bekic1984programming} for lattice-theoretic foundations.)
\end{definition}

\begin{remark}
By the completeness of $\mathbf{Sh}(\mathcal{M})$ and Lawvere’s adjunction~\cite{lawvere1969adjointness}, every monotone operator on subobjects admits well-defined least and greatest fixed points, interpreted internally as objects in the topos (cf.\ \cite{maclanemoerdijk}*{VI.7}, Section~3).
\end{remark}

\subsection{6.2. Tree-Unfolding, Bisimulation, and Invariance}

A central structural property of $\mathcal{M}$ is **tree-unfolding**: every object $M_w$ embeds into the infinite $D$-branching rooted tree, and every path can be extended indefinitely by difference labels (see Section~2). This guarantees that the semantic universe of $\mathbf{Sh}(\mathcal{M})$ encompasses all pointed infinite $D$-trees, matching the classical setting of Janin–Walukiewicz~\cite{janin1995expressive}.

\begin{definition}[Categorical Bisimulation in $\mathcal{M}$]
A bisimulation between objects $M, N$ is a span $R \subseteq \Hom_{\mathcal{M}}(-,M) \times \Hom_{\mathcal{M}}(-,N)$ such that for every $d \in D$ and $(f,g) \in R$:
\begin{itemize}
    \item Whenever $f \xrightarrow{d} f'$ exists, there is $g \xrightarrow{d} g'$ with $(f',g') \in R$,
    \item Symmetrically for $g \xrightarrow{d} g'$.
\end{itemize}
\end{definition}

\begin{definition}[Bisimulation-Invariant Subobjects]
A subobject $A \hookrightarrow yM_0$ is \emph{bisimulation-invariant} if for any $f: N \to M_0$ and $g: N' \to M_0$ related by a bisimulation, $f$ factors through $A(N)$ if and only if $g$ does through $A(N')$.
\end{definition}

\begin{remark}
This matches the classical notion of invariance under tree automorphisms and is preserved under all modal and fixed-point operations (see \cite{johnstone1982stone}, \cite{jacobs1999categorical}).
\end{remark}

\subsection{6.3. Janin–Walukiewicz Theorem: Infinite-Branching Generalization}

\begin{theorem}[Janin–Walukiewicz Expressive Completeness (Infinite-Branching)]
Let $D$ be any set (finite or infinite). In $\mathbf{Sh}(\mathcal{M})$, every bisimulation-invariant subobject $A \hookrightarrow yM_0$ is definable by an internal modal $\mu$-calculus formula over $\{\Box_d : d \in D\}$, and conversely.
\end{theorem}

\begin{proof}[Proof Sketch]
As $\mathcal{M}$ is freely generated by labeled unary extensions (see Section~2) and has the tree-unfolding property, every $M_0$-rooted subtree of $D^\omega$ is realized as an object in $\mathbf{Sh}(\mathcal{M})$.

Given any bisimulation-invariant subobject $A \hookrightarrow yM_0$, by the classical method of Janin–Walukiewicz~\cite{janin1995expressive}, one constructs a monotone modal operator whose least (or greatest) fixed point coincides with $A$—using automata-theoretic arguments on infinite $D$-trees. Completeness of $\mathbf{Sh}(\mathcal{M})$ ensures all required joins and meets exist (see \cite{maclanemoerdijk}*{VI.7}, Kozen~\cite{kozen1983results}). The external fixed points are reflected internally by Lawvere’s adjunction~\cite{lawvere1969adjointness}.

Conversely, any modal $\mu$-calculus formula yields a subobject invariant under bisimulation, since the modal operations and fixed points commute with tree automorphisms by construction.
\end{proof}

\begin{remark}
This result extends Janin–Walukiewicz~\cite{janin1995expressive} beyond the finite-branching case, relying on the *intrinsic tree-unfolding* of $\mathcal{M}$ and the spatiality of $\mathbf{Sh}(\mathcal{M})$ (see Section~5).
\end{remark}

\subsection{6.4. Examples of Modal Fixed-Point Properties}

\begin{example}[Eventuality via Least Fixed Point]
Given a property $P \subseteq yM_0$, the formula
\[
\varphi = \mu X.\ P \vee \bigvee_{d \in D} \Diamond_d X
\]
defines the subobject of $D^\omega$-streams where $P$ holds at some prefix.
\end{example}

\begin{example}[Persistence via Greatest Fixed Point]
The formula
\[
\psi = \nu X.\ P \wedge \bigwedge_{d \in D} \Box_d X
\]
defines the subobject of streams where $P$ holds at every prefix.
\end{example}

