\section*{Appendix: Formal Foundations of the Mnēmaic Topos}

\subsection*{A.1. $\mathcal{M}$ as the Free Difference‐Generated Category}

\paragraph{Signature and Presentation.}  
Let $D$ be a set of \emph{difference labels}.  Consider the \emph{graph} with a single vertex $M_0$ and, for each $d\in D$, a loop‐edge $M_0\xrightarrow{d}M_0$.  The free category on this graph is the category whose objects are finite words $w\in D^*$ and whose morphisms $w\to w'$ are precisely those pairs satisfying $w' = vw$ for some $v\in D^*$.  Relabel each object $w$ as the mnēma $M_w := (w,M_0)$ and each morphism $v\colon w\to vw$ as the extension $f_v\colon M_w\to M_{vw}$.  

\paragraph{Universal Property.}  
For any category $\mathcal{C}$ equipped with an object $X\in\mathcal{C}$ and, for each $d\in D$, a chosen morphism $d_X:X\to X$, there is a unique functor 
\[
  F\colon \mathcal{M}\to\mathcal{C}
\]
sending $M_0\mapsto X$ and each generator $f_d\colon M_0\to M_d$ to $d_X$.  By induction, $F(M_w)=X$ and $F(f_v)=d_{i_k}\circ\cdots\circ d_{i_1}$ for $v=(d_{i_k}\cdots d_{i_1})$.  This establishes that $\mathcal{M}$ is \emph{initial} among $D$‐difference‐generated categories.

\subsection*{A.2. Verification of the Grothendieck Topology Axioms}

Recall the ancestral covering sieve on $M_w$ is
\[
  S_{\mathrm{anc}}(M_w)
  \;=\;
  \{\,f_v\colon M_{w'}\to M_w \mid w' \text{ prefix of }w,\; w=vw'\}.
\]
We check the three Grothendieck axioms:

\begin{enumerate}[label=(\arabic*)]
  \item \emph{Maximality:} The maximal sieve on $M_w$ contains every morphism, in particular all of $S_{\mathrm{anc}}(M_w)$, so it is covering by definition.

  \item \emph{Stability under pullback:}  
    Given $g\colon N\to M_w$, say $N=M_u$ and $g=f_v$ (so $w=vu$).  Then
    \[
      g^*S_{\mathrm{anc}}(M_w)
      =\{\,h\colon P\to N\mid g\circ h\in S_{\mathrm{anc}}(M_w)\}.
    \]
    But $g\circ h=f_{v}\circ f_{v'}=f_{vv'}$, and $f_{vv'}\in S_{\mathrm{anc}}(M_w)$ exactly when $vv'$ is the prefix factor of $w$, i.e.\ when $v'$ prefixes $u$.  Hence 
    \[
      g^*S_{\mathrm{anc}}(M_w)
      = S_{\mathrm{anc}}(N),
    \]
    which is covering.

  \item \emph{Transitivity:}  
    Suppose $S\subseteq\Hom(-,M_w)$ covers $M_w$, so $S_{\mathrm{anc}}(M_w)\subseteq S$.  For each $f\in S$, let $R_f\subseteq\Hom(-,\dom f)$ cover $\dom f$.  The sieve generated by compositions $\{f\circ h\mid f\in S,\;h\in R_f\}$ contains all ancestral maps $M_{w'}\to M_w$, since each $M_{w'}$ prefixes $M_w$ by definition.  Hence it also covers $M_w$.
\end{enumerate}

Thus $J$ is a Grothendieck topology on $\mathcal{M}$.

\subsection*{A.3. Sketch of Internal Logic Completeness}

\paragraph{1. Existence of the Subobject Classifier.}  
By Proposition~3.2 and Theorem II.7.2 of Mac Lane–Moerdijk~\cite{maclanemoerdijk}, $\mathbf{Sh}(\mathcal{M})$ has a subobject classifier $\Omega$ whose sections at $M_w$ are precisely sieves on $M_w$.  

\paragraph{2. Internal Heyting Algebra Structure.}  
Each representable $yM_w$ has $\Sub(yM_w)\cong\mathsf{Pref}(w)$ (a finite distributive lattice).  Finite limits, unions, and exponentials in the topos induce meet, join, and implication, yielding a Heyting algebra per standard topos‐logic correspondence (Johnstone~\cite{johnstone1982stone}, Ch.~1).

\paragraph{3. Modal Closure via Lawvere–Tierney Topologies.}  
Each submonoid $S\subseteq D^*$ yields a Lawvere–Tierney topology $j_S:\Omega\to\Omega$ (Section~5.1), whose associated modal operator $\Box_S$ preserves finite meets and interacts with the Heyting structure as per Jacobs~\cite{jacobs1999categorical}.

\paragraph{4. Fixed‐Point Completeness.}  
Since $\Sub(yM_w)$ is a complete lattice (arbitrary joins exist as colimits of subobjects), every monotone endomap admits $\mu$ and $\nu$ fixpoints externally, and by the adjoint‐fixpoint lemma (Lawvere 1969~\cite{lawvere1969adjointness}) these are respected internally.  Hence the full internal $\mu$‐calculus is interpretable.

