\begin{appendices}
\section{Appendix 1: Algorithm }

\begin{algorithm}[ht]
\begin{algorithmic}[1]
\Require Positions of sensors $[\alpha_i, \lambda_i]$, range $[\rho]$, Earth radius $[R_e]$, LEO bounds $[R_{\text{max}]}$ and $[R_{\text{min}}]$, sensor angles $[\alpha]$

\Ensure Number of sensors $n\geq 2$

\State Initialize $V = 0$\label{appendix:Algorithm1}
\For{each sensor pair $i$ and $j$ where $i \neq j$}
    \State Compute distance $d \gets \text{Euclidean Distance}(\textit{Sensor Positions}[i], \textit{Sensor Positions}[j])$
    \If{$2 \rho > d$ and $H > (R_{max}-R_e + \Delta h)$}
        \State Make cluster of sensors for a $i$ which k sensors are overlapping.
        \State If both satisfy, compute lower  elevation angle of  each sensor j in the cluster:
        \[
        E_{\text{min}_j} = \sin^{-1} \left( \frac{R_{\text{min}}^2 - R_e^2 - \rho^2}{2 R_e \rho} \right) + \frac{\alpha_j}{2}\] 
        \State Compute upper elevation angle of each sensor j in the cluster:
        \[E_{\text{max}_j}  = \sin^{-1} \left( \frac{R_{\text{max}}^2 - R_e^2 - \rho^2}{2 R_e \rho} \right) - \frac{\alpha_j}{2}\]

        \State Compute overlapping volume:
        \[
        v(\alpha_i) = 2\pi \left[\frac{(R_{max}-R_e)^3 - (R_{min}-R_e)^3}{3}\right] \ sin \left(\frac{\alpha_i}{2}\right) \ sin (E_i)
        \]
        \State Compute \[\delta(\phi_i,A_i,E_i)=\delta({\phi_e})=\frac{3}{{\sqrt{2}\pi^2}(R_{max}^3 - R_{min}^3)} \sum_{i=0}^k \frac{N_i}{\sqrt{cos(2\phi_e)- cos(2\iota_i)}}\]
         \EndIf
         \State Calculate minimum of $v(\alpha_i)$
        \State Apply $E_{min_i}$ \& $E_{max_i}$ as bounds for solving optimisation problem
    \EndFor
        \State $A^*_{1 : M},E^*_{1 : M} = \underset{A_{1:M},E_{1:M}}{\arg} \max \  \mathcal{O}_{N_i} = \underset{A_{1:M},E_{1:M}}{\arg} \max \  \sum_{i=1}^M v(\alpha_i) \delta({\phi_i, A_i, E_i})$

\Return $\mathcal{O}_{N_i}$
\end{algorithmic}
\end{algorithm}
\end{appendices}




