      \strng{authorfullhash}{b83ef21b90380cd24b30aa20fab0b692}
      \field{sortinit}{3}
      \field{sortinithash}{ad6fe7482ffbd7b9f99c9e8b5dccd3d7}
      \field{labelnamesource}{author}
      \field{labeltitlesource}{title}
      \field{abstract}{“The car is the ultimate mobile device” [1] and with its connectivity and a large number [2] of sensors and actuators an example for a cyber-physical system. The advantages of a service-oriented architecture (SOA) are shown in comparison to the classic signal-oriented design. A hybrid architecture which contains both static signal- and dynamic service-oriented elements is introduced. With an example we show how the benefits of a SOA can be achieved, even without migrating the whole vehicle away from the current static communication schemes. The “SuperTuxKart” application integrated into the Mercedes CLA as presented by Daimler on the Mobile World Congress 2019 [3] is an additional customer value application and used as our showcase. Its development and implementation can be greatly simplified if the target vehicle has an electric/electronic architecture, which is service-oriented. We introduce a new process to develop an application within a service-oriented vehicle and use software over the air (SOTA) updates to deploy it. The process is illustrated using a fictive, service-based application.}
      \field{booktitle}{2020 9th {Mediterranean} {Conference} on {Embedded} {Computing} ({MECO})}
      \field{month}{6}
      \field{title}{Development {Processes} in {Automotive} {Service}-oriented {Architectures}}
      \field{year}{2020}
      \field{pages}{1\bibrangedash 7}
      \range{pages}{7}
      \keyw{Hybrid Architecture,Network Design,Service-oriented Architecture,Software Over The Air}
    \endentry
