\subsubsection{Network Topologies}

\begin{figure}[]
    \centering
    \includegraphics[width=0.47\textwidth]{figures/NetworkTopologies.pdf}
    \caption{Illustration of all network configurations. Black rectangles denote sending applications, while grey rectangles indicate receiving applications. Arrows represent directed communication between applications.}
