\begin{document}
\title{Quantizing for Noisy Flash Memory Channels} 

\author{%
  \IEEEauthorblockN{Juyun Oh\textsuperscript{*}, Taewoo Park\textsuperscript{*}, Jiwoong Im\textsuperscript{*}, Yuval Cassuto\textsuperscript{†}, and Yongjune Kim\textsuperscript{*}}
