\section{Proof of Proposition~\ref{prop:verify}}\label{pf:prop_verify}

    The MSE can be expressed as follows:
    \begin{align}
    &\mathbb{E}_{X,\widehat{X}}[(X-\widehat{X})^2]  \nonumber \\
    &= \mathbb{E}_{Y,\widehat{X}}[\mathbb{E}_{X}[(X-\widehat{X})^2|Y,\widehat{X}]]  \nonumber \\
    \label{eqn:appendix1}
    &=\mathbb{E}_{Y,\widehat{X}}\left[\mathbb{E}_{X}[(X-\mathbb{E}[X|Y])^2|Y]+(\mathbb{E}[X|Y]-\widehat{X})^2\right] \nonumber \\
    &=\mathbb E_{X,Y}\left[(X-\mathbb E[X|Y])^2\right]\nonumber
    \\
    &\quad +\sum_{i=1}^{M}\sum_{j=1}^{M}p_{Y,\widehat X}(v_i,v_j)\left(\mathbb E[X|Y=v_i]-v_j\right)^2,
    \end{align}
    where $\mathbb E[X|Y=v_{i}] = \widetilde{v}_i$ by \eqref{eq:v_tilde}. Hence, $(\mathbb E[X|Y=v_i]-v_j)^2$ can be replaced with $\gamma_{i,j} = \left(\widetilde{v}_i-v_j\right)^2$ for $i,j\geq1$. 
    In \eqref{eqn:appendix1}, the first term is independent of optimizing the verify levels. 
    Consequently, we focus on the second term, which explicitly accounts for the channel errors. 
    The second term can be reformulated as follows:
    \begin{align}
    &\sum_{i=1}^{M}\sum_{j=1}^{M}p_{Y,\widehat X}(v_i,v_j)\left(\widetilde{v}_i - v_j\right)^2 \nonumber
    \\&=\sum_{i=1}^{M}p_Y(v_i)\sum_{j=1}^{M}p_{\widehat{X}|Y}(v_j|v_i)\left( \widetilde{v}_i - v_j\right)^2  \label{eqn:appendix 2}\\
    & \approx \sum_{i=1}^{M-1}     p_Y(v_{i}) P_{i,i+1} \cdot \gamma_{i,i+1}+p_Y(v_{i+1}) P_{i+1,i}\cdot \gamma_{i+1,i}   \label{eq:appendix_3}
    \\
    &\approx  
    \sum_{i=1}^{M-1}\bigg\{p(s_{i}) Q\left(\frac{\Delta_{i,i+1}}{\sigma_i}\right)\gamma_{i,i+1}  \nonumber \\
    & \quad +  p(s_{i+1})Q\left(\frac{\Delta_{i+1,i} }{\sigma_{i+1}}\right)\gamma_{i+1,i}  \bigg\} \label{eq:appendix_4},
    \end{align}
     where \eqref{eq:appendix_3} follows from the tridiagonal channel transition matrix, with the assumption that $\gamma_{i,i} \ll 1$. 
    Finally, \eqref{eq:appendix_4} follows from $p_Y(v_{i}) = p_S(s_i)$, \eqref{eq:transition_prob_1}, and \eqref{eq:transition_prob_2}.

    Note that \eqref{eq:appendix_4} is convex with respect to $\mathbf{\Delta}$ since $Q(\cdot)$ is a convex function and the coefficients are nonnegative. 


