\begin{df}
  Let $\mu_1,\mu_2$ be two interactions at \Nho names. We say that
  % For to actions $\mu_1,\mu_2$, we set
  \emph{$\mu_1$ justifies $\mu_2$}, noted
  $\mu_1 \justif \mu_2$,
  if:
  $(i)$ either $\mu_1 = \inpA{a}{v}{b}$ and $\mu_2 = \out{b}{v'}{c}$,
 or $(ii)$ $\mu_1 = \out{a}{v}{b}$ and $\mu_2 = \inpA{b}{v'}{c}$.
  % \begin{itemize}
  % \item either $\mu_1 = \inpACT{a}{n,b}$ and $\mu_2 = \out{b}{m}{c}$,
  % \item or $\mu_1 = \out{a}{n}{b}$ and $\mu_2 = \inpACT{b}{m,c}$.
  % \end{itemize}
  When this is not the case, we write $\mu_1\njustif\mu_2$.
\end{df}
$\mu_1\justif\mu_2$ captures the dependency induced by the fact that
$\mu_2$ performs an interaction at a name that has been previously
introduced by $\mu_1$. In contrast with the situation in game
semantics, though, there is no notion of question and answer in our
setting.

We can now define the notion of view.
%
% We say that a trace $\mu_1\ldots\mu_n$ is \emph{fresh} if for all $i$, if
% $\mu_i$ is $\inpA anb$ or $\out anb$, then $b$ does not occur in
% $\mu_j$ for any $j<i$.
% We can always suppose, w.l.o.g., that traces are fresh; we will do so
% implicitly below.
%
In the definition below, we allow a starting
visibility \Vset,  because we want to consider processes that
already have some knowledge about the observer (Opponent).  


\begin{df}[View]\label{d:view}
  Given % a trace $\trace$ and
  $\Vset\subseteq
  \Nho$, we define the \emph{view with starting visibility $\Vset$ of
    a
%    fresh
    trace \trace}, written
  \view\Vset\trace, as follows:
    \begin{mathpar}
  \mathtt{view}_\Vset(\varepsilon) = \Vset
  \and
   \mathtt{view}_\Vset(\trace_1\mu_1\trace_2\mu_2 )=
    \mathtt{view}_\Vset(\trace_1)\cup
    \fNho{\mu_1} \cup \fNho{\mu_2}
%    \bnames{\mu_1}\cup\bnames{\mu_2}
%    \mathtt{bn}(\mu_i,\mu_n)
    \text{ if } {\mu_1}\justif{\mu_2}
    \and
     \mathtt{view}_\Vset(\mu_0\dots\mu_n) = \Vset\cup \fNho{\mu_n}
%    \bnames{\mu_n}
    \text{ if } \forall 0\leq i\leq n-1, {\mu_i}\njustif{\mu_n} 
    \end{mathpar}
    where $\fNho{\mu}$ denotes the set of higher-order names appearing
  in the action $\mu$.
\end{df}


Views capture the idea % of visibility is
that when an action is justified by another
one, the names created in between % the two actions
must have been forgotten,
otherwise this would mean that the process had the ability to store these
names in order to reuse them.
% acces to some
% higher-order store to be able to use these names.
%
In the last clause in Definition~\ref{d:view},
%corresponds to the case where
the action is justified by an action that happened before the
beginning of the trace, therefore it has
the starting visibility.
%
In particular, \view\emptyset\trace{} yields
%Notice that if we instantiate the view with $\Vset=\emptyset$ we get
the usual definition in game semantics. 
\begin{df}[Respecting views]\label{d:respect:view}
  Consider $\Vset\subseteq \Nho$, a trace $(\mu_0\dots\mu_n)$ \emph{respect views under starting visibility }$\Vset$ if $\mathtt{fn}(\mu_0) \subseteq \Vset$ and $\forall 1\leq i\leq n, \mathtt{fn}(\mu_i)\subseteq \mathtt{view}_\Vset(\mu_0\dots\mu_{i-1})$
\end{df}
\begin{lm}\label{l:view}
  Consider $\vfpl,\vfopp,P$ such that $\typ{\vfpl}{P}$, $\vfopp$ is
  compatible with $\vfpl$, and $\vfpl \cup \vfopp$ is
  transitive. Let $\Vset=(\vfopp \cup \vfpl)(\cur)$, 
  then every
  trace of $P$ under visibility $\vfopp$ respects views with starting
  visibility \Vset.
\end{lm}

The idea of the proof is that for a trace $(\mu_0\dots\mu_n)$ there
exist $P_0,\dots,P_{n+1}$, $\vfpl[_0],\dots,\vfpl[_{n}]$,
$\vfopp[_0],\dots,\vfopp[_{n+1}]$ such that $P_0 = P$, $\vfpl[_0] =
\vfpl$, $\vfopp[_0] = \vfopp$ and for all $0\leq i \leq n$,
$\typtrans{\vfopp[_i]}{P_i}{\mu_i}{\vfopp[_{i+1}]}{P_{i+1}}$ and
$\vfpl[_i] \vdash P_i$.
%
We show by induction that for each $1\leq i \leq n$, $(\vfopp_i \cup
\vfpl_i)(\cur) \subseteq \mathtt{view}_\Vset(\mu_0\dots \mu_{i-1})$; it thus
 follows that the trace respects views under starting visibility
\Vset. The condition of $\vfpl\cup \vfopp$ being transitive is crucial, otherwise $(\vfopp_i \cup \vfpl_i) (\cur)$ could grow in unwanted ways.


