\begin{enumerate}
	\item $\inter{\emptyset}{\emptyset}{\emptyset}$
	\item\label{inter:deux} $\inter{\Tag{p}{\OO},\sigma_1}{\sigma_2}
          {\Tag{p}{\OO},\sigma_3}$ if $\inter{\sigma_1}{\sigma_2}{\sigma_3}$
	\item\label{inter:trois} $\inter{\Tag{p}{\OO},\sigma_1}{\Tag{p}{\OO},\sigma_2}{\sigma_3}$ if $\inter{\sigma_1}{\sigma_2}{\sigma_3}$
	\item the same as~(\ref{inter:deux}) and~(\ref{inter:trois})
          with $\Tag{p}{\II}$ instead of $\Tag p\OO$
\end{enumerate}
