\begin{thm}[Subject reduction]\label{t:SR:wb}
  % Consider $\vfpl,\stack, P, P'$ such that
  Suppose $\typ{\typpl{\vfpl}{\stack}}{ P}$ and
  $P\xrightarrow{\mu}P'$. We have:
  \begin{itemize}
  \item if $\mu = \tau$, then either $\stack =
    \co{p},\ci{p},\stack['']$ with $p\in \mathtt{Ncon}\setminus
    \fnames{P'}$, in which case $\typ{\typpl{\resmin{\vfpl}{p}}{\stack['']}}{P'}$,

    or
    % otherwise if $\mu = \tau$ then
    $\typ{\typpl{\vfpl}{\stack}}{P'}$ ;
  \item if $\mu = \out{a}{v}{b,p}$ then $a\in \vfpl(\cur)$ and
    $\typ{\typpl{\resmin\vfpl\cur\cons b\arr \vfpl(\cur),b\cons p\arr
        \vfpl(\cur),b}{\ci{p},\stack}}{P'}$ ;
  \item if $\mu=\out{p}{v}{b}$ then $\stack = \co{p},\stack['']$,
    $p\in \vfpl(\cur)$ and $\typ{\typpl{\resmin\vfpl\cur\cons b\arr
        \vfpl(\cur),b}{ \stack['']}}{P'}$ ;
  \item if $\mu=\inpA{a}{v}{b,p}$
    and $\vfpl\NOTinDom\cur$
    then $\typ{\typpl{ \vfpl \cons
        \cur\arr \vfpl(a),b,p}{\co{p},\stack}}{P'}$ ;
  \item if $\mu = \inpA{p}{v}{b}$
        and $\vfpl\NOTinDom\cur$
        then $\stack =
    \ci{p},\co{q},\stack['']$ and $\typ{\typpl{\resmin{\vfpl}{p} \cons
        \cur \arr \vfpl(p),b}{\co{q},\stack['']}}{P'}$ ;
  \item if $\mu = \inpACT hv$ or %then $\typ{\typpl{\vfpl}{\stack}}{P'}$
%  \item if
    ($\mu = \out{h}{v}{}$
         and $\vfpl\NOTinDom\cur$)
    then $\typ{\typpl{ \vfpl}{\stack}}{P'}$.
  \end{itemize}
\end{thm}

% The following lemma uses the definitions of traces and well-bracketed
% traces of section IV.C of \cite{Hirschkoff_2021}.

As previously, we have to define compatibility of typing environments so to be able
to use the contextual forms of behavioural equivalence from
Section~\ref{s:lang}.  

\begin{df}
%  Two typing environments
  $\typpl{\vfpl[_1]}{\stack_1}$ and
  $\typpl{\vfpl[_2]}{\stack_2}$ are compatible
  if $\ser{(\vfpl[_1]\cap \vfpl[_2])}$
  % if $\vfpl[_1]$ and
  % $\vfpl[_2]$ are compatible
  and $\mathtt{inter}(\stack[_1],
  \stack[_2]) \neq \emptyset$. 
\end{df} % \iwan{moved this definition here because it is needed for the next lemma}

\begin{ex}
\label{ex:INC}
Consider the process
\[
P\defi
\res h (
\begin{array}[t]{l}
 \outDS h 5 | \\
 \boutDS {a} {b,q} .  ( 
\begin{array}[t]{l}
 ! b(p). h(x). (\outDS h{x+1}.\nil| \outC p.\nil)  |  \\
 q. h(x). \outDS h{x} .   \boutDS c {d,r}. r .  h(y). \outDS h{y} . 
\ifte
%\ifthenNEG 
  x y  {\outC s .\nil} \nilact %{{\rm Div}}
  ))
\end{array} 
\end{array} 
 \]
Here $h$ is used as an integer reference, initially set to $5$.
The process calls a service $a$, giving access to a name $b$ that can be used to
increment the reference.  When the call at $a$  returns (at $q$),
the
reference is read twice and, in between, 
a call at $c$ is made. Without visibility, the two values read for $h$ might be
different: as $b$ has been exported, the environment could freely use $b$ and increment
the reference in between the two reads.  
Visibility ensures us that, when the initial call at $a$ is returned, name $b$ is
`forgotten'  by the environment, which cannot therefore use it anymore.    
Thus, if $Q$ is  the process defined like $P$ but with the last line replaced with 
 $q.   \boutDS c {d,r}. r . \outC s.\nil$, then we have $P  \conteqNOtype Q$. 
We refer to Appendix~\ref{a:reentrant:call} for an ML-like
presentation of the example above,  as well as for a longer example,
also showing how re-entrant calls may sometimes 
make  visibility boundaries hard to predict. 
\end{ex} 



