  % \end{array}
  % \right\}\]
\end{df}
\begin{lm}[Extension]
  \label{l:tr_ext}
   Consider $\vfpl,\vfopp,\vfopp['],P,Q$ such that
   $\mathtt{proj}(\fnames{\vfopp,P,Q},\vfopp[']) = \vfopp$ and $\vfpl$ and $\vfopp[']$ are compatible. If
   $P \trEqV{\vfpl}{\vfopp} Q$ then
   $P \trEqV{\vfpl}{\vfopp[']} Q$. 
 \end{lm}

In the statement above, $\fnames{\vfopp,P,Q}$ stands for the union of
all names mentioned in $\vfopp$, together with the names occurring free
in $P$ and $Q$.

\subsection{Pruning Processes using Types}
%{Section~\ref{s:labels}: detecting dead code using visibility}
\label{a:deadcode}

Consider a visibility function $\vfpl$ and
$S \subseteq \Nho$. 
We write \meets\alpha S when $\alpha$ is an input of the form $a(x,b)$
and either $a\in S$ or ($a\in\dom\vfpl$ and $\vfpl(a)\cap
S\neq\emptyset$).


We define
inductively the pruning function on processes that removes
all instances of the names in $S$ as follows: 
\begin{mathpar}
  \prune{S}{\vfpl}{\alpha. P} =
  \begin{cases}
    \nil \text{ if } \meets\alpha S\\
    \alpha. \prune{S}{\vfpl}{P} \text{ otherwise }
  \end{cases} %\hspace{2em}

  \prune{S}{\vfpl}{!\alpha. P} =
  \begin{cases}
    \nil \text{ if } \meets\alpha S\\
    !\alpha. \prune{S}{\vfpl}{P} \text{ otherwise }
  \end{cases}

  \prune{S}{\vfpl}{\out{\alpha}{}{}.P} =
  \out{\alpha}{}{}. \prune{S}{\vfpl}{P}

  \prune{S}{\vfpl}{\new a\ P} = \new a\  \prune{S}{\vfpl}{P}

  \prune{S}{\vfpl}{\new h\ P} = \new h\
  \prune{S}{\vfpl}{P}

  \prune{S}{\vfpl}{P|Q} = \prune{S}{\vfpl}{P} | \prune{S}{\vfpl}{Q}

  \prune{S}{\vfpl}{P+Q} =
  \prune{S}{\vfpl}{P} +\prune{S}{\vfpl}{Q}

  \prune{S}{\vfpl}{\nil} = \nil

  \prune{S}{\vfpl}{\omega} =
  \omega

  \prune{S}{\vfpl}{\ifte efPQ} =
    \ifte{e}{f}{\prune{S}{\vfpl}{P}}{\prune{S}{\vfpl}{Q}}

\end{mathpar}

\begin{lm}[Pruning]
  \label{lm:garbage_coll}
  Let $\vfopp, \vfpl,P$ such $\typ{\vfpl}{P}$ and $\vfopp$ and $\vfpl$
  are compatible and $\vfpl\cup \vfopp$ is transitive. Then for all $S\subseteq \Nho$ such that $S\cap
  (\vfopp\cup \vfpl (\cur)) = \emptyset$,
  $\typ{\resmin{\vfpl}{S}}{\prune{S}{\vfpl}P}$ and $P \trEqV{\vfpl}{\vfopp}
  \prune{S}{\vfpl}P$. 
\end{lm}
We actually remove more than the names in $S$. Indeed,  to
preserve sequentiality, we cannot  simply remove an output;   
we actually  remove
all inputs that may cause an output on the names in $S$.

The idea of the proof is to show that $S\cap (\vfopp \cup \vfpl
(\cur)) = \emptyset$ is an invariant throughout the trace; for this 
we use repeatedly
 transitivity of $\vfopp \cup \vfpl$. 
\begin{proof}
  Let $\mu_1\dots\mu_n$ a trace of $P$ under $\vfopp$, let $P_i,\vfopp_i$ be the processes and visibility functions given that trace and $\vfpl_i$ the visibility functions given by subject reduction.
  We show by induction on $i$ that there exists $\vfopp_i',\vfpl_i'$ such that $\vfopp_i'\supseteq \vfopp_i$ and $\vfpl_i' \supseteq \vfpl_i$ and
  $S\cap (\vfopp_i' \cup \vfpl_i')(\cur)= \emptyset$ and that $\vfpl_i'$ and $\vfopp_i'$ are compatible, have a transitive union and coincide on the intersection of their domains. The case $i=0$ is immediate, let $0\leq i <n$, we assume the induction hypothesis on $i$ and show it for $i+1$ by cases on $\mu_i$ :
  \begin{itemize}
  \item if $\mu_i = \tau$, or $\mu_i = \inpACT{h}{v}$ or $\mu_i = \out{h}{v}{}$ then $\vfopp_{i+1} = \vfopp_i$ and $\vfpl_{i+1} = \vfpl_i$, these cases are immediate by setting $\vfopp_{i+1}'= \vfopp_i'$ and $\vfpl_{i+1}'= \vfpl_i'$.
  \item if $\mu_i = \out{a}{v}{b}$ then $\vfopp_{i+1} = \vfopp_i\cons\cur \arr \vfopp_i(a),b$ and $\vfpl_{i+1} = \resmin{\vfpl_i}{\cur}\cons b\arr \vfpl_i(\cur),b$. 
    Let $\vfopp_{i+1}'= \vfopp_i'\cons\cur \arr \vfpl_i'(\cur),b \supseteq \vfopp_{i+1}$ because $a\in \vfpl_i(\cur)$ therefore $\vfopp_i(a)\subseteq \vfpl_i(\cur)$. And let $\vfpl_{i+1}'=\resmin{\vfpl_i'}{\cur}\cons b\arr \vfpl_i'(\cur),b$.\\
    $\vfopp_{i+1}'$    and $\vfpl_{i+1}'$ are compatible, their union is transitive and they coincide on the intersection of their domains.\\
    $(\vfopp_{i+1}' \cup \vfpl_{i+1}')(\cur) = (\vfopp_{i}' \cup \vfpl_{i}')(\cur),b$ where $b$ is fresh therefore $b\notin S$ and by induction hypothesis $S \cap (\vfopp_{i+1}' \cup \vfpl_{i+1}')(\cur)=\emptyset$.
\item if $\mu_i = a\langle v\rangle(b)$ the case is similar to the
  previous one, swapping $\vfopp$ and $\vfpl$. 
\end{itemize}
This ensures us that none of the $\mu_i$ are inputs or outputs on higher-order names in $S$. Moreover if $a\in \dom{\vfpl}$ and $\vfpl(a)\cap S\neq \emptyset$ then for all $i$, $a\notin (\vfopp_i \cup \vfpl_i)(\cur)$ otherwise we would have $\emptyset \neq \vfpl(a) \cap S = \vfpl_i(a) \cap S \subseteq (\vfopp_i \cup \vfpl_i)(\cur) \cap S = \emptyset$.\\
Therefore the trace $\mu_1\dots\mu_n$ is also a trace of $\prune{S}{\vfpl}{P}$ under $\vfopp$.
\end{proof}

\section{Section~\ref{s:labels}: Labelled Bisimilarity}\label{sec:lab_bisim}

\renewcommand{\typopp}[2]{ \textcolor{red}{#1}  }
\renewcommand{\bisim}[3]{ #2 \mathrel{\approx^{#1}} #3}
\renewcommand{\typtrans}[5]{\typPAIR{#1}{#2} \trans{#3}\typPAIR{#4}{#5}}
\renewcommand{\typpl}[2]{%\langle
 \textcolor{green}{#1}
% |\textcolor{green} {#2} \rangle
}


  A  \emph{typed relation} is a set of triples $\underoppD{{
    \vfopp}}PQ$ intended to represent the visibility of the observer
for processes $P$ and $Q$ in the bisimulation game.  



 %  \begin{itemize}
 %  \item $\typopp{ \vfopp}{}$ is a co-typing
 % \item $P,Q$ are reference complete processes \daniel{to be
 %     introduced; defined, rather}
 %  \end{itemize}


\begin{df}[Typed Bisimulation]
  A  typed relation $\mathcal{R}$ is a \emph{typed (weak) bisimulation} if
whenever $\underoppD{\vfopp}PQ \in \R$ : 
\begin{enumerate}
\item
if   $\typtrans{\typopp{\vfopp}{ }}{ P }{\mu}{ \typopp{\vfopp[']}{}}{
    P'}$ then there is $Q'$ such that
  $\typTrans{\typopp{\vfopp}{}}{ Q }{\mu}{ \typopp{\vfopp[']}{}}{ Q'}$
  and 
 $\underoppD{\vfopp'}{P'}{Q'} \in \R$;

\item  the converse, on the actions from $Q$.
\end{enumerate} 
\emph{Typed bisimilarity}, written $\approx$, is the largest typed
bisimulation. 
  For two $\vfpl$-processes $P,Q$ we write $P \bisEqV{\vfpl}{\vfopp} Q$  when
  $\underoppD{{\vfopp}{}}PQ \in {\approx}$ and $\vfpl$ and $\vfopp$ are compatible.
  In this case, we say that $P$ and $Q$ are \emph{bisimilar under $\vfopp$}.
\end{df}


\begin{ex}
  As for barbed equivalence the visibility of opponent also plays an
  important role in determining whether two process are bisimilar under
  some $\vfopp$. Consider 
$\vfpl$ and $\vfopp$ compatible, and 
a $\vfpl$-process  % $P$ and a process
  of the form $Q =
  P | a.\out{b}{}{}.R$ with $b\notin \mathtt{fn}(P)$ and $b \in
  \dom{\vfopp}$: 
  % of the form $Q =
  % P | a(x,-).\out{b}{}{-}.R$ with $b\notin \mathtt{fn}(P)$ and $b \in
  % \dom{\vfopp}$: 
  \begin{itemize}
  \item if $a \in \mathtt{fn}(P)$, we may have,  for example, $P=
    \out{a}{}{}.R'$, in which case $Q \trans{\tau} R' |
    \out{b}{}{}.R$; such derivative is not bisimilar with $P$ under % visibility
    $\vfopp$, as only $R' | \out{b}{}{}.R$ can make an output on $b$;
  \item if $a\in \vfopp(\cur)$, then 
 we have $Q \trans{a} P| \outC{b}.R$, which is not bisimilar to any
 $P'$ such that $P \trans{a}P'$,  for the same reason as in the previous case;
  \item however, if both $a\notin \mathtt{fn}(P)$ and $a\notin
    \vfopp(\cur)$, then  $Q$ cannot
    make an input on $a$,  and therefore we have $Q\bisEqV{\vfpl}{\vfopp} P$.
  \end{itemize}
\end{ex}

The analogues of Lemmas~\ref{lm:res}-\ref{lm:parcomp_tr} and~\ref{lm:garbage_coll} also hold for 
typed bisimilarity. 
\begin{lm}[Restriction]
  \label{lm:res_bis}
 If 
$P \bisEqV \vfpl \vfopp Q$,
then also 
$\res a P \bisEqV{\resmin{\vfpl}{a}}{ \resmin{\vfopp}{{a}}} \res a Q$.
\end{lm}
\begin{lm}[Input]
  If $P \bisEqV \vfpl \vfopp Q$ and
$\vfopp \NOTinDom \cur$, 
% $\cur \notin \vfopp$ 
then also $a(x,b) .P \bisEqV{\resmin{\vfpl}{\cur,b}}{ (\resmin{\vfopp\cons \cur \arr \vfopp(b))}{b}} a(x,b).Q$.
\end{lm}
\begin{lm}[Output]
  If $P \bisEqV\vfpl \vfopp Q$ and
$\vfopp \NOTinDom \cur$, 
% $\cur \in \vfopp$ 
then also $\out{a}{e}{b}. P \bisEqV{\resmin{(\vfpl\cons \cur \arr \vfpl(b))}{b}}{ \resmin{\vfopp}{\cur,b}} \out{a}{e}{b}.Q$.
\end{lm}


\begin{lm}[Parallel composition]
  \label{lm:parcomp_bis}
Suppose $P \bisEqV \vfpl \vfopp Q$
and 
  $(\vfopp[_1], \vfopp[_2])\in \mathtt{split}(\vfopp)$. 
Then 
  $\typ{\vfopp[_2]}{R}$
implies
 $P| R \bisEqV{(\vfpl\cup \vfopp_2)^+}{\vfopp_1} Q|R$.
\end{lm}

\begin{lm}[Pruning]
  \label{lm:garbage_coll_bis}
  Let $\vfopp, \vfpl,P$ such $\typ{\vfpl}{P}$ and $\vfopp$ and $\vfpl$
  are compatible. Then for all $S\subseteq \Nho$ such that $S\cap
  (\vfopp\cup \vfpl (\cur)) = \emptyset$,
  $\typ{\resmin{\vfpl}{S}}{\prune{S}{\vfpl}P}$ and $P \bisEqV{\vfpl}{\vfopp}
  \prune{S}{\vfpl}P$. 
\end{lm}

Technical lemmas similar to those for trace equivalence also holds,
such as the following ones.

\begin{lm}[Shrinking]
  \label{l:shr:bis}
Suppose
 $\vfopp[']\subseteq \vfopp$, $\vfpl$ and $\vfopp[']$ compatible and
$P \bisEqV\vfpl \vfopp Q$.
Then also 
$P \bisEqV{\vfpl} {\vfopp'} Q$.
\end{lm}

\begin{lm}[extension]
   Consider $\vfopp,\vfopp['],P,Q$ such that
   $\mathtt{proj}(\fnames{\vfopp,P,Q},\vfopp[']) = \vfopp$ and $\vfpl$ and $\vfopp'$ are compatible. If
   $P \bisEqV{\vfpl}{\vfopp} Q$ then
   $P \bisEqV{\vfpl}{\vfopp[']} Q$. 
 \end{lm}

We report the characterisation results.
Soundness follows from the substitutivity properties of labelled
bisimilarity. For completeness, as usual with characterisations of 
barbed equivalence, the proof  uses induction, via 
an  inductive stratification of
bisimilarity, and requires image-finiteness of processes 
(that is, up-to $\alpha $-conversion, the set of possible
type-allowed  weak transitions emanating from a process is finite). 
The image-finite condition is needed 
in the 
 characterisation of bisimilarity via the inductive 
stratification.
Also, and again in line with  proofs about barbed relations, 
   the  proof exploits the  presence of the sum operator and of
success signals that can be emitted by a testing context whenever
needed. 

