\begin{thm}[Soundness of  bisimilarity  for barbed equivalence]
 Suppose $\typ{\typpl{\vfpl}{\stack}}{P,Q}$
with 
$P\bisEqV{\typpl{\vfpl}{\stack}}{\typopp{\vfopp}{\kcats}} Q$.
Then also 
 $P
 \wbe{\typpl{\vfpl}{\stack}}{\typopp{\vfopp}{\kcats}}
 Q$.
\end{thm}

\begin{thm}[Completeness of bisimilarity  for barbed equivalence]
If  $P$ and $Q$ are image-finite processes, and if
 $P
 \wbe{\typpl{\vfpl}{\stack}}{\typopp{\vfopp}{\kcats}}
 Q$,
then 
$P\bisEqV{\typpl{\vfpl}{\stack}}{\typopp{\vfopp}{\kcats}} Q$.
\end{thm}

